    def get_vat_settings(self, company_id: int) -> dict | None:
        row = self.fetch_one(
            """
            SELECT vat_settings, country, vat
            FROM public.companies
            WHERE id = %s
            LIMIT 1;
            """,
            (company_id,),
        )

        if not row:
            return None

        settings = row.get("vat_settings")

        # If vat_settings is stored as TEXT (json dumps), convert to dict
        if isinstance(settings, str) and settings.strip():
            try:
                settings = json.loads(settings)
            except Exception:
                settings = None

        # Default if not set
        if not settings:
            return {
                "frequency": "bi_monthly",
                "anchor_month": 1,
                "filing_lag_days": 25,
                "reminder_days_before": 10,
                "country": (row.get("country") or "ZA").upper(),
                "vat_registered": bool(row.get("vat")),
                "vat_number": row.get("vat"),
                "vat_rate": 15,
                "pricing_includes_vat": False,
                "corp_tax_rate": 27,
            }

        return settings


    def save_vat_settings(self, company_id: int, settings: dict) -> bool:
        sql = "UPDATE public.companies SET vat_settings=%s WHERE id=%s;"
        self.execute_sql(sql, (Json(settings), company_id))

        return True


    def provision_enterprise_company_and_user(
        self,
        *,
        email: str,
        password_hash: str,
        first_name: str,
        last_name: str,
        user_role: str,
        company_payload: dict,
        industry: str,
        sub_industry: str | None,
        confirmation_token: str,
        trial_start_date,
        trial_end_date,
        initialize_coa_fn,  # pass initialize_coa(db_service, company_id, industry, sub_industry)
    ) -> tuple[int, int]:
        """
        Atomic provisioning:
        company + user + schema + coa seed + set owner.
        Returns (company_id, user_id)
        """
        with self.transaction():
            # 1) company (no owner yet)
            company_id = self.insert_company(
                name=company_payload["companyName"],
                client_code=company_payload["clientCode"],
                industry=industry,
                sub_industry=sub_industry,
                currency=company_payload.get("currency"),
                fin_year_start=company_payload.get("finYearStart"),
                company_reg_date=company_payload.get("companyRegDate"),
                country=company_payload.get("country"),
                company_reg_no=company_payload.get("companyRegNo"),
                tin=company_payload.get("tin"),
                vat=company_payload.get("vat"),
                company_email=company_payload.get("companyEmail"),
                owner_user_id=None,  # set after user exists
            )

            # 2) user
            user_id = self.insert_user(
                email=email,
                password_hash=password_hash,
                user_type="Enterprise",
                first_name=first_name,
                last_name=last_name,
                user_role=user_role,
                company_id=company_id,
                is_confirmed=False,
                confirmation_token=confirmation_token,
                trial_start_date=trial_start_date,
                trial_end_date=trial_end_date,
            )
            if not user_id:
                raise RuntimeError("Failed to insert user")

            # 3) schema + COA seed (ONCE)
            self.initialize_company_schema(company_id)      # tables + any one-time setup
            initialize_coa_fn(self, company_id, industry, sub_industry)

            # 4) set owner
            self.set_company_owner(company_id, int(user_id))

            return company_id, int(user_id)

    # ---------------------------
    # companies (public)
    # ---------------------------
    # ✅ UPDATED insert_company: now supports company profile fields that exist in public.companies
    # Adds: physical_address, postal_address, company_phone, logo_url
    # Also makes "name" default to companyName if you pass that upstream.


    def _addr_to_text(self, addr: Optional[Dict[str, Any]]) -> Optional[str]:
        """
        Make a human-readable multi-line string from your structured address object.
        Safe for legacy templates/branding.
        """
        if not isinstance(addr, dict):
            return None

        def clean(v):
            if v is None:
                return None
            s = str(v).strip()
            return s if s else None

        parts = [
            clean(addr.get("line1")),
            clean(addr.get("line2")),
            clean(addr.get("locality")),
            clean(addr.get("city")),
            clean(addr.get("region")),
            clean(addr.get("postalCode")),
            clean(addr.get("country")),
        ]
        parts = [p for p in parts if p]
        return "\n".join(parts) if parts else None

    # make sure this is imported where this function lives
    # from BackEnd.Services.industry_profiles import get_industry_profile, choose_layout, normalize_industry_pair

    def insert_company(
        self,
        name: str,
        client_code: str,
        industry: Optional[str] = None,
        sub_industry: Optional[str] = None,
        organization_type: Optional[str] = None,
        currency: Optional[str] = None,
        fin_year_start: Optional[str] = None,
        company_reg_date: Optional[str] = None,
        country: Optional[str] = None,
        company_reg_no: Optional[str] = None,
        tin: Optional[str] = None,
        vat: Optional[str] = None,
        company_email: Optional[str] = None,
        owner_user_id: Optional[int] = None,
        inventory_mode: Optional[str] = None,
        inventory_valuation: Optional[str] = None,
        physical_address: Optional[str] = None,
        postal_address: Optional[str] = None,
        company_phone: Optional[str] = None,
        logo_url: Optional[str] = None,
        registered_address_json: Optional[Dict[str, Any]] = None,
        postal_address_json: Optional[Dict[str, Any]] = None,
        address_place_id: Optional[str] = None,
        address_lat: Optional[str] = None,
        address_lng: Optional[str] = None,
        industry_slug: Optional[str] = None,
        sub_industry_slug: Optional[str] = None,
        entity_kind: Optional[str] = None,
        make_primary_membership: bool = True,
        membership_kind: Optional[str] = None,
        created_via: Optional[str] = None,
        source_customer_company_id: Optional[int] = None,
        provisioning_context: Optional[str] = None,
    ) -> int:

        try:
            if industry_slug is None or sub_industry_slug is None:
                ind_norm, sub_norm, ind_slug, sub_slug = normalize_industry_pair(industry, sub_industry)

                if not industry:
                    industry = ind_norm
                if not sub_industry:
                    sub_industry = sub_norm

                industry_slug = industry_slug or ind_slug
                sub_industry_slug = sub_industry_slug or sub_slug
        except Exception:
            pass

        entity_kind = (entity_kind or "company").strip().lower()
        if entity_kind not in {"company", "branch_entity"}:
            entity_kind = "company"

        membership_kind = (membership_kind or ("primary" if make_primary_membership else "secondary")).strip().lower()
        if membership_kind not in {"primary", "secondary"}:
            membership_kind = "secondary"

        profile = get_industry_profile(industry, sub_industry)

        if not inventory_mode:
            inventory_mode = profile.get("default_inventory_mode") or "none"

        if inventory_valuation is None:
            inventory_valuation = profile.get("default_valuation")

        default_pnl_layout = profile.get("pnl_layout") or choose_layout("pnl", profile)
        pnl_labels_json = Json(profile.get("pnl_labels") or {})

        if physical_address is None:
            physical_address = self._addr_to_text(registered_address_json)
        if postal_address is None:
            postal_address = self._addr_to_text(postal_address_json)

        reg_json = Json(registered_address_json) if registered_address_json is not None else None
        post_json = Json(postal_address_json) if postal_address_json is not None else None

        created_via = (created_via or "").strip().lower() or None
        if created_via not in {None, "self_signup", "firm_client_provisioning", "related_company", "admin", "migration", "import"}:
            created_via = None

        provisioning_context = (provisioning_context or "").strip() or None
        organization_type = (organization_type or "private_company").strip().lower()

        with self._conn_cursor() as (conn, cur):
            cur.execute(
                """
                INSERT INTO public.companies
                (
                    name, client_code, industry, sub_industry, organization_type,
                    industry_slug, sub_industry_slug, inventory_mode, inventory_valuation,
                    currency, fin_year_start, company_reg_date,
                    country, company_reg_no, tin, vat,
                    company_email, owner_user_id, is_active,
                    default_pnl_layout, pnl_labels_json,
                    physical_address, postal_address, company_phone, logo_url,
                    registered_address_json, postal_address_json,
                    address_place_id, address_lat, address_lng,
                    entity_kind,
                    created_via, source_customer_company_id, provisioning_context
                )
                VALUES
                (
                    %s, %s, %s, %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, TRUE,
                    %s, %s,
                    %s, %s, %s, %s,
                    %s, %s,
                    %s, %s, %s,
                    %s,
                    %s, %s, %s
                )
                RETURNING id;
                """,
                (
                    name, client_code, industry, sub_industry, organization_type,
                    industry_slug, sub_industry_slug, inventory_mode, inventory_valuation,
                    currency, fin_year_start, company_reg_date,
                    country, company_reg_no, tin, vat,
                    company_email, owner_user_id,
                    default_pnl_layout, pnl_labels_json,
                    physical_address, postal_address, company_phone, logo_url,
                    reg_json, post_json,
                    address_place_id, address_lat, address_lng,
                    entity_kind, created_via, source_customer_company_id, provisioning_context,
                ),
            )

            row = cur.fetchone()
            if not row:
                raise RuntimeError("Failed to insert company")

            company_id = int(row["id"])

            if owner_user_id and make_primary_membership:
                cur.execute(
                    """
                    UPDATE public.company_users
                    SET is_primary = FALSE
                    WHERE user_id = %s
                    AND is_primary = TRUE;
                    """,
                    (int(owner_user_id),),
                )

                cur.execute(
                    """
                    INSERT INTO public.company_users
                    (
                        company_id,
                        user_id,
                        role,
                        access_scope,
                        membership_kind,
                        is_primary,
                        is_active,
                        joined_at
                    )
                    VALUES
                    (
                        %s,
                        %s,
                        'owner',
                        'core',
                        %s,
                        %s,
                        TRUE,
                        NOW()
                    )
                    ON CONFLICT (company_id, user_id) DO UPDATE
                    SET
                        role = 'owner',
                        access_scope = 'core',
                        membership_kind = EXCLUDED.membership_kind,
                        is_primary = EXCLUDED.is_primary,
                        is_active = TRUE,
                        joined_at = COALESCE(public.company_users.joined_at, NOW());
                    """,
                    (
                        company_id,
                        int(owner_user_id),
                        membership_kind,
                        bool(make_primary_membership),
                    ),
                )

            conn.commit()

        self.initialize_public_schema()
        self.ensure_company_account_settings(company_id)
        return company_id

    def get_company_group_structure(self, company_id: int) -> dict:
        with self._conn_cursor() as (conn, cur):
            cur.execute(
                "SELECT * FROM public.companies WHERE id = %s",
                (company_id,)
            )
            company = cur.fetchone()

            cur.execute("""
                SELECT
                    r.*,
                    c.name AS child_company_name,
                    c.system_company_code,
                    c.country,
                    c.currency,
                    c.entity_kind
                FROM public.company_relationships r
                JOIN public.companies c
                ON c.id = r.child_company_id
                WHERE r.parent_company_id = %s
                AND r.is_active = TRUE
                ORDER BY c.name
            """, (company_id,))
            relationships = [dict(r) for r in cur.fetchall()]

            cur.execute("""
                SELECT *
                FROM public.company_branches
                WHERE company_id = %s
                AND is_active = TRUE
                ORDER BY name
            """, (company_id,))
            branches = [dict(r) for r in cur.fetchall()]

            cur.execute("""
                SELECT *
                FROM public.company_segments
                WHERE company_id = %s
                AND is_active = TRUE
                ORDER BY name
            """, (company_id,))
            segments = [dict(r) for r in cur.fetchall()]

            return {
                "company": dict(company) if company else None,
                "relationships": relationships,
                "branches": branches,
                "segments": segments,
            }
    
    def get_company_profile(self, company_id: int) -> Optional[Dict[str, Any]]:
        sql = """
            SELECT
            id, owner_user_id, name, country, currency,

            fin_year_start,
            company_reg_date,
            first_reporting_period_start,
            financial_year_end_month,
            financial_year_end_day,
            reporting_period_locked,

            company_email, company_phone,
            physical_address, postal_address,
            registered_address_json, postal_address_json,
            address_place_id, address_lat, address_lng,
            company_reg_no, tin, vat,
            logo_url,
            vat_settings,
            credit_policy
            FROM public.companies
            WHERE id = %s
            LIMIT 1;
        """
        row = self.fetch_one(sql, (int(company_id),))
        if not row:
            return None

        policy = row.get("credit_policy") or {}
        if not isinstance(policy, dict):
            policy = {}

        policy = normalize_policy(policy)
        mode = normalize_policy_mode(policy)
        policy["mode"] = mode

        row["credit_policy"] = policy
        return row

    def update_company_profile(self, company_id: int, payload: Dict[str, Any]) -> bool:
        cid = int(company_id)

        allowed = {
            "name": "name",
            "company_email": "company_email",
            "company_phone": "company_phone",
            "physical_address": "physical_address",
            "postal_address": "postal_address",
            "company_reg_no": "company_reg_no",
            "tin": "tin",
            "vat": "vat",
            "logo_url": "logo_url",
            "credit_policy": "credit_policy",
            "vat_settings": "vat_settings",

            # Reporting / company dates
            "fin_year_start": "fin_year_start",
            "company_reg_date": "company_reg_date",
            "first_reporting_period_start": "first_reporting_period_start",
            "financial_year_end_month": "financial_year_end_month",
            "financial_year_end_day": "financial_year_end_day",
            "reporting_period_locked": "reporting_period_locked",

            # JSONB + meta fields
            "registered_address_json": "registered_address_json",
            "postal_address_json": "postal_address_json",
            "address_place_id": "address_place_id",
            "address_lat": "address_lat",
            "address_lng": "address_lng",
        }

        json_keys = {"registered_address_json", "postal_address_json", "vat_settings", "credit_policy"}
        date_keys = {"company_reg_date", "first_reporting_period_start"}
        int_keys = {"financial_year_end_month", "financial_year_end_day"}
        bool_keys = {"reporting_period_locked"}

        sets: list[str] = []
        params: list[Any] = []

        for k, col in allowed.items():
            if k not in payload:
                continue

            v = payload.get(k)

            if k in json_keys:
                if v is None:
                    pass
                elif isinstance(v, dict):
                    v = Json(v)
                else:
                    raise ValueError(f"{k} must be an object (dict) or null")

            elif k in date_keys:
                v = _safe_date(v)

            elif k in int_keys:
                if v in (None, ""):
                    v = None
                else:
                    v = int(v)

            elif k in bool_keys:
                if isinstance(v, str):
                    v = v.strip().lower() in ("1", "true", "yes", "on")
                else:
                    v = bool(v)

            elif isinstance(v, str):
                v = v.strip()
                if v == "":
                    v = None

            sets.append(f"{col}=%s")
            params.append(v)

        if not sets:
            return True

        params.append(cid)

        sql = f"""
        UPDATE public.companies
        SET {', '.join(sets)}
        WHERE id=%s
        RETURNING id;
        """

        print("=" * 80, flush=True)
        print("UPDATE COMPANY PROFILE", flush=True)
        print("Payload:", payload, flush=True)
        print("SQL:", sql, flush=True)
        print("Params:", params, flush=True)
        print("=" * 80, flush=True)

        try:
            print("ABOUT TO EXECUTE COMPANY UPDATE", flush=True)

            result = self.execute_sql(sql, tuple(params))

            print("UPDATE RETURNING RESULT:", result, flush=True)

            return bool(result)

        except Exception as e:
            print("update_company_profile failed:", e, flush=True)
            return False
        
    def dedupe_company_coa(self, company_id: int) -> int:
        schema = f"company_{company_id}"
        sql = f"""
        WITH ranked AS (
        SELECT
            id,
            name,
            code,
            COALESCE(
            NULLIF(code_family,''),
            split_part(code, '_', 1) || '_' || split_part(code, '_', 2)
            ) AS fam,
            template_code,
            ROW_NUMBER() OVER (
            PARTITION BY
                lower(trim(name)),
                COALESCE(
                NULLIF(code_family,''),
                split_part(code, '_', 1) || '_' || split_part(code, '_', 2)
                )
            ORDER BY
                (NULLIF(cf_bucket,'') IS NOT NULL) DESC,
                (NULLIF(standard,'') IS NOT NULL) DESC,
                (NULLIF(description,'') IS NOT NULL) DESC,
                (lower(name) LIKE '%control%') DESC,
                id ASC
            ) AS rn
        FROM {schema}.coa
        )
        DELETE FROM {schema}.coa c
        USING ranked r
        WHERE c.id = r.id
        AND r.rn > 1
        -- ✅ never delete control accounts
        AND lower(r.name) NOT LIKE '%control%'
        -- ✅ never delete mandatory control template codes
        AND COALESCE(r.template_code,'') NOT IN ('1410','2310','2105','9002')
        RETURNING c.id;
        """
        rows = self.fetch_all(sql) or []
        return len(rows)

    def fetch_coa_pool_rows(self, industry: str, sub_industry: str) -> list[dict]:
        sql = """
        SELECT template_code, name, code, section, category, subcategory, description,
            standard, industry, sub_industry, is_general, posting
        FROM public.coa_pool
        WHERE (industry IS NULL OR industry = %s)
        AND (sub_industry IS NULL OR sub_industry = %s)
        """
        with self._conn_cursor() as (conn, cur):
            cur.execute(sql, (industry, sub_industry))
            rows = [dict(r) for r in cur.fetchall()]
        return rows

    def _make_system_company_code(self, prefix: str = "FS", length: int = 6) -> str:
        alphabet = string.digits  # numeric only (per your request)
        token = "".join(secrets.choice(alphabet) for _ in range(length))
        return f"{prefix}-{token}"

