    def get_income_statement_v2(
        self,
        company_id: int = None,
        date_from: date = None,
        date_to: date = None,
        template: str = "ifrs",
        basis: str = "external",
        compare: str = "none",
        cols_mode: int = 1,
        detail: str = "summary",
        prior_from: Optional[date] = None,
        prior_to: Optional[date] = None,
        comparison_years: int = 1,
        **kwargs: Any,
    ) -> Dict[str, Any]:
        """
        Unified external/management P&L entry point used by /api/.../pnl.

        - basis = external    -> IAS 1 engine (get_pnl_full_v2)
        - basis = management  -> internal builder (build_income_statement_template)

        Compare support:
        - If prior_from/prior_to are provided, they are forwarded to IAS 1 engine.
        - If not provided, IAS 1 engine may compute fallback priors.
        """
        # context
        ctx = get_company_context(self, company_id) or {}
        kwargs.pop("ctx", None)

        # allow passing via kwargs too (non-breaking for older callers)
        if prior_from is None and "prior_from" in kwargs:
            prior_from = kwargs.pop("prior_from", None)
        if prior_to is None and "prior_to" in kwargs:
            prior_to = kwargs.pop("prior_to", None)

        basis_norm = (basis or "external").lower().strip()

        if "comparison_years" in kwargs:
            try:
                comparison_years = int(kwargs.pop("comparison_years") or comparison_years)
            except Exception:
                comparison_years = 1

        comparison_years = max(1, min(int(comparison_years or 1), 10))

        # -------- MANAGEMENT / INTERNAL (classic + Hunter) --------
        if basis_norm == "management":
            prof = ctx.get("industry_profile") or get_industry_profile(
                ctx.get("industry"), ctx.get("sub_industry")
            )
            layout = choose_layout("pnl", prof)

            return build_income_statement_template(
                get_trial_balance_range_fn=self.get_trial_balance,
                get_company_context_fn=lambda cid: get_company_context(self, cid),
                company_id=company_id,
                date_from=date_from,
                date_to=date_to,
                template=template,
                basis="management",
                layout=layout,
                cols_mode=cols_mode,
            )

        # -------- EXTERNAL / IAS 1 --------
        kwargs_for_compare = {}

        if compare == "multi_year":
            kwargs_for_compare = {
                "comparison_years": comparison_years,
            }
        elif compare != "none":
            kwargs_for_compare = {
                "prior_from": prior_from,
                "prior_to": prior_to,
                "comparison_years": comparison_years,
            }

        return get_pnl_full_v2(
            self,
            company_id=company_id,
            date_from=date_from,
            date_to=date_to,
            template=template,
            basis="external",
            compare=compare,
            cols_mode=1,
            detail=detail,
            ctx=ctx,
            **kwargs_for_compare,
        )

    # ✅ Legacy shim for older code paths
    def get_pnl_full(
        self,
        company_id: int,
        date_from: date,
        date_to: date,
        **kwargs: Any,
    ) -> Dict[str, Any]:
        """
        Old entry that now just forwards to get_pnl_full_v2 (external only).
        """
        return get_pnl_full_v2(
            self,
            company_id=company_id,
            date_from=date_from,
            date_to=date_to,
            template=kwargs.get("template", "ifrs"),
            basis=kwargs.get("basis", "external"),
            compare=kwargs.get("compare", "none"),
            cols_mode=int(kwargs.get("cols_mode", 1)),
            detail=kwargs.get("detail", "summary"),
            prior_from=kwargs.get("prior_from"),   # ✅ allow legacy callers to pass
            prior_to=kwargs.get("prior_to"),       # ✅ allow legacy callers to pass
        )


    def get_cashflow_full_v2(
        self,
        company_id: int,
        date_from: date,
        date_to: date,
        template: str = "ifrs",
        basis: str = "external",
        compare: str = "none",
        method: str = "direct",
        compare_mode: Optional[str] = None,
        prior_from: Optional[date] = None,
        prior_to: Optional[date] = None,
        preview_columns: int = 2,
        comparison_years: int = 1,
        cols_mode: int = 1,
    ) -> Dict[str, Any]:

        if not date_from or not date_to:
            return {
                "meta": {"statement": "cf", "template": template, "basis": basis},
                "columns": [{"key": "cur", "label": "Amount"}],
                "sections": [],
                "error": "from/to are required",
            }

        # legacy param support
        if compare_mode is not None:
            compare = compare_mode

        preview_columns = norm_preview_columns(preview_columns)
        compare = norm_compare(compare)

        method = (method or "direct").lower().strip()
        if method not in ("direct", "indirect"):
            method = "direct"

        # RULE: preview=2 => NO compare
        if preview_columns == 2:
            compare = "none"
            prior_from = None
            prior_to = None

        # ✅ Use explicit priors if supplied; only compute as fallback
        if compare == "none":
            prior_from = None
            prior_to = None
        elif prior_from is None or prior_to is None:
            pf, pt = build_compare_range(date_from, date_to, compare)
            prior_from = prior_from or pf
            prior_to = prior_to or pt

        # ---- adapters ----
        def _get_company_context(cid: int) -> Dict[str, Any]:
            return get_company_context(self, cid)

        def _get_journals_period(cid: int, df: date, dt: date):
            return self.get_journals_with_lines_for_period(cid, df, dt)

        def _tb_as_of(cid: int, as_of: date):
            return self.get_trial_balance_with_meta(cid, date(1900, 1, 1), as_of)

        def _cash_position_from_tb(tb_rows):
            return self._cash_position_from_tb(tb_rows)

        # route indirect
        if method == "indirect":
            return self.get_cashflow_indirect_v2(
                company_id=company_id,
                date_from=date_from,
                date_to=date_to,
                template=template,
                basis=basis,
                compare=compare,
                prior_from=prior_from,
                prior_to=prior_to,
                preview_columns=preview_columns,
                cols_mode=cols_mode,
                comparison_years=comparison_years,
            )

        return build_cashflow_full_v2(
            get_company_context_fn=_get_company_context,
            get_journals_period_fn=_get_journals_period,
            tb_as_of_fn=_tb_as_of,
            cash_position_from_tb_fn=_cash_position_from_tb,
            company_id=company_id,
            date_from=date_from,
            date_to=date_to,
            template=template,
            basis=basis,
            compare_mode=compare,
            prior_from=prior_from,
            prior_to=prior_to,
            preview_columns=preview_columns,
            cols_mode=cols_mode,
            comparison_years=comparison_years,
        )


    def get_cashflow_indirect_v2(
        self,
        company_id: int,
        date_from: date,
        date_to: date,
        template: str = "ifrs",
        basis: str = "external",
        compare: str = "none",
        compare_mode: Optional[str] = None,
        prior_from: Optional[date] = None,
        prior_to: Optional[date] = None,
        preview_columns: int = 2,
        comparison_years: int = 1,
        cols_mode: int = 1,
    ) -> Dict[str, Any]:

        if compare_mode is not None:
            compare = compare_mode

        preview_columns = norm_preview_columns(preview_columns)
        compare = norm_compare(compare)

        # RULE: preview=2 => NO compare
        if preview_columns == 2:
            compare = "none"
            prior_from = None
            prior_to = None

        # ✅ Use explicit priors if supplied; only compute as fallback
        if compare == "none":
            prior_from = None
            prior_to = None
        elif prior_from is None or prior_to is None:
            pf, pt = build_compare_range(date_from, date_to, compare)
            prior_from = prior_from or pf
            prior_to = prior_to or pt

        def _get_company_context(cid: int) -> Dict[str, Any]:
            return get_company_context(self, cid)

        def _get_pnl_full(cid: int, df: date, dt: date) -> Dict[str, Any]:
            pnl = self.get_pnl_full(cid, df, dt) or {}
            net = (pnl.get("net_result") or {}).get("amount")
            if net is None:
                pnl["net_result"] = {"amount": float((pnl.get("net") or 0.0) or 0.0)}
            return pnl

        def _decorate_lines_with_coa(lines, coa_map):
            for ln in lines or []:
                code = str(ln.get("code") or ln.get("account") or ln.get("account_code") or "").strip()
                if not code:
                    continue
                coa = coa_map.get(code) or {}
                ln["cf_bucket"] = coa.get("cf_bucket") or ln.get("cf_bucket") or ""
                ln["cf_section"] = coa.get("cf_section") or ln.get("cf_section") or ""
                ln["code_family"] = coa.get("code_family") or ln.get("code_family") or ""
                ln["is_working_capital"] = bool(coa.get("is_working_capital") or ln.get("is_working_capital") or False)
                ln["is_cash_equiv"] = bool(coa.get("is_cash_equiv") or ln.get("is_cash_equiv") or False)
                ln["is_non_cash_addback"] = bool(coa.get("is_non_cash_addback") or ln.get("is_non_cash_addback") or False)
                ln["is_contra"] = bool(coa.get("is_contra") or ln.get("is_contra") or False)

        def _get_journals_period(cid: int, df: date, dt: date):
            journals = self.get_journals_with_lines_for_period(cid, df, dt) or []
            coa_rows = self.get_company_coa(cid) or []
            coa_map = {str(a.get("code") or "").strip(): a for a in coa_rows if a.get("code")}
            for j in journals:
                _decorate_lines_with_coa(j.get("journal_lines") or [], coa_map)
            return journals

        def _get_trial_balance_asof_rows(cid: int, _unused: Optional[date], as_of: date):
            rows = self.get_trial_balance_as_of(cid, as_of) or []

            coa_rows = self.get_company_coa(cid) or []
            coa_map = {str(a.get("code") or "").strip(): a for a in coa_rows if a.get("code")}

            out = []
            for r in rows:
                code = str(r.get("code") or r.get("account") or "").strip()
                if not code:
                    continue

                coa = coa_map.get(code, {})

                tb = {
                    "code": code,
                    "name": r.get("name") or "",
                    "section": r.get("section") or "",
                    "category": r.get("category") or "",
                    "standard": r.get("standard") or "",
                    "debit_total": float(r.get("debit") or r.get("debit_total") or 0.0),
                    "credit_total": float(r.get("credit") or r.get("credit_total") or 0.0),
                    "closing_balance": float(r.get("closing_balance") or 0.0),
                }

                tb["cf_bucket"] = coa.get("cf_bucket") or ""
                tb["cf_section"] = coa.get("cf_section") or ""
                tb["code_family"] = coa.get("code_family") or ""
                tb["is_working_capital"] = bool(coa.get("is_working_capital") or False)
                tb["is_cash_equiv"] = bool(coa.get("is_cash_equiv") or False)
                tb["is_contra"] = bool(coa.get("is_contra") or False)

                out.append(tb)
            return out

        return build_cashflow_indirect_v2(
            get_company_context_fn=_get_company_context,
            get_pnl_full_fn=_get_pnl_full,
            get_trial_balance_asof_fn=_get_trial_balance_asof_rows,
            get_journals_period_fn=_get_journals_period,
            company_id=company_id,
            date_from=date_from,
            date_to=date_to,
            template=template,
            basis=basis,
            compare_mode=compare,
            prior_from=prior_from,
            prior_to=prior_to,
            preview_columns=preview_columns,
            cols_mode=cols_mode,
            comparison_years=comparison_years,
        )

    def _closing_balance_from_tb_row(self, r: Dict[str, Any]) -> float:
        """
        Returns (debit - credit) style balance.
        Works with both get_trial_balance() and get_trial_balance_with_meta() shapes.
        """
        # 1) If closing_balance already exists, trust it.
        if r is None:
            return 0.0

        if "closing_balance" in r and r.get("closing_balance") is not None:
            return float(r.get("closing_balance") or 0.0)

        # 2) Otherwise compute from debit/credit totals (support both key styles)
        debit = float(
            r.get("debit_total")
            if r.get("debit_total") is not None
            else r.get("debit") or 0.0
        )
        credit = float(
            r.get("credit_total")
            if r.get("credit_total") is not None
            else r.get("credit") or 0.0
        )
        return debit - credit

    def _cash_position_from_tb(self, tb_rows: List[Dict[str, Any]]) -> Dict[str, float]:
        from BackEnd.Services import accounting_classifiers as ac

        cash_positive = 0.0
        overdraft = 0.0

        for r in (tb_rows or []):
            # ✅ normalize fields for classifier
            rr = dict(r or {})
            if "code" not in rr and "account" in rr:
                rr["code"] = rr.get("account")
            if "account" not in rr and "code" in rr:
                rr["account"] = rr.get("code")

            if not ac._is_cash_bank(rr):
                continue

            closing = float(self._closing_balance_from_tb_row(rr))
            if closing >= 0:
                cash_positive += closing
            else:
                overdraft += abs(closing)

        return {
            "cash_positive": float(cash_positive),
            "overdraft": float(overdraft),
            "position": float(cash_positive - overdraft),
        }

    def get_socie_v1(
        self,
        company_id: int,
        date_from: date,
        date_to: date,
        template: str = "ifrs",
        basis: str = "external",
        compare: str = "none",
        cols_mode: int = 1,
        prior_from: Optional[date] = None,
        prior_to: Optional[date] = None,
        comparison_ranges: Optional[List[Tuple[date, date]]] = None,
        **kwargs: Any,
    ) -> Dict[str, Any]:
        ctx = get_company_context(self, company_id) or {}
        kwargs.pop("ctx", None)

        if prior_from is None and "prior_from" in kwargs:
            prior_from = kwargs.pop("prior_from", None)
        if prior_to is None and "prior_to" in kwargs:
            prior_to = kwargs.pop("prior_to", None)
        if comparison_ranges is None and "comparison_ranges" in kwargs:
            comparison_ranges = kwargs.pop("comparison_ranges", None)

        basis_norm = (basis or "external").lower().strip()
        compare_norm = (compare or "none").lower().strip()

        if compare_norm not in ("none", "prior_period", "prior_year", "multi_year"):
            compare_norm = "none"

        try:
            cols_mode = int(cols_mode or 1)
        except Exception:
            cols_mode = 1

        if cols_mode not in (1, 2, 3):
            cols_mode = 1

        if cols_mode != 1:
            compare_norm = "none"
            prior_from = None
            prior_to = None
            comparison_ranges = []

        comparison_ranges = comparison_ranges or []

        if not comparison_ranges and compare_norm in ("prior_period", "prior_year") and prior_from and prior_to:
            comparison_ranges = [(prior_from, prior_to)]

        company_name = (
            ctx.get("company_name")
            or ctx.get("name")
            or f"Company {company_id}"
        )

        currency = (
            ctx.get("currency")
            or ctx.get("base_currency")
            or "USD"
        )

        organization_type = (
            ctx.get("organization_type")
            or ctx.get("organisation_type")
            or "private_company"
        )

        coa_rows = self.get_company_coa(company_id) or []
        coa_map = {
            str(a.get("code") or "").strip(): a
            for a in coa_rows
            if a.get("code")
        }

        def _tb_to_equity_accounts(tb_rows):
            out = []
            for r in tb_rows:
                code = str(r.get("code") or r.get("account") or "").strip()
                if not code.startswith("BS_EQ_"):
                    continue

                coa = coa_map.get(code, {})
                out.append({
                    "code": code,
                    "name": coa.get("name") or r.get("name") or code,
                    "role": coa.get("role") or "",
                    "category": coa.get("category") or r.get("category") or "",
                    "balance": float(r.get("closing_balance") or 0.0),
                })
            return out

        def _build_one_socie(df: date, dt: date, key: str = "cur") -> Dict[str, Any]:
            opening_as_of = df - timedelta(days=1)

            opening_tb = self.get_trial_balance_as_of(company_id, opening_as_of) or []
            closing_tb = self.get_trial_balance_as_of(company_id, dt) or []

            opening_equity_accounts = _tb_to_equity_accounts(opening_tb)
            closing_equity_accounts = _tb_to_equity_accounts(closing_tb)

            journals = self.get_journals_with_lines_for_period(company_id, df, dt) or []

            movement_journal_lines = []
            for j in journals:
                jdate = j.get("date")
                for ln in (j.get("journal_lines") or []):
                    code = str(
                        ln.get("account_code")
                        or ln.get("code")
                        or ln.get("account")
                        or ""
                    ).strip()

                    if not code.startswith("BS_EQ_"):
                        continue

                    coa = coa_map.get(code, {})
                    movement_journal_lines.append({
                        "account_code": code,
                        "name": coa.get("name") or "",
                        "role": coa.get("role") or "",
                        "category": coa.get("category") or "",
                        "date": jdate,
                        "debit": float(ln.get("debit") or 0.0),
                        "credit": float(ln.get("credit") or 0.0),
                    })

            profit_for_period = 0.0
            try:
                pnl = self.get_income_statement_v2(
                    company_id=company_id,
                    date_from=df,
                    date_to=dt,
                    template=template,
                    basis="external",
                    compare="none",
                    cols_mode=1,
                    detail="summary",
                ) or {}

                profit_for_period = float(
                    ((pnl.get("net_result") or {}).get("values") or {}).get("cur")
                    or ((pnl.get("net_result") or {}).get("amount"))
                    or 0.0
                )
            except Exception:
                profit_for_period = 0.0

            one = build_statement_of_changes_in_equity(
                company_id=company_id,
                company_name=company_name,
                currency=currency,
                organization_type=organization_type,
                period_from=df.isoformat(),
                period_to=dt.isoformat(),
                opening_equity_accounts=opening_equity_accounts,
                closing_equity_accounts=closing_equity_accounts,
                movement_journal_lines=movement_journal_lines,
                profit_for_period=profit_for_period,
                include_unclosed_profit=True,
            )

            one.setdefault("meta", {})
            one["meta"].update({
                "key": key,
                "period": {"from": df.isoformat(), "to": dt.isoformat()},
            })

            return one

        current_stmt = _build_one_socie(date_from, date_to, "cur")

        comparison_statements = []
        for idx, (pf, pt) in enumerate(comparison_ranges, start=1):
            key = "pri" if idx == 1 else f"p{idx}"
            comparison_statements.append(_build_one_socie(pf, pt, key))

        current_stmt.setdefault("meta", {})
        current_stmt["meta"].update({
            "company_id": company_id,
            "company_name": company_name,
            "currency": currency,
            "statement": "socie",
            "template": template,
            "basis": basis_norm,
            "compare": compare_norm if comparison_statements else "none",
            "cols_mode": cols_mode,
            "period": {"from": date_from.isoformat(), "to": date_to.isoformat()},
            "comparison_periods": [
                {
                    "key": s.get("meta", {}).get("key"),
                    "from": s.get("meta", {}).get("period", {}).get("from"),
                    "to": s.get("meta", {}).get("period", {}).get("to"),
                }
                for s in comparison_statements
            ],
        })

        current_stmt["comparison_statements"] = comparison_statements

        return current_stmt

    def _tb_as_of(self, company_id: int, as_of: date) -> List[Dict[str, Any]]:
        """
        Uses your existing TB query (ledger aggregated up to as_of).
        """
        return self.get_trial_balance(company_id, None, as_of) or []


    def get_cashflow_mini(
        self,
        company_id: int,
        date_from: Optional[date] = None,
        date_to: Optional[date] = None,
        method: str = "direct",
        compare: str = "none",
    ):
        if not date_from or not date_to:
            return []

        compare = (compare or "none").lower().strip()
        if compare not in ("none", "prior_period", "prior_year"):
            compare = "none"

        method = (method or "direct").lower().strip()
        if method not in ("direct", "indirect"):
            method = "direct"

        stmt = self.get_cashflow_full_v2(
            company_id=company_id,
            date_from=date_from,
            date_to=date_to,
            compare=compare,
            method=method,
            cols_mode=1,          # ✅ force safe default for mini
            preview_columns=1,    # ✅ also safest for mini (compare-capable)
        )

        sec = {s.get("key"): float((s.get("totals") or {}).get("cur") or 0.0)
            for s in (stmt.get("sections") or [])}

        return [
            {"section": "operating", "label": "Net cash from operating activities", "amount": sec.get("operating", 0.0)},
            {"section": "investing", "label": "Net cash from investing activities", "amount": sec.get("investing", 0.0)},
            {"section": "financing", "label": "Net cash from financing activities", "amount": sec.get("financing", 0.0)},
        ]


    def get_pnl_mini(
        self,
        company_id: int,
        date_from: Optional[date] = None,
        date_to: Optional[date] = None,
    ) -> List[Dict[str, Any]]:
        """
        Returns a compact P&L summary.
        """
        company = self.get_company(company_id)
        if not company:
            raise ValueError(f"Company {company_id} not found")

        flags = self._get_company_industry_flags(company_id) or {}
        uses_cogs = bool(flags.get("uses_cogs", False))

        tb_rows = self.get_trial_balance(company_id, date_from, date_to) or []

        revenue = 0.0
        cogs = 0.0
        expenses = 0.0
        other_income = 0.0

        for r in tb_rows:
            kind = ac._classify_tb_row(r)

            dr = float(r.get("debit_total") or 0.0)
            cr = float(r.get("credit_total") or 0.0)

            # P&L display sign:
            # revenue/other income positive
            # cogs/expenses negative
            amount = cr - dr

            if kind == "revenue":
                revenue += amount
            elif kind == "cogs":
                cogs += amount
            elif kind == "expense":
                expenses += amount
            elif kind == "other":
                other_income += amount

        rows: List[Dict[str, Any]] = []

        is_npo = "npo" in str(flags.get("industry") or "").lower()
        total_income = revenue + other_income

        if total_income != 0:
            rows.append({
                "label": "Revenue" if not is_npo else "Income",
                "amount": total_income
            })

        if uses_cogs and cogs != 0:
            rows.append({"label": "Cost of Sales", "amount": cogs})
            gross = total_income + cogs
            rows.append({"label": "Gross Profit", "amount": gross})
        else:
            gross = total_income

        if expenses != 0:
            rows.append({"label": "Operating Expenses", "amount": expenses})

        operating_profit = gross + expenses
        label_profit = "Net Profit" if not is_npo else "Surplus / (Deficit)"
        rows.append({"label": label_profit, "amount": operating_profit})

        return rows


    def get_bs_mini(
        self,
        company_id: int,
        as_of: Optional[date] = None,
        *,
        use_meta_when_no_date: bool = True,
    ) -> List[Dict[str, Any]]:
        """
        Compact BS summary for mini card.

        Rules:
        - Assets use debit-credit sign
        - Liabilities/equity use credit-debit sign
        - Negative cash/bank balances are presented as overdraft liabilities
        - Current-year P&L is folded into equity
        """

        if as_of:
            tb_rows = self.get_trial_balance(company_id, None, as_of) or []
        else:
            if use_meta_when_no_date and hasattr(self, "get_trial_balance_with_meta"):
                tb_rows = self.get_trial_balance_with_meta(company_id) or []
            else:
                tb_rows = self.get_trial_balance(company_id, None, None) or []

        assets = 0.0
        liabilities = 0.0
        equity = 0.0
        current_year_pnl = 0.0

        for r in tb_rows:
            kind = ac._classify_tb_row(r)

            code = str(r.get("code") or r.get("account") or "").strip()
            fam = str(r.get("code_family") or "").upper().strip()
            name = str(r.get("name") or "").lower()

            raw = float(
                r.get("closing_balance_raw")
                if r.get("closing_balance_raw") is not None
                else r.get("closing_balance")
                or 0.0
            )

            is_cash = (
                fam == "BS_CA"
                or code == "BS_CA_1000"
                or "cash" in name
                or "bank" in name
            )

            # Reclass negative cash to overdraft liability
            if kind == "asset" and is_cash and raw < 0:
                liabilities += abs(raw)
                continue

            if kind == "asset":
                assets += float(ac._bs_signed_amount(kind, r))
                continue

            if kind == "liability":
                liabilities += float(ac._bs_signed_amount(kind, r))
                continue

            if kind == "equity":
                equity += float(ac._bs_signed_amount(kind, r))
                continue

            if kind in ("revenue", "cogs", "expense", "other"):
                # TB convention is debit-credit:
                # positive = loss, negative = profit
                current_year_pnl += raw

        # net loss reduces equity; net profit increases equity
        equity -= current_year_pnl

        assets = round(assets, 2)
        liabilities = round(liabilities, 2)
        equity = round(equity, 2)

        return [
            {"section": "asset", "label": "Total Assets", "amount": assets},
            {"section": "liability", "label": "Total Liabilities", "amount": liabilities},
            {"section": "equity", "label": "Total Equity", "amount": equity},
            {
                "section": "check",
                "label": "Assets - (Liabilities + Equity)",
                "amount": round(assets - (liabilities + equity), 2),
            },
        ]

    def requires_notes(self, account_code: str) -> bool:
        """
        Simple rule: which accounts automatically get note disclosures.
        You can refine later. For now, receivables/provisions/leases.
        """
        return (
            account_code.startswith("17")
            or account_code.startswith("21")
            or account_code.startswith("26")
        )



    # --------------------------
    # LEASE PERSISTENCE (IFRS 16)
    # ---------------------------
    def insert_lease(
        self,
        company_id: int,
        result: "LeaseScheduleResult",
        *,
        lessor_id: int,
        engagement_company_id: int | None = None,
        engagement_id: int | None = None,
        created_by_user_id: int | None = None,
    ) -> int:
        """
        Persist lease master + schedule into company_{id}.leases and company_{id}.lease_schedule.
        Returns lease_id.
        """
        schema = f"company_{company_id}"
        lease = result.lease_input

        with self._conn_cursor() as (conn, cur):
            # Insert master lease row
            cur.execute(
                f"""
                INSERT INTO {schema}.leases (
                    company_id,
                    lessor_id,
                    lease_name,
                    role,
                    start_date,
                    end_date,
                    payment_amount,
                    payment_frequency,
                    payment_timing,
                    annual_rate,
                    initial_direct_costs,
                    residual_value,
                    vat_rate,
                    opening_lease_liability,
                    opening_rou_asset
                )
                VALUES (
                    %(company_id)s,
                    %(lessor_id)s,
                    %(lease_name)s,
                    %(role)s,
                    %(start_date)s,
                    %(end_date)s,
                    %(payment_amount)s,
                    %(payment_frequency)s,
                    %(payment_timing)s,
                    %(annual_rate)s,
                    %(initial_direct_costs)s,
                    %(residual_value)s,
                    %(vat_rate)s,
                    %(opening_lease_liability)s,
                    %(opening_rou_asset)s
                )
                RETURNING id;
                """,
                {
                    "company_id": int(company_id),
                    "lessor_id": int(lessor_id),
                    "lease_name": lease.lease_name,
                    "role": lease.role,
                    "start_date": lease.start_date,
                    "end_date": lease.end_date,
                    "payment_amount": lease.payment_amount,
                    "payment_frequency": lease.payment_frequency,
                    "payment_timing": lease.payment_timing,
                    "annual_rate": lease.annual_rate,
                    "initial_direct_costs": lease.initial_direct_costs,
                    "residual_value": lease.residual_value,
                    "vat_rate": lease.vat_rate,
                    "opening_lease_liability": result.opening_lease_liability,
                    "opening_rou_asset": result.opening_rou_asset,
                },
            )

            lease_id_row = cur.fetchone()
            lease_id = lease_id_row["id"] if isinstance(lease_id_row, dict) else lease_id_row[0]

            version_no = 1
            for p in result.periods:
                cur.execute(
                    f"""
                    INSERT INTO {schema}.lease_schedule (
                        lease_id,
                        company_id,
                        version_no,
                        is_active,
                        modification_id,
                        period_no,
                        period_start,
                        period_end,
                        opening_liability,
                        interest,
                        payment,
                        principal,
                        closing_liability,
                        depreciation,
                        vat_portion,
                        net_payment,
                        payment_timing
                    )
                    VALUES (
                        %(lease_id)s,
                        %(company_id)s,
                        %(version_no)s,
                        %(is_active)s,
                        %(modification_id)s,
                        %(period_no)s,
                        %(period_start)s,
                        %(period_end)s,
                        %(opening_liability)s,
                        %(interest)s,
                        %(payment)s,
                        %(principal)s,
                        %(closing_liability)s,
                        %(depreciation)s,
                        %(vat_portion)s,
                        %(net_payment)s,
                        %(payment_timing)s
                    )
                    """,
                    {
                        "lease_id": int(lease_id),
                        "company_id": int(company_id),
                        "version_no": int(version_no),
                        "is_active": True,
                        "modification_id": None,
                        "period_no": p.period_no,
                        "period_start": p.period_start,
                        "period_end": p.period_end,
                        "opening_liability": p.opening_liability,
                        "interest": p.interest,
                        "payment": p.payment,
                        "principal": p.principal,
                        "closing_liability": p.closing_liability,
                        "depreciation": p.depreciation,
                        "vat_portion": p.vat_portion,
                        "net_payment": p.net_payment,
                        "payment_timing": lease.payment_timing,
                    },
                )

            if engagement_company_id and engagement_id:
                self.upsert_engagement_posting_activity(
                    cur,
                    company_id=int(engagement_company_id),
                    engagement_id=int(engagement_id),
                    posting_date=lease.start_date,
                    module_name="leases",
                    event_type="draft",
                    reference_no=f"LEASE-{lease_id}",
                    description=f"Lease created - {lease.lease_name}",
                    prepared_by_user_id=created_by_user_id,
                    reviewer_user_id=None,
                    status="draft",
                    amount=float(result.opening_lease_liability or 0.0),
                    currency_code="USD",
                    source_table="leases",
                    source_id=int(lease_id),
                    notes="Lease master and initial schedule created",
                    created_by_user_id=created_by_user_id,
                    updated_by_user_id=created_by_user_id,
                )
                
            return lease_id


    def post_lease_direct_cost_paid(
        self,
        *,
        company_id: int,
        lease_id: int,
        payment_date,
        bank_account_id: int,
        amount: float,
        vat_rate: float = 0.0,
        rou_asset_account: str = "BS_NCA_1610",
        reference: str | None = None,
        description: str | None = None,
        user_id: int | None = None,
    ):
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            try:
                # 1) Validate lease exists
                cur.execute(
                    f"""
                    SELECT id, lease_name
                    FROM {schema}.leases
                    WHERE id = %s
                    """,
                    (lease_id,),
                )
                lease = cur.fetchone()
                if not lease:
                    raise ValueError("Lease not found")

                lease_name = lease.get("lease_name") if isinstance(lease, dict) else lease[1]

                # 2) Validate bank account + linked ledger account
                cur.execute(
                    f"""
                    SELECT id, bank_name, account_name, ledger_account_code
                    FROM {schema}.company_bank_accounts
                    WHERE id = %s
                    """,
                    (bank_account_id,),
                )
                bank = cur.fetchone()
                if not bank:
                    raise ValueError("Bank account not found")

                bank_gl = bank.get("ledger_account_code") if isinstance(bank, dict) else bank[3]
                if not bank_gl:
                    raise ValueError("Selected bank account is not linked to a ledger account")

                gross = Decimal(str(amount or 0)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                if gross <= 0:
                    raise ValueError("Amount must be greater than zero")

                rate = Decimal(str(vat_rate or 0))
                # Frontend passes 0.15, not 15
                if rate > 1:
                    rate = rate / Decimal("100")

                if rate > 0:
                    net = (gross / (Decimal("1.0") + rate)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                    vat = (gross - net).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                else:
                    net = gross
                    vat = Decimal("0.00")

                je_desc = description or f"Lease initial direct cost paid - {lease_name}"
                je_ref = (reference or "").strip() or f"LEASE-DC-{lease_id}"

                lines = [
                    {
                        "account_code": rou_asset_account or "BS_NCA_1610",
                        "debit": float(net),
                        "credit": 0.0,
                        "memo": f"{je_desc} - ROU asset component",
                    }
                ]

                if vat > 0:
                    lines.append({
                        "account_code": "BS_CA_1410",
                        "debit": float(vat),
                        "credit": 0.0,
                        "memo": f"{je_desc} - VAT input",
                    })

                lines.append({
                    "account_code": bank_gl,
                    "debit": 0.0,
                    "credit": float(gross),
                    "memo": f"{je_desc} - paid from bank",
                })

                entry = {
                    "date": payment_date.isoformat() if hasattr(payment_date, "isoformat") else str(payment_date),
                    "ref": je_ref,
                    "description": je_desc,
                    "source": "lease_direct_cost_paid",
                    "source_id": int(lease_id),
                    "created_by_user_id": user_id,
                    "updated_by_user_id": user_id,
                    "gross_amount": float(gross),
                    "currency": "USD",
                    "lines": lines,
                }

                journal_id = self.post_journal_with_overdraft(company_id, entry)

                # Optional but recommended:
                # store capture status back on lease if columns exist
                try:
                    cur.execute(
                        f"""
                        UPDATE {schema}.leases
                        SET
                            direct_cost_capture_status = %s,
                            direct_cost_capture_journal_id = %s,
                            direct_cost_capture_bank_account_id = %s,
                            updated_at = NOW()
                        WHERE id = %s
                        """,
                        ("paid", journal_id, bank_account_id, lease_id),
                    )
                except Exception:
                    # ignore if columns do not exist yet
                    pass

                conn.commit()

                return {
                    "lease_id": int(lease_id),
                    "journal_id": int(journal_id),
                    "bank_account_id": int(bank_account_id),
                    "bank_gl_account_code": bank_gl,
                    "gross_amount": float(gross),
                    "net_amount": float(net),
                    "vat_amount": float(vat),
                    "status": "paid",
                }

            except Exception:
                conn.rollback()
                raise

    def list_lease_schedule_for_month(self, company_id: int, as_of: date, cur=None):
        schema = f"company_{company_id}"

        month_start = as_of.replace(day=1)
        if month_start.month == 12:
            next_month_start = month_start.replace(year=month_start.year + 1, month=1, day=1)
        else:
            next_month_start = month_start.replace(month=month_start.month + 1, day=1)

        has_posted_cols = bool(self.fetch_one(
            """
            SELECT 1
            FROM information_schema.columns
            WHERE table_schema=%s
            AND table_name='lease_schedule'
            AND column_name IN ('posted_journal_id','posted_at')
            LIMIT 1
            """,
            (schema,),
            cur=cur,
        ))

        posted_expr = (
            "COALESCE(s.posted_journal_id, 0) > 0"
            if has_posted_cols
            else f"""EXISTS (
                SELECT 1
                FROM {schema}.journal j
                WHERE j.source = 'lease_monthly'
                AND j.source_id = s.id
            )"""
        )

        sql = f"""
        SELECT
            s.id AS schedule_id,
            s.company_id,
            s.lease_id,
            s.period_no,
            s.period_start,
            s.period_end,
            s.interest,
            s.principal,
            s.payment,
            s.depreciation,
            s.vat_portion,
            s.net_payment,

            l.lease_name,
            l.lessor_id,
            ls.name AS lessor_name,

            {posted_expr} AS posted,

        EXISTS (
            SELECT 1
            FROM {schema}.lease_payments p
            WHERE p.company_id = s.company_id
            AND p.lease_id = s.lease_id
            AND p.schedule_id = s.id
            AND COALESCE(p.status, '') IN ('draft','posted')
        ) AS paid,

        (
            SELECT p.id
            FROM {schema}.lease_payments p
            WHERE p.company_id = s.company_id
            AND p.lease_id = s.lease_id
            AND p.schedule_id = s.id
            ORDER BY p.id DESC
            LIMIT 1
        ) AS payment_id,

        (
            SELECT p.status
            FROM {schema}.lease_payments p
            WHERE p.company_id = s.company_id
            AND p.lease_id = s.lease_id
            AND p.schedule_id = s.id
            ORDER BY p.id DESC
            LIMIT 1
        ) AS payment_status,

        (
            SELECT p.posted_journal_id
            FROM {schema}.lease_payments p
            WHERE p.company_id = s.company_id
            AND p.lease_id = s.lease_id
            AND p.schedule_id = s.id
            ORDER BY p.id DESC
            LIMIT 1
        ) AS payment_journal_id

        FROM {schema}.lease_schedule s
        JOIN {schema}.leases l
            ON l.id = s.lease_id
        AND l.company_id = %s
        LEFT JOIN {schema}.lessors ls
            ON ls.id = l.lessor_id
        WHERE s.company_id = %s
        AND COALESCE(s.is_active, TRUE) = TRUE
        AND s.period_end >= %s
        AND s.period_end < %s
        ORDER BY s.period_end ASC, l.id ASC
        """

        return self.fetch_all(
            sql,
            (int(company_id), int(company_id), month_start, next_month_start),
            cur=cur
        )

    def build_monthly_lease_journal_lines(
        self,
        company_id: int,
        *,
        lease_id: int,
        schedule_id: int,
        cur=None,
    ):
        schema = f"company_{company_id}"

        s = self.fetch_one(
            f"""
            SELECT
                s.*,
                l.lease_name,
                l.bank_account_code,
                l.post_payment
            FROM {schema}.lease_schedule s
            JOIN {schema}.leases l ON l.id = s.lease_id
            WHERE s.id=%s AND s.lease_id=%s
            """,
            (int(schedule_id), int(lease_id)),
            cur=cur,
        )
        if not s:
            return []

        def _resolve_posting_code(candidate: str | None) -> str | None:
            cand = (candidate or "").strip()
            if not cand:
                return None

            # ✅ FIX: get_account_row_for_posting does not take cur=
            row = self.get_account_row_for_posting(company_id, cand)

            if not row:
                return None

            # row is a tuple from get_account_row_for_posting
            return (row[1] if not isinstance(row, dict) else row.get("code"))

        # ensure defaults exist
        self.ensure_company_account_settings(company_id)
        self.ensure_company_lease_defaults(company_id)

        settings = self.fetch_one(
            """
            SELECT
                lease_liability_current_code,
                lease_liability_non_current_code,
                lease_interest_expense_code,
                lease_amortization_code,
                lease_accumulated_depreciation_code
            FROM public.company_account_settings
            WHERE company_id=%s
            LIMIT 1;
            """,
            (int(company_id),),
            cur=cur,
        ) or {}

        liab_cur = _resolve_posting_code(settings.get("lease_liability_current_code"))
        liab_non = _resolve_posting_code(settings.get("lease_liability_non_current_code")) or liab_cur
        int_exp  = _resolve_posting_code(settings.get("lease_interest_expense_code"))
        depr_exp = _resolve_posting_code(settings.get("lease_amortization_code"))
        acc_depr = _resolve_posting_code(settings.get("lease_accumulated_depreciation_code"))

        interest     = float(s.get("interest") or 0.0)
        depreciation = float(s.get("depreciation") or 0.0)
        period_no    = int(s.get("period_no") or 0)

        missing = []
        if interest > 0:
            if not int_exp:
                missing.append("lease_interest_expense_code")
            if not (liab_non or liab_cur):
                missing.append("lease_liability_non_current_code")
                
        if depreciation > 0:
            if not depr_exp: missing.append("lease_amortization_code")
            if not acc_depr: missing.append("lease_accumulated_depreciation_code")

        if missing:
            raise ValueError("LEASE_ACCOUNTS_MISSING|" + ",".join(sorted(set(missing))))

        lines = []

        line_meta = {
            "source": "leases",
            "source_id": int(lease_id),
        }

        # Interest accrual
        if interest > 0:
            amt = round(interest, 2)

            lines.append({
                "account_code": int_exp,
                "debit": amt,
                "credit": 0.0,
                "memo": f"IFRS16 interest – P{period_no}",
                **line_meta,
            })

            lines.append({
                "account_code": liab_cur,
                "debit": 0.0,
                "credit": amt,
                "memo": f"IFRS16 interest accrual – P{period_no}",
                **line_meta,
            })

        # Depreciation
        if depreciation > 0:
            amt = round(depreciation, 2)
            lines.append({
                "account_code": depr_exp,
                "debit": amt,
                "credit": 0.0,
                "memo": f"ROU depreciation – P{period_no}",
                **line_meta,
            })       

            lines.append({
                "account_code": acc_depr,
                "debit": 0.0,
                "credit": amt,
                "memo": f"Accum dep (ROU) – P{period_no}",
                **line_meta,
            })

        return [ln for ln in lines if (ln.get("debit") or 0) != 0 or (ln.get("credit") or 0) != 0]

    def delete_lease(self, company_id: int, lease_id: int) -> None:
        schema = self.company_schema(company_id)
        with self._conn_cursor() as (conn, cur):
            cur.execute(
                f"DELETE FROM {schema}.lease_schedule WHERE lease_id = %s",
                (int(lease_id),),
            )
            cur.execute(
                f"DELETE FROM {schema}.leases WHERE id = %s",
                (int(lease_id),),
            )
            
    def get_lease_posting_accounts(self, company_id: int, cur=None) -> dict:
        self.ensure_company_account_settings(company_id)
