    def pos_create_shift_schedule(
        self,
        company_id: int,
        *,
        employee_user_id: int,
        work_date: str,
        shift_template_id: int | None = None,
        schedule_status: str = "scheduled",
        notes: str | None = None,
    ) -> dict:
        schema = self.company_schema(company_id)

        shift_template_id = None if not shift_template_id else int(shift_template_id)

        return self.fetch_one(f"""
            INSERT INTO {schema}.pos_shift_schedule
            (
                company_id,
                employee_user_id,
                shift_template_id,
                work_date,
                schedule_status,
                notes
            )
            VALUES (%s, %s, %s, %s, %s, %s)
            RETURNING
                id,
                company_id,
                employee_user_id,
                shift_template_id,
                work_date::text AS work_date,
                schedule_status,
                notes,
                is_active,
                deleted_at,
                created_at
        """, (
            int(company_id),
            int(employee_user_id),
            shift_template_id,
            work_date,
            schedule_status or "scheduled",
            notes,
        ))

    def pos_list_shift_schedule(
        self,
        company_id: int,
        *,
        start_date: str | None = None,
        end_date: str | None = None,
        employee_user_id: int | None = None,
    ) -> list[dict]:
        schema = self.company_schema(company_id)

        where = ["s.company_id = %s", "COALESCE(s.is_active, TRUE) = TRUE"]
        params = [int(company_id)]

        if start_date:
            where.append("s.work_date >= %s")
            params.append(start_date)

        if end_date:
            where.append("s.work_date <= %s")
            params.append(end_date)

        if employee_user_id:
            where.append("s.employee_user_id = %s")
            params.append(int(employee_user_id))

        return self.fetch_all(f"""
            SELECT
                s.*,
                t.shift_name,
                t.start_time::text AS start_time,
                t.end_time::text AS end_time
            FROM {schema}.pos_shift_schedule s
            LEFT JOIN {schema}.pos_shift_templates t
                ON t.id = s.shift_template_id
            WHERE {" AND ".join(where)}
            ORDER BY s.work_date, s.employee_user_id
        """, tuple(params))

    def pos_update_shift_schedule(
        self,
        company_id: int,
        schedule_id: int,
        *,
        employee_user_id: int,
        work_date: str,
        shift_template_id: int | None = None,
        schedule_status: str = "scheduled",
        notes: str | None = None,
    ) -> dict:
        schema = self.company_schema(company_id)

        shift_template_id = None if not shift_template_id else int(shift_template_id)

        return self.fetch_one(f"""
            UPDATE {schema}.pos_shift_schedule
            SET employee_user_id = %s,
                shift_template_id = %s,
                work_date = %s,
                schedule_status = %s,
                notes = %s
            WHERE company_id = %s AND id = %s
            RETURNING
                id,
                company_id,
                employee_user_id,
                shift_template_id,
                work_date::text AS work_date,
                schedule_status,
                notes,
                is_active,
                deleted_at,
                created_at
        """, (
            int(employee_user_id),
            shift_template_id,
            work_date,
            schedule_status or "scheduled",
            notes,
            int(company_id),
            int(schedule_id),
        ))

    def pos_delete_shift_schedule(self, company_id: int, schedule_id: int) -> dict:
        schema = self.company_schema(company_id)

        return self.fetch_one(f"""
            DELETE FROM {schema}.pos_shift_schedule
            WHERE company_id = %s AND id = %s
            RETURNING *
        """, (
            int(company_id),
            int(schedule_id),
        ))

    def pos_clock_in_staff(
        self,
        company_id: int,
        *,
        employee_user_id: int,
        schedule_id: int | None = None,
        notes: str | None = None,
    ) -> dict:
        schema = self.company_schema(company_id)
        schedule_id = None if not schedule_id else int(schedule_id)

        existing = self.fetch_one(f"""
            SELECT *
            FROM {schema}.pos_staff_attendance
            WHERE company_id = %s
            AND employee_user_id = %s
            AND status = 'clocked_in'
            ORDER BY clock_in_at DESC
            LIMIT 1
        """, (int(company_id), int(employee_user_id)))

        if existing:
            return existing

        return self.fetch_one(f"""
            INSERT INTO {schema}.pos_staff_attendance
            (company_id, employee_user_id, schedule_id, clock_in_at, status, notes)
            VALUES (%s, %s, %s, NOW(), 'clocked_in', %s)
            RETURNING
                id,
                company_id,
                employee_user_id,
                schedule_id,
                clock_in_at::text AS clock_in_at,
                clock_out_at::text AS clock_out_at,
                status,
                late_minutes,
                notes,
                created_at::text AS created_at
        """, (
            int(company_id),
            int(employee_user_id),
            schedule_id,
            notes,
        ))


    def pos_clock_out_staff(
        self,
        company_id: int,
        *,
        employee_user_id: int,
        attendance_id: int | None = None,
        notes: str | None = None,
    ) -> dict:
        schema = self.company_schema(company_id)

        where = ["company_id = %s", "employee_user_id = %s", "status = 'clocked_in'"]
        params = [int(company_id), int(employee_user_id)]

        if attendance_id:
            where.append("id = %s")
            params.append(int(attendance_id))

        params.extend([notes, int(company_id), int(employee_user_id)])

        return self.fetch_one(f"""
            UPDATE {schema}.pos_staff_attendance
            SET clock_out_at = NOW(),
                status = 'clocked_out',
                notes = COALESCE(%s, notes)
            WHERE id = (
                SELECT id
                FROM {schema}.pos_staff_attendance
                WHERE {" AND ".join(where)}
                ORDER BY clock_in_at DESC
                LIMIT 1
            )
            RETURNING
                id,
                company_id,
                employee_user_id,
                schedule_id,
                clock_in_at::text AS clock_in_at,
                clock_out_at::text AS clock_out_at,
                status,
                late_minutes,
                notes,
                created_at::text AS created_at
        """, tuple(params))


    def pos_list_staff_attendance(
        self,
        company_id: int,
        *,
        start_date: str | None = None,
        end_date: str | None = None,
        employee_user_id: int | None = None,
        status: str = "",
    ) -> list[dict]:
        schema = self.company_schema(company_id)

        where = ["a.company_id = %s"]
        params = [int(company_id)]

        if start_date:
            where.append("a.clock_in_at::date >= %s")
            params.append(start_date)

        if end_date:
            where.append("a.clock_in_at::date <= %s")
            params.append(end_date)

        if employee_user_id:
            where.append("a.employee_user_id = %s")
            params.append(int(employee_user_id))

        if status:
            where.append("a.status = %s")
            params.append(status)

        return self.fetch_all(f"""
            SELECT
                a.id,
                a.company_id,
                a.employee_user_id,
                a.schedule_id,
                a.clock_in_at::text AS clock_in_at,
                a.clock_out_at::text AS clock_out_at,
                a.status,
                a.late_minutes,
                a.notes,
                a.created_at::text AS created_at,
                s.work_date::text AS work_date,
                t.shift_name,
                t.start_time::text AS start_time,
                t.end_time::text AS end_time
            FROM {schema}.pos_staff_attendance a
            LEFT JOIN {schema}.pos_shift_schedule s
                ON s.id = a.schedule_id
            LEFT JOIN {schema}.pos_shift_templates t
                ON t.id = s.shift_template_id
            WHERE {" AND ".join(where)}
            ORDER BY a.clock_in_at DESC
        """, tuple(params))

