    # CUSTOMERS (per-company)
    # ---------------------------
    def insert_customer(self, company_id: int, data: Dict[str, Any]) -> int:
        schema = f"company_{company_id}"
       # self.ensure_company_schema(company_id)

        sql = f"""
        INSERT INTO {schema}.customers (
            company_id,              -- ✅ ADD
            external_code,
            name,
            email,
            phone,
            billing_address,
            shipping_address,
            country,
            billing_country,
            tax_number,
            vat_number,
            registration_no,
            tax_exempt,
            wht_percent,
            payment_terms,
            credit_limit,
            credit_status,
            customer_type,
            default_service,
            on_hold,
            notes,
            tags,
            contacts,
            is_active,
            approved_by_user_id,
            approved_at
        )
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
        RETURNING id;
        """

        def pick(*keys, default=None):
            for k in keys:
                v = data.get(k)
                if v not in (None, ""):
                    return v
            return default

        params = (
            company_id,  # ✅ ADD (matches company_id column)

            pick("external_code", "externalCode"),
            pick("name"),
            pick("email"),
            pick("phone"),
            pick("billAddr", "billing_address", "billingAddress"),
            pick("shipAddr", "shipping_address", "shippingAddress"),
            pick("country"),
            pick("billCountry", "billing_country", "billingCountry"),
            pick("taxNo", "tax_number", "taxNumber"),
            pick("vatNo", "vat_number", "vatNumber"),
            pick("regNo", "registration_no", "registrationNo"),
            pick("taxExempt", "tax_exempt", "taxExempt"),
            (float(pick("wht", "wht_percent", "whtPercent"))
            if pick("wht", "wht_percent", "whtPercent") not in (None, "") else None),
            pick("terms", "payment_terms", "paymentTerms"),
            float(pick("creditLimit", "credit_limit", "creditLimit", default=0) or 0),
            pick("credit_status", "creditStatus", default="draft") or "draft",
            pick("type", "customer_type", "customerType"),
            pick("service", "default_service", "defaultService"),
            pick("onHold", "on_hold", "onHold"),
            pick("notes"),
            pick("tags"),
            psycopg2.extras.Json(data.get("contacts") or []),
            data.get("is_active", True),
            data.get("approved_by_user_id"),
            data.get("approved_at"),
        )

        return self.execute_sql(sql, params) or 0


    def archive_duplicate_customers(self, company_id: int) -> Dict[str, Any]:
        """
        Archives duplicates by (LOWER(name), LOWER(email)).
        Keeps the newest active record; archives older duplicates.
        """
        schema = f"company_{company_id}"
       # self.ensure_company_schema(company_id)

        # Find duplicates
        find_sql = f"""
        SELECT
            LOWER(COALESCE(name,''))  AS k_name,
            LOWER(COALESCE(email,'')) AS k_email,
            ARRAY_AGG(id ORDER BY is_active DESC, updated_at DESC NULLS LAST, created_at DESC NULLS LAST, id DESC) AS ids
        FROM {schema}.customers
        GROUP BY 1,2
        HAVING COUNT(*) > 1
        AND (LOWER(COALESCE(name,'')) <> '' OR LOWER(COALESCE(email,'')) <> '');
        """

        groups = self.fetch_all(find_sql) or []
        archived = []

        with self._conn_cursor() as (_c, cur):
            for g in groups:
                ids = g["ids"] or []
                if len(ids) < 2:
                    continue

                keep_id = ids[0]
                drop_ids = ids[1:]

                # archive the rest
                cur.execute(
                    f"UPDATE {schema}.customers SET is_active = FALSE, updated_at = NOW() WHERE id = ANY(%s);",
                    (drop_ids,)
                )

                archived.append({"keep": keep_id, "archived": drop_ids})

        return {"groups": len(groups), "actions": archived}


    def update_customer(self, company_id: int, customer_id: int, **fields: Any) -> bool:
        """
        Update a customer.
        Supports BOTH:
        - Frontend/readForm() keys (billAddr, creditLimit, onHold, terms, ...)
        - Backend/API keys (billing_address, credit_limit, on_hold, payment_terms, ...)
        """
        if not fields:
            return True

        schema = f"company_{company_id}"

        column_map = {
            "external_code": "external_code",
            "name": "name",
            "email": "email",
            "phone": "phone",
            "billAddr": "billing_address",
            "shipAddr": "shipping_address",
            "country": "country",
            "billCountry": "billing_country",
            "taxNo": "tax_number",
            "vatNo": "vat_number",
            "regNo": "registration_no",
            "taxExempt": "tax_exempt",
            "wht": "wht_percent",
            "terms": "payment_terms",
            "creditLimit": "credit_limit",
            "credit_status": "credit_status",
            "credit_profile_id": "credit_profile_id",
            "created_by_user_id": "created_by_user_id",
            "approved_by_user_id": "approved_by_user_id",
            "approved_at": "approved_at",
            "pending_reason": "pending_reason",
            "type": "customer_type",
            "service": "default_service",
            "onHold": "on_hold",
            "notes": "notes",
            "tags": "tags",
            "contacts": "contacts",
            "is_active": "is_active",

            "billing_address": "billing_address",
            "shipping_address": "shipping_address",
            "billing_country": "billing_country",
            "tax_number": "tax_number",
            "vat_number": "vat_number",
            "registration_no": "registration_no",
            "tax_exempt": "tax_exempt",
            "wht_percent": "wht_percent",
            "payment_terms": "payment_terms",
            "credit_limit": "credit_limit",
            "customer_type": "customer_type",
            "default_service": "default_service",
            "on_hold": "on_hold",
        }

        numeric_keys = {"wht", "wht_percent", "creditLimit", "credit_limit"}
        int_keys = {"credit_profile_id", "created_by_user_id", "approved_by_user_id"}

        set_clauses: list[str] = []
        params: list[Any] = []

        for key, value in fields.items():
            col = column_map.get(key)
            if not col:
                continue

            # normalize blank strings globally
            if isinstance(value, str):
                value = value.strip()
                if value == "":
                    value = None

            # integer coercions
            if key in int_keys and value is not None:
                value = int(value)

            # numeric coercions
            if key in numeric_keys and value is not None:
                value = float(value)

            if key == "contacts":
                value = psycopg2.extras.Json(value or [])

            if key == "is_active":
                if isinstance(value, str):
                    value = value.strip().lower() not in ("false", "0", "no")
                else:
                    value = bool(value)

            if key in ("onHold", "on_hold") and isinstance(value, str):
                v = value.strip().lower()
                if v in ("true", "1", "yes", "y"):
                    value = "yes"
                elif v in ("false", "0", "no", "n"):
                    value = "no"

            set_clauses.append(f"{col} = %s")
            params.append(value)

        if not set_clauses:
            return True

        set_clauses.append("updated_at = NOW()")

        sql = f"""
        UPDATE {schema}.customers
        SET {', '.join(set_clauses)}
        WHERE id = %s;
        """
        params.append(customer_id)

        with self._conn_cursor() as (_c, cur):
            cur.execute(sql, tuple(params))
            return cur.rowcount > 0


    def list_customers(self, company_id: int, include_inactive: bool = False) -> List[Dict[str, Any]]:
        schema = f"company_{company_id}"

        where_sql = ""
        if not include_inactive:
            where_sql = "WHERE c.is_active = TRUE"

        sql = f"""
            SELECT
                c.*,

                -- ✅ Hydrated / effective values
                COALESCE(NULLIF(BTRIM(c.country), ''), NULLIF(BTRIM(c.billing_country), ''), cmp.country) AS country,
                COALESCE(NULLIF(BTRIM(c.currency), ''), cmp.currency) AS currency,
                COALESCE(NULLIF(BTRIM(c.industry), ''), cmp.industry) AS industry,
                COALESCE(NULLIF(BTRIM(c.sub_industry), ''), cmp.sub_industry) AS sub_industry,
                COALESCE(NULLIF(BTRIM(c.fin_year_start), ''), cmp.fin_year_start) AS fin_year_start,

                -- Optional debugging / traceability
                cmp.id AS linked_company_id,
                cmp.name AS linked_company_name,
                cmp.country AS linked_company_country,
                cmp.currency AS linked_company_currency,
                cmp.industry AS linked_company_industry,
                cmp.sub_industry AS linked_company_sub_industry,
                cmp.fin_year_start AS linked_company_fin_year_start

            FROM {schema}.customers c
            LEFT JOIN public.companies cmp
            ON cmp.id = c.company_master_id
            {where_sql}
            ORDER BY c.name ASC;
        """

        return self.fetch_all(sql)

