    def insert_vendor(self, company_id: int, data: Dict[str, Any]) -> int:
        schema = f"company_{company_id}"

        def pick(*keys, default=None):
            for k in keys:
                v = data.get(k)
                if v not in (None, ""):
                    return v
            return default

        sql = f"""
        INSERT INTO {schema}.vendors (
            company_id,
            external_code,
            name,
            email,
            phone,
            remit_address,
            country,
            tax_number,
            vat_number,
            registration_no,
            wht_percent,
            payment_terms,
            vendor_status,
            on_hold,
            notes,
            tags,
            contacts,
            is_active,
            approved_by_user_id,
            approved_at,

            bank_name,
            branch_code,
            account_name,
            account_number,
            account_type,
            bank_currency,
            swift_code,

            compliance_status,
            compliance_required,
            missing_docs,
            compliance_updated_at
        )
        VALUES (
            %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
            %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
            %s,%s,%s,%s,%s,%s,%s,
            %s,%s,%s,NOW()
        )
        RETURNING id;
        """

        # numbers
        wht_raw = pick("wht", "wht_percent", "whtPercent")
        wht_val = float(wht_raw) if wht_raw not in (None, "") else None

        # normalize text fields
        name = (pick("name") or "").strip()
        email = (pick("email") or "").strip() or None
        phone = (pick("phone") or "").strip() or None
        reg_no = (pick("regNo", "registration_no", "registrationNo") or "").strip() or None

        bank_name = (pick("bank_name", "bankName") or "").strip() or None
        branch_code = (pick("branch_code", "branchCode") or "").strip() or None
        account_name = (pick("account_name", "accountName") or "").strip() or None
        account_number = (pick("account_number", "accountNumber") or "").strip() or None
        account_type = (pick("account_type", "accountType") or "").strip() or None
        bank_currency = (pick("bank_currency", "bankCurrency") or "").strip() or None
        swift_code = (pick("swift_code", "swiftCode") or "").strip() or None

        compliance_status = (pick("compliance_status", default="draft") or "draft").strip().lower()
        compliance_required = bool(pick("compliance_required", default=False))
        missing_docs = data.get("missing_docs") or []

        params = (
            int(company_id),
            pick("external_code", "externalCode"),
            name,
            email,
            phone,
            pick("remitAddr", "remit_address", "remitAddress"),
            pick("country", default="ZA"),
            pick("taxNo", "tax_number", "taxNumber"),
            pick("vatNo", "vat_number", "vatNumber"),
            reg_no,
            wht_val,
            pick("terms", "payment_terms", "paymentTerms"),
            (pick("vendor_status", "vendorStatus", default="active") or "active"),
            pick("onHold", "on_hold", default="no"),
            pick("notes", default=""),
            pick("tags", default=""),
            psycopg2.extras.Json(data.get("contacts") or []),
            bool(data.get("is_active", True)),
            data.get("approved_by_user_id"),
            data.get("approved_at"),

            bank_name,
            branch_code,
            account_name,
            account_number,
            account_type,
            bank_currency,
            swift_code,

            compliance_status,
            compliance_required,
            psycopg2.extras.Json(missing_docs),
        )

        row = self.fetch_one(sql, params) or {}
        return int(row.get("id") or 0)


    def update_vendor(self, company_id: int, vendor_id: int, **fields: Any) -> bool:
        if not fields:
            return True

        schema = f"company_{company_id}"

        column_map = {
            "external_code": "external_code",
            "externalCode": "external_code",
            "name": "name",
            "email": "email",
            "phone": "phone",
            "remitAddr": "remit_address",
            "remit_address": "remit_address",
            "country": "country",
            "taxNo": "tax_number",
            "tax_number": "tax_number",
            "vatNo": "vat_number",
            "vat_number": "vat_number",
            "regNo": "registration_no",
            "registration_no": "registration_no",
            "wht": "wht_percent",
            "wht_percent": "wht_percent",
            "terms": "payment_terms",
            "payment_terms": "payment_terms",
            "vendor_status": "vendor_status",
            "vendorStatus": "vendor_status",
            "onHold": "on_hold",
            "on_hold": "on_hold",
            "notes": "notes",
            "tags": "tags",
            "contacts": "contacts",
            "is_active": "is_active",
            "approved_by_user_id": "approved_by_user_id",
            "approved_at": "approved_at",

            "bank_name": "bank_name",
            "bankName": "bank_name",
            "branch_code": "branch_code",
            "branchCode": "branch_code",
            "account_name": "account_name",
            "accountName": "account_name",
            "account_number": "account_number",
            "accountNumber": "account_number",
            "account_type": "account_type",
            "accountType": "account_type",
            "bank_currency": "bank_currency",
            "bankCurrency": "bank_currency",
            "swift_code": "swift_code",
            "swiftCode": "swift_code",

            "compliance_status": "compliance_status",
            "complianceStatus": "compliance_status",
            "compliance_required": "compliance_required",
            "complianceRequired": "compliance_required",
            "missing_docs": "missing_docs",
            "missingDocs": "missing_docs",
        }

        set_clauses: list[str] = []
        params: list[Any] = []
        touch_compliance = False

        for key, value in fields.items():
            col = column_map.get(key)
            if not col:
                continue

            if col in ("compliance_status", "compliance_required", "missing_docs"):
                touch_compliance = True

            if col == "approved_by_user_id" and value not in (None, ""):
                value = int(value)

            if col == "wht_percent" and value not in (None, ""):
                value = float(value)

            if col == "contacts":
                value = psycopg2.extras.Json(value or [])

            if col == "missing_docs":
                value = psycopg2.extras.Json(value or [])

            if col == "is_active":
                if isinstance(value, str):
                    value = value.strip().lower() not in ("false", "0", "no", "n")
                else:
                    value = bool(value)

            if col == "compliance_required":
                if isinstance(value, str):
                    value = value.strip().lower() in ("true", "1", "yes", "y")
                else:
                    value = bool(value)

            if col == "compliance_status" and isinstance(value, str):
                value = value.strip().lower()

            if col == "on_hold" and isinstance(value, str):
                v = value.strip().lower()
                value = "yes" if v in ("true", "1", "yes", "y") else "no" if v in ("false", "0", "no", "n") else value

            set_clauses.append(f"{col} = %s")
            params.append(value)

        if not set_clauses:
            return True

        if touch_compliance:
            set_clauses.append("compliance_updated_at = NOW()")

        set_clauses.append("updated_at = NOW()")

        sql = f"""
        UPDATE {schema}.vendors
        SET {', '.join(set_clauses)}
        WHERE id = %s;
        """
        params.append(int(vendor_id))

        with self._conn_cursor() as (_c, cur):
            cur.execute(sql, tuple(params))
            return cur.rowcount > 0

