    def allocate_receipt_to_invoice(self, company_id: int, *, receipt_id: int, invoice_id: int, amount):
        from decimal import Decimal

        schema = self.company_schema(company_id)
        amt = Decimal(str(amount or "0")).quantize(Decimal("0.01"))
        if amt <= Decimal("0.00"):
            raise ValueError("Allocation amount must be > 0")

        # receipt balance
        rb = self.get_receipt_unallocated_balance(company_id, receipt_id)
        if rb <= Decimal("0.00"):
            raise ValueError("Receipt has no unallocated balance")

        if amt > rb:
            raise ValueError(f"Allocation exceeds receipt balance (balance={rb})")

        # invoice outstanding
        inv = self.get_invoice_by_id(company_id, invoice_id)
        if not inv:
            raise ValueError("Invoice not found")

        total = Decimal(str(inv.get("total_amount") or "0")).quantize(Decimal("0.01"))
        inv_paid = Decimal(str(self.get_invoice_allocated_total(company_id, invoice_id) or "0")).quantize(Decimal("0.01"))
        inv_outstanding = (total - inv_paid).quantize(Decimal("0.01"))
        if inv_outstanding <= Decimal("0.00"):
            raise ValueError("Invoice already fully paid")

        if amt > inv_outstanding:
            raise ValueError(f"Allocation exceeds invoice outstanding (outstanding={inv_outstanding})")

        return self.fetch_one(
            f"""
            INSERT INTO {schema}.receipt_allocations (company_id, receipt_id, invoice_id, amount)
            VALUES (%s, %s, %s, %s)
            RETURNING id;
            """,
            (company_id, receipt_id, invoice_id, amt),
        )


