    def update_asset_revaluation(
        self,
        cur,
        company_id: int,
        *,
        revaluation_id: int,
        asset_id: int,
        revaluation_date,
        carrying_amount_before: float,
        fair_value: float,
        carrying_amount_after: float,
        cost_before=None,
        accum_dep_before=None,
        cost_after=None,
        accum_dep_after=None,
        oci_revaluation_surplus: float = 0,
        pnl_revaluation_gain: float = 0,
        pnl_revaluation_loss: float = 0,
        method: str = "gross_restated",
        reason: str = None,
        notes: str = None,
    ):
        schema = self.company_schema(company_id)
        revaluation_change = float(carrying_amount_after or 0) - float(carrying_amount_before or 0)

        cur.execute(f"""
            UPDATE {schema}.asset_revaluations
            SET asset_id = %s,
                revaluation_date = %s,
                carrying_amount_before = %s,
                cost_before = %s,
                accum_dep_before = %s,
                fair_value = %s,
                carrying_amount_after = %s,
                cost_after = %s,
                accum_dep_after = %s,
                revaluation_change = %s,
                oci_revaluation_surplus = %s,
                pnl_revaluation_gain = %s,
                pnl_revaluation_loss = %s,
                method = %s,
                reason = %s,
                notes = %s
            WHERE company_id = %s
            AND id = %s
        """, (
            asset_id,
            revaluation_date,
            carrying_amount_before,
            cost_before,
            accum_dep_before,
            fair_value,
            carrying_amount_after,
            cost_after,
            accum_dep_after,
            revaluation_change,
            oci_revaluation_surplus,
            pnl_revaluation_gain,
            pnl_revaluation_loss,
            method,
            reason,
            notes,
            company_id,
            revaluation_id,
        ))

    def create_full_asset_revaluation_flow(
        self,
        conn,
        company_id: int,
        payload: dict,
        user_id=None,
        cur=None,
        revaluation_id: int | None = None,
    ):
        if cur is None:
            raise ValueError("create_full_asset_revaluation_flow requires an active cursor")

        asset_id = int(payload["asset_id"])

        if revaluation_id:
            self.update_asset_revaluation(
                cur,
                company_id,
                revaluation_id=revaluation_id,
                asset_id=asset_id,
                revaluation_date=payload["revaluation_date"],
                carrying_amount_before=payload.get("carrying_amount_before", 0),
                fair_value=payload.get("fair_value", 0),
                carrying_amount_after=payload.get("carrying_amount_after", 0),
                cost_before=payload.get("cost_before"),
                accum_dep_before=payload.get("accum_dep_before"),
                cost_after=payload.get("cost_after"),
                accum_dep_after=payload.get("accum_dep_after"),
                oci_revaluation_surplus=payload.get("oci_revaluation_surplus", 0),
                pnl_revaluation_gain=payload.get("pnl_revaluation_gain", 0),
                pnl_revaluation_loss=payload.get("pnl_revaluation_loss", 0),
                method=payload.get("method", "gross_restated"),
                reason=payload.get("reason"),
                notes=payload.get("notes"),
            )

            schema = self.company_schema(company_id)
            cur.execute(f"""
                DELETE FROM {schema}.asset_revaluation_valuations
                WHERE company_id = %s
                AND revaluation_id = %s
            """, (company_id, revaluation_id))

        else:
            revaluation_id = self.create_asset_revaluation(
                cur,
                company_id,
                asset_id=asset_id,
                revaluation_date=payload["revaluation_date"],
                carrying_amount_before=payload.get("carrying_amount_before", 0),
                fair_value=payload.get("fair_value", 0),
                carrying_amount_after=payload.get("carrying_amount_after", 0),
                cost_before=payload.get("cost_before"),
                accum_dep_before=payload.get("accum_dep_before"),
                cost_after=payload.get("cost_after"),
                accum_dep_after=payload.get("accum_dep_after"),
                oci_revaluation_surplus=payload.get("oci_revaluation_surplus", 0),
                pnl_revaluation_gain=payload.get("pnl_revaluation_gain", 0),
                pnl_revaluation_loss=payload.get("pnl_revaluation_loss", 0),
                method=payload.get("method", "gross_restated"),
                reason=payload.get("reason"),
                notes=payload.get("notes"),
                created_by=user_id,
            )

        valuation_rows = payload.get("valuations") or []

        for row in valuation_rows:
            valuer_id = row.get("valuer_id")

            if not valuer_id and row.get("valuer_name"):
                valuer_id = self.get_or_create_asset_valuer(
                    cur,
                    company_id,
                    valuer_name=row.get("valuer_name"),
                    valuer_firm=row.get("valuer_firm"),
                    registration_no=row.get("valuer_registration_no"),
                    phone=row.get("phone"),
                    email=row.get("email"),
                    address=row.get("address"),
                    is_external=row.get("valuer_is_external", True),
                    notes=row.get("valuer_notes"),
                    created_by=user_id,
                )

            self.create_asset_revaluation_valuation(
                cur,
                company_id,
                asset_id=asset_id,
                revaluation_id=revaluation_id,
                valuer_id=valuer_id,
                valuer_role=row.get("valuer_role"),
                valuation_date=row.get("valuation_date") or payload["revaluation_date"],
                effective_date=row.get("effective_date"),
                valuer_name=row.get("valuer_name"),
                valuer_firm=row.get("valuer_firm"),
                valuer_registration_no=row.get("valuer_registration_no"),
                valuer_is_external=row.get("valuer_is_external", True),
                valuation_method=row.get("valuation_method"),
                valuation_approach=row.get("valuation_approach"),
                fair_value_hierarchy_level=row.get("fair_value_hierarchy_level"),
                key_assumptions=row.get("key_assumptions"),
                significant_inputs=row.get("significant_inputs"),
                restrictions_on_title=row.get("restrictions_on_title"),
                highest_best_use_same_as_current=row.get("highest_best_use_same_as_current"),
                source_document_id=row.get("source_document_id"),
                report_reference=row.get("report_reference"),
                report_date=row.get("report_date"),
                notes=row.get("notes"),
                created_by=user_id,
            )

        return int(revaluation_id)

    def list_asset_revaluations(self, cur, company_id: int, asset_id: int):
        schema = self.company_schema(company_id)
        cur.execute(f"""
            SELECT
                r.id,
                r.asset_id,
                r.revaluation_date,
                r.carrying_amount_before,
                r.fair_value,
                r.carrying_amount_after,
                r.revaluation_change,
                r.oci_revaluation_surplus,
                r.pnl_revaluation_gain,
                r.pnl_revaluation_loss,
                r.method,
                r.status,
                r.reason,
                r.notes,
                r.posted_journal_id,
                r.posted_at,
                r.created_at
            FROM {schema}.asset_revaluations r
            WHERE r.company_id = %s
            AND r.asset_id = %s
            ORDER BY r.revaluation_date DESC, r.id DESC
        """, (company_id, asset_id))
        return [dict(x) for x in (cur.fetchall() or [])]

