    def get_asset_revaluation_detail(self, cur, company_id: int, revaluation_id: int):
        schema = self.company_schema(company_id)

        cur.execute(f"""
            SELECT
                r.*
            FROM {schema}.asset_revaluations r
            WHERE r.company_id = %s
            AND r.id = %s
            LIMIT 1
        """, (company_id, revaluation_id))
        header = cur.fetchone()
        if not header:
            return None

        cur.execute(f"""
            SELECT
                v.id,
                v.company_id,
                v.asset_id,
                v.revaluation_id,
                v.valuer_id,
                v.valuer_role,
                v.valuation_date,
                v.effective_date,
                v.valuer_name,
                v.valuer_firm,
                v.valuer_registration_no,
                v.valuer_is_external,
                v.valuation_method,
                v.valuation_approach,
                v.fair_value_hierarchy_level,
                v.key_assumptions,
                v.significant_inputs,
                v.restrictions_on_title,
                v.highest_best_use_same_as_current,
                v.source_document_id,
                v.report_reference,
                v.report_date,
                v.notes,
                av.phone AS valuer_phone,
                av.email AS valuer_email,
                av.address AS valuer_address
            FROM {schema}.asset_revaluation_valuations v
            LEFT JOIN {schema}.asset_valuers av
                ON av.id = v.valuer_id
            WHERE v.company_id = %s
            AND v.revaluation_id = %s
            ORDER BY
                CASE v.valuer_role
                    WHEN 'primary_valuer' THEN 1
                    WHEN 'reviewer' THEN 2
                    WHEN 'internal_assessor' THEN 3
                    WHEN 'specialist' THEN 4
                    ELSE 9
                END,
                v.id ASC
        """, (company_id, revaluation_id))

        return {
            "revaluation": dict(header),
            "valuations": [dict(x) for x in (cur.fetchall() or [])]
        }

    def asset_tax_list_runs(self, company_id: int) -> list[dict]:
        schema = self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                r.*,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,
                COUNT(l.id) AS line_count,
                COALESCE(SUM(l.total_capital_allowance), 0) AS total_capital_allowance,
                COALESCE(SUM(l.closing_tax_wdv), 0) AS closing_tax_wdv
            FROM {schema}.asset_tax_runs r
            JOIN public.tax_authorities ta ON ta.id = r.tax_authority_id
            LEFT JOIN {schema}.asset_tax_run_lines l ON l.run_id = r.id
            WHERE r.company_id = %s
            GROUP BY r.id, ta.code, ta.name
            ORDER BY r.tax_year DESC, ta.code
        """, (company_id,))


    def asset_tax_create_run(self, company_id: int, payload: dict) -> dict:
        schema = self.company_schema(company_id)

        tax_authority_id = int(payload.get("tax_authority_id"))
        tax_year = int(payload.get("tax_year"))
        tax_year_start = payload.get("tax_year_start")
        tax_year_end = payload.get("tax_year_end")

        if not tax_year_start or not tax_year_end:
            raise ValueError("tax_year_start and tax_year_end are required")

        return self.fetch_one(f"""
            INSERT INTO {schema}.asset_tax_runs (
                company_id,
                tax_authority_id,
                tax_year,
                tax_year_start,
                tax_year_end,
                status,
                notes
            )
            VALUES (%s,%s,%s,%s,%s,'draft',%s)
            RETURNING *
        """, (
            company_id,
            tax_authority_id,
            tax_year,
            tax_year_start,
            tax_year_end,
            payload.get("notes"),
        ))

    def _asset_tax_classify_asset(self, asset: dict) -> str:
        current = str(asset.get("tax_asset_class") or "").strip().lower()
        if current:
            return current

        text = " ".join(str(asset.get(k) or "") for k in (
            "asset_name", "asset_code", "asset_class",
            "asset_class_group", "category", "accounting_standard"
        )).lower()

        checks = [
            (("right of use", "rou asset", "rou"), "rou_asset"),
            (("investment property",), "investment_property"),
            (("land",), "land"),
            (("building", "property"), "building"),
            (("software", "application", "system"), "software"),
            (("trademark",), "trademark"),
            (("patent",), "patent"),
            (("computer", "laptop", "desktop", "server", "tablet"), "computer"),
            (("motorcycle", "scooter", "vehicle", "car", "bicycle"), "vehicle"),
            (("manufacturing", "production line", "factory equipment"), "manufacturing_equipment"),
            (("warehouse", "forklift", "racking", "shelving"), "warehouse"),
            (("furniture", "fitting"), "furniture"),
            (("office equipment", "photocopier", "printer"), "office_equipment"),
            (("security", "alarm", "camera", "cctv"), "security"),
            (("medical",), "medical_equipment"),
            (("telecom", "telephone", "network"), "telecom_equipment"),
            (("leasehold",), "leasehold_improvement"),
            (("bearer plant",), "bearer_plant"),
            (("biological",), "biological_asset"),
            (("plant", "machinery", "generator", "compressor", "tool"), "plant"),
        ]

        for words, classification in checks:
            if any(word in text for word in words):
                return classification

        return "other"

    def _asset_tax_default_rule(self, cur, authority_id: int, asset: dict, as_at):
        tax_class = self._asset_tax_classify_asset(asset)

        rules = self.fetch_all("""
            SELECT *
            FROM public.tax_allowance_rules
            WHERE tax_authority_id = %s
            AND is_active = TRUE
            AND effective_from <= %s
            AND (effective_to IS NULL OR effective_to >= %s)
            ORDER BY effective_from DESC, id
        """, (authority_id, as_at, as_at), cur=cur) or []

        exact = [r for r in rules if str(r.get("tax_asset_class") or "").lower() == tax_class]
        if exact:
            return exact[0]

        code_map = {
            "land": ("LAND_NON_DEPRECIABLE",),
            "building": ("BUILDINGS_GENERAL_REVIEW", "COMMERCIAL_BUILDING_REVIEW"),
            "computer": ("PERSONAL_COMPUTER", "SERVER", "TABLET"),
            "vehicle": ("PASSENGER_CAR", "DELIVERY_VEHICLE", "MOTORCYCLE", "BICYCLE"),
            "furniture": ("FURNITURE_FITTINGS",),
            "office_equipment": ("OFFICE_EQUIPMENT_ELECTRONIC", "OFFICE_EQUIPMENT_MECHANICAL"),
            "warehouse": ("WAREHOUSE_EQUIPMENT", "FORKLIFTS", "SHELVING_RACKING"),
            "manufacturing_equipment": ("MANUFACTURING_MACHINERY", "FACTORY_EQUIPMENT"),
            "plant": ("GENERATORS", "COMPRESSORS", "TOOLS_HEAVY"),
        }

        for token in code_map.get(tax_class, ()):
            for rule in rules:
                if token in str(rule.get("rule_code") or "").upper():
                    return rule

        return None

    def _asset_tax_bootstrap_opening_wdv(
        self,
        *,
        qualifying_cost,
        tax_start_date,
        run_start_date,
        method,
        annual_rate,
        allowance_pattern=None,
    ):
        D = lambda value: Decimal(str(value or 0))
        q2 = lambda value: D(value).quantize(Decimal("0.01"))

        base = q2(qualifying_cost)
        years = max(
            0,
            run_start_date.year - tax_start_date.year,
        )

        if not years or base <= 0:
            return base

        method = str(method or "").upper()

        if method == "IMMEDIATE":
            return D(0)

        if method == "SL":
            annual = q2(base * D(annual_rate) / D(100))
            return q2(max(D(0), base - annual * years))

        if method == "WDV":
            rate = D(annual_rate) / D(100)

            for _ in range(years):
                base = q2(base - base * rate)

            return max(D(0), base)

        if method == "MULTI_YEAR":
            pattern = allowance_pattern or []

            if isinstance(pattern, str):
                pattern = json.loads(pattern or "[]")

            original_cost = base

            for index in range(years):
                rate = (
                    D(pattern[index])
                    if index < len(pattern)
                    else D(0)
                )

                allowance = min(
                    base,
                    q2(original_cost * rate / D(100)),
                )

                base = q2(base - allowance)

            return max(D(0), base)

        return base

    def asset_tax_calculate_run(self, company_id: int, run_id: int) -> dict:
        from decimal import Decimal, ROUND_HALF_UP
        import json

        schema = self.company_schema(company_id)
        D = lambda value: Decimal(str(value or 0))
        q2 = lambda value: D(value).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )

        with self._conn_cursor() as (conn, cur):
            run = self.fetch_one(f"""
                SELECT *
                FROM {schema}.asset_tax_runs
                WHERE company_id=%s AND id=%s
                LIMIT 1
            """, (company_id, run_id), cur=cur)

            if not run:
                raise ValueError("Tax run not found.")

            if run["status"] == "locked":
                raise ValueError("Cannot recalculate a locked tax run.")

            start_date = run["tax_year_start"]
            end_date = run["tax_year_end"]
            authority_id = int(run["tax_authority_id"])
            tax_year = int(run["tax_year"])

            self.ensure_ppe_reporting_views(cur, company_id)
            self.asset_tax_create_missing_profiles(company_id, cur=cur)

            profiles = self.fetch_all(f"""
                SELECT
                    p.*,
                    a.asset_code,
                    a.asset_name,
                    a.asset_class,
                    a.asset_class_group,
                    a.category,
                    a.accounting_standard,
                    a.tax_asset_class,
                    a.measurement_basis,
                    COALESCE(a.fair_value_model,FALSE) AS fair_value_model,
                    a.acquisition_date,
                    a.available_for_use_date,
                    a.cost AS register_cost,
                    a.opening_cost,
                    COALESCE(a.is_component_group,FALSE) AS is_component_group
                FROM {schema}.asset_tax_profiles p
                JOIN {schema}.assets a
                ON a.id=p.asset_id
                WHERE p.company_id=%s
                AND p.tax_authority_id=%s
                AND p.is_active=TRUE
                AND COALESCE(a.status,'active') NOT IN ('void','cancelled')
                AND COALESCE(a.is_component_group,FALSE)=FALSE
                ORDER BY a.id
            """, (company_id, authority_id), cur=cur) or []

            cur.execute(
                f"DELETE FROM {schema}.asset_tax_run_lines WHERE run_id=%s",
                (run_id,),
            )

            inserted = 0
            review_count = 0

            for p in profiles:
                asset_id = int(p["asset_id"])
                tax_asset_class = self._asset_tax_classify_asset(p)

                if not p.get("tax_asset_class"):
                    cur.execute(f"""
                        UPDATE {schema}.assets
                        SET tax_asset_class=%s
                        WHERE company_id=%s AND id=%s
                    """, (tax_asset_class, company_id, asset_id))

                    p["tax_asset_class"] = tax_asset_class

                # Keep your automatic country-default matching for profiles
                # that have no rule assigned yet.
                if not (
                    p.get("default_rule_id")
                    or p.get("override_rule_id")
                    or p.get("allowance_rule_id")
                ):
                    default_rule = self._asset_tax_default_rule(
                        cur,
                        authority_id,
                        p,
                        end_date,
                    )

                    if default_rule:
                        cur.execute(f"""
                            UPDATE {schema}.asset_tax_profiles
                            SET allowance_rule_id=%s,
                                default_rule_id=%s,
                                override_rule_id=NULL,
                                rule_source='default',
                                is_tax_depreciable=CASE
                                    WHEN UPPER(%s) LIKE '%%LAND_NON_DEPRECIABLE%%'
                                        THEN FALSE
                                    ELSE is_tax_depreciable
                                END,
                                updated_at=NOW()
                            WHERE company_id=%s AND id=%s
                        """, (
                            default_rule["id"],
                            default_rule["id"],
                            default_rule.get("rule_code"),
                            company_id,
                            p["id"],
                        ))

                        p["allowance_rule_id"] = default_rule["id"]
                        p["default_rule_id"] = default_rule["id"]
                        p["override_rule_id"] = None
                        p["rule_source"] = "default"

                rule = self.resolve_asset_tax_rule(
                    company_id,
                    profile=p,
                    asset=p,
                    tax_authority_id=authority_id,
                    as_at=end_date,
                    cur=cur,
                )

                snapshot = self.asset_tax_rule_snapshot(rule)
                configured = rule is not None

                if rule:
                    method = str(rule.get("method") or "CUSTOM").upper()
                    annual_rate = D(
                        rule.get("annual_allowance_percent")
                        or rule.get("rate_percent")
                    )
                    initial_rate = D(
                        rule.get("initial_allowance_percent")
                    )
                    allowance_pattern = rule.get("allowance_pattern") or []
                    rule_code = rule.get("rule_code")
                    rule_name = rule.get("rule_name")
                    default_rule_id = rule.get("default_rule_id")
                    override_rule_id = rule.get("override_rule_id")
                    rule_source = rule.get("rule_source")
                else:
                    method = "CUSTOM"
                    annual_rate = D(0)
                    initial_rate = D(0)
                    allowance_pattern = []
                    rule_code = None
                    rule_name = None
                    default_rule_id = None
                    override_rule_id = None
                    rule_source = None

                movements = self.fetch_one(f"""
                    SELECT
                        COALESCE(SUM(
                            CASE WHEN event_date<=%s
                            THEN carrying_delta ELSE 0 END
                        ),0) AS carrying_amount,

                        COALESCE(SUM(
                            CASE
                                WHEN event_date BETWEEN %s AND %s
                                AND movement_type='depreciation'
                                THEN ABS(carrying_delta)
                                ELSE 0
                            END
                        ),0) AS book_depreciation,

                        COALESCE(SUM(
                            CASE
                                WHEN event_date BETWEEN %s AND %s
                                AND movement_type='subsequent_addition'
                                THEN cost_delta
                                ELSE 0
                            END
                        ),0) AS subsequent_additions,

                        COALESCE(SUM(
                            CASE
                                WHEN event_date<=%s
                                AND movement_type IN (
                                    'revaluation_up',
                                    'revaluation_down'
                                )
                                THEN carrying_delta
                                ELSE 0
                            END
                        ),0) AS revaluation_movement,

                        COALESCE(SUM(
                            CASE
                                WHEN event_date<=%s
                                AND movement_type='impairment_loss'
                                THEN impairment_delta
                                ELSE 0
                            END
                        ),0) AS impairment_losses,

                        COALESCE(SUM(
                            CASE
                                WHEN event_date<=%s
                                AND movement_type='impairment_reversal'
                                THEN ABS(impairment_delta)
                                ELSE 0
                            END
                        ),0) AS impairment_reversals

                    FROM {schema}.vw_ppe_movements
                    WHERE company_id=%s AND asset_id=%s
                """, (
                    end_date,
                    start_date,
                    end_date,
                    start_date,
                    end_date,
                    end_date,
                    end_date,
                    end_date,
                    company_id,
                    asset_id,
                ), cur=cur) or {}

                acquisition = self.fetch_one(f"""
                    SELECT COALESCE(SUM(
                        COALESCE(
                            net_amount
                            + CASE
                                WHEN COALESCE(
                                    nonrecoverable_vat_capitalized,
                                    FALSE
                                )
                                THEN COALESCE(
                                    non_recoverable_vat_amount,
                                    0
                                )
                                ELSE 0
                            END,
                            amount,
                            gross_amount,
                            0
                        )
                    ),0) AS capitalised_cost
                    FROM {schema}.asset_acquisitions
                    WHERE company_id=%s
                    AND asset_id=%s
                    AND status='posted'
                    AND acquisition_date<=%s
                """, (
                    company_id,
                    asset_id,
                    end_date,
                ), cur=cur) or {}

                previous = self.fetch_one(f"""
                    SELECT l.closing_tax_wdv
                    FROM {schema}.asset_tax_run_lines l
                    JOIN {schema}.asset_tax_runs r
                    ON r.id=l.run_id
                    WHERE l.company_id=%s
                    AND l.asset_id=%s
                    AND l.tax_authority_id=%s
                    AND r.tax_year_end<%s
                    AND r.status IN (
                        'calculated',
                        'approved',
                        'locked',
                        'posted'
                    )
                    ORDER BY r.tax_year_end DESC,r.id DESC
                    LIMIT 1
                """, (
                    company_id,
                    asset_id,
                    authority_id,
                    start_date,
                ), cur=cur)

                acquisition_cost = q2(acquisition.get("capitalised_cost"))
                opening_cost = q2(p.get("opening_cost"))
                register_cost = q2(p.get("register_cost"))

                profile_tax_cost = (
                    q2(p.get("tax_cost"))
                    if p.get("tax_cost") is not None
                    else None
                )

                if acquisition_cost > 0:
                    accounting_cost = acquisition_cost
                    tax_cost = acquisition_cost
                    tax_cost_source = "vat_adjusted_acquisition"

                elif opening_cost > 0:
                    accounting_cost = opening_cost
                    tax_cost = (
                        profile_tax_cost
                        if profile_tax_cost is not None
                        else opening_cost
                    )
                    tax_cost_source = (
                        "profile_override"
                        if profile_tax_cost is not None
                        else "opening_balance"
                    )

                else:
                    accounting_cost = register_cost
                    tax_cost = (
                        profile_tax_cost
                        if profile_tax_cost is not None
                        else register_cost
                    )
                    tax_cost_source = (
                        "profile_override"
                        if profile_tax_cost is not None
                        else "asset_register"
                    )

                qualifying_factor = (
                    D(p.get("qualifying_percent") or 100) / D(100)
                )
                business_factor = (
                    D(100) - D(p.get("private_use_percent") or 0)
                ) / D(100)

                qualifying_cost = q2(
                    tax_cost
                    * qualifying_factor
                    * business_factor
                )

                previous_wdv = (
                    (previous or {}).get("closing_tax_wdv")
                )

                tax_start = p.get("tax_start_date")
                available_date = p.get("available_for_use_date")
                acquisition_date = p.get("acquisition_date")

                if tax_start and tax_start > end_date:
                    continue

                first_year = bool(
                    tax_start
                    and start_date <= tax_start <= end_date
                )

                if previous_wdv is None:
                    opening_wdv = Decimal("0.00")
                else:
                    opening_wdv = q2(previous_wdv)

                if previous_wdv is None and tax_start and tax_start < start_date:
                    opening_wdv = self._asset_tax_bootstrap_opening_wdv(
                        qualifying_cost=qualifying_cost,
                        tax_start_date=tax_start,
                        run_start_date=start_date,
                        method=method,
                        annual_rate=annual_rate,
                        allowance_pattern=allowance_pattern,
                    )

                additions = (
                    qualifying_cost
                    if first_year and previous_wdv is None
                    else D(0)
                )

                additions += q2(
                    D(movements.get("subsequent_additions"))
                    * qualifying_factor
                    * business_factor
                )

                depreciable = bool(
                    p.get("is_tax_depreciable")
                ) and configured

                allowance_base = q2(opening_wdv + additions)

                initial_allowance = (
                    q2(additions * initial_rate / D(100))
                    if depreciable
                    else D(0)
                )

                remaining_base = max(
                    D(0),
                    allowance_base - initial_allowance,
                )

                requires_review = not configured

                if not depreciable:
                    annual_allowance = D(0)

                elif method == "IMMEDIATE":
                    annual_allowance = remaining_base

                elif method == "WDV":
                    annual_allowance = q2(
                        remaining_base
                        * annual_rate
                        / D(100)
                    )

                elif method == "SL":
                    annual_allowance = min(
                        q2(
                            qualifying_cost
                            * annual_rate
                            / D(100)
                        ),
                        remaining_base,
                    )

                elif method == "MULTI_YEAR":
                    pattern = allowance_pattern

                    if isinstance(pattern, str):
                        pattern = json.loads(pattern or "[]")

                    tax_start = p.get("tax_start_date")
                    start_year = (
                        tax_start.year
                        if tax_start
                        else tax_year
                    )
                    year_index = max(
                        0,
                        tax_year - start_year,
                    )
                    rate = (
                        D(pattern[year_index])
                        if year_index < len(pattern)
                        else D(0)
                    )

                    annual_allowance = min(
                        q2(
                            qualifying_cost
                            * rate
                            / D(100)
                        ),
                        remaining_base,
                    )

                else:
                    annual_allowance = D(0)
                    requires_review = True

                total_allowance = q2(
                    initial_allowance
                    + annual_allowance
                )
                closing_wdv = q2(
                    max(
                        D(0),
                        allowance_base - total_allowance,
                    )
                )

                carrying_amount = q2(
                    movements.get("carrying_amount")
                )
                book_depreciation = q2(
                    movements.get("book_depreciation")
                )
                temporary_difference = q2(
                    carrying_amount - closing_wdv
                )
                tax_adjustment = q2(
                    book_depreciation - total_allowance
                )

                notes = []

                if not configured:
                    notes.append(
                        "No active allowance rule matched; review required."
                    )

                elif method in {"CUSTOM", ""}:
                    notes.append(
                        f"{rule_name or 'Custom rule'} requires review."
                    )
                    requires_review = True

                if D(movements.get("revaluation_movement")):
                    notes.append(
                        "Accounting revaluation left tax WDV unchanged."
                    )

                if (
                    D(movements.get("impairment_losses"))
                    or D(movements.get("impairment_reversals"))
                ):
                    notes.append(
                        "Accounting impairment left tax WDV unchanged."
                    )

                source_notes = {
                    "vat_adjusted_acquisition": (
                        "Capital-allowance cost derived from the "
                        "VAT-adjusted posted acquisition."
                    ),
                    "profile_override": (
                        "Capital-allowance cost uses the tax-profile override."
                    ),
                    "opening_balance": (
                        "Capital-allowance cost derived from the "
                        "asset opening balance."
                    ),
                    "asset_register": (
                        "Capital-allowance cost derived from the "
                        "asset register."
                    ),
                }

                notes.append(source_notes[tax_cost_source])

                if requires_review:
                    review_count += 1

                cur.execute(f"""
                    INSERT INTO {schema}.asset_tax_run_lines (
                        run_id,
                        company_id,
                        asset_tax_profile_id,
                        asset_id,
                        tax_authority_id,
                        allowance_rule_id,
                        default_rule_id,
                        override_rule_id,
                        rule_source,
                        rule_snapshot,
                        tax_year,
                        opening_tax_wdv,
                        additions,
                        disposal_proceeds,
                        disposal_tax_value,
                        allowance_base,
                        initial_allowance,
                        annual_allowance,
                        total_capital_allowance,
                        closing_tax_wdv,
                        book_depreciation,
                        accounting_carrying_amount,
                        tax_adjustment,
                        temporary_difference,
                        calculation_method,
                        rate_percent,
                        requires_review,
                        notes
                    )
                    VALUES (
                        %s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,
                        %s,%s,%s,0,0,%s,%s,%s,%s,%s,
                        %s,%s,%s,%s,%s,%s,%s,%s
                    )
                """, (
                    run_id,
                    company_id,
                    p["id"],
                    asset_id,
                    authority_id,
                    default_rule_id or p.get("allowance_rule_id"),
                    default_rule_id,
                    override_rule_id,
                    rule_source,
                    json.dumps(snapshot, default=str),
                    tax_year,
                    opening_wdv,
                    additions,
                    allowance_base,
                    initial_allowance,
                    annual_allowance,
                    total_allowance,
                    closing_wdv,
                    book_depreciation,
                    carrying_amount,
                    tax_adjustment,
                    temporary_difference,
                    method or "NONE",
                    annual_rate,
                    requires_review,
                    " ".join(notes),
                ))

                inserted += 1

            cur.execute(f"""
                UPDATE {schema}.asset_tax_runs
                SET status='calculated',
                    calculated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING *
            """, (company_id, run_id))

            updated_run = dict(cur.fetchone())
            conn.commit()

        return {
            "run": updated_run,
            "line_count": inserted,
            "review_count": review_count,
        }

    def _asset_tax_cost_basis(
        self,
        cur,
        *,
        schema: str,
        company_id: int,
        asset_id: int,
        tax_year_end,
    ):
        """
        Returns the asset's tax-cost additions up to the tax year end.

        Tax cost excludes recoverable input VAT and includes only
        non-recoverable VAT that forms part of the asset's cost.
        """
        cur.execute(
            f"""
            SELECT
                aa.id,
                aa.acquisition_date,
                aa.posting_date,
                aa.amount,
                aa.vat_treatment,
                COALESCE(aa.net_amount, 0) AS net_amount,
                COALESCE(aa.gross_amount, 0) AS gross_amount,
                COALESCE(aa.vat_amount, 0) AS vat_amount,
                COALESCE(
                    aa.non_recoverable_vat_amount,
                    0
                ) AS non_recoverable_vat_amount,
                COALESCE(
                    aa.vat_input_claimable,
                    FALSE
                ) AS vat_input_claimable,
                COALESCE(
                    aa.vat_recovery_percent,
                    100
                ) AS vat_recovery_percent,
                COALESCE(
                    aa.nonrecoverable_vat_capitalized,
                    FALSE
                ) AS nonrecoverable_vat_capitalized,
                aa.status
            FROM {schema}.asset_acquisitions aa
            WHERE aa.company_id = %s
            AND aa.asset_id = %s
            AND COALESCE(
                    aa.posting_date,
                    aa.acquisition_date
                ) <= %s
            AND aa.status NOT IN (
                    'void',
                    'reversed'
                )
            ORDER BY
                COALESCE(
                    aa.posting_date,
                    aa.acquisition_date
                ),
                aa.id;
            """,
            (
                int(company_id),
                int(asset_id),
                tax_year_end,
            ),
        )

        acquisitions = cur.fetchall() or []

        total_tax_cost = Decimal("0")
        total_net = Decimal("0")
        total_gross = Decimal("0")
        total_vat = Decimal("0")
        total_recoverable_vat = Decimal("0")
        total_non_recoverable_vat = Decimal("0")
        basis_sources = []

        for acquisition in acquisitions:
            amount = Decimal(str(
                acquisition.get("amount") or 0
            ))

            net_amount = Decimal(str(
                acquisition.get("net_amount") or 0
            ))

            gross_amount = Decimal(str(
                acquisition.get("gross_amount") or 0
            ))

            vat_amount = Decimal(str(
                acquisition.get("vat_amount") or 0
            ))

            non_recoverable_vat = Decimal(str(
                acquisition.get(
                    "non_recoverable_vat_amount"
                ) or 0
            ))

            vat_claimable = bool(
                acquisition.get("vat_input_claimable")
            )

            recovery_percent = Decimal(str(
                acquisition.get(
                    "vat_recovery_percent"
                ) or 0
            ))

            recovery_percent = max(
                Decimal("0"),
                min(Decimal("100"), recovery_percent),
            )

            vat_treatment = str(
                acquisition.get("vat_treatment")
                or "no_vat"
            ).strip().lower()

            # Backward-compatible reconstruction for older acquisitions.
            if gross_amount <= 0:
                if vat_treatment == "exclusive":
                    gross_amount = amount + vat_amount
                else:
                    gross_amount = amount

            if net_amount <= 0:
                if vat_treatment == "inclusive":
                    net_amount = max(
                        Decimal("0"),
                        gross_amount - vat_amount,
                    )
                elif vat_treatment == "exclusive":
                    net_amount = amount
                else:
                    net_amount = amount

            if vat_amount <= 0:
                vat_amount = max(
                    Decimal("0"),
                    gross_amount - net_amount,
                )

            recoverable_vat = Decimal("0")

            if vat_claimable and vat_amount > 0:
                recoverable_vat = (
                    vat_amount
                    * recovery_percent
                    / Decimal("100")
                )

            # Use stored non-recoverable VAT where available.
            if non_recoverable_vat <= 0:
                non_recoverable_vat = max(
                    Decimal("0"),
                    vat_amount - recoverable_vat,
                )

            # Tax cost is net value plus VAT that cannot be recovered.
            tax_cost = (
                net_amount + non_recoverable_vat
            ).quantize(Decimal("0.01"))

            total_tax_cost += tax_cost
            total_net += net_amount
            total_gross += gross_amount
            total_vat += vat_amount
            total_recoverable_vat += recoverable_vat
            total_non_recoverable_vat += (
                non_recoverable_vat
            )

            basis_sources.append({
                "acquisition_id": acquisition.get("id"),
                "vat_treatment": vat_treatment,
                "vat_input_claimable": vat_claimable,
                "vat_recovery_percent":
                    str(recovery_percent),
                "net_amount": str(
                    net_amount.quantize(
                        Decimal("0.01")
                    )
                ),
                "gross_amount": str(
                    gross_amount.quantize(
                        Decimal("0.01")
                    )
                ),
                "vat_amount": str(
                    vat_amount.quantize(
                        Decimal("0.01")
                    )
                ),
                "recoverable_vat": str(
                    recoverable_vat.quantize(
                        Decimal("0.01")
                    )
                ),
                "non_recoverable_vat": str(
                    non_recoverable_vat.quantize(
                        Decimal("0.01")
                    )
                ),
                "tax_cost": str(tax_cost),
            })

        return {
            "tax_cost": total_tax_cost.quantize(
                Decimal("0.01")
            ),
            "net_amount": total_net.quantize(
                Decimal("0.01")
            ),
            "gross_amount": total_gross.quantize(
                Decimal("0.01")
            ),
            "vat_amount": total_vat.quantize(
                Decimal("0.01")
            ),
            "recoverable_vat": (
                total_recoverable_vat
            ).quantize(Decimal("0.01")),
            "non_recoverable_vat": (
                total_non_recoverable_vat
            ).quantize(Decimal("0.01")),
            "basis_source": (
                "asset_acquisitions"
                if acquisitions
                else "asset_register_fallback"
            ),
            "acquisitions": basis_sources,
        }

    def asset_tax_get_run(self, company_id: int, run_id: int) -> dict:
        schema = self.company_schema(company_id)

        run = self.fetch_one(f"""
            SELECT
                r.*,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name
            FROM {schema}.asset_tax_runs r
            JOIN public.tax_authorities ta ON ta.id = r.tax_authority_id
            WHERE r.company_id = %s
            AND r.id = %s
        """, (company_id, run_id))

        if not run:
            raise ValueError("Tax run not found")

        lines = self.fetch_all(f"""
            SELECT
                l.*,
                a.asset_name,
                a.asset_code,
                a.asset_class,
                rr.rule_name,
                rr.rule_code
            FROM {schema}.asset_tax_run_lines l
            JOIN {schema}.assets a ON a.id = l.asset_id
            LEFT JOIN public.tax_allowance_rules rr ON rr.id = l.allowance_rule_id
            WHERE l.run_id = %s
            ORDER BY a.asset_name
        """, (run_id,))

        return {
            "run": run,
            "lines": lines,
        }

    def asset_tax_reconciliation(self, company_id: int, tax_authority_id: int | None = None, tax_year: int | None = None) -> dict:
        schema = self.company_schema(company_id)

        params = [company_id]
        where = ["r.company_id = %s", "r.status IN ('calculated','approved','locked')"]

        if tax_authority_id:
            where.append("r.tax_authority_id = %s")
            params.append(int(tax_authority_id))

        if tax_year:
            where.append("r.tax_year = %s")
            params.append(int(tax_year))

        runs = self.fetch_all(f"""
            SELECT
                r.id,
                r.tax_year,
                r.tax_year_start,
                r.tax_year_end,
                r.status,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,

                COUNT(l.id) AS asset_count,
                COALESCE(SUM(l.book_depreciation), 0) AS book_depreciation,
                COALESCE(SUM(l.total_capital_allowance), 0) AS capital_allowance,
                COALESCE(SUM(l.tax_adjustment), 0) AS net_tax_adjustment,
                COALESCE(SUM(l.accounting_carrying_amount), 0) AS accounting_carrying_amount,
                COALESCE(SUM(l.closing_tax_wdv), 0) AS closing_tax_wdv,
                COALESCE(SUM(l.temporary_difference), 0) AS temporary_difference
            FROM {schema}.asset_tax_runs r
            JOIN public.tax_authorities ta ON ta.id = r.tax_authority_id
            LEFT JOIN {schema}.asset_tax_run_lines l ON l.run_id = r.id
            WHERE {" AND ".join(where)}
            GROUP BY r.id, ta.code, ta.name
            ORDER BY r.tax_year DESC, ta.code
        """, tuple(params))

        return {"runs": runs}
        
    def asset_tax_computation(self, company_id: int, tax_authority_id=None, tax_year=None) -> dict:
        recon = self.asset_tax_reconciliation(
            company_id,
            tax_authority_id=tax_authority_id,
            tax_year=tax_year,
        )

        runs = recon.get("runs", [])

        if tax_year:
            runs = [r for r in runs if int(r.get("tax_year") or 0) == int(tax_year)]

        if tax_authority_id:
            runs = [r for r in runs if int(r.get("tax_authority_id") or 0) == int(tax_authority_id)]

        if not runs:
            return {
                "accounting_profit": 0,
                "book_depreciation_addback": 0,
                "capital_allowance_deduction": 0,
                "estimated_taxable_income": 0,
                "runs": [],
            }

        # use selected/latest run period
        run = runs[0]

        date_from = run["tax_year_start"]
        date_to = run["tax_year_end"]

        if isinstance(date_from, str):
            date_from = date.fromisoformat(date_from[:10])

        if isinstance(date_to, str):
            date_to = date.fromisoformat(date_to[:10])

        pnl = self.get_pnl_full(
            company_id,
            date_from=date_from,
            date_to=date_to,
            template="ifrs",
            basis="external",
        ) or {}

        current_app.logger.warning("ASSET_TAX_PNL_KEYS=%s", list((pnl or {}).keys()))
        accounting_profit = _extract_pnl_profit(pnl)

        book_dep = sum(float(r.get("book_depreciation") or 0) for r in runs)
        cap_allowance = sum(float(r.get("capital_allowance") or 0) for r in runs)

        taxable_income = accounting_profit + book_dep - cap_allowance

        return {
            "tax_year_start": date_from,
            "tax_year_end": date_to,
            "accounting_profit": accounting_profit,
            "book_depreciation_addback": book_dep,
            "capital_allowance_deduction": cap_allowance,
            "estimated_taxable_income": taxable_income,
            "runs": runs,
        }
        
    def asset_tax_deferred_tax(self, company_id: int, tax_rate: float = 27.0) -> dict:
        recon = self.asset_tax_reconciliation(company_id)
        runs = recon.get("runs", [])

        carrying = sum(float(r.get("accounting_carrying_amount") or 0) for r in runs)
        tax_wdv = sum(float(r.get("closing_tax_wdv") or 0) for r in runs)
        temp_diff = carrying - tax_wdv
        deferred_tax = temp_diff * (tax_rate / 100.0)

        return {
            "tax_rate": tax_rate,
            "accounting_carrying_amount": carrying,
            "tax_wdv": tax_wdv,
            "temporary_difference": temp_diff,
            "deferred_tax": deferred_tax,
            "runs": runs,
        }


    def asset_tax_return_support(self, company_id: int) -> dict:
        recon = self.asset_tax_reconciliation(company_id)
        runs = recon.get("runs", [])

        return {
            "runs": runs,
            "totals": {
                "book_depreciation_addback": sum(float(r.get("book_depreciation") or 0) for r in runs),
                "capital_allowance_deduction": sum(float(r.get("capital_allowance") or 0) for r in runs),
                "net_tax_adjustment": sum(float(r.get("net_tax_adjustment") or 0) for r in runs),
            },
        }

    def ensure_asset_tax_profile_for_asset(self, company_id: int, asset_id: int) -> int | None:
        schema = self.company_schema(company_id)
        ta = self.asset_tax_authority_for_company(company_id)
        if not ta:
            return None

        row = self.fetch_one(f"""
            INSERT INTO {schema}.asset_tax_profiles (
                company_id,
                asset_id,
                tax_authority_id,
                tax_start_date,
                tax_cost,
                notes
            )
            SELECT
                a.company_id,
                a.id,
                %s,
                COALESCE(a.available_for_use_date, a.acquisition_date),
                COALESCE(a.opening_cost, a.cost),
                'Auto-created from asset register'
            FROM {schema}.assets a
            WHERE a.id = %s
            AND a.company_id = %s
            AND NOT EXISTS (
                SELECT 1
                FROM {schema}.asset_tax_profiles p
                WHERE p.company_id = a.company_id
                    AND p.asset_id = a.id
                    AND p.tax_authority_id = %s
            )
            RETURNING id
        """, (ta["id"], asset_id, company_id, ta["id"]))

        return row["id"] if row else None

    def asset_tax_get_authorities(self) -> list[dict]:
        return self.fetch_all("""
            SELECT *
            FROM public.tax_authorities
            WHERE is_active = TRUE
            ORDER BY code
        """)


    def asset_tax_default_authority_code(self, company_id: int) -> str:
        company = self.get_company(company_id) or {}
        country = str(
            company.get("country_code")
            or company.get("country")
            or ""
        ).strip().upper()

        if country in ("ZA", "SOUTH AFRICA"):
            return "SARS"
        if country in ("BW", "BOTSWANA"):
            return "BURS"
        return "RSL"


    def asset_tax_create_missing_profiles(self, company_id: int, cur=None) -> dict:
        schema = self.company_schema(company_id)
        tax_code = self.asset_tax_default_authority_code(company_id)

        owns_cursor = cur is None
        if owns_cursor:
            ctx = self._conn_cursor()
            conn, cur = ctx.__enter__()

        try:
            cur.execute("""
                SELECT id
                FROM public.tax_authorities
                WHERE code = %s
                AND is_active = TRUE
                LIMIT 1
            """, (tax_code,))
            ta = cur.fetchone()

            if not ta:
                raise ValueError(f"Tax authority not found for code {tax_code}")

            cur.execute(f"""
                INSERT INTO {schema}.asset_tax_profiles (
                    company_id,
                    asset_id,
                    tax_authority_id,
                    tax_start_date,
                    tax_cost,
                    notes
                )
                SELECT
                    a.company_id,
                    a.id,
                    %s,
                    COALESCE(a.available_for_use_date, a.acquisition_date),
                    COALESCE(a.opening_cost, a.cost),
                    'Auto-created from asset register'
                FROM {schema}.assets a
                WHERE a.company_id = %s
                AND NOT EXISTS (
                    SELECT 1
                    FROM {schema}.asset_tax_profiles p
                    WHERE p.company_id = a.company_id
                        AND p.asset_id = a.id
                        AND p.tax_authority_id = %s
                )
            """, (ta["id"], company_id, ta["id"]))

            created = cur.rowcount or 0

            if owns_cursor:
                conn.commit()

            return {
                "created": created,
                "tax_authority_code": tax_code,
                "tax_authority_id": ta["id"],
            }

        finally:
            if owns_cursor:
                ctx.__exit__(None, None, None)


    def ensure_asset_tax_profile_for_asset_cur(self, cur, company_id: int, asset_id: int) -> int | None:
        schema = self.company_schema(company_id)
        tax_code = self.asset_tax_default_authority_code(company_id)

        cur.execute("""
            SELECT id
            FROM public.tax_authorities
            WHERE code = %s
            AND is_active = TRUE
            LIMIT 1
        """, (tax_code,))
        ta = cur.fetchone()

        if not ta:
            return None

        cur.execute(f"""
            INSERT INTO {schema}.asset_tax_profiles (
                company_id,
                asset_id,
                tax_authority_id,
                tax_start_date,
                tax_cost,
                notes
            )
            SELECT
                a.company_id,
                a.id,
                %s,
                COALESCE(a.available_for_use_date, a.acquisition_date),
                COALESCE(a.opening_cost, a.cost),
                'Auto-created from asset register'
            FROM {schema}.assets a
            WHERE a.company_id = %s
            AND a.id = %s
            AND NOT EXISTS (
                SELECT 1
                FROM {schema}.asset_tax_profiles p
                WHERE p.company_id = a.company_id
                    AND p.asset_id = a.id
                    AND p.tax_authority_id = %s
            )
            RETURNING id
        """, (ta["id"], company_id, asset_id, ta["id"]))

        row = cur.fetchone()
        return int(row["id"]) if row else None


    def asset_tax_list_profiles(self, company_id: int) -> list[dict]:
        schema = self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                p.id AS profile_id,
                p.company_id,
                p.asset_id,

                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.asset_class_group,
                a.category,
                a.acquisition_date,
                a.available_for_use_date,
                a.cost,
                a.opening_cost,
                a.status AS asset_status,

                p.tax_authority_id,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,

                p.allowance_rule_id,
                r.rule_code,
                r.rule_name,
                r.method,
                r.rate_percent,
                r.initial_allowance_percent,
                r.annual_allowance_percent,

                p.tax_start_date,
                p.tax_cost,
                p.qualifying_percent,
                p.private_use_percent,
                p.is_tax_depreciable,
                p.is_active,
                p.notes,

                CASE
                    WHEN p.allowance_rule_id IS NULL THEN 'not_configured'
                    ELSE 'configured'
                END AS config_status

            FROM {schema}.asset_tax_profiles p
            JOIN {schema}.assets a ON a.id = p.asset_id
            JOIN public.tax_authorities ta ON ta.id = p.tax_authority_id
            LEFT JOIN public.tax_allowance_rules r ON r.id = p.allowance_rule_id
            WHERE p.company_id = %s
            ORDER BY a.asset_name, a.id
        """, (company_id,))


    def asset_tax_get_rules(self, tax_authority_id: int | None = None) -> list[dict]:
        params = []
        where = [
            "r.is_active = TRUE",
            "ta.is_active = TRUE",
        ]

        if tax_authority_id:
            where.append("r.tax_authority_id = %s")
            params.append(tax_authority_id)

        return self.fetch_all(f"""
            SELECT
                r.*,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name
            FROM public.tax_allowance_rules r
            JOIN public.tax_authorities ta ON ta.id = r.tax_authority_id
            WHERE {" AND ".join(where)}
            ORDER BY ta.code, r.rule_name, r.effective_from DESC
        """, tuple(params))


    def asset_tax_update_profile(self, company_id: int, profile_id: int, payload: dict) -> dict | None:
        schema = self.company_schema(company_id)

        allowed = {
            "tax_authority_id",
            "allowance_rule_id",
            "tax_start_date",
            "tax_cost",
            "qualifying_percent",
            "private_use_percent",
            "is_tax_depreciable",
            "is_active",
            "notes",
        }

        fields = []
        vals = []

        for k, v in (payload or {}).items():
            if k not in allowed:
                continue

            if k in {"qualifying_percent", "private_use_percent"}:
                v = Decimal(str(v or 0))
                if v < 0 or v > 100:
                    raise ValueError(f"{k} must be between 0 and 100")

            if k == "tax_cost" and v not in ("", None):
                v = Decimal(str(v))
                if v < 0:
                    raise ValueError("tax_cost cannot be negative")

            if k == "allowance_rule_id" and v in ("", 0, "0"):
                v = None

            fields.append(f"{k} = %s")
            vals.append(v)

        if not fields:
            raise ValueError("No valid fields to update.")

        fields.append("updated_at = NOW()")

        vals.extend([company_id, profile_id])

        return self.fetch_one(f"""
            UPDATE {schema}.asset_tax_profiles
            SET {", ".join(fields)}
            WHERE company_id = %s
            AND id = %s
            RETURNING *
        """, tuple(vals))
   
    def get_fixed_assets_snapshot(self, company_id: int, *, as_of=None) -> dict:
        report = self.list_asset_register_report(
            company_id,
            as_of=as_of,
            limit=100000,
            offset=0,
        )

        items = report.get("items", []) or []

        def _f(v):
            try:
                return float(v or 0)
            except Exception:
                return 0.0

        book_value = 0.0
        accum_dep = 0.0
        net_carrying = 0.0
        pending_dep = 0

        for a in items:
            status = str(a.get("status") or "").strip().lower()
            if status in {"disposed", "void"}:
                continue

            cost = _f(a.get("cost"))
            acc_dep_val = _f(a.get("accumulated_depreciation"))
            carrying = _f(a.get("carrying_amount"))
            residual = _f(a.get("residual_value"))

            book_value += cost
            accum_dep += acc_dep_val
            net_carrying += carrying

            dep_method = str(a.get("depreciation_method") or "").strip().upper()
            available = a.get("available_for_use_date")
            dep_as_of = a.get("depreciation_as_of")

            is_depreciable = dep_method in {"SL", "RB", "UOP"}
            in_use = bool(available) and (not as_of or str(available) <= str(as_of))
            not_fully_dep = carrying > residual and carrying > 0

            already_done = False
            if as_of and dep_as_of:
                already_done = str(dep_as_of)[:7] == str(as_of)[:7]

            if is_depreciable and in_use and not_fully_dep and not already_done:
                pending_dep += 1

        return {
            "book_value": round(book_value, 2),
            "accum_depreciation": round(accum_dep, 2),
            "net_carrying_amount": round(net_carrying, 2),
            "pending_depreciation_count": int(pending_dep),
            "asset_count": int(len(items)),
        }

