            engagement_code,
            engagement_name,
            engagement_type,
            status,
            governance_mode,
            reporting_cycle,
            due_date,
            start_date,
            end_date,
            manager_user_id,
            partner_user_id,
            target_company_id,
            description,
            scope_summary,
            fiscal_year_end,
            priority,
            workflow_stage,
            is_active,
            requires_workspace,
            workspace_status,
            workspace_status,
            workspace_source,
            target_company_source,
            updated_by_user_id,
