    def get_analytics_overview(self, cur, company_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH engagement_base AS (
                SELECT
                    e.id,
                    e.customer_id,
                    e.engagement_type,
                    e.status,
                    e.priority,
                    e.workflow_stage,
                    e.due_date,
                    e.is_active
                FROM {schema}.engagements e
                WHERE e.company_id = %s
                AND e.is_active = TRUE
            ),
            overdue_engagements AS (
                SELECT COUNT(*)::int AS cnt
                FROM engagement_base
                WHERE due_date IS NOT NULL
                AND due_date < CURRENT_DATE
                AND status NOT IN ('completed', 'cancelled', 'archived')
            ),
            blocked_reporting_items AS (
                SELECT COUNT(*)::int AS cnt
                FROM {schema}.engagement_reporting_items i
                WHERE i.company_id = %s
                AND i.is_active = TRUE
                AND i.status = 'blocked'
            ),
            outstanding_deliverables AS (
                SELECT COUNT(*)::int AS cnt
                FROM {schema}.engagement_deliverables d
                WHERE d.company_id = %s
                AND d.is_active = TRUE
                AND d.status IN ('requested', 'outstanding', 'in_review')
            ),
            pending_signoffs AS (
                SELECT COUNT(*)::int AS cnt
                FROM {schema}.engagement_signoff_steps s
                WHERE s.company_id = %s
                AND s.is_active = TRUE
                AND s.status IN ('not_started', 'in_progress', 'blocked')
            ),
            completion_stats AS (
                SELECT
                    COUNT(*) FILTER (WHERE status = 'completed')::int AS completed_count,
                    COUNT(*) FILTER (WHERE status NOT IN ('cancelled', 'archived'))::int AS total_live_count
                FROM engagement_base
            ),
            engagement_counts AS (
                SELECT
                    COUNT(*)::int AS active_engagements,
                    COUNT(*) FILTER (
                        WHERE due_date IS NOT NULL
                        AND date_trunc('month', due_date::timestamp) = date_trunc('month', CURRENT_DATE::timestamp)
                    )::int AS due_this_month
                FROM engagement_base
            )
            SELECT
                ec.active_engagements,
                ec.due_this_month,
                (
                    COALESCE(oe.cnt, 0) +
                    COALESCE(bri.cnt, 0) +
                    COALESCE(od.cnt, 0) +
                    COALESCE(ps.cnt, 0)
                )::int AS at_risk_items,
                CASE
                    WHEN COALESCE(cs.total_live_count, 0) = 0 THEN 0
                    ELSE ROUND(
                        (cs.completed_count::numeric / NULLIF(cs.total_live_count, 0)::numeric) * 100,
                        2
                    )
                END AS completion_rate
            FROM engagement_counts ec
            CROSS JOIN overdue_engagements oe
            CROSS JOIN blocked_reporting_items bri
            CROSS JOIN outstanding_deliverables od
            CROSS JOIN pending_signoffs ps
            CROSS JOIN completion_stats cs
        """
        cur.execute(sql, (company_id, company_id, company_id, company_id))
        row = cur.fetchone()
        if row:
            return row

        return {
            "active_engagements": 0,
            "due_this_month": 0,
            "at_risk_items": 0,
            "completion_rate": 0,
        }

    def get_engagement_profitability_summary(self, cur, company_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                COUNT(*) FILTER (
                    WHERE is_active = TRUE
                ) AS portfolio_total,

                COUNT(*) FILTER (
                    WHERE is_active = TRUE
                    AND status IN ('active', 'pending')
                    AND (due_date IS NULL OR due_date >= CURRENT_DATE)
                    AND priority IN ('low', 'normal')
                ) AS healthy_count,

                COUNT(*) FILTER (
                    WHERE is_active = TRUE
                    AND (
                        priority = 'high'
                        OR workflow_stage IN ('planning')
                        OR (due_date IS NOT NULL AND due_date < CURRENT_DATE + INTERVAL '14 days')
                    )
                ) AS watchlist_count,

                COUNT(*) FILTER (
                    WHERE is_active = TRUE
                    AND (
                        status = 'on_hold'
                        OR priority = 'urgent'
                        OR (due_date IS NOT NULL AND due_date < CURRENT_DATE)
                    )
                ) AS critical_count
            FROM {schema}.engagements
            WHERE company_id = %s
        """
        cur.execute(sql, (company_id,))
        return cur.fetchone()

    def list_engagement_profitability_rows(
        self,
        cur,
        company_id: int,
        *,
        status: str = None,
        engagement_type: str = None,
        manager_user_id: int = None,
        priority: str = None,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                e.id,
                e.engagement_code,
                e.engagement_name,
                c.name,
                e.engagement_type,
                e.status,
                e.priority,
                e.workflow_stage,
                e.due_date,
                e.manager_user_id,
                CASE
                    WHEN e.status = 'on_hold'
                        OR e.priority = 'urgent'
                        OR (e.due_date IS NOT NULL AND e.due_date < CURRENT_DATE)
                        THEN 'critical'
                    WHEN e.priority = 'high'
                        OR (e.due_date IS NOT NULL AND e.due_date <= CURRENT_DATE + INTERVAL '14 days')
                        THEN 'watchlist'
                    ELSE 'healthy'
                END AS signal
            FROM {schema}.engagements e
            JOIN {schema}.customers c
            ON c.id = e.customer_id
            WHERE e.company_id = %s
            AND e.is_active = TRUE
            AND (%s IS NULL OR e.status = %s)
            AND (%s IS NULL OR e.engagement_type = %s)
            AND (%s IS NULL OR e.manager_user_id = %s)
            AND (%s IS NULL OR e.priority = %s)
            ORDER BY
                CASE
                    WHEN e.due_date IS NULL THEN 1
                    ELSE 0
                END,
                e.due_date ASC,
                e.engagement_name ASC
        """
        cur.execute(sql, (
            company_id,
            status, status,
            engagement_type, engagement_type,
            manager_user_id, manager_user_id,
            priority, priority,
        ))
        return cur.fetchall()

    def get_client_service_trends_summary(self, cur, company_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                COUNT(DISTINCT e.customer_id) AS clients_served,
                COUNT(DISTINCT e.engagement_type) AS active_service_lines,
                COUNT(*) FILTER (
                    WHERE e.reporting_cycle IS NOT NULL
                ) AS recurring_engagements,
                COUNT(*) FILTER (
                    WHERE e.due_date IS NOT NULL
                    AND e.due_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + INTERVAL '30 days')
                    AND e.status NOT IN ('completed', 'cancelled', 'archived')
                ) AS upcoming_due_dates
            FROM {schema}.engagements e
            WHERE e.company_id = %s
            AND e.is_active = TRUE
        """
        cur.execute(sql, (company_id,))
        return cur.fetchone()

    def list_client_service_trends_rows(self, cur, company_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                c.id AS customer_id,
                c.customer_name,
                COUNT(e.id) AS engagement_count,
                COUNT(DISTINCT e.engagement_type) AS service_line_count,
                MIN(e.due_date) AS next_due_date,
                COUNT(*) FILTER (
                    WHERE e.status IN ('active', 'pending', 'draft')
                ) AS open_engagements
            FROM {schema}.customers c
            LEFT JOIN {schema}.engagements e
            ON e.customer_id = c.id
            AND e.company_id = %s
            AND e.is_active = TRUE
            WHERE c.company_id = %s
            GROUP BY c.id, c.customer_name
            ORDER BY engagement_count DESC, c.customer_name ASC
        """
        cur.execute(sql, (company_id, company_id))
        return cur.fetchall()

    def get_risk_alerts_summary(self, cur, company_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                (
                    SELECT COUNT(*)
                    FROM {schema}.engagements e
                    WHERE e.company_id = %s
                    AND e.is_active = TRUE
                    AND e.due_date IS NOT NULL
                    AND e.due_date < CURRENT_DATE
                    AND e.status NOT IN ('completed', 'cancelled', 'archived')
                ) AS overdue_engagements,

                (
                    SELECT COUNT(*)
                    FROM {schema}.engagement_reporting_items i
                    WHERE i.company_id = %s
                    AND i.is_active = TRUE
                    AND i.status = 'blocked'
                ) AS blocked_items,

                (
                    SELECT COUNT(*)
                    FROM {schema}.engagement_deliverables d
                    WHERE d.company_id = %s
                    AND d.is_active = TRUE
                    AND d.status IN ('requested', 'outstanding')
                ) AS outstanding_deliverables,

                (
                    SELECT COUNT(*)
                    FROM {schema}.engagement_signoff_steps s
                    WHERE s.company_id = %s
                    AND s.is_active = TRUE
                    AND s.status IN ('not_started', 'in_progress', 'blocked')
                ) AS pending_signoffs
        """
        cur.execute(sql, (company_id, company_id, company_id, company_id))
        return cur.fetchone()

    def list_risk_alert_rows(self, cur, company_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                e.id AS engagement_id,
                e.engagement_name,
                c.name,
                e.status AS engagement_status,
                e.priority,
                e.due_date,
                COALESCE(ri.blocked_count, 0) AS blocked_reporting_items,
                COALESCE(dv.outstanding_count, 0) AS outstanding_deliverables,
                COALESCE(sf.pending_count, 0) AS pending_signoffs
            FROM {schema}.engagements e
            JOIN {schema}.customers c
            ON c.id = e.customer_id
            LEFT JOIN (
                SELECT engagement_id, COUNT(*) AS blocked_count
                FROM {schema}.engagement_reporting_items
                WHERE company_id = %s
                AND is_active = TRUE
                AND status = 'blocked'
                GROUP BY engagement_id
            ) ri ON ri.engagement_id = e.id
            LEFT JOIN (
                SELECT engagement_id, COUNT(*) AS outstanding_count
                FROM {schema}.engagement_deliverables
                WHERE company_id = %s
                AND is_active = TRUE
                AND status IN ('requested', 'outstanding')
                GROUP BY engagement_id
            ) dv ON dv.engagement_id = e.id
            LEFT JOIN (
                SELECT engagement_id, COUNT(*) AS pending_count
                FROM {schema}.engagement_signoff_steps
                WHERE company_id = %s
                AND is_active = TRUE
                AND status IN ('not_started', 'in_progress', 'blocked')
                GROUP BY engagement_id
            ) sf ON sf.engagement_id = e.id
            WHERE e.company_id = %s
            AND e.is_active = TRUE
            AND (
                (e.due_date IS NOT NULL AND e.due_date < CURRENT_DATE)
                OR COALESCE(ri.blocked_count, 0) > 0
                OR COALESCE(dv.outstanding_count, 0) > 0
                OR COALESCE(sf.pending_count, 0) > 0
            )
            ORDER BY
                CASE
                    WHEN e.due_date IS NOT NULL AND e.due_date < CURRENT_DATE THEN 0
                    ELSE 1
                END,
                e.due_date ASC NULLS LAST,
                e.engagement_name ASC
        """
        cur.execute(sql, (company_id, company_id, company_id, company_id))
        return cur.fetchall()

    def get_client_overview_summary(
        self,
        cur,
        company_id: int,
        *,
        customer_id: int,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH client_engagements AS (
                SELECT e.*
                FROM {schema}.engagements e
                WHERE e.company_id = %s
                AND e.customer_id = %s
                AND e.is_active = TRUE
            ),
            team_counts AS (
                SELECT COUNT(DISTINCT et.user_id) AS assigned_team_members
                FROM {schema}.engagement_team et
                JOIN client_engagements e
                ON e.id = et.engagement_id
                WHERE et.company_id = %s
                AND et.is_active = TRUE
            ),
            open_items AS (
                SELECT COUNT(*) AS cnt
                FROM (
                    SELECT ri.id
                    FROM {schema}.engagement_reporting_items ri
                    JOIN client_engagements e ON e.id = ri.engagement_id
                    WHERE ri.company_id = %s
                    AND ri.is_active = TRUE
                    AND LOWER(ri.status) NOT IN ('completed', 'approved', 'waived')

                    UNION ALL

                    SELECT d.id
                    FROM {schema}.engagement_deliverables d
                    JOIN client_engagements e ON e.id = d.engagement_id
                    WHERE d.company_id = %s
                    AND d.is_active = TRUE
                    AND LOWER(d.status) NOT IN ('completed', 'waived', 'received')

                    UNION ALL

                    SELECT mt.id
                    FROM {schema}.engagement_monthly_close_tasks mt
                    JOIN client_engagements e ON e.id = mt.engagement_id
                    WHERE mt.company_id = %s
                    AND mt.is_active = TRUE
                    AND LOWER(mt.status) NOT IN ('completed', 'skipped')

                    UNION ALL

                    SELECT yt.id
                    FROM {schema}.engagement_year_end_tasks yt
                    JOIN client_engagements e ON e.id = yt.engagement_id
                    WHERE yt.company_id = %s
                    AND yt.is_active = TRUE
                    AND LOWER(yt.status) NOT IN ('completed', 'waived')

                    UNION ALL

                    SELECT ss.id
                    FROM {schema}.engagement_signoff_steps ss
                    JOIN client_engagements e ON e.id = ss.engagement_id
                    WHERE ss.company_id = %s
                    AND ss.is_active = TRUE
                    AND LOWER(ss.status) NOT IN ('completed', 'waived')
                ) x
            ),
            overdue_items AS (
                SELECT COUNT(*) AS cnt
                FROM (
                    SELECT ri.id
                    FROM {schema}.engagement_reporting_items ri
                    JOIN client_engagements e ON e.id = ri.engagement_id
                    WHERE ri.company_id = %s
                    AND ri.is_active = TRUE
                    AND ri.due_date IS NOT NULL
                    AND ri.due_date < CURRENT_DATE
                    AND LOWER(ri.status) NOT IN ('completed', 'approved', 'waived')

                    UNION ALL

                    SELECT d.id
                    FROM {schema}.engagement_deliverables d
                    JOIN client_engagements e ON e.id = d.engagement_id
                    WHERE d.company_id = %s
                    AND d.is_active = TRUE
                    AND d.due_date IS NOT NULL
                    AND d.due_date < CURRENT_DATE
                    AND LOWER(d.status) NOT IN ('completed', 'waived', 'received')

                    UNION ALL

                    SELECT mt.id
                    FROM {schema}.engagement_monthly_close_tasks mt
                    JOIN client_engagements e ON e.id = mt.engagement_id
                    WHERE mt.company_id = %s
                    AND mt.is_active = TRUE
                    AND mt.due_date IS NOT NULL
                    AND mt.due_date < CURRENT_DATE
                    AND LOWER(mt.status) NOT IN ('completed', 'skipped')

                    UNION ALL

                    SELECT yt.id
                    FROM {schema}.engagement_year_end_tasks yt
                    JOIN client_engagements e ON e.id = yt.engagement_id
                    WHERE yt.company_id = %s
                    AND yt.is_active = TRUE
                    AND yt.due_date IS NOT NULL
                    AND yt.due_date < CURRENT_DATE
                    AND LOWER(yt.status) NOT IN ('completed', 'waived')

                    UNION ALL

                    SELECT ss.id
                    FROM {schema}.engagement_signoff_steps ss
                    JOIN client_engagements e ON e.id = ss.engagement_id
                    WHERE ss.company_id = %s
                    AND ss.is_active = TRUE
                    AND ss.due_date IS NOT NULL
                    AND ss.due_date < CURRENT_DATE
                    AND LOWER(ss.status) NOT IN ('completed', 'waived')
                ) y
            )
            SELECT
                c.id AS customer_id,
                c.name,
                COUNT(DISTINCT e.id) AS active_engagements,
                COUNT(DISTINCT CASE WHEN LOWER(e.status) = 'completed' THEN e.id END) AS completed_engagements,
                COUNT(DISTINCT CASE WHEN LOWER(e.priority) IN ('high', 'urgent') THEN e.id END) AS priority_engagements,
                COALESCE((SELECT cnt FROM open_items), 0) AS open_items,
                COALESCE((SELECT cnt FROM overdue_items), 0) AS overdue_items,
                COALESCE((SELECT assigned_team_members FROM team_counts), 0) AS assigned_team_members
            FROM {schema}.customers c
            LEFT JOIN client_engagements e
            ON e.customer_id = c.id
            WHERE c.id = %s
            GROUP BY c.id, c.name
            LIMIT 1
        """
        cur.execute(
            sql,
            (
                company_id, customer_id,
                company_id,
                company_id, company_id, company_id, company_id, company_id,
                company_id, company_id, company_id, company_id, company_id,
                customer_id,
            ),
        )
        return cur.fetchone()

    def list_client_overview_engagements(
        self,
        cur,
        company_id: int,
        *,
        customer_id: int,
        status: str = "",
        engagement_type: str = "",
        q: str = "",
        active_only: bool = True,
        limit: int = 200,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)

        where = ["e.company_id = %s", "e.customer_id = %s"]
        params = [company_id, customer_id]

        if status:
            where.append("LOWER(e.status) = LOWER(%s)")
            params.append(status)

        if engagement_type:
            where.append("LOWER(e.engagement_type) = LOWER(%s)")
            params.append(engagement_type)

        if active_only:
            where.append("e.is_active = TRUE")

        if q:
            where.append("""
                (
                    e.engagement_name ILIKE %s
                    OR COALESCE(e.engagement_code, '') ILIKE %s
                    OR COALESCE(e.description, '') ILIKE %s
                    OR COALESCE(e.scope_summary, '') ILIKE %s
                )
            """)
            like = f"%{q.strip()}%"
            params.extend([like, like, like, like])

        sql = f"""
            SELECT
                e.*,
                c.name,

                manager_u.first_name AS manager_first_name,
                manager_u.last_name AS manager_last_name,
                manager_u.email AS manager_email,

                partner_u.first_name AS partner_first_name,
                partner_u.last_name AS partner_last_name,
                partner_u.email AS partner_email,

                COALESCE(ri_counts.open_reporting_items, 0) AS open_reporting_items,
                COALESCE(d_counts.open_deliverables, 0) AS open_deliverables,
                COALESCE(task_counts.open_close_items, 0) AS open_close_items

            FROM {schema}.engagements e
            JOIN {schema}.customers c
            ON c.id = e.customer_id

            LEFT JOIN public.users manager_u
            ON manager_u.id = e.manager_user_id

            LEFT JOIN public.users partner_u
            ON partner_u.id = e.partner_user_id

            LEFT JOIN (
                SELECT
                    engagement_id,
                    COUNT(*) AS open_reporting_items
                FROM {schema}.engagement_reporting_items
                WHERE company_id = %s
                AND is_active = TRUE
                AND LOWER(status) NOT IN ('completed', 'approved', 'waived')
                GROUP BY engagement_id
            ) ri_counts
            ON ri_counts.engagement_id = e.id

            LEFT JOIN (
                SELECT
                    engagement_id,
                    COUNT(*) AS open_deliverables
                FROM {schema}.engagement_deliverables
                WHERE company_id = %s
                AND is_active = TRUE
                AND LOWER(status) NOT IN ('completed', 'waived', 'received')
                GROUP BY engagement_id
            ) d_counts
            ON d_counts.engagement_id = e.id

            LEFT JOIN (
                SELECT
                    t.engagement_id,
                    COUNT(*) AS open_close_items
                FROM (
                    SELECT engagement_id
                    FROM {schema}.engagement_monthly_close_tasks
                    WHERE company_id = %s
                    AND is_active = TRUE
                    AND LOWER(status) NOT IN ('completed', 'skipped')

                    UNION ALL

                    SELECT engagement_id
                    FROM {schema}.engagement_year_end_tasks
                    WHERE company_id = %s
                    AND is_active = TRUE
                    AND LOWER(status) NOT IN ('completed', 'waived')

                    UNION ALL

                    SELECT engagement_id
                    FROM {schema}.engagement_signoff_steps
                    WHERE company_id = %s
                    AND is_active = TRUE
                    AND LOWER(status) NOT IN ('completed', 'waived')
                ) t
                GROUP BY t.engagement_id
            ) task_counts
            ON task_counts.engagement_id = e.id

            WHERE {" AND ".join(where)}
            ORDER BY
                e.due_date NULLS LAST,
                e.updated_at DESC,
                e.id DESC
            LIMIT %s OFFSET %s
        """
        params.extend([company_id, company_id, company_id, company_id, company_id, limit, offset])
        cur.execute(sql, tuple(params))
        return cur.fetchall()

