    def set_engagement_working_paper_status(
        self,
        cur,
        company_id: int,
        *,
        working_paper_id: int,
        status: str,
        updated_by_user_id: int = None,
        prepared_at=None,
        reviewed_at=None,
        cleared_at=None,
    ) -> int | None:
        schema = self.company_schema(company_id)

        sql = f"""
            UPDATE {schema}.engagement_working_papers
            SET
                status = %s,
                prepared_at = COALESCE(%s, prepared_at),
                reviewed_at = COALESCE(%s, reviewed_at),
                cleared_at = COALESCE(%s, cleared_at),
                updated_by_user_id = %s,
                updated_at = NOW()
            WHERE company_id = %s
              AND id = %s
            RETURNING id
        """
        cur.execute(
            sql,
            (
                status,
                prepared_at,
                reviewed_at,
                cleared_at,
                updated_by_user_id,
                company_id,
                working_paper_id,
            ),
        )
        row = cur.fetchone()
        if not row:
            return None
        return int(row["id"] if isinstance(row, dict) else row[0])

    def deactivate_engagement_working_paper(
        self,
        cur,
        company_id: int,
        *,
        working_paper_id: int,
        updated_by_user_id: int = None,
    ) -> int | None:
        schema = self.company_schema(company_id)

        sql = f"""
            UPDATE {schema}.engagement_working_papers
            SET
                is_active = FALSE,
                updated_by_user_id = %s,
                updated_at = NOW()
            WHERE company_id = %s
              AND id = %s
              AND is_active = TRUE
            RETURNING id
        """
        cur.execute(sql, (updated_by_user_id, company_id, working_paper_id))
        row = cur.fetchone()
        if not row:
            return None
        return int(row["id"] if isinstance(row, dict) else row[0])

    def get_engagement_working_papers_summary(
        self,
        cur,
        company_id: int,
        *,
        customer_id: int = None,
        engagement_id: int = None,
        current_user_id: int = None,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH scoped AS (
                SELECT wp.*
                FROM {schema}.engagement_working_papers wp
                JOIN {schema}.engagements e
                  ON e.id = wp.engagement_id
                WHERE wp.company_id = %s
                  AND wp.is_active = TRUE
                  AND e.is_active = TRUE
                  AND (%s IS NULL OR e.customer_id = %s)
                  AND (%s IS NULL OR wp.engagement_id = %s)
            )
            SELECT
                COUNT(*) AS total_items,
                COUNT(*) FILTER (WHERE status IN ('prepared', 'in_review')) AS ready_or_in_review,
                COUNT(*) FILTER (
                    WHERE due_date IS NOT NULL
                      AND due_date < CURRENT_DATE
                      AND status NOT IN ('reviewed', 'cleared', 'archived')
                ) AS overdue_items,
                COUNT(*) FILTER (WHERE status = 'blocked') AS blocked_items,
                COUNT(*) FILTER (
                    WHERE %s IS NOT NULL
                      AND (
                        preparer_user_id = %s
                        OR reviewer_user_id = %s
                      )
                ) AS my_items
            FROM scoped
        """
        cur.execute(
            sql,
            (
                company_id,
                customer_id, customer_id,
                engagement_id, engagement_id,
                current_user_id, current_user_id, current_user_id,
            ),
        )
        return cur.fetchone()

    def get_team_capacity_summary(
        self,
        cur,
        company_id: int,
        *,
        search: str = "",
        role_on_engagement: str = "",
        active_only: bool = True,
        as_of_date=None,
    ):
        schema = self.company_schema(company_id)
        as_of_date = as_of_date or "CURRENT_DATE"

        sql = f"""
            WITH team_scope AS (
                SELECT
                    et.id,
                    et.company_id,
                    et.engagement_id,
                    et.user_id,
                    LOWER(et.role_on_engagement) AS role_on_engagement,
                    et.allocation_percent,
                    et.start_date,
                    et.end_date,
                    et.is_active,
                    e.engagement_name,
                    e.engagement_code,
                    e.status AS engagement_status,
                    u.email,
                    TRIM(
                        CONCAT(
                            COALESCE(u.first_name, ''),
                            CASE
                                WHEN COALESCE(u.last_name, '') <> '' THEN ' ' || u.last_name
                                ELSE ''
                            END
                        )
                    ) AS full_name
                FROM {schema}.engagement_team et
                JOIN {schema}.engagements e
                ON e.id = et.engagement_id
                AND e.company_id = et.company_id
                JOIN public.users u
                ON u.id = et.user_id
                WHERE et.company_id = %s
                AND e.company_id = %s
                AND e.is_active = TRUE
                AND (%s = FALSE OR et.is_active = TRUE)
                AND (%s = '' OR LOWER(et.role_on_engagement) = LOWER(%s))
                AND (
                        %s = ''
                        OR TRIM(
                            CONCAT(
                                COALESCE(u.first_name, ''),
                                CASE
                                    WHEN COALESCE(u.last_name, '') <> '' THEN ' ' || u.last_name
                                    ELSE ''
                                END
                            )
                        ) ILIKE %s
                        OR COALESCE(u.email, '') ILIKE %s
                        OR COALESCE(e.engagement_name, '') ILIKE %s
                        OR COALESCE(e.engagement_code, '') ILIKE %s
                    )
                AND (
                        et.start_date IS NULL
                        OR et.start_date <= {as_of_date}
                    )
                AND (
                        et.end_date IS NULL
                        OR et.end_date >= {as_of_date}
                    )
            ),
            alloc_by_user AS (
                SELECT
                    user_id,
                    MAX(full_name) AS full_name,
                    MAX(email) AS email,
                    COUNT(*) AS active_assignments,
                    COUNT(DISTINCT engagement_id) AS active_engagements,
                    COALESCE(SUM(COALESCE(allocation_percent, 0)), 0) AS total_allocation_percent
                FROM team_scope
                GROUP BY user_id
            ),
            reviewer_load AS (
                SELECT
                    wp.reviewer_user_id AS user_id,
                    COUNT(*) FILTER (
                        WHERE wp.status IN ('prepared', 'in_review')
                    ) AS review_queue_count,
                    COUNT(*) FILTER (
                        WHERE wp.status = 'in_review'
                    ) AS in_review_count,
                    COUNT(*) FILTER (
                        WHERE wp.due_date IS NOT NULL
                        AND wp.due_date < CURRENT_DATE
                        AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
                    ) AS overdue_review_items
                FROM {schema}.engagement_working_papers wp
                JOIN {schema}.engagements e
                ON e.id = wp.engagement_id
                AND e.company_id = wp.company_id
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                AND e.is_active = TRUE
                AND wp.reviewer_user_id IS NOT NULL
                GROUP BY wp.reviewer_user_id
            ),
            combined AS (
                SELECT
                    a.user_id,
                    a.full_name,
                    a.email,
                    a.active_assignments,
                    a.active_engagements,
                    a.total_allocation_percent,
                    GREATEST(0, 100 - a.total_allocation_percent) AS available_capacity_percent,
                    COALESCE(r.review_queue_count, 0) AS review_queue_count,
                    COALESCE(r.in_review_count, 0) AS in_review_count,
                    COALESCE(r.overdue_review_items, 0) AS overdue_review_items,
                    CASE
                        WHEN a.total_allocation_percent >= 100 THEN 'overloaded'
                        WHEN a.total_allocation_percent >= 80 THEN 'near_capacity'
                        ELSE 'available'
                    END AS load_band
                FROM alloc_by_user a
                LEFT JOIN reviewer_load r
                ON r.user_id = a.user_id
            )
            SELECT
                COUNT(*) AS total_users,
                COUNT(*) FILTER (WHERE total_allocation_percent >= 100) AS overloaded_users,
                COUNT(*) FILTER (WHERE total_allocation_percent BETWEEN 80 AND 99.99) AS near_capacity_users,
                COUNT(*) FILTER (WHERE total_allocation_percent < 80) AS available_users,
                COUNT(*) FILTER (
                    WHERE review_queue_count > 0
                    OR overdue_review_items > 0
                ) AS reviewers_with_pressure,
                COALESCE(SUM(active_assignments), 0) AS total_assignments,
                COALESCE(SUM(active_engagements), 0) AS total_engagement_links,
                COALESCE(AVG(total_allocation_percent), 0) AS avg_allocation_percent,
                COALESCE(SUM(review_queue_count), 0) AS total_review_queue,
                COALESCE(SUM(overdue_review_items), 0) AS total_overdue_review_items
            FROM combined
        """
        like = f"%{search.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                company_id,
                active_only,
                role_on_engagement.strip(),
                role_on_engagement.strip(),
                search.strip(),
                like,
                like,
                like,
                like,
                company_id,
            ),
        )
        return cur.fetchone()


    def list_team_capacity_by_user(
        self,
        cur,
        company_id: int,
        *,
        search: str = "",
        role_on_engagement: str = "",
        active_only: bool = True,
        only_available: bool = False,
        only_overloaded: bool = False,
        limit: int = 100,
        offset: int = 0,
        as_of_date=None,
    ):
        schema = self.company_schema(company_id)
        as_of_date = as_of_date or "CURRENT_DATE"

        sql = f"""
            WITH team_scope AS (
                SELECT
                    et.id,
                    et.company_id,
                    et.engagement_id,
                    et.user_id,
                    LOWER(et.role_on_engagement) AS role_on_engagement,
                    et.allocation_percent,
                    et.start_date,
                    et.end_date,
                    et.notes,
                    et.is_active,
                    e.engagement_name,
                    e.engagement_code,
                    e.status AS engagement_status,
                    e.due_date AS engagement_due_date,
                    u.email,
                    TRIM(
                        CONCAT(
                            COALESCE(u.first_name, ''),
                            CASE
                                WHEN COALESCE(u.last_name, '') <> '' THEN ' ' || u.last_name
                                ELSE ''
                            END
                        )
                    ) AS full_name
                FROM {schema}.engagement_team et
                JOIN {schema}.engagements e
                ON e.id = et.engagement_id
                AND e.company_id = et.company_id
                JOIN public.users u
                ON u.id = et.user_id
                WHERE et.company_id = %s
                AND e.company_id = %s
                AND e.is_active = TRUE
                AND (%s = FALSE OR et.is_active = TRUE)
                AND (%s = '' OR LOWER(et.role_on_engagement) = LOWER(%s))
                AND (
                        et.start_date IS NULL
                        OR et.start_date <= {as_of_date}
                    )
                AND (
                        et.end_date IS NULL
                        OR et.end_date >= {as_of_date}
                    )
                AND (
                        %s = ''
                        OR TRIM(
                            CONCAT(
                                COALESCE(u.first_name, ''),
                                CASE
                                    WHEN COALESCE(u.last_name, '') <> '' THEN ' ' || u.last_name
                                    ELSE ''
                                END
                            )
                        ) ILIKE %s
                        OR COALESCE(u.email, '') ILIKE %s
                        OR COALESCE(e.engagement_name, '') ILIKE %s
                        OR COALESCE(e.engagement_code, '') ILIKE %s
                    )
            ),
            alloc_by_user AS (
                SELECT
                    user_id,
                    MAX(full_name) AS full_name,
                    MAX(email) AS email,
                    COUNT(*) AS active_assignments,
                    COUNT(DISTINCT engagement_id) AS active_engagements,
                    COALESCE(SUM(COALESCE(allocation_percent, 0)), 0) AS total_allocation_percent,
                    COALESCE(AVG(NULLIF(allocation_percent, 0)), 0) AS avg_assignment_allocation_percent,
                    MIN(start_date) AS first_assignment_start_date,
                    MAX(end_date) AS last_assignment_end_date,
                    COUNT(*) FILTER (
                        WHERE engagement_due_date IS NOT NULL
                        AND engagement_due_date < CURRENT_DATE
                        AND engagement_status NOT IN ('completed', 'cancelled', 'archived')
                    ) AS overdue_engagements
                FROM team_scope
                GROUP BY user_id
            ),
            reviewer_load AS (
                SELECT
                    wp.reviewer_user_id AS user_id,
                    COUNT(*) FILTER (
                        WHERE wp.status IN ('prepared', 'in_review')
                    ) AS review_queue_count,
                    COUNT(*) FILTER (
                        WHERE wp.status = 'in_review'
                    ) AS in_review_count,
                    COUNT(*) FILTER (
                        WHERE wp.due_date IS NOT NULL
                        AND wp.due_date < CURRENT_DATE
                        AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
                    ) AS overdue_review_items
                FROM {schema}.engagement_working_papers wp
                JOIN {schema}.engagements e
                ON e.id = wp.engagement_id
                AND e.company_id = wp.company_id
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                AND e.is_active = TRUE
                AND wp.reviewer_user_id IS NOT NULL
                GROUP BY wp.reviewer_user_id
            ),
            preparer_load AS (
                SELECT
                    wp.preparer_user_id AS user_id,
                    COUNT(*) FILTER (
                        WHERE wp.status IN ('draft', 'prepared', 'returned', 'blocked')
                    ) AS prep_queue_count,
                    COUNT(*) FILTER (
                        WHERE wp.status = 'blocked'
                    ) AS blocked_items
                FROM {schema}.engagement_working_papers wp
                JOIN {schema}.engagements e
                ON e.id = wp.engagement_id
                AND e.company_id = wp.company_id
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                AND e.is_active = TRUE
                AND wp.preparer_user_id IS NOT NULL
                GROUP BY wp.preparer_user_id
            ),
            combined AS (
                SELECT
                    a.user_id,
                    a.full_name,
                    a.email,
                    a.active_assignments,
                    a.active_engagements,
                    ROUND(a.total_allocation_percent::numeric, 2) AS total_allocation_percent,
                    ROUND(a.avg_assignment_allocation_percent::numeric, 2) AS avg_assignment_allocation_percent,
                    GREATEST(0, ROUND((100 - a.total_allocation_percent)::numeric, 2)) AS available_capacity_percent,
                    a.first_assignment_start_date,
                    a.last_assignment_end_date,
                    a.overdue_engagements,
                    COALESCE(r.review_queue_count, 0) AS review_queue_count,
                    COALESCE(r.in_review_count, 0) AS in_review_count,
                    COALESCE(r.overdue_review_items, 0) AS overdue_review_items,
                    COALESCE(p.prep_queue_count, 0) AS prep_queue_count,
                    COALESCE(p.blocked_items, 0) AS blocked_items,
                    CASE
                        WHEN a.total_allocation_percent >= 100 THEN 'overloaded'
                        WHEN a.total_allocation_percent >= 80 THEN 'near_capacity'
                        ELSE 'available'
                    END AS load_band
                FROM alloc_by_user a
                LEFT JOIN reviewer_load r
                ON r.user_id = a.user_id
                LEFT JOIN preparer_load p
                ON p.user_id = a.user_id
            )
            SELECT
                *
            FROM combined
            WHERE (%s = FALSE OR total_allocation_percent < 80)
            AND (%s = FALSE OR total_allocation_percent >= 100)
            ORDER BY
                total_allocation_percent DESC,
                overdue_review_items DESC,
                review_queue_count DESC,
                full_name ASC
            LIMIT %s OFFSET %s
        """
        like = f"%{search.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                company_id,
                active_only,
                role_on_engagement.strip(),
                role_on_engagement.strip(),
                search.strip(),
                like,
                like,
                like,
                like,
                company_id,
                company_id,
                only_available,
                only_overloaded,
                limit,
                offset,
            ),
        )
        return cur.fetchall()


    def list_team_capacity_user_engagements(
        self,
        cur,
        company_id: int,
        *,
        user_id: int,
        active_only: bool = True,
        as_of_date=None,
    ):
        schema = self.company_schema(company_id)
        as_of_date = as_of_date or "CURRENT_DATE"

        sql = f"""
            WITH wp_stats AS (
                SELECT
                    wp.engagement_id,
                    COUNT(*) FILTER (
                        WHERE wp.preparer_user_id = %s
                    ) AS prepared_items,
                    COUNT(*) FILTER (
                        WHERE wp.reviewer_user_id = %s
                    ) AS assigned_for_review,
                    COUNT(*) FILTER (
                        WHERE wp.reviewer_user_id = %s
                        AND wp.status IN ('prepared', 'in_review')
                    ) AS review_queue_count,
                    COUNT(*) FILTER (
                        WHERE wp.reviewer_user_id = %s
                        AND wp.due_date IS NOT NULL
                        AND wp.due_date < CURRENT_DATE
                        AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
                    ) AS overdue_review_items,
                    COUNT(*) FILTER (
                        WHERE (wp.preparer_user_id = %s OR wp.reviewer_user_id = %s)
                        AND wp.status = 'blocked'
                    ) AS blocked_items
                FROM {schema}.engagement_working_papers wp
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                GROUP BY wp.engagement_id
            )
            SELECT
                et.id,
                et.engagement_id,
                e.customer_id,
                e.engagement_code,
                e.engagement_name,
                e.engagement_type,
                e.status AS engagement_status,
                e.priority,
                e.workflow_stage,
                e.due_date,
                LOWER(et.role_on_engagement) AS role_on_engagement,
                et.allocation_percent,
                et.start_date,
                et.end_date,
                et.notes,
                et.is_active,
                COALESCE(w.prepared_items, 0) AS prepared_items,
                COALESCE(w.assigned_for_review, 0) AS assigned_for_review,
                COALESCE(w.review_queue_count, 0) AS review_queue_count,
                COALESCE(w.overdue_review_items, 0) AS overdue_review_items,
                COALESCE(w.blocked_items, 0) AS blocked_items
            FROM {schema}.engagement_team et
            JOIN {schema}.engagements e
            ON e.id = et.engagement_id
            AND e.company_id = et.company_id
            LEFT JOIN wp_stats w
            ON w.engagement_id = et.engagement_id
            WHERE et.company_id = %s
            AND et.user_id = %s
            AND e.is_active = TRUE
            AND (%s = FALSE OR et.is_active = TRUE)
            AND (
                    et.start_date IS NULL
                    OR et.start_date <= {as_of_date}
                )
            AND (
                    et.end_date IS NULL
                    OR et.end_date >= {as_of_date}
                )
            ORDER BY
                COALESCE(et.allocation_percent, 0) DESC,
                e.due_date NULLS LAST,
                e.engagement_name ASC
        """
        cur.execute(
            sql,
            (
                user_id,
                user_id,
                user_id,
                user_id,
                user_id,
                user_id,
                company_id,
                company_id,
                user_id,
                active_only,
            ),
        )
        return cur.fetchall()


    def get_team_capacity_user_totals(
        self,
        cur,
        company_id: int,
        *,
        user_id: int,
        active_only: bool = True,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH assignments AS (
                SELECT
                    et.engagement_id,
                    COALESCE(et.allocation_percent, 0) AS allocation_percent
                FROM {schema}.engagement_team et
                JOIN {schema}.engagements e
                ON e.id = et.engagement_id
                AND e.company_id = et.company_id
                WHERE et.company_id = %s
                AND et.user_id = %s
                AND e.is_active = TRUE
                AND (%s = FALSE OR et.is_active = TRUE)
            ),
            reviewer_load AS (
                SELECT
                    COUNT(*) FILTER (
                        WHERE wp.reviewer_user_id = %s
                        AND wp.status IN ('prepared', 'in_review')
                    ) AS review_queue_count,
                    COUNT(*) FILTER (
                        WHERE wp.reviewer_user_id = %s
                        AND wp.status = 'in_review'
                    ) AS in_review_count,
                    COUNT(*) FILTER (
                        WHERE wp.reviewer_user_id = %s
                        AND wp.due_date IS NOT NULL
                        AND wp.due_date < CURRENT_DATE
                        AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
                    ) AS overdue_review_items
                FROM {schema}.engagement_working_papers wp
                JOIN {schema}.engagements e
                ON e.id = wp.engagement_id
                AND e.company_id = wp.company_id
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                AND e.is_active = TRUE
            )
            SELECT
                COALESCE((SELECT COUNT(*) FROM assignments), 0) AS active_assignments,
                COALESCE((SELECT COUNT(DISTINCT engagement_id) FROM assignments), 0) AS active_engagements,
                COALESCE((SELECT SUM(allocation_percent) FROM assignments), 0) AS total_allocation_percent,
                GREATEST(
                    0,
                    100 - COALESCE((SELECT SUM(allocation_percent) FROM assignments), 0)
                ) AS available_capacity_percent,
                COALESCE((SELECT review_queue_count FROM reviewer_load), 0) AS review_queue_count,
                COALESCE((SELECT in_review_count FROM reviewer_load), 0) AS in_review_count,
                COALESCE((SELECT overdue_review_items FROM reviewer_load), 0) AS overdue_review_items
        """
        cur.execute(
            sql,
            (
                company_id,
                user_id,
                active_only,
                user_id,
                user_id,
                user_id,
                company_id,
            ),
        )
        return cur.fetchone()

    def get_portfolio_review_summary(
        self,
        cur,
        company_id: int,
        *,
        customer_id: int = None,
        q: str = "",
        active_only: bool = True,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH scoped_engagements AS (
                SELECT
                    e.id,
                    e.company_id,
                    e.customer_id,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.status,
                    e.priority,
                    e.workflow_stage,
                    e.start_date,
                    e.due_date,
                    c.name AS customer_name
                FROM {schema}.engagements e
                LEFT JOIN {schema}.customers c
                ON c.id = e.customer_id
                AND c.company_id = e.company_id
                WHERE e.company_id = %s
                AND (%s = FALSE OR e.is_active = TRUE)
                AND (%s IS NULL OR e.customer_id = %s)
                AND (
                        %s = ''
                        OR COALESCE(e.engagement_name, '') ILIKE %s
                        OR COALESCE(e.engagement_code, '') ILIKE %s
                        OR COALESCE(e.engagement_type, '') ILIKE %s
                        OR COALESCE(c.name, '') ILIKE %s
                    )
            ),
            wp_stats AS (
                SELECT
                    wp.engagement_id,
                    COUNT(*) AS total_working_papers,
                    COUNT(*) FILTER (WHERE wp.status IN ('reviewed', 'cleared', 'archived')) AS completed_working_papers,
                    COUNT(*) FILTER (
                        WHERE wp.due_date IS NOT NULL
                        AND wp.due_date < CURRENT_DATE
                        AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
                    ) AS overdue_working_papers,
                    COUNT(*) FILTER (WHERE wp.status = 'blocked') AS blocked_working_papers,
                    COUNT(*) FILTER (WHERE wp.status IN ('prepared', 'in_review')) AS in_review_working_papers
                FROM {schema}.engagement_working_papers wp
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                GROUP BY wp.engagement_id
            ),
            deliverable_stats AS (
                SELECT
                    d.engagement_id,
                    COUNT(*) AS total_deliverables,
                    COUNT(*) FILTER (WHERE d.status IN ('approved', 'completed', 'signed_off')) AS completed_deliverables,
                    COUNT(*) FILTER (
                        WHERE d.due_date IS NOT NULL
                        AND d.due_date < CURRENT_DATE
                        AND d.status NOT IN ('approved', 'completed', 'signed_off')
                    ) AS overdue_deliverables,
                    COUNT(*) FILTER (WHERE d.status = 'blocked') AS blocked_deliverables
                FROM {schema}.engagement_deliverables d
                WHERE d.company_id = %s
                AND d.is_active = TRUE
                GROUP BY d.engagement_id
            ),
            signoff_stats AS (
                SELECT
                    s.engagement_id,
                    COUNT(*) AS total_signoff_steps,
                    COUNT(*) FILTER (WHERE s.status IN ('completed', 'approved', 'signed_off')) AS completed_signoff_steps,
                    COUNT(*) FILTER (
                        WHERE s.status NOT IN ('completed', 'approved', 'signed_off')
                    ) AS pending_signoff_steps
                FROM {schema}.engagement_signoff_steps s
                WHERE s.company_id = %s
                AND s.is_active = TRUE
                GROUP BY s.engagement_id
            ),
            escalations AS (
                SELECT
                    x.engagement_id,
                    COUNT(*) FILTER (WHERE x.status NOT IN ('resolved', 'closed')) AS open_escalations
                FROM {schema}.engagement_escalations x
                WHERE x.company_id = %s
                AND x.is_active = TRUE
                GROUP BY x.engagement_id
            ),
            combined AS (
                SELECT
                    e.id,
                    e.customer_id,
                    e.customer_name,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.status,
                    e.priority,
                    e.workflow_stage,
                    e.start_date,
                    e.due_date,

                    COALESCE(w.total_working_papers, 0) AS total_working_papers,
                    COALESCE(w.completed_working_papers, 0) AS completed_working_papers,
                    COALESCE(w.overdue_working_papers, 0) AS overdue_working_papers,
                    COALESCE(w.blocked_working_papers, 0) AS blocked_working_papers,
                    COALESCE(w.in_review_working_papers, 0) AS in_review_working_papers,

                    COALESCE(d.total_deliverables, 0) AS total_deliverables,
                    COALESCE(d.completed_deliverables, 0) AS completed_deliverables,
                    COALESCE(d.overdue_deliverables, 0) AS overdue_deliverables,
                    COALESCE(d.blocked_deliverables, 0) AS blocked_deliverables,

                    COALESCE(s.total_signoff_steps, 0) AS total_signoff_steps,
                    COALESCE(s.completed_signoff_steps, 0) AS completed_signoff_steps,
                    COALESCE(s.pending_signoff_steps, 0) AS pending_signoff_steps,

                    COALESCE(x.open_escalations, 0) AS open_escalations
                FROM scoped_engagements e
                LEFT JOIN wp_stats w
                ON w.engagement_id = e.id
                LEFT JOIN deliverable_stats d
                ON d.engagement_id = e.id
                LEFT JOIN signoff_stats s
                ON s.engagement_id = e.id
                LEFT JOIN escalations x
                ON x.engagement_id = e.id
            )
            SELECT
                COUNT(*) AS total_engagements,
                COUNT(*) FILTER (
                    WHERE due_date IS NOT NULL
                    AND due_date < CURRENT_DATE
                    AND status NOT IN ('completed', 'cancelled', 'archived')
                ) AS overdue_engagements,
                COUNT(*) FILTER (
                    WHERE due_date IS NOT NULL
                    AND due_date >= CURRENT_DATE
                    AND due_date < (CURRENT_DATE + INTERVAL '7 days')
                    AND status NOT IN ('completed', 'cancelled', 'archived')
                ) AS due_this_week,
                COUNT(*) FILTER (
                    WHERE due_date IS NOT NULL
                    AND due_date >= date_trunc('month', CURRENT_DATE)
                    AND due_date < (date_trunc('month', CURRENT_DATE) + INTERVAL '1 month')
                    AND status NOT IN ('completed', 'cancelled', 'archived')
                ) AS due_this_month,
                COUNT(*) FILTER (
                    WHERE blocked_working_papers > 0
                    OR blocked_deliverables > 0
                ) AS blocked_engagements,
                COUNT(*) FILTER (
                    WHERE open_escalations > 0
                ) AS escalated_engagements,
                COUNT(*) FILTER (
                    WHERE pending_signoff_steps > 0
                ) AS pending_signoff_engagements,
                COALESCE(SUM(total_working_papers), 0) AS total_working_papers,
                COALESCE(SUM(completed_working_papers), 0) AS completed_working_papers,
                COALESCE(SUM(total_deliverables), 0) AS total_deliverables,
                COALESCE(SUM(completed_deliverables), 0) AS completed_deliverables
            FROM combined
        """
        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                customer_id, customer_id,
                q.strip(), like, like, like, like,
                company_id,
                company_id,
                company_id,
                company_id,
            ),
        )
        return cur.fetchone()

    def list_portfolio_review_engagements(
        self,
        cur,
        company_id: int,
        *,
        customer_id: int = None,
        q: str = "",
        active_only: bool = True,
        risk_only: bool = False,
        overdue_only: bool = False,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH scoped_engagements AS (
                SELECT
                    e.id,
                    e.company_id,
                    e.customer_id,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.status,
                    e.priority,
                    e.workflow_stage,
                    e.start_date,
                    e.due_date,
                    c.name AS customer_name
                FROM {schema}.engagements e
                LEFT JOIN {schema}.customers c
                ON c.id = e.customer_id
                AND c.company_id = e.company_id
                WHERE e.company_id = %s
                AND (%s = FALSE OR e.is_active = TRUE)
                AND (%s IS NULL OR e.customer_id = %s)
                AND (
                        %s = ''
                        OR COALESCE(e.engagement_name, '') ILIKE %s
                        OR COALESCE(e.engagement_code, '') ILIKE %s
                        OR COALESCE(e.engagement_type, '') ILIKE %s
                        OR COALESCE(c.name, '') ILIKE %s
                    )
            ),
            wp_stats AS (
                SELECT
                    wp.engagement_id,
                    COUNT(*) AS total_working_papers,
                    COUNT(*) FILTER (WHERE wp.status IN ('reviewed', 'cleared', 'archived')) AS completed_working_papers,
                    COUNT(*) FILTER (
                        WHERE wp.due_date IS NOT NULL
                        AND wp.due_date < CURRENT_DATE
                        AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
                    ) AS overdue_working_papers,
                    COUNT(*) FILTER (WHERE wp.status = 'blocked') AS blocked_working_papers,
                    COUNT(*) FILTER (WHERE wp.status IN ('prepared', 'in_review')) AS in_review_working_papers
                FROM {schema}.engagement_working_papers wp
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                GROUP BY wp.engagement_id
            ),
            deliverable_stats AS (
                SELECT
                    d.engagement_id,
                    COUNT(*) AS total_deliverables,
                    COUNT(*) FILTER (WHERE d.status IN ('approved', 'completed', 'signed_off')) AS completed_deliverables,
                    COUNT(*) FILTER (
                        WHERE d.due_date IS NOT NULL
                        AND d.due_date < CURRENT_DATE
                        AND d.status NOT IN ('approved', 'completed', 'signed_off')
                    ) AS overdue_deliverables,
                    COUNT(*) FILTER (WHERE d.status = 'blocked') AS blocked_deliverables
                FROM {schema}.engagement_deliverables d
                WHERE d.company_id = %s
                AND d.is_active = TRUE
                GROUP BY d.engagement_id
            ),
            signoff_stats AS (
                SELECT
                    s.engagement_id,
                    COUNT(*) AS total_signoff_steps,
                    COUNT(*) FILTER (WHERE s.status IN ('completed', 'approved', 'signed_off')) AS completed_signoff_steps,
                    COUNT(*) FILTER (
                        WHERE s.status NOT IN ('completed', 'approved', 'signed_off')
                    ) AS pending_signoff_steps
                FROM {schema}.engagement_signoff_steps s
                WHERE s.company_id = %s
                AND s.is_active = TRUE
                GROUP BY s.engagement_id
            ),
            escalations AS (
                SELECT
                    x.engagement_id,
                    COUNT(*) FILTER (WHERE x.status NOT IN ('resolved', 'closed')) AS open_escalations
                FROM {schema}.engagement_escalations x
                WHERE x.company_id = %s
                AND x.is_active = TRUE
                GROUP BY x.engagement_id
            ),
            combined AS (
                SELECT
                    e.id,
                    e.customer_id,
                    e.customer_name,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.status,
                    e.priority,
                    e.workflow_stage,
                    e.start_date,
                    e.due_date,

                    COALESCE(w.total_working_papers, 0) AS total_working_papers,
                    COALESCE(w.completed_working_papers, 0) AS completed_working_papers,
                    COALESCE(w.overdue_working_papers, 0) AS overdue_working_papers,
                    COALESCE(w.blocked_working_papers, 0) AS blocked_working_papers,
                    COALESCE(w.in_review_working_papers, 0) AS in_review_working_papers,

                    COALESCE(d.total_deliverables, 0) AS total_deliverables,
                    COALESCE(d.completed_deliverables, 0) AS completed_deliverables,
                    COALESCE(d.overdue_deliverables, 0) AS overdue_deliverables,
                    COALESCE(d.blocked_deliverables, 0) AS blocked_deliverables,

                    COALESCE(s.total_signoff_steps, 0) AS total_signoff_steps,
                    COALESCE(s.completed_signoff_steps, 0) AS completed_signoff_steps,
                    COALESCE(s.pending_signoff_steps, 0) AS pending_signoff_steps,

                    COALESCE(x.open_escalations, 0) AS open_escalations
                FROM scoped_engagements e
                LEFT JOIN wp_stats w
                ON w.engagement_id = e.id
                LEFT JOIN deliverable_stats d
                ON d.engagement_id = e.id
                LEFT JOIN signoff_stats s
                ON s.engagement_id = e.id
                LEFT JOIN escalations x
                ON x.engagement_id = e.id
            ),
            final AS (
                SELECT
                    *,
                    CASE
                        WHEN (
                            (due_date IS NOT NULL AND due_date < CURRENT_DATE AND status NOT IN ('completed', 'cancelled', 'archived'))
                            OR overdue_working_papers > 0
                            OR overdue_deliverables > 0
                            OR open_escalations > 0
                        ) THEN 'high'
                        WHEN (
                            blocked_working_papers > 0
                            OR blocked_deliverables > 0
                            OR pending_signoff_steps > 0
                            OR in_review_working_papers > 0
                        ) THEN 'medium'
                        ELSE 'low'
                    END AS risk_band,
                    CASE
                        WHEN (total_working_papers + total_deliverables + total_signoff_steps) = 0 THEN 0
                        ELSE ROUND(
                            (
                                (completed_working_papers + completed_deliverables + completed_signoff_steps)::numeric
                                / NULLIF((total_working_papers + total_deliverables + total_signoff_steps), 0)
                            ) * 100,
                            2
                        )
                    END AS readiness_percent
                FROM combined
            )
            SELECT *
            FROM final
            WHERE (%s = FALSE OR risk_band IN ('high', 'medium'))
            AND (
                    %s = FALSE
                    OR (
                        due_date IS NOT NULL
                        AND due_date < CURRENT_DATE
                        AND status NOT IN ('completed', 'cancelled', 'archived')
                    )
                )
            ORDER BY
                CASE risk_band
                    WHEN 'high' THEN 1
                    WHEN 'medium' THEN 2
                    ELSE 3
                END,
                due_date NULLS LAST,
                engagement_name ASC
            LIMIT %s OFFSET %s
        """
        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                customer_id, customer_id,
                q.strip(), like, like, like, like,
                company_id,
                company_id,
                company_id,
                company_id,
                risk_only,
                overdue_only,
                limit,
                offset,
            ),
        )
        return cur.fetchall()

    def list_portfolio_review_client_risk(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        active_only: bool = True,
        limit: int = 50,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH scoped_engagements AS (
                SELECT
                    e.id,
                    e.customer_id,
                    c.name AS customer_name,
                    e.status,
                    e.due_date
                FROM {schema}.engagements e
                LEFT JOIN {schema}.customers c
                ON c.id = e.customer_id
                AND c.company_id = e.company_id
                WHERE e.company_id = %s
                AND (%s = FALSE OR e.is_active = TRUE)
                AND (
                        %s = ''
                        OR COALESCE(c.name, '') ILIKE %s
                    )
            ),
            wp_stats AS (
                SELECT
                    wp.engagement_id,
                    COUNT(*) FILTER (
                        WHERE wp.due_date IS NOT NULL
                        AND wp.due_date < CURRENT_DATE
                        AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
                    ) AS overdue_working_papers,
                    COUNT(*) FILTER (WHERE wp.status = 'blocked') AS blocked_working_papers
                FROM {schema}.engagement_working_papers wp
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                GROUP BY wp.engagement_id
            ),
            deliverable_stats AS (
                SELECT
                    d.engagement_id,
                    COUNT(*) FILTER (
                        WHERE d.due_date IS NOT NULL
                        AND d.due_date < CURRENT_DATE
                        AND d.status NOT IN ('approved', 'completed', 'signed_off')
                    ) AS overdue_deliverables,
                    COUNT(*) FILTER (WHERE d.status = 'blocked') AS blocked_deliverables
                FROM {schema}.engagement_deliverables d
                WHERE d.company_id = %s
                AND d.is_active = TRUE
                GROUP BY d.engagement_id
            ),
            escalations AS (
                SELECT
                    x.engagement_id,
                    COUNT(*) FILTER (WHERE x.status NOT IN ('resolved', 'closed')) AS open_escalations
                FROM {schema}.engagement_escalations x
                WHERE x.company_id = %s
                AND x.is_active = TRUE
                GROUP BY x.engagement_id
            )
            SELECT
                e.customer_id,
                MAX(e.customer_name) AS customer_name,
                COUNT(*) AS total_engagements,
                COUNT(*) FILTER (
                    WHERE e.due_date IS NOT NULL
                    AND e.due_date < CURRENT_DATE
                    AND e.status NOT IN ('completed', 'cancelled', 'archived')
                ) AS overdue_engagements,
                COALESCE(SUM(COALESCE(w.overdue_working_papers, 0)), 0) AS overdue_working_papers,
                COALESCE(SUM(COALESCE(d.overdue_deliverables, 0)), 0) AS overdue_deliverables,
                COALESCE(SUM(COALESCE(w.blocked_working_papers, 0)), 0) AS blocked_working_papers,
                COALESCE(SUM(COALESCE(d.blocked_deliverables, 0)), 0) AS blocked_deliverables,
                COALESCE(SUM(COALESCE(x.open_escalations, 0)), 0) AS open_escalations
            FROM scoped_engagements e
            LEFT JOIN wp_stats w
            ON w.engagement_id = e.id
            LEFT JOIN deliverable_stats d
            ON d.engagement_id = e.id
            LEFT JOIN escalations x
            ON x.engagement_id = e.id
            GROUP BY e.customer_id
            ORDER BY
                open_escalations DESC,
                overdue_engagements DESC,
                overdue_deliverables DESC,
                customer_name ASC
            LIMIT %s OFFSET %s
        """
        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                q.strip(), like,
                company_id,
                company_id,
                company_id,
                limit,
                offset,
            ),
        )
        return cur.fetchall()

    def list_engagement_escalations(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int = None,
        customer_id: int = None,
        status: str = "",
        severity: str = "",
        escalation_type: str = "",
        source_type: str = "",
        assigned_to_user_id: int = None,
        q: str = "",
        active_only: bool = True,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                e.*,
                eng.engagement_name,
                eng.engagement_code,
                eng.customer_id,
                c.name AS customer_name,

                CONCAT(
                    COALESCE(ru.first_name, ''),
                    CASE
                        WHEN COALESCE(ru.last_name, '') <> '' THEN ' ' || ru.last_name
                        ELSE ''
                    END
                ) AS raised_by_user_name,

                CONCAT(
                    COALESCE(au.first_name, ''),
                    CASE
                        WHEN COALESCE(au.last_name, '') <> '' THEN ' ' || au.last_name
                        ELSE ''
                    END
                ) AS assigned_to_user_name
            FROM {schema}.engagement_escalations e
            JOIN {schema}.engagements eng
            ON eng.id = e.engagement_id
            AND eng.company_id = e.company_id
            LEFT JOIN {schema}.customers c
            ON c.id = eng.customer_id
            AND c.company_id = eng.company_id
            LEFT JOIN public.users ru
            ON ru.id = e.raised_by_user_id
            LEFT JOIN public.users au
            ON au.id = e.assigned_to_user_id
            WHERE e.company_id = %s
            AND (%s = FALSE OR e.is_active = TRUE)
            AND (%s IS NULL OR e.engagement_id = %s)
            AND (%s IS NULL OR eng.customer_id = %s)
            AND (%s = '' OR LOWER(e.status) = LOWER(%s))
            AND (%s = '' OR LOWER(e.severity) = LOWER(%s))
            AND (%s = '' OR LOWER(e.escalation_type) = LOWER(%s))
            AND (%s = '' OR LOWER(e.source_type) = LOWER(%s))
            AND (%s IS NULL OR e.assigned_to_user_id = %s)
            AND (
                    %s = ''
                    OR COALESCE(e.escalation_code, '') ILIKE %s
                    OR COALESCE(e.title, '') ILIKE %s
                    OR COALESCE(e.description, '') ILIKE %s
                    OR COALESCE(eng.engagement_name, '') ILIKE %s
                    OR COALESCE(eng.engagement_code, '') ILIKE %s
                    OR COALESCE(c.name, '') ILIKE %s
                )
            ORDER BY
                CASE e.severity
                    WHEN 'critical' THEN 1
                    WHEN 'high' THEN 2
                    WHEN 'medium' THEN 3
                    ELSE 4
                END,
                CASE e.status
                    WHEN 'open' THEN 1
                    WHEN 'in_progress' THEN 2
                    ELSE 3
                END,
                e.due_date NULLS LAST,
                e.created_at DESC
            LIMIT %s OFFSET %s
        """
        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                engagement_id, engagement_id,
                customer_id, customer_id,
                status.strip(), status.strip(),
                severity.strip(), severity.strip(),
                escalation_type.strip(), escalation_type.strip(),
                source_type.strip(), source_type.strip(),
                assigned_to_user_id, assigned_to_user_id,
                q.strip(),
                like, like, like, like, like, like,
                limit, offset,
            ),
        )
        return cur.fetchall()

