    def set_engagement_override_log_status(
        self,
        cur,
        company_id: int,
        *,
        override_log_id: int,
        status: str,
        decision_outcome: str = None,
        resolution_summary: str = None,
        actor_user_id: int = None,
    ):
        schema = self.company_schema(company_id)
        normalized = (status or "").strip().lower()

        if normalized not in ("open", "under_review", "resolved", "closed"):
            raise ValueError("Invalid status.")

        cur.execute(
            f"""
            UPDATE {schema}.engagement_override_log
            SET
                status = %s,
                decision_outcome = COALESCE(%s, decision_outcome),
                resolution_summary = COALESCE(%s, resolution_summary),
                decided_by_user_id = CASE
                    WHEN %s IN ('resolved', 'closed') THEN COALESCE(decided_by_user_id, %s)
                    ELSE decided_by_user_id
                END,
                resolved_by_user_id = CASE
                    WHEN %s IN ('resolved', 'closed') THEN COALESCE(resolved_by_user_id, %s)
                    ELSE resolved_by_user_id
                END,
                decision_date = CASE
                    WHEN %s IN ('resolved', 'closed') AND decision_date IS NULL THEN NOW()
                    ELSE decision_date
                END,
                resolved_at = CASE
                    WHEN %s = 'resolved' AND resolved_at IS NULL THEN NOW()
                    WHEN %s = 'closed' AND resolved_at IS NULL THEN NOW()
                    ELSE resolved_at
                END,
                closed_at = CASE
                    WHEN %s = 'closed' AND closed_at IS NULL THEN NOW()
                    ELSE closed_at
                END,
                updated_by_user_id = %s,
                updated_at = NOW()
            WHERE company_id = %s
            AND id = %s
            """,
            (
                normalized,
                decision_outcome,
                resolution_summary,
                normalized, actor_user_id,
                normalized, actor_user_id,
                normalized,
                normalized,
                normalized,
                normalized,
                actor_user_id,
                company_id,
                override_log_id,
            ),
        )
        return cur.rowcount


    def get_engagement_override_log_summary(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int = None,
        customer_id: int = None,
        q: str = "",
        active_only: bool = True,
    ):
        schema = self.company_schema(company_id)
        like = f"%{q.strip()}%"

        cur.execute(
            f"""
            SELECT
                COUNT(*) FILTER (WHERE (%s = FALSE OR o.is_active = TRUE)) AS total_items,
                COUNT(*) FILTER (
                    WHERE (%s = FALSE OR o.is_active = TRUE)
                    AND o.status IN ('open', 'under_review')
                ) AS open_items,
                COUNT(*) FILTER (
                    WHERE (%s = FALSE OR o.is_active = TRUE)
                    AND o.severity IN ('high', 'critical')
                ) AS high_risk_items,
                COUNT(*) FILTER (
                    WHERE (%s = FALSE OR o.is_active = TRUE)
                    AND o.override_type = 'exception'
                ) AS exception_items,
                COUNT(*) FILTER (
                    WHERE (%s = FALSE OR o.is_active = TRUE)
                    AND o.status = 'closed'
                ) AS closed_items
            FROM {schema}.engagement_override_log o
            JOIN {schema}.engagements e
            ON e.id = o.engagement_id
            AND e.company_id = o.company_id
            JOIN {schema}.customers c
            ON c.id = e.customer_id
            WHERE o.company_id = %s
            AND (%s IS NULL OR o.engagement_id = %s)
            AND (%s IS NULL OR e.customer_id = %s)
            AND (
                    %s = ''
                    OR COALESCE(e.engagement_name, '') ILIKE %s
                    OR COALESCE(e.engagement_code, '') ILIKE %s
                    OR COALESCE(c.name, '') ILIKE %s
                    OR COALESCE(o.title, '') ILIKE %s
            )
            """,
            (
                active_only,
                active_only,
                active_only,
                active_only,
                active_only,
                company_id,
                engagement_id, engagement_id,
                customer_id, customer_id,
                q.strip(),
                like, like, like, like,
            ),
        )
        return cur.fetchone()

    def insert_ticket(
        self,
        cur,
        company_id: int,
        *,
        user_id: int = None,
        email: str,
        subject: str,
        description: str,
        priority: str = "normal",
        created_by: int = None,
    ):
        schema = self.company_schema(company_id)

        cur.execute(f"""
            INSERT INTO {schema}.support_tickets (
                company_id,
                user_id,
                email,
                subject,
                description,
                status,
                priority,
                created_by
            )
            VALUES (%s,%s,%s,%s,%s,'open',%s,%s)
            RETURNING id
        """, (
            company_id,
            user_id,
            email,
            subject,
            description,
            priority,
            created_by,
        ))
        return cur.fetchone()["id"]

    # List all tickets for a company
    def list_tickets(self, cur, company_id: int):
        schema = self.company_schema(company_id)
        cur.execute(f"""
            SELECT id, email, subject, status, priority, created_at, updated_at
            FROM {schema}.support_tickets
            WHERE company_id = %s
            ORDER BY created_at DESC
        """, (company_id,))
        rows = cur.fetchall() or []

        result = []
        for row in rows:
            if isinstance(row, dict):
                item = row.copy()
            else:
                item = {
                    "id": row[0] if len(row) > 0 else None,
                    "email": row[1] if len(row) > 1 else None,
                    "subject": row[2] if len(row) > 2 else None,
                    "status": row[3] if len(row) > 3 else None,
                    "priority": row[4] if len(row) > 4 else None,
                    "created_at": str(row[5]) if len(row) > 5 and row[5] is not None else None,
                    "updated_at": str(row[6]) if len(row) > 6 and row[6] is not None else None,
                }
            result.append(item)

        return result

    # Get tickets for a specific user
    def get_tickets(self, cur, company_id: int, user_id: int):
        schema = self.company_schema(company_id)
        cur.execute(f"""
            SELECT id, email, subject, status, priority, created_at, updated_at
            FROM {schema}.support_tickets
            WHERE company_id = %s AND user_id = %s
            ORDER BY created_at DESC
        """, (company_id, user_id))
        return cur.fetchall()

    # Get a single ticket by ID
    def get_ticket_by_id(self, cur, company_id: int, ticket_id: int):
        schema = self.company_schema(company_id)
        cur.execute(f"""
            SELECT *
            FROM {schema}.support_tickets
            WHERE company_id = %s AND id = %s
            LIMIT 1
        """, (company_id, ticket_id))
        return cur.fetchone()

    def update_ticket(
        self,
        cur,
        company_id: int,
        ticket_id: int,
        *,
        status: str = None,
        priority: str = None,
        assigned_to: int = None,
        notes: str = None,
        resolved_at=None,
    ):
        schema = self.company_schema(company_id)

        fields = []
        values = []

        if status:
            fields.append("status = %s")
            values.append(status)
        if priority:
            fields.append("priority = %s")
            values.append(priority)
        if assigned_to:
            fields.append("assigned_to = %s")
            values.append(assigned_to)
        if notes:
            fields.append("notes = %s")
            values.append(notes)
        if resolved_at:
            fields.append("resolved_at = %s")
            values.append(resolved_at)

        if not fields:
            return None  # nothing to update

        fields.append("updated_at = NOW()")

        sql = f"""
            UPDATE {schema}.support_tickets
            SET {", ".join(fields)}
            WHERE company_id = %s AND id = %s
            RETURNING id
        """
        values.extend([company_id, ticket_id])

        cur.execute(sql, tuple(values))
        row = cur.fetchone()
        return row["id"] if row else None

    def void_ticket(self, cur, company_id: int, ticket_id: int, *, notes: str = None):
        schema = self.company_schema(company_id)

        fields = ["status = 'void'", "updated_at = NOW()"]
        values = []

        if notes:
            fields.append("notes = %s")
            values.append(notes)

        sql = f"""
            UPDATE {schema}.support_tickets
            SET {", ".join(fields)}
            WHERE company_id = %s AND id = %s
            RETURNING id
        """
        values.extend([company_id, ticket_id])

        cur.execute(sql, tuple(values))
        row = cur.fetchone()
        return row["id"] if row else None

    def _apply_engagement_bridge(body: dict, *, user_id=None) -> dict:
        body = dict(body or {})

        auth_ctx = getattr(g, "auth_context", {}) or {}
        jwt_payload = getattr(request, "jwt_payload", {}) or {}

        is_delegated = (
            auth_ctx.get("is_delegated_company_access")
            or jwt_payload.get("is_delegated_company_access")
            or str(jwt_payload.get("access_scope") or "").lower() == "delegated_workspace"
        )

        if is_delegated:
            body["source_company_id"] = (
                auth_ctx.get("source_company_id")
                or jwt_payload.get("source_company_id")
            )
            body["engagement_company_id"] = (
                auth_ctx.get("source_company_id")
                or jwt_payload.get("source_company_id")
            )
            body["engagement_id"] = (
                auth_ctx.get("engagement_id")
                or jwt_payload.get("engagement_id")
            )

        if user_id:
            body.setdefault("created_by_user_id", user_id)
            body.setdefault("updated_by_user_id", user_id)

        return body

    def get_revenue_contract(self, company_id: int, contract_id: int, cur=None) -> dict | None:
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                rc.*,
                c.name AS customer_name,
                p.project_code,
                p.project_name
            FROM {schema}.revenue_contracts rc
            LEFT JOIN {schema}.customers c
                ON c.id = rc.customer_id
            LEFT JOIN {schema}.projects p
                ON p.company_id = rc.company_id
            AND p.id = rc.project_id
            WHERE rc.company_id = %s
            AND rc.id = %s
            LIMIT 1;
        """

        row = self.fetch_one(sql, (int(company_id), int(contract_id)), cur=cur)

        if not row:
            return None

        payload_json = row.get("payload_json") or {}
        if isinstance(payload_json, str):
            try:
                payload_json = json.loads(payload_json or "{}")
            except Exception:
                payload_json = {}

        if row.get("project_id"):
            payload_json["project_id"] = int(row.get("project_id"))
            payload_json["project_code"] = row.get("project_code")
            payload_json["project_name"] = row.get("project_name")

        row["payload_json"] = payload_json

        return row

    def validate_project_task(
        self,
        company_id: int,
        *,
        project_id: int,
        task_id: int | None,
        cur=None,
    ):
        if not task_id:
            return None

        schema = self.company_schema(company_id)

        row = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.project_tasks
            WHERE company_id = %s
            AND id = %s
            AND project_id = %s
            LIMIT 1
            """,
            (
                int(company_id),
                int(task_id),
                int(project_id),
            ),
            cur=cur,
        )

        if not row:
            raise ValueError(
                f"INVALID_PROJECT_TASK_LINK|project_id={project_id}|task_id={task_id}"
            )

        return row

    def validate_project_cost_code(
        self,
        company_id: int,
        cost_code_id: int | None,
        cur=None,
    ):
        if not cost_code_id:
            return None

        schema = self.company_schema(company_id)

