    def list_revenue_contracts(
        self,
        company_id: int,
        limit: int = 100,
        q: str | None = None,
        status: str | None = None,
        project_id: int | None = None,
        customer_id: int | None = None,
    ):
        schema = self.company_schema(company_id)

        where = ["rc.company_id = %s"]
        params = [int(company_id)]

        if q:
            like = f"%{q.strip()}%"
            where.append("""
                (
                    rc.contract_number ILIKE %s
                    OR rc.contract_title ILIKE %s
                    OR c.name ILIKE %s
                    OR p.project_code ILIKE %s
                    OR p.project_name ILIKE %s
                )
            """)
            params += [like, like, like, like, like]

        if status:
            where.append("rc.status = %s")
            params.append(status)

        if project_id:
            where.append("rc.project_id = %s")
            params.append(int(project_id))

        if customer_id:
            where.append("rc.customer_id = %s")
            params.append(int(customer_id))

        sql = f"""
            SELECT
                rc.*,
                c.name AS customer_name,
                p.project_code,
                p.project_name,

                COALESCE(rc.payload_json->>'settlement_pattern', '') AS settlement_pattern,

                CASE
                    WHEN COALESCE(rc.billed_to_date, 0) - COALESCE(rc.recognized_revenue_to_date, 0) > 0 THEN 'liability'
                    WHEN COALESCE(rc.billed_to_date, 0) - COALESCE(rc.recognized_revenue_to_date, 0) < 0 THEN 'asset'
                    ELSE 'neutral'
                END AS contract_position_type,

                ABS(
                    COALESCE(rc.billed_to_date, 0)
                    - COALESCE(rc.recognized_revenue_to_date, 0)
                ) AS contract_position_amount

            FROM {schema}.revenue_contracts rc
            LEFT JOIN {schema}.customers c
                ON c.id = rc.customer_id
            LEFT JOIN {schema}.projects p
                ON p.company_id = rc.company_id
            AND p.id = rc.project_id
            WHERE {" AND ".join(where)}
            ORDER BY rc.created_at DESC, rc.id DESC
            LIMIT %s
        """

        params.append(int(limit))

        return self.fetch_all(sql, tuple(params)) or []

    def list_revenue_recognition_runs(self, company_id: int, limit: int = 50, contract_id: int | None = None):
        schema = self.company_schema(company_id)
        where = ["1=1"]
        params = []

        if contract_id:
            where.append("contract_id = %s")
            params.append(int(contract_id))

        sql = f"""
            SELECT *
            FROM {schema}.revenue_recognition_runs
            WHERE {" AND ".join(where)}
            ORDER BY id DESC
            LIMIT %s
        """
        params.append(int(limit))
        return self.fetch_all(sql, tuple(params)) or []


    def create_revenue_contract(self, company_id: int, data: dict, user_id: int | None = None) -> dict:
        import json

        schema = self.company_schema(company_id)

        customer_id = data.get("customer_id") or data.get("customerId")
        customer_id = int(customer_id) if customer_id not in (None, "", 0, "0") else None

        if customer_id is None:
            raise ValueError("Customer is required for revenue contracts")

        project_id = data.get("project_id") or data.get("projectId")
        project_id = int(project_id) if project_id not in (None, "", 0, "0") else None

        with self._conn_cursor() as (conn, cur):
            customer = self.fetch_one(
                f"""
                SELECT id, name
                FROM {schema}.customers
                WHERE id=%s
                LIMIT 1
                """,
                (customer_id,),
                cur=cur,
            )

            if not customer:
                raise ValueError("Selected customer not found")

            project = None
            if project_id:
                project = self.fetch_one(
                    f"""
                    SELECT id, project_code, project_name, customer_id
                    FROM {schema}.projects
                    WHERE company_id=%s
                    AND id=%s
                    LIMIT 1
                    """,
                    (int(company_id), int(project_id)),
                    cur=cur,
                )

                if not project:
                    raise ValueError("Selected project not found")

                if project.get("customer_id") and int(project["customer_id"]) != int(customer_id):
                    raise ValueError("Selected project belongs to a different customer")

            data, financing_component_amount = self._normalize_and_validate_sfc(data)
            self._validate_contract_billing_method(data)
            data = self._validate_contract_milestones(data)

            sql = f"""
            INSERT INTO {schema}.revenue_contracts (
                company_id,
                customer_id,
                project_id,
                contract_number,
                contract_title,
                status,
                contract_currency,
                contract_date,
                start_date,
                end_date,
                billing_method,
                transaction_price,
                variable_consideration_est,
                variable_consideration_constrained,
                financing_component_amount,
                has_significant_financing_component,
                is_over_time,
                notes,
                payload_json,
                created_by_user_id,
                updated_by_user_id,
                source_company_id,
                engagement_company_id,
                engagement_id
            )
            VALUES (
                %s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,
                %s,%s,%s,%s::jsonb,
                %s,%s,%s,%s,%s,%s
            )
            RETURNING *;
            """

            params = (
                int(company_id),
                customer_id,
                project_id,
                (data.get("contract_number") or "").strip(),
                (data.get("contract_title") or "").strip(),
                (data.get("status") or "draft").strip().lower(),
                (data.get("contract_currency") or "USD").strip().upper(),
                data.get("contract_date"),
                data.get("start_date"),
                data.get("end_date"),
                (data.get("billing_method") or "milestone").strip().lower(),
                float(data.get("transaction_price") or 0.0),
                float(data.get("variable_consideration_est") or 0.0),
                float(data.get("variable_consideration_constrained") or 0.0),
                float(financing_component_amount or 0.0),
                bool(data.get("has_significant_financing_component", False)),
                bool(data.get("is_over_time", True)),
                data.get("notes"),
                json.dumps(data.get("payload_json") or {}, default=str),

                int(user_id) if user_id else None,
                data.get("updated_by_user_id") or user_id,
                data.get("source_company_id"),
                data.get("engagement_company_id"),
                data.get("engagement_id"),
            )

            cur.execute(sql, params)
            row = dict(cur.fetchone())

            row["customer_name"] = customer.get("name")

            if project:
                row["project_code"] = project.get("project_code")
                row["project_name"] = project.get("project_name")

            contract_ref = (row.get("contract_number") or f"REV-CON-{row.get('id')}").strip()

            payload_json = row.get("payload_json") or {}
            if isinstance(payload_json, str):
                try:
                    payload_json = json.loads(payload_json)
                except Exception:
                    payload_json = {}

            engagement_company_id = (
                data.get("engagement_company_id")
                or data.get("source_company_id")
                or company_id
            )
            engagement_id = (
                data.get("engagement_id")
                or payload_json.get("engagement_id")
            )
            if engagement_id:
                try:
                    self.upsert_engagement_posting_activity(
                        cur,
                        company_id=int(engagement_company_id),
                        engagement_id=int(engagement_id),
                        posting_date=row.get("contract_date") or row.get("start_date"),
                        module_name="revenue",
                        event_type="created",
                        reference_no=contract_ref,
                        description=f"Created revenue contract {contract_ref}",
                        prepared_by_user_id=int(user_id) if user_id else None,
                        reviewer_user_id=None,
                        status=str(row.get("status") or "draft"),
                        amount=float(row.get("transaction_price") or 0.0),
                        currency_code=(row.get("contract_currency") or "USD"),
                        source_table="revenue_contracts",
                        source_id=int(row["id"]),
                        notes="Revenue contract created",
                        created_by_user_id=int(user_id) if user_id else None,
                        updated_by_user_id=int(user_id) if user_id else None,
                    )
                except Exception:
                    pass

            try:
                tax_profile = (
                    self.revenue_contract_tax_profile_ensure(
                        company_id=int(company_id),
                        contract_id=int(row["id"]),
                        user_id=(
                            int(user_id)
                            if user_id
                            else None
                        ),
                        cur=cur,
                    )
                )

                row["revenue_tax_profile"] = tax_profile

            except ValueError as exc:
                row["revenue_tax_profile"] = None
                row["revenue_tax_profile_warning"] = str(exc)
            conn.commit()

        return row

    def update_revenue_contract(self, company_id: int, contract_id: int, data: dict, user_id: int | None = None) -> dict:
        import json

        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            before = self.get_revenue_contract(company_id, contract_id, cur=cur)
            if not before:
                raise ValueError("Revenue contract not found")

            data, financing_component_amount = self._normalize_and_validate_sfc(data, existing=before)
            self._validate_contract_billing_method(data)
            data = self._validate_contract_milestones(data)

            customer_id = data.get("customer_id") or data.get("customerId")

            if customer_id in ("", 0, "0"):
                customer_id = None
            elif customer_id is not None:
                customer_id = int(customer_id)

                customer = self.fetch_one(
                    f"""
                    SELECT id, name
                    FROM {schema}.customers
                    WHERE id=%s
                    LIMIT 1
                    """,
                    (customer_id,),
                    cur=cur,
                )

                if not customer:
                    raise ValueError("Selected customer not found")

            project_id = data.get("project_id") or data.get("projectId")

            if project_id in ("", 0, "0"):
                project_id = None
            elif project_id is not None:
                project_id = int(project_id)

                effective_customer_id = customer_id or before.get("customer_id")

                project = self.fetch_one(
                    f"""
                    SELECT id, project_code, project_name, customer_id
                    FROM {schema}.projects
                    WHERE company_id=%s
                    AND id=%s
                    LIMIT 1
                    """,
                    (int(company_id), int(project_id)),
                    cur=cur,
                )

                if not project:
                    raise ValueError("Selected project not found")

                if project.get("customer_id") and effective_customer_id:
                    if int(project["customer_id"]) != int(effective_customer_id):
                        raise ValueError("Selected project belongs to a different customer")

            payload_json_param = None
            if "payload_json" in data:
                payload_json_param = json.dumps(data.get("payload_json") or {}, default=str)

            sql = f"""
            UPDATE {schema}.revenue_contracts
            SET
                customer_id = COALESCE(%s, customer_id),
                project_id = COALESCE(%s, project_id),
                contract_number = COALESCE(NULLIF(%s,''), contract_number),
                contract_title = COALESCE(NULLIF(%s,''), contract_title),
                status = COALESCE(NULLIF(%s,''), status),
                contract_currency = COALESCE(NULLIF(%s,''), contract_currency),
                contract_date = COALESCE(%s, contract_date),
                start_date = COALESCE(%s, start_date),
                end_date = COALESCE(%s, end_date),
                billing_method = COALESCE(NULLIF(%s,''), billing_method),
                transaction_price = COALESCE(%s, transaction_price),
                variable_consideration_est = COALESCE(%s, variable_consideration_est),
                variable_consideration_constrained = COALESCE(%s, variable_consideration_constrained),
                financing_component_amount = COALESCE(%s, financing_component_amount),
                has_significant_financing_component = COALESCE(%s, has_significant_financing_component),
                is_over_time = COALESCE(%s, is_over_time),
                notes = COALESCE(%s, notes),
                payload_json = COALESCE(%s::jsonb, payload_json),
                updated_by_user_id = COALESCE(%s, updated_by_user_id),
                source_company_id = COALESCE(%s, source_company_id),
                engagement_company_id = COALESCE(%s, engagement_company_id),
                engagement_id = COALESCE(%s, engagement_id),
                updated_at = NOW()
            WHERE company_id = %s
            AND id = %s
            RETURNING *;
            """

            cur.execute(
                sql,
                (
                    customer_id,
                    project_id,
                    (data.get("contract_number") or "").strip(),
                    (data.get("contract_title") or "").strip(),
                    (data.get("status") or "").strip().lower(),
                    (data.get("contract_currency") or "").strip().upper(),
                    data.get("contract_date"),
                    data.get("start_date"),
                    data.get("end_date"),
                    (data.get("billing_method") or "").strip().lower(),
                    float(data["transaction_price"]) if data.get("transaction_price") is not None else None,
                    float(data["variable_consideration_est"]) if data.get("variable_consideration_est") is not None else None,
                    float(data["variable_consideration_constrained"]) if data.get("variable_consideration_constrained") is not None else None,
                    (
                        float(financing_component_amount)
                        if data.get("has_significant_financing_component") is not None
                        or data.get("payload_json") is not None
                        else None
                    ),
                    data.get("has_significant_financing_component"),
                    data.get("is_over_time"),
                    data.get("notes"),
                    payload_json_param,
                    int(user_id) if user_id else data.get("updated_by_user_id"),
                    data.get("source_company_id"),
                    data.get("engagement_company_id"),
                    data.get("engagement_id"),
                    int(company_id),
                    int(contract_id),
                ),
            )

            after = dict(cur.fetchone())

            if after and after.get("customer_id"):
                cust = self.fetch_one(
                    f"""
                    SELECT name
                    FROM {schema}.customers
                    WHERE id=%s
                    LIMIT 1
                    """,
                    (int(after["customer_id"]),),
                    cur=cur,
                )
                after["customer_name"] = (cust or {}).get("name")

            if after and after.get("project_id"):
                project = self.fetch_one(
                    f"""
                    SELECT project_code, project_name
                    FROM {schema}.projects
                    WHERE company_id=%s
                    AND id=%s
                    LIMIT 1
                    """,
                    (int(company_id), int(after["project_id"])),
                    cur=cur,
                )
                after["project_code"] = (project or {}).get("project_code")
                after["project_name"] = (project or {}).get("project_name")

            try:
                tax_profile = (
                    self.revenue_contract_tax_profile_ensure(
                        company_id=int(company_id),
                        contract_id=int(contract_id),
                        user_id=(
                            int(user_id)
                            if user_id
                            else None
                        ),
                        cur=cur,
                    )
                )

                after["revenue_tax_profile"] = tax_profile

            except ValueError as exc:
                after["revenue_tax_profile"] = None
                after["revenue_tax_profile_warning"] = str(exc)

            conn.commit()

        return {
            "before": before,
            "after": after,
        }

    def _validate_obligation_progress_payload(self, data: dict) -> dict:
        
        payload_json = data.get("payload_json") or {}
        if not isinstance(payload_json, dict):
            payload_json = {}
        else:
            payload_json = dict(payload_json)

        def clear_milestone_link():
            payload_json.pop("linked_billing_milestone_code", None)
            payload_json.pop("linked_billing_milestone", None)
            payload_json.pop("milestone_code", None)
            
        timing = str(data.get("recognition_timing") or "point_in_time").strip().lower()
        method = str(data.get("progress_method") or "").strip().lower()

        if timing != "over_time":
            data["payload_json"] = payload_json
            return data

        if method == "cost_to_cost":
            expected_total_cost = float(data.get("expected_total_cost") or 0.0)
            if expected_total_cost <= 0:
                raise ValueError("Cost-to-cost requires expected total cost.")

            payload_json.pop("units_done", None)
            payload_json.pop("units_total", None)
            clear_milestone_link()

        elif method in {"units", "units_delivered"}:
            units_total = float(payload_json.get("units_total") or payload_json.get("total_units") or 0.0)
            if units_total <= 0:
                raise ValueError("Units-based progress requires payload_json.units_total > 0.")

            if float(data.get("expected_total_cost") or 0.0) < 0:
                raise ValueError("Expected total cost cannot be negative.")

            data["progress_percent"] = None
            clear_milestone_link()

        elif method == "milestone":
            milestone_code = str(
                payload_json.get("milestone_code") or ""
            ).strip()

            obligation_milestones = (
                payload_json.get("obligation_milestones") or []
            )

            has_table = (
                isinstance(obligation_milestones, list)
                and len(obligation_milestones) > 0
            )

            if not milestone_code and not has_table:
                raise ValueError(
                    "Milestone progress requires milestone_code or obligation_milestones."
                )

            if float(data.get("expected_total_cost") or 0.0) < 0:
                raise ValueError(
                    "Expected milestone cost cannot be negative."
                )

            data["progress_percent"] = 0.0

            payload_json.pop("units_done", None)
            payload_json.pop("units_total", None)

            if float(data.get("expected_total_cost") or 0.0) < 0:
                raise ValueError("Expected milestone cost cannot be negative.")

            data["progress_percent"] = 0.0
            payload_json.pop("units_done", None)
            payload_json.pop("units_total", None)

        elif method == "manual":
            progress_percent = data.get("progress_percent")
            if progress_percent is not None:
                pct = float(progress_percent or 0.0)
                if pct < 0 or pct > 100:
                    raise ValueError("progress_percent must be between 0 and 100.")

            payload_json.pop("units_done", None)
            payload_json.pop("units_total", None)
            clear_milestone_link()

        elif method == "time_elapsed":
            start_date = payload_json.get("performance_start_date")
            end_date = payload_json.get("performance_end_date")

            if not start_date or not end_date:
                raise ValueError("Time elapsed requires performance_start_date and performance_end_date.")

            if str(start_date) >= str(end_date):
                raise ValueError("performance_end_date must be after performance_start_date.")

            if data.get("progress_percent") is not None:
                pct = float(data.get("progress_percent") or 0.0)

                if pct < 0 or pct > 100:
                    raise ValueError(
                        "progress_percent must be between 0 and 100."
                    )
            payload_json.pop("units_done", None)
            payload_json.pop("units_total", None)
            clear_milestone_link()

        data["payload_json"] = payload_json
        return data

    def _contract_milestones(self, contract: dict) -> list[dict]:
        payload = contract.get("payload_json") or {}
        if not isinstance(payload, dict):
            return []

        billing_cfg = payload.get("billing_config") or {}
        if not isinstance(billing_cfg, dict):
            return []

        milestones = billing_cfg.get("milestones") or []
        return [m for m in milestones if isinstance(m, dict)]

    def add_revenue_obligation(self, company_id: int, contract_id: int, data: dict, user_id: int | None = None) -> dict:
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            contract = self.get_revenue_contract(company_id, contract_id, cur=cur)
            if not contract:
                raise ValueError("Invalid contract: contract does not exist")

            payload_contract_id = data.get("contract_id")
            if payload_contract_id not in (None, "", 0, "0"):
                if int(payload_contract_id) != int(contract_id):
                    raise ValueError("Payload contract_id does not match selected contract")

            status = str(contract.get("status") or "").strip().lower()
            approval_status = str(contract.get("approval_status") or "").strip().lower()

            if status not in {"draft", "active"}:
                raise ValueError(f"Cannot add obligation to contract with status '{status}'")

            if approval_status not in {"draft", "approved"}:
                raise ValueError(f"Cannot add obligation when approval_status is '{approval_status}'")

            if float(contract.get("recognized_revenue_to_date") or 0.0) > 0:
                raise ValueError("Cannot add obligations after revenue recognition has started")

            # apply contract-level billing rules + progress payload rules
            data = self._validate_obligation_against_contract(contract, data)
            data = self._validate_obligation_progress_payload(data)

            existing = self.fetch_one(
                f"""
                SELECT COALESCE(SUM(allocated_transaction_price), 0) AS total_allocated
                FROM {schema}.revenue_obligations
                WHERE contract_id = %s
                """,
                (int(contract_id),),
                cur=cur,
            ) or {}

            existing_allocated = float(existing.get("total_allocated") or 0.0)
            new_allocated = float(data.get("allocated_transaction_price") or 0.0)
            contract_price = float(contract.get("transaction_price") or 0.0)

            if existing_allocated + new_allocated > contract_price:
                raise ValueError(
                    f"Allocated obligations exceed contract price. "
                    f"Existing: {existing_allocated:.2f}, New: {new_allocated:.2f}, Limit: {contract_price:.2f}"
                )

            obligation_code = (data.get("obligation_code") or "").strip()
            obligation_name = (data.get("obligation_name") or "").strip()
            distinct_flag = bool(data.get("distinct_flag", True))
            obligation_status = (data.get("obligation_status") or "draft").strip().lower()

            recognition_timing = (data.get("recognition_timing") or "point_in_time").strip().lower()
            if recognition_timing not in {"over_time", "point_in_time"}:
                raise ValueError("Invalid recognition timing. Use 'over_time' or 'point_in_time'.")

            recognition_trigger = (data.get("recognition_trigger") or "").strip().lower() or None

            standalone_selling_price = float(data.get("standalone_selling_price") or 0.0)
            allocated_transaction_price = float(data.get("allocated_transaction_price") or 0.0)
            expected_total_cost = float(data.get("expected_total_cost") or 0.0)
            actual_cost_to_date = float(data.get("actual_cost_to_date") or 0.0)
            progress_percent = float(data.get("progress_percent") or 0.0)
            revenue_to_date = float(data.get("revenue_to_date") or 0.0)
            recognized_at_point_in_time_date = data.get("recognized_at_point_in_time_date")
            notes = data.get("notes")

            raw_progress_method = (data.get("progress_method") or "").strip().lower()

            satisfaction_status = (data.get("satisfaction_status") or "pending").strip().lower()
            if satisfaction_status not in {"pending", "satisfied", "reversed"}:
                raise ValueError("Invalid satisfaction status.")

            satisfied_at = data.get("satisfied_at")
            satisfaction_evidence_ref = (data.get("satisfaction_evidence_ref") or "").strip() or None
            satisfaction_confirmed_by_user_id = int(user_id) if user_id and satisfaction_status == "satisfied" else None

            valid_progress_methods = {
                "cost_to_cost",
                "milestone",
                "units",
                "time_elapsed",
                "manual",
                "units_delivered",
            }

            if recognition_timing == "point_in_time":
                if not recognition_trigger:
                    raise ValueError("Point-in-time obligations require a recognition trigger.")

                progress_method = None
                expected_total_cost = 0.0
                actual_cost_to_date = 0.0
                progress_percent = 0.0

                if satisfaction_status in {"satisfied", "reversed"}:
                    satisfied_at = satisfied_at or recognized_at_point_in_time_date
                    if not satisfied_at:
                        raise ValueError("Satisfied point-in-time obligations require satisfied_at.")

            else:
                progress_method = raw_progress_method or "cost_to_cost"

                if progress_method not in valid_progress_methods:
                    raise ValueError("Invalid progress method for over-time obligation.")

                if progress_method == "cost_to_cost" and expected_total_cost <= 0:
                    raise ValueError("Over-time obligations using cost-to-cost require expected total cost.")

                recognized_at_point_in_time_date = None
                recognition_trigger = None
                satisfaction_status = "pending"
                satisfied_at = None
                satisfaction_evidence_ref = None
                satisfaction_confirmed_by_user_id = None

            payload_json = dict(data.get("payload_json") or {})

            # preserve contract billing context exactly as set by validator
            contract_payload = contract.get("payload_json") or {}
            if not isinstance(contract_payload, dict):
                contract_payload = {}
            billing_cfg = contract_payload.get("billing_config") or {}
            if not isinstance(billing_cfg, dict):
                billing_cfg = {}

            payload_json["milestone_basis"] = (
                payload_json.get("milestone_basis")
                or billing_cfg.get("milestone_basis")
                or "obligation"
            )

            contract_method = str(contract.get("billing_method") or "milestone").strip().lower()
            if not payload_json.get("billing_source"):
                if contract_method == "periodic":
                    payload_json["billing_source"] = "contract"
                elif contract_method == "progress":
                    payload_json["billing_source"] = "contract"
                elif contract_method == "manual":
                    payload_json["billing_source"] = "manual"
                elif contract_method == "milestone" and payload_json.get("milestone_basis") == "custom":
                    payload_json["billing_source"] = "custom_milestone"
                else:
                    payload_json["billing_source"] = "obligation"

            # final milestone check after full normalization
            # ----------------------------------------------------------
            # Linked billing milestone validation
            # ----------------------------------------------------------

            linked_milestone_code = str(
                payload_json.get("linked_billing_milestone_code")
                or payload_json.get("milestone_code")
                or ""
            ).strip()

            if linked_milestone_code:

                milestones = self._contract_milestones(contract)

                linked_milestone = next(
                    (
                        m for m in milestones
                        if str(m.get("code") or "").strip().lower()
                        == linked_milestone_code.lower()
                    ),
                    None
                )

                if not linked_milestone:
                    raise ValueError(
                        f"Milestone code '{linked_milestone_code}' is not defined on the contract."
                    )

                payload_json["linked_billing_milestone_code"] = linked_milestone_code
                payload_json["milestone_code"] = linked_milestone_code
                payload_json["linked_billing_milestone"] = linked_milestone

            payload_json["catalog_item_type"] = data.get("catalog_item_type")
            payload_json["catalog_item_id"] = data.get("catalog_item_id")
            payload_json["catalog_item_code"] = data.get("catalog_item_code")
            payload_json["catalog_item_label"] = data.get("catalog_item_label")
            payload_json["recognition_trigger"] = recognition_trigger

            payload_json = self._enrich_revenue_obligation_project_link(
                company_id=int(company_id),
                contract=contract,
                data=data,
                payload_json=payload_json,
                cur=cur,
            )

            cur.execute(
                f"""
                INSERT INTO {schema}.revenue_obligations (
                    company_id,
                    contract_id,
                    obligation_code,
                    obligation_name,
                    distinct_flag,
                    recognition_timing,
                    progress_method,
                    obligation_status,
                    standalone_selling_price,
                    allocated_transaction_price,
                    expected_total_cost,
                    actual_cost_to_date,
                    progress_percent,
                    revenue_to_date,
                    recognized_at_point_in_time_date,
                    recognition_trigger,
                    satisfaction_status,
                    satisfied_at,
                    satisfaction_evidence_ref,
                    satisfaction_confirmed_by_user_id,
                    notes,
                    payload_json
                )
                VALUES (
                    %s, %s, %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s, %s,
                    %s, %s::jsonb
                )
                RETURNING *;
                """,
                (
                    int(company_id),
                    int(contract_id),
                    obligation_code,
                    obligation_name,
                    distinct_flag,
                    recognition_timing,
                    progress_method,
                    obligation_status,
                    standalone_selling_price,
                    allocated_transaction_price,
                    expected_total_cost,
                    actual_cost_to_date,
                    progress_percent,
                    revenue_to_date,
                    recognized_at_point_in_time_date,
                    recognition_trigger,
                    satisfaction_status,
                    satisfied_at,
                    satisfaction_evidence_ref,
                    satisfaction_confirmed_by_user_id,
                    notes,
                    _json_dumps(payload_json),
                )
            )

            row = dict(cur.fetchone())
            conn.commit()

        return row

    def update_revenue_obligation(self, company_id: int, obligation_id: int, data: dict, user_id: int | None = None) -> dict:
        import json

        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            before = self.fetch_one(
                f"SELECT * FROM {schema}.revenue_obligations WHERE id=%s LIMIT 1;",
                (int(obligation_id),),
                cur=cur,
            )
            if not before:
                raise ValueError("Revenue obligation not found")

            contract = self.get_revenue_contract(company_id, int(before["contract_id"]), cur=cur)
            if not contract:
                raise ValueError("Parent revenue contract not found")

            data = self._validate_obligation_against_contract(contract, data)
            data = self._validate_obligation_progress_payload(data)

            timing = (
                data.get("recognition_timing")
                if data.get("recognition_timing") not in (None, "")
                else before.get("recognition_timing") or "point_in_time"
            )
            timing = str(timing).strip().lower()

            progress_method = (
                data.get("progress_method")
                if data.get("progress_method") not in (None, "")
                else before.get("progress_method")
            )
            progress_method = (str(progress_method).strip().lower() if progress_method is not None else None)

            expected_total_cost = (
                float(data["expected_total_cost"])
                if data.get("expected_total_cost") is not None
                else float(before.get("expected_total_cost") or 0.0)
            )

            pit_date = (
                data.get("recognized_at_point_in_time_date")
                if "recognized_at_point_in_time_date" in data
                else before.get("recognized_at_point_in_time_date")
            )

            before_payload = before.get("payload_json") or {}
            if isinstance(before_payload, str):
                try:
                    before_payload = json.loads(before_payload)
                except Exception:
                    before_payload = {}

            payload_json = dict(before_payload)

            contract_payload = contract.get("payload_json") or {}
            if not isinstance(contract_payload, dict):
                contract_payload = {}
            billing_cfg = contract_payload.get("billing_config") or {}
            if not isinstance(billing_cfg, dict):
                billing_cfg = {}

            payload_json["milestone_basis"] = (
                payload_json.get("milestone_basis")
                or billing_cfg.get("milestone_basis")
                or "obligation"
            )

            contract_method = str(contract.get("billing_method") or "milestone").strip().lower()
            if not payload_json.get("billing_source"):
                if contract_method == "periodic":
                    payload_json["billing_source"] = "contract"
                elif contract_method == "progress":
                    payload_json["billing_source"] = "contract"
                elif contract_method == "manual":
                    payload_json["billing_source"] = "manual"
                elif contract_method == "milestone" and payload_json.get("milestone_basis") == "custom":
                    payload_json["billing_source"] = "custom_milestone"
                else:
                    payload_json["billing_source"] = "obligation"

            pit_trigger = (
                data.get("recognition_trigger")
                if "recognition_trigger" in data
                else before.get("recognition_trigger")
                or before_payload.get("recognition_trigger")
            )
            pit_trigger = (pit_trigger or "").strip().lower()

            satisfaction_status = (
                data.get("satisfaction_status")
                if data.get("satisfaction_status") not in (None, "")
                else before.get("satisfaction_status") or "pending"
            )
            satisfaction_status = str(satisfaction_status).strip().lower()

            satisfied_at = (
                data.get("satisfied_at")
                if "satisfied_at" in data
                else before.get("satisfied_at")
            )

            satisfaction_evidence_ref = (
                data.get("satisfaction_evidence_ref")
                if "satisfaction_evidence_ref" in data
                else before.get("satisfaction_evidence_ref")
            )

            if timing not in {"over_time", "point_in_time"}:
                raise ValueError("Invalid recognition timing. Use 'over_time' or 'point_in_time'.")

            if satisfaction_status not in {"pending", "satisfied", "reversed"}:
                raise ValueError("Invalid satisfaction status.")

            if timing == "point_in_time":
                if not pit_trigger:
                    raise ValueError("Point-in-time obligations require a recognition trigger.")

                data["expected_total_cost"] = 0.0
                data["actual_cost_to_date"] = 0.0
                data["progress_percent"] = 0.0
                data["progress_method"] = None

                if satisfaction_status in {"satisfied", "reversed"}:
                    satisfied_at = satisfied_at or pit_date
                    if not satisfied_at:
                        raise ValueError("Satisfied point-in-time obligations require satisfied_at.")

            if timing == "over_time":
                allowed_methods = {"cost_to_cost", "milestone", "units", "time_elapsed", "manual", "units_delivered"}
                if progress_method not in allowed_methods:
                    raise ValueError("Invalid progress method for over-time obligation.")

                data["recognized_at_point_in_time_date"] = None
                data["recognition_trigger"] = None
                satisfaction_status = "pending"
                satisfied_at = None
                satisfaction_evidence_ref = None

                if progress_method == "cost_to_cost":
                    if expected_total_cost <= 0:
                        raise ValueError("Cost-to-cost requires expected total cost.")

                    data["progress_percent"] = None
                    payload_json.pop("units_done", None)
                    payload_json.pop("units_total", None)
                    payload_json.pop("linked_billing_milestone_code", None)
                    payload_json.pop("linked_billing_milestone", None)
                    payload_json.pop("milestone_code", None)           

                elif progress_method in {"units", "units_delivered"}:
                    data["actual_cost_to_date"] = 0.0
                    data["progress_percent"] = None

                    payload_json.pop("linked_billing_milestone_code", None)
                    payload_json.pop("linked_billing_milestone", None)
                    payload_json.pop("milestone_code", None)

                elif progress_method == "manual":
                    data["actual_cost_to_date"] = 0.0

                    payload_json.pop("units_done", None)
                    payload_json.pop("units_total", None)
                    payload_json.pop("linked_billing_milestone_code", None)
                    payload_json.pop("linked_billing_milestone", None)
                    payload_json.pop("milestone_code", None)

                elif progress_method == "milestone":
                    milestone_basis = payload_json.get("milestone_basis") or "obligation"

                    data["actual_cost_to_date"] = None
                    data["progress_percent"] = 0.0
                    payload_json.pop("units_done", None)
                    payload_json.pop("units_total", None)

                    if milestone_basis == "obligation":
                        effective_name = (data.get("obligation_name") or before.get("obligation_name") or "").strip()
                        if not effective_name:
                            raise ValueError("Obligation-based milestone requires obligation_name.")
                    else:
                        if not str(payload_json.get("milestone_code") or "").strip():
                            raise ValueError("Custom milestone progress requires payload_json.milestone_code.")

                elif progress_method == "time_elapsed":
                    data["actual_cost_to_date"] = 0.0
                    data["progress_percent"] = None

                    payload_json.pop("units_done", None)
                    payload_json.pop("units_total", None)
                    payload_json.pop("linked_billing_milestone_code", None)
                    payload_json.pop("linked_billing_milestone", None)
                    payload_json.pop("milestone_code", None)

            if "payload_json" in data and isinstance(data.get("payload_json"), dict):
                payload_json.update(data.get("payload_json") or {})

            linked_milestone_code = str(
                payload_json.get("linked_billing_milestone_code")
                or payload_json.get("milestone_code")
                or ""
            ).strip()

            if linked_milestone_code:

                milestones = self._contract_milestones(contract)

                linked_milestone = next(
                    (
                        m for m in milestones
                        if str(m.get("code") or "").strip().lower()
                        == linked_milestone_code.lower()
                    ),
                    None
                )

                if not linked_milestone:
                    raise ValueError(
                        f"Milestone code '{linked_milestone_code}' is not defined on the contract."
                    )

                payload_json["linked_billing_milestone_code"] = linked_milestone_code
                payload_json["milestone_code"] = linked_milestone_code
                payload_json["linked_billing_milestone"] = linked_milestone

            # preserve contract context again after update merge
            payload_json["milestone_basis"] = (
                payload_json.get("milestone_basis")
                or billing_cfg.get("milestone_basis")
                or "obligation"
            )

            if not payload_json.get("billing_source"):
                if contract_method == "periodic":
                    payload_json["billing_source"] = "contract"
                elif contract_method == "progress":
                    payload_json["billing_source"] = "contract"
                elif contract_method == "manual":
                    payload_json["billing_source"] = "manual"
                elif contract_method == "milestone" and payload_json.get("milestone_basis") == "custom":
                    payload_json["billing_source"] = "custom_milestone"
                else:
                    payload_json["billing_source"] = "obligation"

            if "catalog_item_type" in data:
                payload_json["catalog_item_type"] = data.get("catalog_item_type")
            if "catalog_item_id" in data:
                payload_json["catalog_item_id"] = data.get("catalog_item_id")
            if "catalog_item_code" in data:
                payload_json["catalog_item_code"] = data.get("catalog_item_code")
            if "catalog_item_label" in data:
                payload_json["catalog_item_label"] = data.get("catalog_item_label")
            if "recognition_trigger" in data:
                payload_json["recognition_trigger"] = data.get("recognition_trigger")

            payload_json = self._enrich_revenue_obligation_project_link(
                company_id=int(company_id),
                contract=contract,
                data=data,
                payload_json=payload_json,
                cur=cur,
            )

            cur.execute(
                f"""
                UPDATE {schema}.revenue_obligations
                SET
                    obligation_name = COALESCE(NULLIF(%s,''), obligation_name),
                    distinct_flag = COALESCE(%s, distinct_flag),
                    recognition_timing = COALESCE(NULLIF(%s,''), recognition_timing),
                    progress_method = %s,
                    obligation_status = COALESCE(NULLIF(%s,''), obligation_status),
                    standalone_selling_price = COALESCE(%s, standalone_selling_price),
                    allocated_transaction_price = COALESCE(%s, allocated_transaction_price),
                    expected_total_cost = COALESCE(%s, expected_total_cost),
                    actual_cost_to_date = COALESCE(%s, actual_cost_to_date),
                    progress_percent = COALESCE(%s, progress_percent),
                    revenue_to_date = COALESCE(%s, revenue_to_date),
                    recognized_at_point_in_time_date = %s,
                    recognition_trigger = %s,
                    satisfaction_status = %s,
                    satisfied_at = %s,
                    satisfaction_evidence_ref = %s,
                    satisfaction_confirmed_by_user_id = %s,
                    notes = COALESCE(%s, notes),
                    payload_json = COALESCE(%s::jsonb, payload_json),
                    updated_at = NOW()
                WHERE id=%s
                RETURNING *;
                """,
                (
                    (data.get("obligation_name") or "").strip(),
                    data.get("distinct_flag"),
                    (data.get("recognition_timing") or "").strip().lower(),
                    (None if data.get("progress_method") is None else (data.get("progress_method") or "").strip().lower()),
                    (data.get("obligation_status") or "").strip().lower(),
                    float(data["standalone_selling_price"]) if data.get("standalone_selling_price") is not None else None,
                    float(data["allocated_transaction_price"]) if data.get("allocated_transaction_price") is not None else None,
                    float(data["expected_total_cost"]) if data.get("expected_total_cost") is not None else None,
                    float(data["actual_cost_to_date"]) if data.get("actual_cost_to_date") is not None else None,
                    float(data["progress_percent"]) if data.get("progress_percent") is not None else None,
                    float(data["revenue_to_date"]) if data.get("revenue_to_date") is not None else None,
                    data.get("recognized_at_point_in_time_date"),
                    data.get("recognition_trigger"),
                    satisfaction_status,
                    satisfied_at,
                    satisfaction_evidence_ref,
                    int(user_id) if user_id and satisfaction_status == "satisfied" else before.get("satisfaction_confirmed_by_user_id"),
                    data.get("notes"),
                    _json_dumps(payload_json),
                    int(obligation_id),
                )
            )
            after = dict(cur.fetchone())
            conn.commit()

        return {"before": before, "after": after}

    def create_revenue_contract_version(self, company_id: int, contract_id: int, data: dict, user_id: int | None = None) -> dict:
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            contract = self.get_revenue_contract(company_id, contract_id, cur=cur)
            if not contract:
                raise ValueError("Revenue contract not found")

            last_row = self.fetch_one(
                f"SELECT COALESCE(MAX(version_no), 0) AS max_no FROM {schema}.revenue_contract_versions WHERE contract_id=%s;",
                (int(contract_id),),
                cur=cur,
            )
            version_no = int((last_row or {}).get("max_no") or 0) + 1

            cur.execute(
                f"""
                INSERT INTO {schema}.revenue_contract_versions (
                    company_id, contract_id, version_no, effective_date, version_reason,
                    transaction_price, allocated_revenue_total, expected_cost_total,
                    payload_json, created_by_user_id
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s)
                RETURNING *;
                """,
                (
                    int(company_id),
                    int(contract_id),
                    version_no,
                    data.get("effective_date"),
                    (data.get("version_reason") or "initial").strip().lower(),
                    float(data.get("transaction_price") or contract.get("transaction_price") or 0.0),
                    float(data.get("allocated_revenue_total") or 0.0),
                    float(data.get("expected_cost_total") or 0.0),
                    _json_dumps(data.get("payload_json")),
                    int(user_id) if user_id else None,
                )
            )
            row = dict(cur.fetchone())
            conn.commit()

        return row

    def _normalize_revenue_contract_body(body: dict) -> dict:
        body = dict(body or {})

        has_financing = bool(body.get("has_significant_financing_component", False))

        payload_json = body.get("payload_json") or {}
        if not isinstance(payload_json, dict):
            payload_json = {}

        financing = payload_json.get("financing")
        if not isinstance(financing, dict):
            financing = {}

        if has_financing:
            payload_json["financing"] = {
                "role": str(financing.get("role") or "").strip().lower(),
                "rate": float(financing.get("rate") or 0.0),
                "start_date": financing.get("start_date") or None,
                "end_date": financing.get("end_date") or None,
                "notes": str(financing.get("notes") or "").strip(),
            }
        else:
            payload_json["financing"] = None
            body["financing_component_amount"] = 0.0

        if body.get("contract_currency"):
            body["contract_currency"] = str(body.get("contract_currency") or "").strip().upper()

        billing_method = str(body.get("billing_method") or "").strip().lower() or "milestone"
        body["billing_method"] = billing_method

        billing_cfg = payload_json.get("billing_config") or {}
        if not isinstance(billing_cfg, dict):
            billing_cfg = {}

        raw_billing_day = billing_cfg.get("billing_day")
        try:
            billing_day = int(raw_billing_day) if raw_billing_day not in (None, "", 0, "0") else None
        except (TypeError, ValueError):
            raise ValueError("billing_config.billing_day must be a valid integer.")

        raw_milestones = billing_cfg.get("milestones") or []
        if not isinstance(raw_milestones, list):
            raw_milestones = []

        payload_json["billing_config"] = {
            "method": billing_method,
            "periodicity": str(billing_cfg.get("periodicity") or "").strip().lower() or None,

            "billing_day": (
                int(billing_cfg.get("billing_day"))
                if billing_cfg.get("billing_day") not in (None, "", 0, "0")
                else None
            ),

            "billing_weekday": (
                str(billing_cfg.get("billing_weekday") or "").strip().lower() or None
            ),

            "billing_month": (
                int(billing_cfg.get("billing_month"))
                if billing_cfg.get("billing_month") not in (None, "", 0, "0")
                else None
            ),

            "auto_allocate_contract_pool": bool(
                billing_cfg.get("auto_allocate_contract_pool", True)
            ),

            "allow_obligation_override": bool(
                billing_cfg.get("allow_obligation_override", False)
            ),

            "milestone_basis": str(
                billing_cfg.get("milestone_basis") or "obligation"
            ).strip().lower(),

            "notes": str(billing_cfg.get("notes") or "").strip() or None,

            # ✅ NEW
            "milestones": raw_milestones,
        }

        if body.get("status"):
            body["status"] = str(body.get("status") or "").strip().lower()

        body["payload_json"] = payload_json
        return body
    
    VALID_CONTRACT_BILLING_METHODS = {"milestone", "progress", "periodic", "manual"}

    def _normalize_contract_milestones(self, milestones) -> list[dict]:
        if not milestones:
            return []

        if not isinstance(milestones, list):
            raise ValueError("billing_config.milestones must be a list.")

        allowed_triggers = {
            "manual",
            "date",
            "progress_percent",
            "certificate",
            "approval",
        }

        out = []
        seen = set()

        for idx, raw in enumerate(milestones, start=1):
            if not isinstance(raw, dict):
                raise ValueError(f"Milestone row {idx} must be an object.")

            code = str(raw.get("code") or "").strip()
            description = str(raw.get("description") or "").strip()

            if not code and not description:
                continue

            if not code:
                raise ValueError(f"Milestone row {idx} requires a code.")

            code_key = code.lower()
            if code_key in seen:
                raise ValueError(f"Duplicate milestone code: {code}")
            seen.add(code_key)

            trigger_type = str(raw.get("trigger_type") or "manual").strip().lower()
            if trigger_type not in allowed_triggers:
                raise ValueError(f"Invalid milestone trigger_type '{trigger_type}' for {code}.")

            billing_amount = float(raw.get("billing_amount") or 0.0)

            billing_percent_raw = raw.get("billing_percent")
            billing_percent = (
                None
                if billing_percent_raw in (None, "")
                else float(billing_percent_raw)
            )

            if billing_amount < 0:
                raise ValueError(f"Milestone {code} billing_amount cannot be negative.")

            if billing_percent is not None and (billing_percent < 0 or billing_percent > 100):
                raise ValueError(f"Milestone {code} billing_percent must be between 0 and 100.")

            if billing_amount <= 0 and billing_percent in (None, 0):
                raise ValueError(f"Milestone {code} requires billing_amount or billing_percent.")

            out.append({
                "code": code,
                "description": description or None,
                "trigger_type": trigger_type,
                "billing_amount": billing_amount,
                "billing_percent": billing_percent,
                "certificate_required": bool(raw.get("certificate_required", False)),
                "approval_required": bool(raw.get("approval_required", False)),
                "expected_completion_date": raw.get("expected_completion_date") or None,
                "billing_enabled": raw.get("billing_enabled", True) is not False,
            })

        return out


    def _validate_contract_milestones(self, data: dict) -> dict:
        payload_json = data.get("payload_json") or {}
        if not isinstance(payload_json, dict):
            payload_json = {}

        billing_cfg = payload_json.get("billing_config") or {}
        if not isinstance(billing_cfg, dict):
            billing_cfg = {}

        billing_method = str(data.get("billing_method") or billing_cfg.get("method") or "").strip().lower()
        milestone_basis = str(billing_cfg.get("milestone_basis") or "obligation").strip().lower()

        milestones = self._normalize_contract_milestones(
            billing_cfg.get("milestones") or []
        )

        # Custom milestone billing should define at least one contract milestone.
        if billing_method == "milestone" and milestone_basis == "custom" and not milestones:
            raise ValueError("Custom milestone billing requires at least one billing milestone.")

        billing_cfg["milestones"] = milestones
        payload_json["billing_config"] = billing_cfg
        data["payload_json"] = payload_json
        return data


    def _contract_milestone_codes(self, contract: dict) -> set[str]:
        payload = contract.get("payload_json") or {}
        if not isinstance(payload, dict):
            payload = {}

        billing_cfg = payload.get("billing_config") or {}
        if not isinstance(billing_cfg, dict):
            billing_cfg = {}

        milestones = billing_cfg.get("milestones") or []
        if not isinstance(milestones, list):
            return set()

        return {
            str(m.get("code") or "").strip().lower()
            for m in milestones
            if isinstance(m, dict) and str(m.get("code") or "").strip()
        }

    def _validate_contract_billing_method(self, data: dict):
        method = str(data.get("billing_method") or "").strip().lower()
        if method not in self.VALID_CONTRACT_BILLING_METHODS:
            raise ValueError(
                "Invalid contract billing_method. Use milestone, progress, periodic, or manual."
            )

        payload_json = data.get("payload_json") or {}
        if not isinstance(payload_json, dict):
            payload_json = {}

        billing_cfg = payload_json.get("billing_config") or {}
        if not isinstance(billing_cfg, dict):
            billing_cfg = {}

        if method == "periodic":
            periodicity = str(billing_cfg.get("periodicity") or "").strip().lower()

            if periodicity not in {"weekly", "monthly", "quarterly", "annual"}:
                raise ValueError("Periodic contracts require billing_config.periodicity.")

            if periodicity == "weekly":
                if not billing_cfg.get("billing_weekday"):
                    raise ValueError("Weekly periodic billing requires billing_weekday.")

            if periodicity in {"monthly", "quarterly"}:
                if not billing_cfg.get("billing_day"):
                    raise ValueError("Monthly/Quarterly billing requires billing_day.")

            if periodicity == "annual":
                if not billing_cfg.get("billing_day") or not billing_cfg.get("billing_month"):
                    raise ValueError("Annual billing requires billing_month and billing_day.")
                
        if method == "milestone":
            milestone_basis = str(billing_cfg.get("milestone_basis") or "obligation").strip().lower()
            if milestone_basis not in {"obligation", "custom"}:
                raise ValueError("Milestone contracts require valid milestone_basis.")
            
    def _normalize_and_validate_sfc(self, data: dict, existing: dict | None = None) -> tuple[dict, float]:
        data = dict(data or {})

        existing_payload = (existing or {}).get("payload_json") or {}
        if not isinstance(existing_payload, dict):
            existing_payload = {}

        incoming_payload = data.get("payload_json") or {}
        if not isinstance(incoming_payload, dict):
            incoming_payload = {}

        payload_json = dict(existing_payload)
        payload_json.update(incoming_payload)

        has_financing = data.get("has_significant_financing_component")
        if has_financing is None:
            has_financing = bool((existing or {}).get("has_significant_financing_component", False))
        else:
            has_financing = bool(has_financing)

        raw_fin = payload_json.get("financing")
        financing = dict(raw_fin or {}) if isinstance(raw_fin, dict) else {}

        if not has_financing:
            payload_json["financing"] = None
            data["payload_json"] = payload_json
            data["financing_component_amount"] = 0.0
            data["has_significant_financing_component"] = False
            return data, 0.0

        role = str(financing.get("role") or "").strip().lower()

        try:
            rate = float(financing.get("rate") or 0.0)
        except (TypeError, ValueError):
            raise ValueError("Financing rate must be a valid number.")

        start_date = str(financing.get("start_date") or "").strip()
        end_date = str(financing.get("end_date") or "").strip()
        notes = str(financing.get("notes") or "").strip()

        if role not in {"entity_finances_customer", "customer_finances_entity"}:
            raise ValueError("Invalid financing role.")

        if rate <= 0:
            raise ValueError("Financing rate must be greater than zero.")

        if not start_date:
            raise ValueError("Financing start date is required.")

        if not end_date:
            raise ValueError("Financing end date is required.")

        if start_date >= end_date:
            raise ValueError("Financing end date must be after start date.")

        financing_component_amount = float(data.get("financing_component_amount") or 0.0)

        payload_json["financing"] = {
            "role": role,
            "rate": rate,
            "start_date": start_date,
            "end_date": end_date,
            "notes": notes,
        }

        data["payload_json"] = payload_json
        data["has_significant_financing_component"] = True
        data["financing_component_amount"] = financing_component_amount

        return data, financing_component_amount

    def _enrich_revenue_obligation_project_link(self, company_id: int, contract: dict, data: dict, payload_json: dict, cur=None) -> dict:
        project_id = contract.get("project_id")

        if project_id:
            payload_json["project_id"] = int(project_id)
            payload_json["project_code"] = contract.get("project_code")
            payload_json["project_name"] = contract.get("project_name")

        task_id = (
            data.get("project_task_id")
            or payload_json.get("project_task_id")
            or payload_json.get("task_id")
        )

        if project_id and task_id:
            task = self.validate_project_task(
                company_id,
                project_id=int(project_id),
                task_id=int(task_id),
                cur=cur,
            )

            payload_json["project_task_id"] = int(task_id)
            payload_json["task_id"] = int(task_id)
            payload_json["project_task_code"] = task.get("task_code")
            payload_json["project_task_name"] = task.get("task_name")

        return payload_json

    def mark_revenue_obligation_satisfied(
        self,
        company_id: int,
        obligation_id: int,
        data: dict,
        user_id: int | None = None,
    ) -> dict:
        import json

        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            before = self.fetch_one(
                f"SELECT * FROM {schema}.revenue_obligations WHERE id=%s LIMIT 1;",
                (int(obligation_id),),
                cur=cur,
            )
            if not before:
                raise ValueError("Revenue obligation not found")

            if int(before.get("company_id") or 0) != int(company_id):
                raise ValueError("Obligation does not belong to this company")

            timing = str(before.get("recognition_timing") or "").strip().lower()
            if timing != "point_in_time":
                raise ValueError("Only point-in-time obligations can be marked satisfied")

            obligation_status = str(before.get("obligation_status") or "").strip().lower()
            if obligation_status not in {"draft", "active", "completed"}:
                raise ValueError(f"Cannot satisfy obligation with status '{obligation_status}'")

            contract = self.get_revenue_contract(company_id, int(before["contract_id"]), cur=cur)
            if not contract:
                raise ValueError("Parent revenue contract not found")

            contract_status = str(contract.get("status") or "").strip().lower()
            approval_status = str(contract.get("approval_status") or "").strip().lower()

            if contract_status not in {"draft", "active", "completed"}:
                raise ValueError(f"Cannot satisfy obligation under contract status '{contract_status}'")

            if approval_status not in {"draft", "approved"}:
                raise ValueError(f"Cannot satisfy obligation when approval_status is '{approval_status}'")

            before_payload = before.get("payload_json") or {}
            if isinstance(before_payload, str):
                try:
                    before_payload = json.loads(before_payload)
                except Exception:
                    before_payload = {}

            recognition_trigger = (
                data.get("recognition_trigger")
                if "recognition_trigger" in data
                else before.get("recognition_trigger")
                or before_payload.get("recognition_trigger")
            )
            recognition_trigger = (recognition_trigger or "").strip().lower()

            if not recognition_trigger:
                raise ValueError("Point-in-time obligations require a recognition trigger")

            satisfaction_status = str(data.get("satisfaction_status") or "satisfied").strip().lower()
            if satisfaction_status not in {"satisfied", "reversed"}:
                raise ValueError("Satisfaction action only supports 'satisfied' or 'reversed'")

            satisfied_at = (
                data.get("satisfied_at")
                or before.get("satisfied_at")
                or before.get("recognized_at_point_in_time_date")
            )
            if not satisfied_at:
                raise ValueError("Satisfied point-in-time obligations require satisfied_at")

            satisfaction_evidence_ref = (
                data.get("satisfaction_evidence_ref")
                if "satisfaction_evidence_ref" in data
                else before.get("satisfaction_evidence_ref")
            )
            satisfaction_evidence_ref = (satisfaction_evidence_ref or "").strip() or None

            notes = data.get("notes")

            payload_json = dict(before_payload)
            payload_json["recognition_trigger"] = recognition_trigger
            payload_json["manual_pit_satisfied"] = (satisfaction_status == "satisfied")
            payload_json["satisfied_at"] = str(satisfied_at) if satisfied_at is not None else None

            if satisfaction_evidence_ref:
                payload_json["satisfaction_evidence_ref"] = satisfaction_evidence_ref

            cur.execute(
                f"""
                UPDATE {schema}.revenue_obligations
                SET
                    recognition_timing = 'point_in_time',
                    progress_method = NULL,
                    expected_total_cost = 0,
                    actual_cost_to_date = 0,
                    progress_percent = 0,
                    recognition_trigger = %s,
                    satisfaction_status = %s,
                    satisfied_at = %s,
                    satisfaction_evidence_ref = %s,
                    satisfaction_confirmed_by_user_id = %s,
                    notes = COALESCE(%s, notes),
                    payload_json = %s::jsonb,
                    updated_at = NOW()
                WHERE id = %s
                RETURNING *;
                """,
                (
                    recognition_trigger,
                    satisfaction_status,
                    satisfied_at,
                    satisfaction_evidence_ref,
                    int(user_id) if user_id else None,
                    notes,
                    _json_dumps(payload_json),
                    int(obligation_id),
                )
            )
            after = dict(cur.fetchone())
            conn.commit()

        return {"before": before, "after": after}

    def list_revenue_progress_updates(self, company_id: int, obligation_id: int, cur=None) -> list[dict]:
        schema = self.company_schema(company_id)
        rows = self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.revenue_progress_updates
            WHERE obligation_id = %s
            ORDER BY period_end DESC, created_at DESC, id DESC
            """,
            (int(obligation_id),),
            cur=cur,
        ) or []
        return rows
    
    def _validate_obligation_against_contract(self, contract: dict, data: dict):
        contract_method = str(contract.get("billing_method") or "milestone").strip().lower()

        contract_payload = contract.get("payload_json") or {}
        if not isinstance(contract_payload, dict):
            contract_payload = {}

        contract_billing_cfg = contract_payload.get("billing_config") or {}
        if not isinstance(contract_billing_cfg, dict):
            contract_billing_cfg = {}

        milestone_basis = str(
            contract_billing_cfg.get("milestone_basis") or "obligation"
        ).strip().lower()

        payload_json = data.get("payload_json") or {}
        if not isinstance(payload_json, dict):
            payload_json = {}
        else:
            payload_json = dict(payload_json)

        obligation_name = str(data.get("obligation_name") or "").strip()
        milestone_code = str(payload_json.get("milestone_code") or "").strip()

        if contract_method == "milestone":
            payload_json["milestone_basis"] = milestone_basis

            if milestone_basis == "obligation":
                # obligation itself is the billing milestone
                if not obligation_name:
                    raise ValueError(
                        "Obligation-based milestone contracts require each obligation to have an obligation_name."
                    )

                payload_json["billing_source"] = (
                    payload_json.get("billing_source") or "obligation"
                )

                # optional cleanup: custom milestone reference is not primary here
                if not milestone_code:
                    payload_json.pop("linked_billing_milestone_code", None)
                    payload_json.pop("linked_billing_milestone", None)
                    payload_json.pop("milestone_code", None)

            elif milestone_basis == "custom":
                # billing milestone can differ from obligation structure
                if not milestone_code and not obligation_name:
                    raise ValueError(
                        "Custom milestone-billed contracts require either payload_json.milestone_code or obligation_name."
                    )

                payload_json["billing_source"] = (
                    payload_json.get("billing_source") or "custom_milestone"
                )

        elif contract_method == "periodic":
            payload_json["billing_source"] = (
                payload_json.get("billing_source") or "contract"
            )

        elif contract_method == "progress":
            payload_json["billing_source"] = (
                payload_json.get("billing_source") or "contract"
            )

        elif contract_method == "manual":
            payload_json["billing_source"] = (
                payload_json.get("billing_source") or "manual"
            )

        data["payload_json"] = payload_json
        return data

    def get_revenue_contract_billing_policy(self, company_id: int, contract_id: int, cur=None) -> dict:
        contract = self.get_revenue_contract(company_id, contract_id, cur=cur)
        if not contract:
            raise ValueError("Revenue contract not found")

        payload_json = contract.get("payload_json") or {}
        if isinstance(payload_json, str):
            import json
            try:
                payload_json = json.loads(payload_json)
            except Exception:
                payload_json = {}

        billing_cfg = payload_json.get("billing_config") or {}
        method = str(contract.get("billing_method") or "milestone").strip().lower()

        return {
            "contract_id": int(contract["id"]),
            "billing_method": method,
            "billing_config": billing_cfg,
            "is_contract_level_primary": method in {"periodic", "manual", "progress"},
            "requires_obligation_link": method == "milestone",
            "allows_contract_pool_billing": method in {"progress", "periodic", "manual"},
        }

    def record_revenue_cash_event(
        self,
        company_id: int,
        contract_id: int,
        data: dict,
        user_id: int,
        cur=None,
    ):
        schema = self.company_schema(company_id)

        def _run(_cur):
            _cur.execute(
                f"""
                INSERT INTO {schema}.revenue_cash_events (
                    company_id,
                    contract_id,
                    obligation_id,
                    event_date,
                    event_type,
                    source_receipt_id,
                    amount,
                    currency,
                    notes,
                    payload_json
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                RETURNING id;
                """,
                (
                    int(company_id),
                    int(contract_id),
                    data.get("obligation_id"),
                    data.get("event_date"),
                    data.get("event_type", "receipt"),
                    data.get("source_receipt_id"),
                    float(data.get("amount") or 0),
                    data.get("currency") or "USD",
                    data.get("notes"),
                    json.dumps(data.get("payload_json") or {}),
                ),
            )

            row = _cur.fetchone()
            return int(row["id"] if isinstance(row, dict) else row[0])

        if cur:
            return _run(cur)

        with self._conn_cursor() as (conn, _cur):
            try:
                out = _run(_cur)
                conn.commit()
                return out
            except Exception:
                conn.rollback()
                raise

    def auto_allocate_customer_advance_to_invoice(
        self,
        company_id: int,
        *,
        customer_id: int,
        contract_id: int,
        invoice_id: int,
        amount: float,
        currency: str = "USD",
        cur=None,
    ) -> dict:
        from decimal import Decimal, ROUND_HALF_UP

        def money(x):
            return float(
                Decimal(str(x or 0)).quantize(
                    Decimal("0.01"),
                    rounding=ROUND_HALF_UP
                )
            )

        schema = self.company_schema(company_id)

        def _run(_cur):
            target = money(amount)

            if target <= 0:
                return {
                    "allocated": 0.0,
                    "remaining": 0.0,
                    "allocations": [],
                }

            _cur.execute(
                f"""
                SELECT
                    e.id,
                    e.amount,
                    COALESCE((
                        SELECT SUM((a->>'amount')::numeric)
                        FROM jsonb_array_elements(
                            COALESCE(e.payload_json->'invoice_allocations', '[]'::jsonb)
                        ) a
                    ), 0) AS allocated_amount
                FROM {schema}.revenue_cash_events e
                WHERE e.company_id = %s
                AND e.contract_id = %s
                AND e.event_type IN ('receipt', 'advance_receipt', 'manual')
                AND COALESCE((e.payload_json->>'customer_id')::int, %s) = %s
                AND COALESCE(e.currency, %s) = %s
                ORDER BY e.event_date ASC, e.id ASC
                FOR UPDATE;
                """,
                (
                    int(company_id),
                    int(contract_id),
                    int(customer_id),
                    int(customer_id),
                    currency,
                    currency,
                ),
            )

            rows = _cur.fetchall() or []

            remaining = target
            allocations = []

            for r in rows:
                event_id = int(r["id"] if isinstance(r, dict) else r[0])
                event_amount = money(r["amount"] if isinstance(r, dict) else r[1])
                already_allocated = money(r["allocated_amount"] if isinstance(r, dict) else r[2])

                available = money(event_amount - already_allocated)
                if available <= 0:
                    continue

                alloc = money(min(available, remaining))
                if alloc <= 0:
                    continue

                _cur.execute(
                    f"""
                    UPDATE {schema}.revenue_cash_events
                    SET payload_json =
                        jsonb_set(
                            COALESCE(payload_json, '{{}}'::jsonb),
                            '{{invoice_allocations}}',
                            COALESCE(payload_json->'invoice_allocations', '[]'::jsonb)
                            || jsonb_build_array(
                                jsonb_build_object(
                                    'invoice_id', %s,
                                    'amount', %s,
                                    'allocated_at', NOW()
                                )
                            ),
                            true
                        )
                    WHERE id = %s;
                    """,
                    (
                        int(invoice_id),
                        alloc,
                        int(event_id),
                    ),
                )

                allocations.append({
                    "cash_event_id": event_id,
                    "invoice_id": int(invoice_id),
                    "amount": alloc,
                })

                remaining = money(remaining - alloc)

                if remaining <= 0:
                    break

            return {
                "allocated": money(target - remaining),
                "remaining": money(remaining),
                "allocations": allocations,
            }

        if cur is not None:
            return _run(cur)

        with self._conn_cursor() as (conn, _cur):
            try:
                out = _run(_cur)
                conn.commit()
                return out
            except Exception:
                conn.rollback()
                raise

    def calculate_revenue_billing_position(
        self,
        company_id: int,
        contract_id: int,
        *,
        obligation_id: int | None = None,
        billing_amount=0,
        cur=None,
    ) -> dict:
        from decimal import Decimal, ROUND_HALF_UP

        schema = self.company_schema(company_id)

        def money(value):
            return Decimal(str(value or 0)).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

        amount = money(billing_amount)

        if amount <= Decimal("0.00"):
            raise ValueError(
                "Billing position calculation requires a positive amount"
            )

        # --------------------------------------------------
        # Obligation-level position
        # --------------------------------------------------
        if obligation_id is not None:
            obligation = self.fetch_one(
                f"""
                SELECT
                    id,
                    contract_id,
                    revenue_to_date
                FROM {schema}.revenue_obligations
                WHERE company_id = %s
                AND contract_id = %s
                AND id = %s
                LIMIT 1
                """,
                (
                    int(company_id),
                    int(contract_id),
                    int(obligation_id),
                ),
                cur=cur,
            )

            if not obligation:
                raise ValueError(
                    "Revenue obligation not found"
                )

            recognised_to_date = money(
                obligation.get("revenue_to_date")
            )

            billing_row = self.fetch_one(
                f"""
                SELECT
                    COALESCE(SUM(amount), 0) AS billed_to_date
                FROM {schema}.revenue_billing_events
                WHERE company_id = %s
                AND contract_id = %s
                AND obligation_id = %s
                """,
                (
                    int(company_id),
                    int(contract_id),
                    int(obligation_id),
                ),
                cur=cur,
            ) or {}

        # --------------------------------------------------
        # Contract-level position
        # --------------------------------------------------
        else:
            contract = self.fetch_one(
                f"""
                SELECT
                    id,
                    recognized_revenue_to_date
                FROM {schema}.revenue_contracts
                WHERE company_id = %s
                AND id = %s
                LIMIT 1
                """,
                (
                    int(company_id),
                    int(contract_id),
                ),
                cur=cur,
            )

            if not contract:
                raise ValueError(
                    "Revenue contract not found"
                )

            recognised_to_date = money(
                contract.get("recognized_revenue_to_date")
            )

            billing_row = self.fetch_one(
                f"""
                SELECT
                    COALESCE(SUM(amount), 0) AS billed_to_date
                FROM {schema}.revenue_billing_events
                WHERE company_id = %s
                AND contract_id = %s
                """,
                (
                    int(company_id),
                    int(contract_id),
                ),
                cur=cur,
            ) or {}

        billed_before_event = money(
            billing_row.get("billed_to_date")
        )

        billed_after_event = money(
            billed_before_event + amount
        )

        # Revenue already earned but not yet billed.
        contract_asset_before = money(
            max(
                recognised_to_date - billed_before_event,
                Decimal("0.00"),
            )
        )

        # Portion of this invoice that clears the contract asset.
        contract_asset_release = money(
            min(
                amount,
                contract_asset_before,
            )
        )

        # Any invoice amount above earned revenue becomes liability.
        contract_liability_increase = money(
            amount - contract_asset_release
        )

        position_after = money(
            billed_after_event - recognised_to_date
        )

        if position_after > Decimal("0.00"):
            position_type_after = "liability"
        elif position_after < Decimal("0.00"):
            position_type_after = "asset"
        else:
            position_type_after = "neutral"

        return {
            "billing_amount": float(amount),
            "recognised_to_date": float(recognised_to_date),
            "billed_before_event": float(billed_before_event),
            "billed_after_event": float(billed_after_event),

            "contract_asset_before": float(
                contract_asset_before
            ),
            "contract_asset_release": float(
                contract_asset_release
            ),
            "contract_liability_increase": float(
                contract_liability_increase
            ),

            "position_after": float(
                abs(position_after)
            ),
            "position_type_after": position_type_after,

            "billing_before_revenue": (
                contract_liability_increase
                > Decimal("0.00")
            ),
        }

    def record_revenue_billing_event(
        self,
        company_id: int,
        contract_id: int,
        data: dict,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        import json

        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            contract = self.get_revenue_contract(company_id, contract_id, cur=cur)
            if not contract:
                raise ValueError("Revenue contract not found")

            method = str(contract.get("billing_method") or "milestone").strip().lower()
            if method not in {"milestone", "progress", "periodic", "manual"}:
                raise ValueError(f"Unsupported contract billing method '{method}'")

            obligation_id = data.get("obligation_id")
            if obligation_id in ("", 0, "0"):
                obligation_id = None
            elif obligation_id is not None:
                obligation_id = int(obligation_id)

            amount = float(data.get("amount") or 0.0)
            event_type = (data.get("event_type") or "invoice").strip().lower()

            if amount == 0:
                raise ValueError("Billing amount must be non-zero")

            currency = (data.get("currency") or contract.get("contract_currency") or "USD").strip().upper()

            payload_json = data.get("payload_json") or {}
            if isinstance(payload_json, str):
                try:
                    payload_json = json.loads(payload_json)
                except Exception:
                    payload_json = {}
            elif not isinstance(payload_json, dict):
                payload_json = {}
            else:
                payload_json = dict(payload_json)

            contract_payload = contract.get("payload_json") or {}
            if isinstance(contract_payload, str):
                try:
                    contract_payload = json.loads(contract_payload)
                except Exception:
                    contract_payload = {}
            elif not isinstance(contract_payload, dict):
                contract_payload = {}

            billing_cfg = contract_payload.get("billing_config") or {}
            if not isinstance(billing_cfg, dict):
                billing_cfg = {}

            allow_obligation_override = bool(billing_cfg.get("allow_obligation_override", False))

            obligation_row = None
            if obligation_id is not None:
                obligation_row = self.fetch_one(
                    f"""
                    SELECT id, company_id, contract_id, obligation_code, obligation_name
                    FROM {schema}.revenue_obligations
                    WHERE id=%s
                    LIMIT 1
                    """,
                    (int(obligation_id),),
                    cur=cur,
                )
                if not obligation_row:
                    raise ValueError("Selected obligation was not found")
                if int(obligation_row.get("company_id") or 0) != int(company_id):
                    raise ValueError("Selected obligation does not belong to this company")
                if int(obligation_row.get("contract_id") or 0) != int(contract_id):
                    raise ValueError("Selected obligation does not belong to this contract")


            billing_position = self.calculate_revenue_billing_position(
                company_id=int(company_id),
                contract_id=int(contract_id),
                obligation_id=(
                    int(obligation_id)
                    if obligation_id is not None
                    else None
                ),
                billing_amount=amount,
                cur=cur,
            )

            settlement_pattern = (
                contract_payload.get("settlement_pattern")
                or contract_payload.get("ifrs15_settlement_pattern")
                or ""
            ).strip().lower()

            milestone_basis = (
                billing_cfg.get("milestone_basis")
                or ""
            ).strip().lower()

            if method == "milestone":

                allow_contract_level = (
                    settlement_pattern in {
                        "billing_before_revenue",
                        "cash_before_service",
                        "cash_before_revenue",
                    }
                )

                if obligation_id is None:

                    if milestone_basis == "obligation" and not allow_contract_level:
                        raise ValueError(
                            "Milestone billing requires an obligation-linked billing event."
                        )

                    payload_json["billing_level"] = "contract"

                else:
                    payload_json["billing_level"] = "obligation"

            elif method == "periodic":
                if obligation_id is not None and not allow_obligation_override:
                    obligation_id = None
                payload_json["billing_level"] = "contract" if obligation_id is None else "obligation"

            elif method == "manual":
                payload_json["billing_level"] = "contract" if obligation_id is None else "obligation"

            elif method == "progress":
                payload_json["billing_level"] = "contract" if obligation_id is None else "obligation"

            payload_json["contract_billing_method"] = method
            payload_json["effective_obligation_id"] = obligation_id
            payload_json["posted_via"] = "record_revenue_billing_event"

            payload_json["ifrs15_billing_position"] = (
                billing_position
            )

            payload_json["billing_before_revenue"] = bool(
                billing_position.get(
                    "billing_before_revenue"
                )
            )

            payload_json["contract_asset_release"] = float(
                billing_position.get(
                    "contract_asset_release"
                ) or 0
            )

            payload_json["contract_liability_increase"] = float(
                billing_position.get(
                    "contract_liability_increase"
                ) or 0
            )

            payload_json["position_type_after"] = (
                billing_position.get(
                    "position_type_after"
                )
            )

            if obligation_row:
                payload_json["obligation_code"] = obligation_row.get("obligation_code")
                payload_json["obligation_name"] = obligation_row.get("obligation_name")

            cur.execute(
                f"""
                INSERT INTO {schema}.revenue_billing_events (
                    company_id, contract_id, obligation_id, event_date, event_type,
                    source_invoice_id, amount, currency, notes, payload_json
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb)
                RETURNING *;
                """,
                (
                    int(company_id),
                    int(contract_id),
                    int(obligation_id) if obligation_id is not None else None,
                    data.get("event_date"),
                    event_type,
                    data.get("source_invoice_id"),
                    amount,
                    currency,
                    data.get("notes"),
                    _json_dumps(payload_json),
                )
            )
            row = dict(cur.fetchone())

            cur.execute(
                f"""
                UPDATE {schema}.revenue_contracts
                SET billed_to_date = COALESCE((
                        SELECT SUM(amount)
                        FROM {schema}.revenue_billing_events
                        WHERE contract_id = %s
                    ), 0),
                    billing_status = CASE
                        WHEN COALESCE((
                            SELECT SUM(amount)
                            FROM {schema}.revenue_billing_events
                            WHERE contract_id = %s
                        ), 0) <= 0 THEN 'unbilled'
                        WHEN COALESCE((
                            SELECT SUM(amount)
                            FROM {schema}.revenue_billing_events
                            WHERE contract_id = %s
                        ), 0) >= transaction_price THEN 'fully_billed'
                        ELSE 'partially_billed'
                    END,
                    updated_at = NOW()
                WHERE id = %s
                RETURNING *;
                """,
                (int(contract_id), int(contract_id), int(contract_id), int(contract_id)),
            )
            updated_contract = dict(cur.fetchone())

            conn.commit()

        return {
            "event": row,
            "contract": updated_contract,
            "billing_position": billing_position,
        }

    def record_revenue_cash_event(self, company_id: int, contract_id: int, data: dict, user_id: int | None = None) -> dict:
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            cur.execute(
                f"""
                INSERT INTO {schema}.revenue_cash_events (
                    company_id, contract_id, obligation_id, event_date, event_type,
                    source_receipt_id, amount, currency, notes, payload_json
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb)
                RETURNING *;
                """,
                (
                    int(company_id),
                    int(contract_id),
                    data.get("obligation_id"),
                    data.get("event_date"),
                    (data.get("event_type") or "receipt").strip().lower(),
                    data.get("source_receipt_id"),
                    float(data.get("amount") or 0.0),
                    (data.get("currency") or "USD").strip().upper(),
                    data.get("notes"),
                    _json_dumps(data.get("payload_json")),
                )
            )
            row = dict(cur.fetchone())

            cur.execute(
                f"""
                UPDATE {schema}.revenue_contracts
                SET cash_received_to_date = COALESCE((
                        SELECT SUM(amount) FROM {schema}.revenue_cash_events WHERE contract_id=%s
                    ), 0),
                    cash_status = CASE
                        WHEN COALESCE((
                            SELECT SUM(amount) FROM {schema}.revenue_cash_events WHERE contract_id=%s
                        ), 0) <= 0 THEN 'uncollected'
                        WHEN COALESCE((
                            SELECT SUM(amount) FROM {schema}.revenue_cash_events WHERE contract_id=%s
                        ), 0) >= billed_to_date THEN 'fully_collected'
                        ELSE 'partially_collected'
                    END,
                    updated_at = NOW()
                WHERE id=%s
                """,
                (int(contract_id), int(contract_id), int(contract_id), int(contract_id)),
            )

            contract = self.get_revenue_contract(company_id, contract_id, cur=cur)
            conn.commit()

        return {"event": row, "contract": contract}

    def list_revenue_billing_events(
        self,
        company_id: int,
        contract_id: int,
        limit: int = 100,
        cur=None,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                rbe.*,
                i.number AS source_invoice_number
            FROM {schema}.revenue_billing_events rbe
            LEFT JOIN {schema}.invoices i
            ON i.id = rbe.source_invoice_id
            WHERE rbe.contract_id = %s
            ORDER BY rbe.event_date DESC, rbe.id DESC
            LIMIT %s
        """
        return self.fetch_all(sql, (int(contract_id), int(limit)), cur=cur) or []


    def list_revenue_cash_events(
        self,
        company_id: int,
        contract_id: int,
        limit: int = 100,
        cur=None,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                rce.*
            FROM {schema}.revenue_cash_events rce
            WHERE rce.contract_id = %s
            ORDER BY rce.event_date DESC, rce.id DESC
            LIMIT %s
        """
        return self.fetch_all(sql, (int(contract_id), int(limit)), cur=cur) or []

    def record_revenue_progress_update(self, company_id: int, obligation_id: int, data: dict, user_id: int | None = None) -> dict:
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            obl = self.fetch_one(
                f"SELECT * FROM {schema}.revenue_obligations WHERE id=%s LIMIT 1;",
                (int(obligation_id),),
                cur=cur,
            )
            if not obl:
                raise ValueError("Revenue obligation not found")

            contract = self.get_revenue_contract(company_id, int(obl["contract_id"]), cur=cur)
            obl = self._enrich_obligation_milestone_fields(contract, dict(obl))

            timing = str(obl.get("recognition_timing") or "").strip().lower()
            if timing != "over_time":
                raise ValueError("Progress updates are only allowed for over-time obligations")

            period_end = self._as_date(data.get("period_end"))
            if not period_end:
                raise ValueError("period_end is required")

            configured_method = str(obl.get("progress_method") or "cost_to_cost").strip().lower()
            update_type = (data.get("update_type") or configured_method).strip().lower()

            if update_type != configured_method:
                raise ValueError(
                    f"Progress update type '{update_type}' does not match obligation progress method '{configured_method}'."
                )

            expected_total_cost = float(data["expected_total_cost"]) if data.get("expected_total_cost") is not None else None
            actual_cost_to_date = float(data["actual_cost_to_date"]) if data.get("actual_cost_to_date") is not None else None
            progress_percent = float(data["progress_percent"]) if data.get("progress_percent") not in (None, "") else None
            units_done = float(data["units_done"]) if data.get("units_done") is not None else None
            units_total = float(data["units_total"]) if data.get("units_total") is not None else None
            milestone_code = (data.get("milestone_code") or "").strip() or None
            notes = data.get("notes")
            payload_json = data.get("payload_json") or {}
            if not isinstance(payload_json, dict):
                payload_json = {}

            if update_type == "cost_to_cost":
                if expected_total_cost is None or expected_total_cost <= 0:
                    raise ValueError("Expected total cost is required for cost-to-cost.")
                if actual_cost_to_date is None or actual_cost_to_date < 0:
                    raise ValueError("Actual cost to date is required for cost-to-cost.")

                progress_percent = float(
                    (Decimal(str(actual_cost_to_date)) / Decimal(str(expected_total_cost))) * Decimal("100")
                )
                units_done = None
                units_total = None
                milestone_code = None

                payload_json["cost_to_cost"] = {
                    "expected_total_cost": expected_total_cost,
                    "actual_cost_to_date": actual_cost_to_date,
                }

            elif update_type in {"units", "units_delivered"}:

                units_payload = payload_json.get("units") or {}
                if not isinstance(units_payload, dict):
                    units_payload = {}

                units_done = (
                    data.get("units_done")
                    if data.get("units_done") is not None
                    else units_payload.get("delivered_units")
                )

                units_total = (
                    data.get("units_total")
                    if data.get("units_total") is not None
                    else units_payload.get("total_units")
                )

                certified_units = units_payload.get("certified_units")

                units_done = float(units_done or 0.0)
                units_total = float(units_total or 0.0)
                certified_units = (
                    None
                    if certified_units in (None, "")
                    else float(certified_units)
                )

                if units_total <= 0:
                    raise ValueError("Total units is required for units-based progress.")
                if units_done < 0:
                    raise ValueError("Delivered units cannot be negative.")
                if units_done > units_total:
                    raise ValueError("Delivered units cannot exceed total units.")
                if certified_units is not None and certified_units > units_total:
                    raise ValueError("Certified units cannot exceed total units.")

                recognition_units = certified_units if certified_units is not None else units_done

                progress_percent = float(
                    (Decimal(str(recognition_units)) / Decimal(str(units_total))) * Decimal("100")
                )

                expected_total_cost = None
                actual_cost_to_date = None
                milestone_code = None

                payload_json["units"] = {
                    "unit_of_measure": str(units_payload.get("unit_of_measure") or "").strip() or None,
                    "delivered_units": units_done,
                    "total_units": units_total,
                    "certified_units": certified_units,
                }

            elif update_type == "manual":
                if progress_percent is None:
                    raise ValueError("Progress percent is required for manual updates.")
                if progress_percent < 0 or progress_percent > 100:
                    raise ValueError("Progress percent must be between 0 and 100.")

                expected_total_cost = None
                actual_cost_to_date = None
                units_done = None
                units_total = None
                milestone_code = None

                payload_json["manual"] = {
                    "progress_percent": progress_percent,
                }
            elif update_type == "milestone":

                milestone_payload = payload_json.get("milestone") or {}
                if not isinstance(milestone_payload, dict):
                    milestone_payload = {}

                milestone_code = (
                    data.get("milestone_code")
                    or data.get("linked_billing_milestone_code")
                    or (data.get("payload_json") or {}).get("linked_billing_milestone_code")
                    or milestone_payload.get("code")
                    or obl.get("linked_milestone_code")
                    or ""
                )

                milestone_code = str(milestone_code).strip() or None

                if not milestone_code:
                    raise ValueError("Milestone code is required for milestone updates.")

                contract = self.get_revenue_contract(company_id, int(obl["contract_id"]), cur=cur)
                known_codes = self._contract_milestone_codes(contract or {})

                # If contract has a custom milestone table, code must exist there.
                if known_codes and milestone_code.lower() not in known_codes:
                    raise ValueError(f"Milestone code '{milestone_code}' is not defined on the contract.")

                status = str(milestone_payload.get("status") or "achieved").strip().lower()
                if status not in {"pending", "achieved", "certified", "approved"}:
                    raise ValueError("Invalid milestone status.")

                # V1 rule:
                # pending = 0%, achieved/certified/approved = 100%.
                certified_percent = milestone_payload.get("certified_percent")

                if certified_percent not in (None, ""):
                    certified_percent = float(certified_percent)

                    if certified_percent < 0 or certified_percent > 100:
                        raise ValueError(
                            "Certified percent must be between 0 and 100."
                        )

                    progress_percent = certified_percent

                else:
                    progress_percent = (
                        0.0 if status == "pending" else 100.0
                    )
                expected_total_cost = None
                actual_cost_to_date = None
                units_done = None
                units_total = None

                payload_json["milestone"] = {
                    "code": milestone_code,

                    "description":
                        str(
                            milestone_payload.get("description") or ""
                        ).strip() or None,

                    "status": status,

                    "certificate_ref":
                        str(
                            milestone_payload.get("certificate_ref") or ""
                        ).strip() or None,

                    "approval_date":
                        milestone_payload.get("approval_date"),

                    "approved_by":
                        str(
                            milestone_payload.get("approved_by") or ""
                        ).strip() or None,

                    "certified_percent":
                        certified_percent,

                    "certified_amount":
                        (
                            float(milestone_payload.get("certified_amount"))
                            if milestone_payload.get("certified_amount") not in (None, "")
                            else None
                        ),

                    "retention_percent":
                        (
                            float(milestone_payload.get("retention_percent"))
                            if milestone_payload.get("retention_percent") not in (None, "")
                            else None
                        ),

                    "retention_amount":
                        (
                            float(milestone_payload.get("retention_amount"))
                            if milestone_payload.get("retention_amount") not in (None, "")
                            else None
                        ),

                    "billing_ready":
                        bool(milestone_payload.get("billing_ready")),

                    "blocked_reason":
                        str(
                            milestone_payload.get("blocked_reason") or ""
                        ).strip() or None,
                }

            elif update_type == "time_elapsed":
                obl_payload = obl.get("payload_json") or {}
                if isinstance(obl_payload, str):
                    try:
                        obl_payload = json.loads(obl_payload)
                    except Exception:
                        obl_payload = {}

                start_date = self._as_date(
                    data.get("performance_start_date")
                    or payload_json.get("performance_start_date")
                    or obl_payload.get("performance_start_date")
                )

                end_date = self._as_date(
                    data.get("performance_end_date")
                    or payload_json.get("performance_end_date")
                    or obl_payload.get("performance_end_date")
                )

                if not start_date or not end_date:
                    raise ValueError("Time elapsed requires performance start and end dates.")

                if end_date <= start_date:
                    raise ValueError("Performance end date must be after start date.")

                if period_end <= start_date:
                    progress_percent = 0.0
                elif period_end >= end_date:
                    progress_percent = 100.0
                else:
                    elapsed_days = (period_end - start_date).days
                    total_days = (end_date - start_date).days
                    progress_percent = float(
                        (Decimal(str(elapsed_days)) / Decimal(str(total_days))) * Decimal("100")
                    )

                expected_total_cost = (
                    float(data["expected_total_cost"])
                    if data.get("expected_total_cost") is not None
                    else float(obl.get("expected_total_cost") or 0.0)
                )

                actual_cost_to_date = (
                    float(data["actual_cost_to_date"])
                    if data.get("actual_cost_to_date") is not None
                    else None
                )

                units_done = None
                units_total = None
                milestone_code = None

                time_elapsed_payload = payload_json.get("time_elapsed") or {}

                payload_json["time_elapsed"] = {
                    "performance_start_date": str(start_date),

                    "performance_end_date": str(end_date),

                    "period_end": str(period_end),

                    "basis":
                        str(
                            time_elapsed_payload.get("basis")
                            or "calendar_days"
                        ).strip().lower(),

                    "billing_cycle":
                        str(
                            time_elapsed_payload.get("billing_cycle")
                            or ""
                        ).strip() or None,

                    "elapsed_days":
                        (
                            int(time_elapsed_payload.get("elapsed_days"))
                            if time_elapsed_payload.get("elapsed_days") not in (None, "")
                            else max(
                                0,
                                min(
                                    (period_end - start_date).days,
                                    (end_date - start_date).days
                                )
                            )
                        ),

                    "total_days":
                        (
                            int(time_elapsed_payload.get("total_days"))
                            if time_elapsed_payload.get("total_days") not in (None, "")
                            else (end_date - start_date).days
                        ),

                    "elapsed_percent":
                        (
                            float(time_elapsed_payload.get("elapsed_percent"))
                            if time_elapsed_payload.get("elapsed_percent") not in (None, "")
                            else float(progress_percent or 0.0)
                        ),

                    "actual_cost_to_date":
                        actual_cost_to_date,

                    "notes":
                        str(
                            time_elapsed_payload.get("notes") or ""
                        ).strip() or None,
                }

            else:
                raise ValueError(f"Unsupported progress method '{update_type}'.")

            cur.execute(
                f"""
                INSERT INTO {schema}.revenue_progress_updates (
                    company_id, contract_id, obligation_id, period_end, update_type,
                    expected_total_cost, actual_cost_to_date, progress_percent,
                    units_done, units_total, milestone_code, certified_by_user_id,
                    notes, payload_json
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb)
                ON CONFLICT (obligation_id, period_end, update_type)
                DO UPDATE SET
                    expected_total_cost = EXCLUDED.expected_total_cost,
                    actual_cost_to_date = EXCLUDED.actual_cost_to_date,
                    progress_percent = EXCLUDED.progress_percent,
                    units_done = EXCLUDED.units_done,
                    units_total = EXCLUDED.units_total,
                    milestone_code = EXCLUDED.milestone_code,
                    certified_by_user_id = EXCLUDED.certified_by_user_id,
                    notes = EXCLUDED.notes,
                    payload_json = EXCLUDED.payload_json
                RETURNING *;
                """,
                (
                    int(company_id),
                    int(obl["contract_id"]),
                    int(obligation_id),
                    period_end,
                    update_type,
                    expected_total_cost,
                    actual_cost_to_date,
                    progress_percent,
                    units_done,
                    units_total,
                    milestone_code,
                    int(user_id) if user_id else None,
                    notes,
                    _json_dumps(payload_json),
                )
            )
            row = dict(cur.fetchone())

            cur.execute(
                f"""
                UPDATE {schema}.revenue_obligations
                SET
                    expected_total_cost = %s,
                    actual_cost_to_date = %s,
                    progress_percent = %s,
                    updated_at = NOW()
                WHERE id=%s
                RETURNING *;
                """,
                (
                    float(expected_total_cost) if expected_total_cost is not None else None,
                    float(actual_cost_to_date) if actual_cost_to_date is not None else None,
                    float(progress_percent or 0.0),
                    int(obligation_id),
                )
            )
            obligation = dict(cur.fetchone())
            self.sync_obligation_progress_to_project_task(company_id, int(obligation_id), cur=cur)
            conn.commit()

        return {"progress_update": row, "obligation": obligation}


    def _point_in_time_satisfied(self, obligation: dict, period_end) -> bool:
        pe = self._as_date(period_end)

        payload = obligation.get("payload_json") or {}
        if isinstance(payload, str):
            try:
                payload = json.loads(payload)
            except Exception:
                payload = {}

        status = str(obligation.get("satisfaction_status") or "").strip().lower()
        satisfied_at = self._as_date(
            obligation.get("satisfied_at") or payload.get("satisfied_at")
        )

        if status == "satisfied":
            if pe is None:
                return True
            if satisfied_at is None:
                return True
            return satisfied_at <= pe

        if bool(payload.get("manual_pit_satisfied")):
            if pe is None:
                return True
            if satisfied_at is None:
                return True
            return satisfied_at <= pe

        return False

    def _obligation_progress_pct(self, obligation: dict, period_end) -> Decimal:
        """
        Returns a 0..100 percentage.
        Supports:
        - cost_to_cost
        - units
        - milestone/manual/time_elapsed fallback to stored progress_percent
        """
        method = str(obligation.get("progress_method") or "cost_to_cost").strip().lower()

        if str(obligation.get("recognition_timing") or "").strip().lower() == "point_in_time":
            return Decimal("100") if self._point_in_time_satisfied(obligation, period_end) else Decimal("0")

        if method == "cost_to_cost":
            expected_total_cost = _d(obligation.get("expected_total_cost"))
            actual_cost_to_date = _d(obligation.get("actual_cost_to_date"))
            if expected_total_cost <= 0:
                return _pct(obligation.get("progress_percent") or 0)
            return _pct((actual_cost_to_date / expected_total_cost) * Decimal("100"))

        if method == "units":
            payload = obligation.get("payload_json") or {}
            if isinstance(payload, str):
                try:
                    payload = json.loads(payload)
                except Exception:
                    payload = {}

            units_done = _d(payload.get("units_done"))
            units_total = _d(payload.get("units_total"))
            if units_total <= 0:
                return _pct(obligation.get("progress_percent") or 0)
            return _pct((units_done / units_total) * Decimal("100"))

        if method == "time_elapsed":
            payload = obligation.get("payload_json") or {}
            if isinstance(payload, str):
                try:
                    payload = json.loads(payload)
                except Exception:
                    payload = {}

            start_date = self._as_date(payload.get("performance_start_date"))
            end_date = self._as_date(payload.get("performance_end_date"))
            pe = self._as_date(period_end)

            if not start_date or not end_date or not pe or end_date <= start_date:
                return _pct(obligation.get("progress_percent") or 0)

            if pe <= start_date:
                return Decimal("0")
            if pe >= end_date:
                return Decimal("100")

            elapsed_days = Decimal(str((pe - start_date).days))
            total_days = Decimal(str((end_date - start_date).days))

            return _pct((elapsed_days / total_days) * Decimal("100"))
        # milestone / manual / time_elapsed / fallback
        return _pct(obligation.get("progress_percent") or 0)


    def _obligation_billed_to_date(self, company_id: int, obligation: dict, period_end, cur=None) -> Decimal:
        contract = self.get_revenue_contract(company_id, int(obligation["contract_id"]), cur=cur)
        if not contract:
            return Decimal("0.00")

        return self._allocated_obligation_billed_to_date(
            company_id=company_id,
            contract=contract,
            obligation=obligation,
            period_end=period_end,
            cur=cur,
        )


    def _contract_fallback_billed_to_date(self, company_id: int, contract_id: int, period_end, cur=None) -> Decimal:
        schema = self.company_schema(company_id)
        pe = self._as_date(period_end)

        row = self.fetch_one(
            f"""
            SELECT COALESCE(SUM(amount), 0) AS amt
            FROM {schema}.revenue_billing_events
            WHERE contract_id = %s
            AND (%s IS NULL OR event_date <= %s)
            """,
            (int(contract_id), pe, pe),
            cur=cur,
        ) or {}
        return _money2(row.get("amt") or 0)


    def _recognized_to_date_as_of_period_end(
        self,
        company_id: int,
        obligation_id: int,
        period_end,
        cur=None,
        exclude_run_id: int | None = None,
    ) -> Decimal:
        schema = self.company_schema(company_id)
        pe = self._as_date(period_end)

        if pe is None:
            return Decimal("0.00")

        params = [int(obligation_id), pe]
        extra = ""

        if exclude_run_id is not None:
            extra = "AND r.id <> %s"
            params.append(int(exclude_run_id))

        row = self.fetch_one(
            f"""
            SELECT COALESCE(SUM(e.revenue_delta_this_run), 0) AS amt
            FROM {schema}.revenue_recognition_entries e
            JOIN {schema}.revenue_recognition_runs r
            ON r.id = e.run_id
            WHERE e.obligation_id = %s
            AND r.status IN ('draft', 'posted')
            AND r.period_end <= %s
            {extra}
            """,
            tuple(params),
            cur=cur,
        ) or {}

        return _money2(row.get("amt") or 0)

    def _calculate_obligation_revenue(self, company_id: int, contract: dict, obligation: dict, period_start, period_end, cur=None) -> dict:
        """
        Core IFRS 15 cumulative calculation for one obligation.
        Method driver:
        - cost_to_cost
        - milestone
        - units / units_delivered
        - manual
        - time_elapsed
        - point_in_time
        """
        allocated = _money2(obligation.get("allocated_transaction_price") or 0)
        progress_pct = self._obligation_progress_pct(obligation, period_end)
        revenue_required_to_date = _money2((allocated * progress_pct) / Decimal("100"))

        revenue_previously_recognized = self._recognized_to_date_as_of_period_end(
            company_id=company_id,
            obligation_id=int(obligation["id"]),
            period_end=period_end,
            cur=cur,
        )

        raw_delta = _money2(revenue_required_to_date - revenue_previously_recognized)
        delta = raw_delta
        if delta < Decimal("0.00"):
            delta = Decimal("0.00")

        billed_to_date = self._allocated_obligation_billed_to_date(
            company_id=company_id,
            contract=contract,
            obligation=obligation,
            period_end=period_end,
            cur=cur,
        )

        # Use the ACTUAL recognized position after this run, not the theoretical required one,
        # otherwise you can get zero revenue delta with non-zero CA/CL movement.
        recognized_after_this_run = _money2(revenue_previously_recognized + delta)

        prev_position = _money2(billed_to_date - revenue_previously_recognized)
        new_position = _money2(billed_to_date - recognized_after_this_run)

        prev_liability = prev_position if prev_position > 0 else Decimal("0.00")
        prev_asset = -prev_position if prev_position < 0 else Decimal("0.00")

        new_liability = new_position if new_position > 0 else Decimal("0.00")
        new_asset = -new_position if new_position < 0 else Decimal("0.00")

        contract_liability_delta = _money2(prev_liability - new_liability)
        contract_asset_delta = _money2(new_asset - prev_asset)

        if delta == Decimal("0.00") and (
            contract_asset_delta != Decimal("0.00")
            or contract_liability_delta != Decimal("0.00")
        ):
            raise ValueError(
                f"Invalid recognition calc for obligation {obligation.get('obligation_code') or obligation.get('id')}: "
                f"zero revenue delta with contract movement "
                f"(ca={contract_asset_delta}, cl={contract_liability_delta})"
            )
        
        return {
            "company_id": int(company_id),
            "contract_id": int(contract["id"]),
            "contract_number": contract.get("contract_number"),
            "obligation_id": int(obligation["id"]),
            "obligation_code": obligation.get("obligation_code"),
            "obligation_name": obligation.get("obligation_name"),
            "recognition_timing": obligation.get("recognition_timing"),
            "progress_method": obligation.get("progress_method"),
            "progress_percent": float(progress_pct),
            "allocated_transaction_price": float(allocated),

            "revenue_required_to_date": float(revenue_required_to_date),
            "revenue_previously_recognized": float(revenue_previously_recognized),
            "revenue_delta_this_run": float(delta),

            "billed_to_date": float(billed_to_date),
            "contract_asset_delta": float(contract_asset_delta),
            "contract_liability_delta": float(contract_liability_delta),

            "run_reason": "period_close",
            "payload_json": {
                "calc": {
                    "allocated_transaction_price": float(allocated),
                    "progress_percent": float(progress_pct),
                    "billed_to_date": float(billed_to_date),
                    "previous_position": float(prev_position),
                    "new_position": float(new_position),
                }
            },
        }

    def resolve_ifrs15_accounts(self, company_id: int, cur=None, strict: bool = True) -> dict:
        schema = self.company_schema(company_id)

        rows = self.fetch_all(
            f"""
            SELECT code, role, name, section, category, standard, posting
            FROM {schema}.coa
            WHERE posting = TRUE
            """,
            (),
            cur=cur,
        ) or []

        def norm(v) -> str:
            return str(v or "").strip()

        def norm_upper(v) -> str:
            return norm(v).upper()

        by_role: dict[str, str] = {}

        # 1) First preference: explicit role mappings
        for r in rows:
            role = norm_upper(r.get("role"))
            code = norm(r.get("code"))
            if role in {"CONTRACT_ASSET", "CONTRACT_LIABILITY", "CONTRACT_REVENUE"} and code and role not in by_role:
                by_role[role] = code

        # 2) Fallback: infer from account metadata if role is blank/not maintained
        if "CONTRACT_ASSET" not in by_role:
            for r in rows:
                code = norm(r.get("code"))
                name = norm_upper(r.get("name"))
                section = norm_upper(r.get("section"))
                category = norm_upper(r.get("category"))
                standard = norm_upper(r.get("standard"))

                if not code:
                    continue

                if (
                    "CONTRACT ASSET" in name
                    or category == "CONTRACT ASSET"
                    or section == "CONTRACT ASSET"
                    or standard == "IFRS15_CONTRACT_ASSET"
                    or code.startswith("BS_CA_1716")
                ):
                    by_role["CONTRACT_ASSET"] = code
                    break

        if "CONTRACT_LIABILITY" not in by_role:
            for r in rows:
                code = norm(r.get("code"))
                name = norm_upper(r.get("name"))
                section = norm_upper(r.get("section"))
                category = norm_upper(r.get("category"))
                standard = norm_upper(r.get("standard"))

                if not code:
                    continue

                if (
                    "CONTRACT LIABILITY" in name
                    or "DEFERRED REVENUE" in name
                    or category == "CONTRACT LIABILITY"
                    or section == "CONTRACT LIABILITY"
                    or standard == "IFRS15_CONTRACT_LIABILITY"
                    or code.startswith("BS_CL_2700")
                ):
                    by_role["CONTRACT_LIABILITY"] = code
                    break

        if "CONTRACT_REVENUE" not in by_role:
            for r in rows:
                code = norm(r.get("code"))
                name = norm_upper(r.get("name"))
                section = norm_upper(r.get("section"))
                category = norm_upper(r.get("category"))
                standard = norm_upper(r.get("standard"))

                if not code:
                    continue

                if (
                    "CONTRACT REVENUE" in name
                    or category == "CONTRACT REVENUE"
                    or section == "CONTRACT REVENUE"
                    or standard == "IFRS15_CONTRACT_REVENUE"
                    or code.startswith("PL_REV_")
                ):
                    by_role["CONTRACT_REVENUE"] = code
                    break

        missing = [
            role for role in ("CONTRACT_ASSET", "CONTRACT_LIABILITY", "CONTRACT_REVENUE")
            if role not in by_role
        ]

        print("[IFRS15 RESOLVER MATCHED]", by_role, flush=True)
        print("[IFRS15 RESOLVER MISSING]", missing, flush=True)

        if strict and missing:
            raise ValueError(f"Missing IFRS 15 posting account(s): {', '.join(missing)}")

        return {
            "revenue_code": by_role.get("CONTRACT_REVENUE", ""),
            "contract_asset_code": by_role.get("CONTRACT_ASSET", ""),
            "contract_liability_code": by_role.get("CONTRACT_LIABILITY", ""),

            "contract_revenue_account": by_role.get("CONTRACT_REVENUE", ""),
            "contract_asset_account": by_role.get("CONTRACT_ASSET", ""),
            "contract_liability_account": by_role.get("CONTRACT_LIABILITY", ""),
        }

    def preview_revenue_recognition_run(self, company_id: int, period_start, period_end, contract_id: int | None = None) -> dict:
        from decimal import Decimal

        schema = self.company_schema(company_id)

        period_start_s = str(period_start) if period_start is not None else None
        period_end_s = str(period_end) if period_end is not None else None

        with self._conn_cursor() as (conn, cur):
            contracts_sql = f"""
            SELECT *
            FROM {schema}.revenue_contracts
            WHERE (%s IS NULL OR id=%s)
            AND status IN ('draft','active','completed')
            ORDER BY id ASC
            """
            contracts = self.fetch_all(
                contracts_sql,
                (int(contract_id) if contract_id else None, int(contract_id) if contract_id else None),
                cur=cur,
            ) or []

            preview_contracts = []
            flat_entries = []

            total_rev = Decimal("0.00")
            total_ca = Decimal("0.00")
            total_cl = Decimal("0.00")

            for c in contracts:
                obligations = self.fetch_all(
                    f"""
                    SELECT *
                    FROM {schema}.revenue_obligations
                    WHERE contract_id=%s
                    ORDER BY id ASC
                    """,
                    (int(c["id"]),),
                    cur=cur,
                ) or []

                cash_to_date_contract = Decimal(str(
                    (self.fetch_one(
                        f"""
                        SELECT COALESCE(SUM(amount),0) AS amt
                        FROM {schema}.revenue_cash_events
                        WHERE contract_id=%s
                        AND event_date <= %s
                        """,
                        (int(c["id"]), period_end),
                        cur=cur,
                    ) or {}).get("amt") or 0
                )).quantize(Decimal("0.01"))

                contract_entries = []
                contract_rev = Decimal("0.00")
                contract_ca = Decimal("0.00")
                contract_cl = Decimal("0.00")

                for obl in obligations:
                    allocated = _money2(obl.get("allocated_transaction_price") or 0)
                    recognized_to_date = _money2(obl.get("revenue_to_date") or 0)
                    timing = str(obl.get("recognition_timing") or "").strip().lower()
                    satisfaction_status = str(obl.get("satisfaction_status") or "").strip().lower()

                    print("REV PREVIEW OBLIGATION STATE", {
                        "contract_id": int(c["id"]),
                        "obligation_id": int(obl["id"]),
                        "timing": timing,
                        "allocated": str(allocated),
                        "recognized_to_date": str(recognized_to_date),
                        "satisfaction_status": satisfaction_status,
                        "period_start": str(period_start),
                        "period_end": str(period_end),
                    })

                    # For point-in-time obligations:
                    # - skip only if already fully recognized
                    # - require PIT event date to have occurred by period_end
                    if timing == "point_in_time":
                        if recognized_to_date >= allocated:
                            print("REV PREVIEW SKIP PIT COMPLETE", {
                                "contract_id": int(c["id"]),
                                "obligation_id": int(obl["id"]),
                                "reason": "point_in_time_already_fully_recognized",
                            })
                            continue

                        pit_date = obl.get("recognized_at_point_in_time_date")
                        pit_date_s = str(pit_date) if pit_date is not None else None
                        period_end_cmp = str(period_end) if period_end is not None else None

                        # Not yet due for recognition
                        if not pit_date_s or (period_end_cmp and pit_date_s > period_end_cmp):
                            print("REV PREVIEW SKIP PIT NOT_DUE", {
                                "contract_id": int(c["id"]),
                                "obligation_id": int(obl["id"]),
                                "pit_date": pit_date_s,
                                "period_end": period_end_cmp,
                                "reason": "point_in_time_not_due",
                            })
                            continue

                    existing = self.fetch_one(
                        f"""
                        SELECT e.id, e.run_id, r.status
                        FROM {schema}.revenue_recognition_entries e
                        JOIN {schema}.revenue_recognition_runs r
                        ON r.id = e.run_id
                        WHERE e.contract_id = %s
                        AND e.obligation_id = %s
                        AND e.period_start = %s::date
                        AND e.period_end = %s::date
                        AND r.status IN ('draft', 'posted')
                        LIMIT 1
                        """,
                        (int(c["id"]), int(obl["id"]), str(period_start), str(period_end)),
                        cur=cur,
                    )

                    print("REV PREVIEW EXISTING CHECK", {
                        "contract_id": int(c["id"]),
                        "obligation_id": int(obl["id"]),
                        "period_start": str(period_start),
                        "period_end": str(period_end),
                        "existing": existing,
                    })

                    if existing:
                        # If a draft entry already exists for this obligation + period,
                        # do not re-add it into preview again.
                        # This prevents duplicate revenue lines.
                        if existing.get("status") == "draft":
                            continue

                        # If already posted → skip
                        if existing.get("status") == "posted":
                            continue


                    calc = self._calculate_obligation_revenue(
                        company_id=company_id,
                        contract=c,
                        obligation=obl,
                        period_start=period_start,
                        period_end=period_end,
                        cur=cur,
                    )

                    delta = Decimal(str(calc["revenue_delta_this_run"])).quantize(Decimal("0.01"))
                    ca_delta = Decimal(str(calc["contract_asset_delta"])).quantize(Decimal("0.01"))
                    cl_delta = Decimal(str(calc["contract_liability_delta"])).quantize(Decimal("0.01"))

                    # 🚨 HARD STOP: cannot hit both sides
                    if ca_delta != Decimal("0.00") and cl_delta != Decimal("0.00"):
                        raise ValueError(
                            f"Invalid calculation: obligation {obl.get('id')} "
                            f"has both contract_asset_delta ({ca_delta}) "
                            f"and contract_liability_delta ({cl_delta})"
                        )

                    if delta < Decimal("0.00"):
                        delta = Decimal("0.00")
                        calc["revenue_delta_this_run"] = float(delta)

                    if delta == Decimal("0.00") and ca_delta == Decimal("0.00") and cl_delta == Decimal("0.00"):
                        continue

                    validation = self._validate_revenue_recognition_chain(
                        company_id=company_id,
                        contract=c,
                        obligation=obl,
                        period_end=period_end,
                        cur=cur,
                    )

                    entry = {
                        "contract_id": int(c["id"]),
                        "contract_number": c.get("contract_number"),
                        "contract_title": c.get("contract_title"),
                        "obligation_id": int(obl["id"]),
                        "obligation_code": obl.get("obligation_code"),
                        "obligation_name": obl.get("obligation_name"),
                        "period_start": period_start_s,
                        "period_end": period_end_s,
                        "revenue_required_to_date": float(calc["revenue_required_to_date"]),
                        "revenue_previously_recognized": float(calc["revenue_previously_recognized"]),
                        "revenue_delta_this_run": float(calc["revenue_delta_this_run"]),
                        "billed_to_date": float(calc["billed_to_date"]),
                        "cash_received_to_date": float(cash_to_date_contract),
                        "contract_asset_delta": float(calc["contract_asset_delta"]),
                        "contract_liability_delta": float(calc["contract_liability_delta"]),
                        "source_basis": "system",
                        "notes": None,
                        "validation": validation,
                        "payload_json": {
                            **(calc.get("payload_json") or {}),
                            "contract_cash_to_date": float(cash_to_date_contract),
                        },
                    }

                    contract_entries.append(entry)
                    flat_entries.append(entry)

                    contract_rev += delta
                    contract_ca += ca_delta
                    contract_cl += cl_delta

                if contract_entries:
                    preview_contracts.append({
                        "contract_id": int(c["id"]),
                        "contract_number": c.get("contract_number"),
                        "contract_title": c.get("contract_title"),
                        "customer_id": c.get("customer_id"),
                        "customer_name": c.get("customer_name"),
                        "period_start": period_start_s,
                        "period_end": period_end_s,
                        "entries": contract_entries,
                        "totals": {
                            "total_revenue_delta": float(contract_rev.quantize(Decimal("0.01"))),
                            "total_contract_asset_delta": float(contract_ca.quantize(Decimal("0.01"))),
                            "total_contract_liability_delta": float(contract_cl.quantize(Decimal("0.01"))),
                        },
                    })

                    total_rev += contract_rev
                    total_ca += contract_ca
                    total_cl += contract_cl

                journal_preview_lines = self._build_revenue_recognition_journal_lines(
                    company_id=int(company_id),
                    run={
                        "company_id": int(company_id),
                        "contract_id": int(contract_id) if contract_id else None,
                        "period_start": period_start_s,
                        "period_end": period_end_s,
                        "status": "draft",
                        "run_scope": "contract" if contract_id else "company",
                        "total_revenue_delta": float(total_rev.quantize(Decimal("0.01"))),
                        "total_contract_asset_delta": float(total_ca.quantize(Decimal("0.01"))),
                        "total_contract_liability_delta": float(total_cl.quantize(Decimal("0.01"))),
                    },
                    entries=flat_entries,
                    cur=cur,
                )
            return {
                "ok": True,
                "scope": "contract" if contract_id else "company",
                "contract_id": int(contract_id) if contract_id else None,
                "period_start": period_start_s,
                "period_end": period_end_s,
                "contracts": preview_contracts,
                "entries": flat_entries,
                "journal_lines": journal_preview_lines,   # ADD THIS
                "totals": {
                    "total_revenue_delta": float(total_rev.quantize(Decimal("0.01"))),
                    "total_contract_asset_delta": float(total_ca.quantize(Decimal("0.01"))),
                    "total_contract_liability_delta": float(total_cl.quantize(Decimal("0.01"))),
                },
            }

    def _enrich_obligation_milestone_fields(self, contract: dict | None, obligation: dict | None) -> dict | None:
        import json

        if not obligation:
            return obligation

        obligation = dict(obligation)

        payload_json = obligation.get("payload_json") or {}
        if isinstance(payload_json, str):
            try:
                payload_json = json.loads(payload_json)
            except Exception:
                payload_json = {}
        elif not isinstance(payload_json, dict):
            payload_json = {}

        contract_payload = (contract or {}).get("payload_json") or {}
        if isinstance(contract_payload, str):
            try:
                contract_payload = json.loads(contract_payload)
            except Exception:
                contract_payload = {}
        elif not isinstance(contract_payload, dict):
            contract_payload = {}

        billing_cfg = contract_payload.get("billing_config") or {}
        if not isinstance(billing_cfg, dict):
            billing_cfg = {}

        milestones = billing_cfg.get("milestones") or []
        if not isinstance(milestones, list):
            milestones = []

        linked_code = (
            payload_json.get("linked_billing_milestone_code")
            or payload_json.get("milestone_code")
            or ""
        )
        linked_code = str(linked_code).strip()

        linked = None
        if linked_code:
            linked = next(
                (
                    m for m in milestones
                    if isinstance(m, dict)
                    and str(m.get("code") or "").strip().lower() == linked_code.lower()
                ),
                None,
            )

        if linked:
            payload_json["linked_billing_milestone_code"] = linked_code
            payload_json["milestone_code"] = linked_code
            payload_json["linked_billing_milestone"] = linked

        obligation["payload_json"] = payload_json
        obligation["linked_milestone_code"] = linked_code or None
        obligation["linked_milestone_description"] = linked.get("description") if linked else None
        obligation["linked_milestone_amount"] = float(linked.get("billing_amount") or 0) if linked else None
        obligation["linked_milestone_percent"] = float(linked.get("billing_percent") or 0) if linked else None
        obligation["linked_milestone_expected_date"] = linked.get("expected_completion_date") if linked else None

        return obligation

    def _validate_revenue_recognition_chain(
        self,
        company_id: int,
        contract: dict,
        obligation: dict,
        period_end,
        cur=None,
    ) -> dict:
        schema = self.company_schema(company_id)

        blocking: list[str] = []
        warnings: list[str] = []

        contract_id = int(contract.get("id"))
        obligation_id = int(obligation.get("id"))

        payload = contract.get("payload_json") or {}
        if isinstance(payload, str):
            try:
                import json
                payload = json.loads(payload)
            except Exception:
                payload = {}

        settlement_pattern = str(payload.get("settlement_pattern") or "").strip().lower()
        if settlement_pattern not in {
            "revenue_before_billing",
            "billing_before_revenue",
            "cash_before_service",
        }:
            blocking.append("missing_settlement_pattern")

        allocated = float(obligation.get("allocated_transaction_price") or 0.0)
        if allocated <= 0:
            blocking.append("missing_allocated_transaction_price")

        # Prevent duplicate recognition for same obligation and period
        if cur is not None:
            cur.execute(
                f"""
                SELECT COUNT(*)
                FROM {schema}.revenue_recognition_entries e
                JOIN {schema}.revenue_recognition_runs r
                ON r.id = e.run_id
                WHERE e.company_id = %s
                AND e.contract_id = %s
                AND e.obligation_id = %s
                AND e.period_end = %s
                AND COALESCE(r.status, '') NOT IN ('reversed', 'cancelled', 'void')
                """,
                (company_id, contract_id, obligation_id, period_end),
            )

            row = cur.fetchone()
            existing_count = int(
                (row[0] if not isinstance(row, dict) else row.get("count")) or 0
            )

            if existing_count > 0:
                blocking.append("recognition_already_run_for_obligation_period")
        try:
            self.resolve_ifrs15_accounts(company_id, cur=cur)
        except Exception:
            blocking.append("missing_ifrs15_accounts")

        timing = str(obligation.get("recognition_timing") or "over_time").strip().lower()

        billing_stats = self._obligation_billing_validation_stats(
            company_id=company_id,
            contract=contract,
            obligation=obligation,
            period_end=period_end,
            cur=cur,
        )

        billed_amt = float(billing_stats.get("billed_to_date") or 0.0)
        billing_count = int(billing_stats.get("billing_count") or 0)
        linked_invoice_count = int(billing_stats.get("linked_invoice_count") or 0)

        if timing == "point_in_time":
            pit_date = obligation.get("recognized_at_point_in_time_date")
            pit_date_s = str(pit_date) if pit_date is not None else None
            period_end_s = str(period_end) if period_end is not None else None

            due_for_recognition = bool(pit_date_s and period_end_s and pit_date_s <= period_end_s)

            if due_for_recognition and billed_amt <= 0:
                blocking.append("point_in_time_missing_billing")

            if due_for_recognition and billing_count > 0 and linked_invoice_count == 0:
                warnings.append("point_in_time_billing_not_linked_to_invoice")

        else:
            if billed_amt > 0 and linked_invoice_count == 0:
                warnings.append("billing_not_linked_to_invoice")

        contract_status = str(contract.get("status") or "").strip().lower()
        approval_status = str(contract.get("approval_status") or "").strip().lower()

        if contract_status not in {"active", "completed", "draft"}:
            blocking.append(f"invalid_contract_status:{contract_status}")

        if approval_status not in {"approved", "draft"}:
            warnings.append(f"contract_approval_status:{approval_status}")

        return {
            "ok": len(blocking) == 0,
            "contract_id": contract_id,
            "obligation_id": obligation_id,
            "blocking": blocking,
            "warnings": warnings,
            "settlement_pattern": settlement_pattern or None,
            "billed_to_date": billed_amt,
            "billing_count": billing_count,
            "linked_invoice_count": linked_invoice_count,
        }

    def _obligation_billing_validation_stats(self, company_id: int, contract: dict, obligation: dict, period_end=None, cur=None) -> dict:
        schema = self.company_schema(company_id)
        obligation_id = int(obligation["id"])
        contract_id = int(contract["id"])
        pe = self._as_date(period_end)

        direct = self.fetch_one(
            f"""
            SELECT
                COALESCE(SUM(amount), 0) AS billed_amt,
                COUNT(*) AS billing_count,
                COUNT(source_invoice_id) AS linked_invoice_count
            FROM {schema}.revenue_billing_events
            WHERE obligation_id = %s
            AND (%s IS NULL OR event_date <= %s)
            """,
            (obligation_id, pe, pe),
            cur=cur,
        ) or {}

        direct_billed = _money2(direct.get("billed_amt") or 0)

        if direct_billed > Decimal("0.00"):
            return {
                "billed_to_date": direct_billed,
                "billing_count": int(direct.get("billing_count") or 0),
                "linked_invoice_count": int(direct.get("linked_invoice_count") or 0),
            }

        allocated_billed = self._allocated_obligation_billed_to_date(
            company_id=company_id,
            contract=contract,
            obligation=obligation,
            period_end=period_end,
            cur=cur,
        )

        contract_pool = self.fetch_one(
            f"""
            SELECT
                COUNT(*) AS billing_count,
                COUNT(source_invoice_id) AS linked_invoice_count
            FROM {schema}.revenue_billing_events
            WHERE contract_id = %s
            AND obligation_id IS NULL
            AND (%s IS NULL OR event_date <= %s)
            """,
            (contract_id, pe, pe),
            cur=cur,
        ) or {}

        return {
            "billed_to_date": allocated_billed,
            "billing_count": int(contract_pool.get("billing_count") or 0),
            "linked_invoice_count": int(contract_pool.get("linked_invoice_count") or 0),
        }

    def _allocated_obligation_billed_to_date(
        self,
        company_id: int,
        contract: dict,
        obligation: dict,
        period_end=None,
        cur=None,
    ) -> Decimal:
        """
        Returns billed-to-date for an obligation using this priority:

        1. Direct obligation-linked billing events
        2. Plus proportional share of contract-level billing pool
        using allocated_transaction_price / total allocated obligation price

        Notes:
        - Contract-level billing pool means revenue_billing_events where obligation_id IS NULL
        - period_end is optional; if supplied, only events up to that date are included
        - This supports mixed cases:
            * some billing tagged directly to obligation
            * some billing posted only at contract level
        """
        schema = self.company_schema(company_id)
        pe = self._as_date(period_end)

        obligation_id = int(obligation["id"])
        contract_id = int(contract["id"])

        allocated_tp = _money2(obligation.get("allocated_transaction_price") or 0)

        if allocated_tp <= Decimal("0.00"):
            return Decimal("0.00")

        # ---------------------------------------
        # 1) Direct obligation billing
        # ---------------------------------------
        direct_row = self.fetch_one(
            f"""
            SELECT COALESCE(SUM(amount), 0) AS amt
            FROM {schema}.revenue_billing_events
            WHERE obligation_id = %s
            AND (%s IS NULL OR event_date <= %s)
            """,
            (obligation_id, pe, pe),
            cur=cur,
        ) or {}

        direct_billed = _money2(direct_row.get("amt") or 0)

        # ---------------------------------------
        # 2) Contract-level billing pool (untagged)
        # ---------------------------------------
        pool_row = self.fetch_one(
            f"""
            SELECT COALESCE(SUM(amount), 0) AS amt
            FROM {schema}.revenue_billing_events
            WHERE contract_id = %s
            AND obligation_id IS NULL
            AND (%s IS NULL OR event_date <= %s)
            """,
            (contract_id, pe, pe),
            cur=cur,
        ) or {}

        contract_level_pool = _money2(pool_row.get("amt") or 0)

        if contract_level_pool <= Decimal("0.00"):
            return direct_billed

        # ---------------------------------------
        # 3) Total allocation basis from obligations
        #    Use obligation allocations, not contract.transaction_price
        # ---------------------------------------
        alloc_row = self.fetch_one(
            f"""
            SELECT COALESCE(SUM(allocated_transaction_price), 0) AS total_allocated
            FROM {schema}.revenue_obligations
            WHERE contract_id = %s
            """,
            (contract_id,),
            cur=cur,
        ) or {}

        total_allocated = _money2(alloc_row.get("total_allocated") or 0)

        if total_allocated <= Decimal("0.00"):
            return direct_billed

        # ---------------------------------------
        # 4) Proportional allocation of contract-level pool
        # ---------------------------------------
        allocated_share = _money2((contract_level_pool * allocated_tp) / total_allocated)

        # ---------------------------------------
        # 5) Final billed to date = direct + allocated pool share
        # ---------------------------------------
        return _money2(direct_billed + allocated_share)


    def get_revenue_obligation_billing_position(self, company_id: int, obligation_id: int, cur=None) -> dict | None:
        schema = self.company_schema(company_id)

        obligation = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.revenue_obligations
            WHERE id = %s
            LIMIT 1
            """,
            (int(obligation_id),),
            cur=cur,
        )
        if not obligation:
            return None

        contract = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.revenue_contracts
            WHERE id = %s
            LIMIT 1
            """,
            (int(obligation["contract_id"]),),
            cur=cur,
        )
        if not contract:
            return None

        obligation = self._enrich_obligation_milestone_fields(contract, dict(obligation))

        billed_to_date = self._allocated_obligation_billed_to_date(
            company_id=company_id,
            contract=contract,
            obligation=obligation,
            period_end=None,
            cur=cur,
        )

        allocated_tp = _money2(obligation.get("allocated_transaction_price") or 0)
        remaining_to_bill = _money2(max(Decimal("0.00"), allocated_tp - billed_to_date))

        return {
            "obligation_id": int(obligation["id"]),
            "contract_id": int(obligation["contract_id"]),
            "obligation_code": obligation.get("obligation_code"),
            "obligation_name": obligation.get("obligation_name"),
            "linked_milestone_code": obligation.get("linked_milestone_code"),
            "linked_milestone_description": obligation.get("linked_milestone_description"),
            "linked_milestone_amount": obligation.get("linked_milestone_amount"),
            "allocated_transaction_price": float(allocated_tp),
            "billed_to_date": float(billed_to_date),
            "remaining_to_bill": float(remaining_to_bill),
        }

    def get_revenue_obligation(self, company_id: int, obligation_id: int, cur=None) -> dict | None:
        schema = self.company_schema(company_id)

        row = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.revenue_obligations
            WHERE id = %s
            """,
            (int(obligation_id),),
            cur=cur,
        )

        if not row:
            return None

        # normalize important fields
        row = dict(row)

        row["progress_method"] = (
            str(row.get("progress_method") or "cost_to_cost")
            .strip()
            .lower()
        )

        row["recognition_timing"] = (
            str(row.get("recognition_timing") or "point_in_time")
            .strip()
            .lower()
        )

        contract = self.get_revenue_contract(
            company_id,
            int(row["contract_id"]),
            cur=cur,
        )

        row = self._enrich_obligation_milestone_fields(contract, row)

        payload_json = row.get("payload_json") or {}
        if isinstance(payload_json, str):
            try:
                payload_json = json.loads(payload_json or "{}")
            except Exception:
                payload_json = {}

        if contract:
            project_id = contract.get("project_id")

            if project_id:
                payload_json["project_id"] = int(project_id)
                payload_json["project_code"] = contract.get("project_code")
                payload_json["project_name"] = contract.get("project_name")

        row["payload_json"] = payload_json

        return row

    def create_revenue_recognition_run(self, company_id: int, data: dict, user_id: int | None = None) -> dict:
        schema = self.company_schema(company_id)
        period_start = self._as_date(data.get("period_start"))
        period_end = self._as_date(data.get("period_end"))
        contract_id = data.get("contract_id")

        if not period_start:
            raise ValueError("period_start is required")
        if not period_end:
            raise ValueError("period_end is required")
        if period_end < period_start:
            raise ValueError("period_end cannot be before period_start")

        preview = self.preview_revenue_recognition_run(
            company_id=int(company_id),
            period_start=period_start,
            period_end=period_end,
            contract_id=int(contract_id) if contract_id else None,
        )

        run_payload = dict(data.get("payload_json") or {})
        # Do not persist preview journal lines.
        # Posting must rebuild journal lines from entries.
        run_payload.pop("journal_lines", None)

        with self._conn_cursor() as (conn, cur):
            existing_posted = self.fetch_one(
                f"""
                SELECT id
                FROM {schema}.revenue_recognition_runs
                WHERE (
                    (%s IS NULL AND contract_id IS NULL)
                    OR contract_id = %s
                )
                AND period_start = %s
                AND period_end = %s
                AND status = 'posted'
                LIMIT 1
                """,
                (
                    int(contract_id) if contract_id else None,
                    int(contract_id) if contract_id else None,
                    period_start,
                    period_end,
                ),
                cur=cur,
            )

            if existing_posted:
                raise ValueError("A posted recognition run already exists for this scope and period.")

            cur.execute(
                f"""
                INSERT INTO {schema}.revenue_recognition_runs (
                    company_id, contract_id, run_scope, period_start, period_end, status,
                    run_reason, total_revenue_delta, total_contract_asset_delta, total_contract_liability_delta,
                    requested_by_user_id, payload_json
                )
                VALUES (%s,%s,%s,%s,%s,'draft',%s,%s,%s,%s,%s,%s::jsonb)
                RETURNING *;
                """,
                (
                    int(company_id),
                    int(contract_id) if contract_id else None,
                    "contract" if contract_id else "company",
                    period_start,
                    period_end,
                    (data.get("run_reason") or "period_end").strip().lower(),
                    float(preview["totals"]["total_revenue_delta"]),
                    float(preview["totals"]["total_contract_asset_delta"]),
                    float(preview["totals"]["total_contract_liability_delta"]),
                    int(user_id) if user_id else None,
                    _json_dumps(run_payload),
                )
            )
            run = dict(cur.fetchone())
            run_id = int(run["id"])

            for e in preview["entries"]:
                cur.execute(
                    f"""
                    INSERT INTO {schema}.revenue_recognition_entries (
                        company_id, run_id, contract_id, obligation_id,
                        period_start, period_end,
                        revenue_required_to_date, revenue_previously_recognized, revenue_delta_this_run,
                        billed_to_date, cash_received_to_date, contract_asset_delta, contract_liability_delta,
                        source_basis, notes, payload_json
                    )
                    VALUES (
                        %s,%s,%s,%s,
                        %s,%s,
                        %s,%s,%s,
                        %s,%s,%s,%s,
                        %s,%s,%s::jsonb
                    )
                    """,
                    (
                        int(company_id),
                        run_id,
                        int(e["contract_id"]),
                        int(e["obligation_id"]) if e.get("obligation_id") else None,
                        e["period_start"],
                        e["period_end"],
                        float(e["revenue_required_to_date"]),
                        float(e["revenue_previously_recognized"]),
                        float(e["revenue_delta_this_run"]),
                        float(e["billed_to_date"]),
                        float(e["cash_received_to_date"]),
                        float(e["contract_asset_delta"]),
                        float(e["contract_liability_delta"]),
                        e.get("source_basis") or "system",
                        e.get("notes"),
                        _json_dumps(e.get("payload_json") or {}),
                    )
                )

            conn.commit()

        return {
            "run": run,
            "preview": preview,
        }

    def approve_revenue_contract(self, company_id: int, contract_id: int, user_id: int | None = None) -> dict:
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            cur.execute(
                f"""
                SELECT *
                FROM {schema}.revenue_contracts
                WHERE id=%s
                LIMIT 1
                """,
                (int(contract_id),),
            )
            row = cur.fetchone()
            if not row:
                raise ValueError("Revenue contract not found")

            before = dict(row)
            approval_before = str(before.get("approval_status") or "draft").strip().lower()

            if approval_before not in {"draft", "pending_approval", "rejected"}:
                raise ValueError(
                    f"Revenue contract cannot be approved from approval_status '{approval_before}'"
                )

            cur.execute(
                f"""
                UPDATE {schema}.revenue_contracts
                SET
                    status='active',
                    approval_status='approved',
                    approved_by_user_id=%s,
                    approved_at=NOW(),
                    updated_at=NOW()
                WHERE id=%s
                RETURNING *
                """,
                (
                    int(user_id) if user_id else None,
                    int(contract_id),
                ),
            )
            after = dict(cur.fetchone())

            contract_ref = (after.get("contract_number") or f"REV-CON-{after.get('id')}").strip()

            payload_json = after.get("payload_json") or {}
            if isinstance(payload_json, str):
                try:
                    payload_json = json.loads(payload_json)
                except Exception:
                    payload_json = {}

            engagement_id = payload_json.get("engagement_id")

            if engagement_id:
                try:
                    self.upsert_engagement_posting_activity(
                        cur,
                        company_id=int(company_id),
                        engagement_id=int(engagement_id),
                        posting_date=after.get("approved_at") or after.get("contract_date") or after.get("start_date"),
                        module_name="revenue",
                        event_type="approved",
                        reference_no=contract_ref,
                        description=f"Approved revenue contract {contract_ref}",
                        prepared_by_user_id=after.get("created_by_user_id"),
                        reviewer_user_id=int(user_id) if user_id else None,
                        status="approved",
                        amount=float(after.get("transaction_price") or 0.0),
                        currency_code=(after.get("contract_currency") or "USD"),
                        source_table="revenue_contracts",
                        source_id=int(after["id"]),
                        notes="Revenue contract approved",
                        created_by_user_id=after.get("created_by_user_id"),
                        updated_by_user_id=int(user_id) if user_id else None,
                    )
                except Exception:
                    pass

            conn.commit()

        contract_ref = (after.get("contract_number") or f"REV-CON-{after.get('id')}").strip()

        try:
            self.audit_log(
                int(company_id),
                actor_user_id=int(user_id or 0) or None,
                module="revenue",
                action="approve_revenue_contract",
                severity="info",
                entity_type="revenue_contract",
                entity_id=str(after["id"]),
                entity_ref=contract_ref,
                before_json=before,
                after_json=after,
                message=f"Approved revenue contract {contract_ref}",
                source="approval",
            )

        except Exception:
            pass

        return after

    def _build_revenue_recognition_journal_lines(
        self,
        company_id: int,
        run: dict,
        entries: list[dict],
        cur=None,
    ) -> list[dict]:
        from decimal import Decimal, ROUND_HALF_UP

        acct = self.resolve_ifrs15_accounts(company_id, cur=cur, strict=True)

        revenue_code = acct["revenue_code"]
        contract_asset_code = acct["contract_asset_code"]
        contract_liability_code = acct["contract_liability_code"]

        def q2(v) -> Decimal:
            return Decimal(str(v or 0)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        def add_line(bucket: list[dict], account_code: str, debit=0, credit=0, memo: str = ""):
            if not account_code:
                raise ValueError(f"Missing account code for journal line: {memo}")
            d = q2(debit)
            c = q2(credit)
            if d == Decimal("0.00") and c == Decimal("0.00"):
                return
            bucket.append({
                "account_code": account_code,
                "debit": float(d),
                "credit": float(c),
                "memo": memo,
            })

        jlines: list[dict] = []

        for e in entries:
            delta = q2(e.get("revenue_delta_this_run"))
            ca = q2(e.get("contract_asset_delta"))
            cl = q2(e.get("contract_liability_delta"))

            print("[revenue_run] ENTRY DEBUG:", {
                "obligation_id": e.get("obligation_id"),
                "delta": str(delta),
                "contract_asset_delta": str(ca),
                "contract_liability_delta": str(cl),
            }, flush=True)

            ref = (
                e.get("obligation_code")
                or e.get("obligation_name")
                or str(e.get("obligation_id") or "")
            ).strip()

            if delta == Decimal("0.00") and ca == Decimal("0.00") and cl == Decimal("0.00"):
                continue

            # 1) Never allow both sides at once
            if ca != Decimal("0.00") and cl != Decimal("0.00"):
                raise ValueError(
                    f"Recognition entry cannot hit both contract asset and liability in same line for obligation {ref}"
                )

            # 2) Delta must reconcile to exactly one side
            side_total = abs(ca) + abs(cl)
            if delta != Decimal("0.00") and side_total != abs(delta):
                raise ValueError(
                    f"Recognition entry mismatch for obligation {ref}: "
                    f"revenue_delta_this_run={delta}, contract_asset_delta={ca}, contract_liability_delta={cl}"
                )

            # 3) Sign consistency checks
            if delta > Decimal("0.00"):
                if ca < Decimal("0.00") or cl < Decimal("0.00"):
                    raise ValueError(
                        f"Positive revenue delta cannot have negative contract position delta for obligation {ref}"
                    )

                if cl > Decimal("0.00"):
                    amt = cl
                    add_line(
                        jlines,
                        contract_liability_code,
                        debit=amt,
                        credit=0,
                        memo=f"Revenue recognition release {ref}",
                    )
                    add_line(
                        jlines,
                        revenue_code,
                        debit=0,
                        credit=amt,
                        memo=f"Revenue recognized {ref}",
                    )

                elif ca > Decimal("0.00"):
                    amt = ca
                    add_line(
                        jlines,
                        contract_asset_code,
                        debit=amt,
                        credit=0,
                        memo=f"Unbilled revenue recognized {ref}",
                    )
                    add_line(
                        jlines,
                        revenue_code,
                        debit=0,
                        credit=amt,
                        memo=f"Revenue recognized {ref}",
                    )

                else:
                    raise ValueError(
                        f"Positive revenue delta with no asset/liability movement for obligation {ref}"
                    )

            elif delta < Decimal("0.00"):
                if ca > Decimal("0.00") or cl > Decimal("0.00"):
                    raise ValueError(
                        f"Negative revenue delta cannot have positive contract position delta for obligation {ref}"
                    )

                if cl < Decimal("0.00"):
                    amt = abs(cl)
                    add_line(
                        jlines,
                        revenue_code,
                        debit=amt,
                        credit=0,
                        memo=f"Revenue reversal {ref}",
                    )
                    add_line(
                        jlines,
                        contract_liability_code,
                        debit=0,
                        credit=amt,
                        memo=f"Reverse liability release {ref}",
                    )

                elif ca < Decimal("0.00"):
                    amt = abs(ca)
                    add_line(
                        jlines,
                        revenue_code,
                        debit=amt,
                        credit=0,
                        memo=f"Revenue reversal {ref}",
                    )
                    add_line(
                        jlines,
                        contract_asset_code,
                        debit=0,
                        credit=amt,
                        memo=f"Reverse unbilled revenue {ref}",
                    )

                else:
                    raise ValueError(
                        f"Negative revenue delta with no asset/liability movement for obligation {ref}"
                    )

        total_debits = sum(q2(x.get("debit")) for x in jlines)
        total_credits = sum(q2(x.get("credit")) for x in jlines)
        if total_debits != total_credits:
            raise ValueError(
                f"Recognition journal is out of balance: debits={total_debits} credits={total_credits}"
            )

        print("[revenue_run] FINAL JOURNAL LINES:", jlines, flush=True)
        return jlines

    def apply_revenue_contract_modification(
        self,
        company_id: int,
        contract_id: int,
        data: dict,
        user_id: int | None = None,
    ) -> dict:
        schema = self.company_schema(company_id)

        allowed_fields = {
            "customer_id",
            "contract_number",
            "contract_title",
            "contract_currency",
            "contract_date",
            "start_date",
            "end_date",
            "billing_method",
            "transaction_price",
            "variable_consideration_est",
            "variable_consideration_constrained",
            "financing_component_amount",
            "has_significant_financing_component",
            "is_over_time",
            "notes",
            "payload_json",
        }

        patch = {k: v for k, v in (data or {}).items() if k in allowed_fields}
        if not patch:
            raise ValueError("No valid revenue contract modification fields supplied")

        with self._conn_cursor() as (conn, cur):
            cur.execute(
                f"""
                SELECT *
                FROM {schema}.revenue_contracts
                WHERE id=%s
                LIMIT 1
                """,
                (int(contract_id),),
            )
            row = cur.fetchone()
            if not row:
                raise ValueError("Revenue contract not found")

            before = dict(row)
            status_before = str(before.get("status") or "draft").strip().lower()

            if status_before not in {"approved", "active", "pending_approval", "draft"}:
                raise ValueError(f"Revenue contract cannot be modified from status '{status_before}'")

            customer_id = patch.get("customer_id", before.get("customer_id"))
            customer_id = int(customer_id) if customer_id not in (None, "", 0, "0") else None
            if customer_id is None:
                raise ValueError("Customer is required for revenue contracts")

            customer = self.fetch_one(
                f"SELECT id, name FROM {schema}.customers WHERE id=%s LIMIT 1;",
                (customer_id,),
                cur=cur,
            )
            if not customer:
                raise ValueError("Selected customer not found")

            payload_json = patch.get("payload_json", before.get("payload_json") or {})
            if not isinstance(payload_json, dict):
                payload_json = before.get("payload_json") or {}

            cur.execute(
                f"""
                UPDATE {schema}.revenue_contracts
                SET
                    customer_id=%s,
                    contract_number=%s,
                    contract_title=%s,
                    contract_currency=%s,
                    contract_date=%s,
                    start_date=%s,
                    end_date=%s,
                    billing_method=%s,
                    transaction_price=%s,
                    variable_consideration_est=%s,
                    variable_consideration_constrained=%s,
                    financing_component_amount=%s,
                    has_significant_financing_component=%s,
                    is_over_time=%s,
                    notes=%s,
                    payload_json=%s::jsonb,
                    updated_at=NOW()
                WHERE id=%s
                RETURNING *
                """,
                (
                    customer_id,
                    (patch.get("contract_number", before.get("contract_number")) or "").strip(),
                    (patch.get("contract_title", before.get("contract_title")) or "").strip(),
                    (patch.get("contract_currency", before.get("contract_currency") or "USD") or "USD").strip().upper(),
                    patch.get("contract_date", before.get("contract_date")),
                    patch.get("start_date", before.get("start_date")),
                    patch.get("end_date", before.get("end_date")),
                    (patch.get("billing_method", before.get("billing_method") or "milestone") or "milestone").strip().lower(),
                    float(patch.get("transaction_price", before.get("transaction_price") or 0.0)),
                    float(patch.get("variable_consideration_est", before.get("variable_consideration_est") or 0.0)),
                    float(patch.get("variable_consideration_constrained", before.get("variable_consideration_constrained") or 0.0)),
                    float(patch.get("financing_component_amount", before.get("financing_component_amount") or 0.0)),
                    bool(patch.get("has_significant_financing_component", before.get("has_significant_financing_component", False))),
                    bool(patch.get("is_over_time", before.get("is_over_time", True))),
                    patch.get("notes", before.get("notes")),
                    json.dumps(payload_json, default=str),
                    int(contract_id),
                ),
            )
            after = dict(cur.fetchone())
            after["customer_name"] = customer.get("name")

            contract_ref = (after.get("contract_number") or f"REV-CON-{after.get('id')}").strip()

            # structured engagement posting activity
            engagement_id = None
            pj = after.get("payload_json") or {}
            if isinstance(pj, str):
                try:
                    pj = json.loads(pj)
                except Exception:
                    pj = {}
            if isinstance(pj, dict):
                engagement_id = pj.get("engagement_id")

            if engagement_id:
                try:
                    self.upsert_engagement_posting_activity(
                        cur,
                        company_id=int(company_id),
                        engagement_id=int(engagement_id),
                        posting_date=after.get("contract_date") or after.get("start_date"),
                        module_name="revenue",
                        event_type="modified",
                        reference_no=contract_ref,
                        description=f"Applied approved modification to revenue contract {contract_ref}",
                        prepared_by_user_id=after.get("created_by_user_id"),
                        reviewer_user_id=int(user_id) if user_id else None,
                        status=str(after.get("status") or "active"),
                        amount=float(after.get("transaction_price") or 0.0),
                        currency_code=(after.get("contract_currency") or "USD"),
                        source_table="revenue_contracts",
                        source_id=int(after["id"]),
                        notes="Approved revenue contract modification applied",
                        created_by_user_id=after.get("created_by_user_id"),
                        updated_by_user_id=int(user_id) if user_id else None,
                    )
                except Exception:
                    pass

            conn.commit()

        try:
            self.audit_log(
                int(company_id),
                actor_user_id=int(user_id or 0) or None,
                module="revenue",
                action="apply_revenue_contract_modification",
                severity="info",
                entity_type="revenue_contract",
                entity_id=str(after["id"]),
                entity_ref=contract_ref,
                before_json=before,
                after_json=after,
                message=f"Applied approved modification to revenue contract {contract_ref}",
                source="approval",
            )
        except Exception:
            pass

        return {
            "before": before,
            "after": after,
        }

    def _get_revenue_setup_accounts(self, company_id: int, entries: list[dict] | None = None) -> dict:
        """
        Resolve IFRS 15 posting accounts by role / mapping, not raw company settings.

        Validation is contextual:
        - revenue_code is always required for recognition posting
        - contract_asset_code is required only if any entry hits contract asset
        - contract_liability_code is required only if any entry hits contract liability
        """
        acct_map = self.resolve_ifrs15_accounts(company_id, strict=False) or {}
        print("[IFRS15 ACCOUNTS]", acct_map, flush=True)

        revenue_code = (
            acct_map.get("contract_revenue_account")
            or acct_map.get("revenue_code")
            or acct_map.get("revenue")
            or acct_map.get("revenue_account_code")
            or ""
        ).strip()

        contract_asset_code = (
            acct_map.get("contract_asset_account")
            or acct_map.get("contract_asset_code")
            or acct_map.get("contract_asset")
            or acct_map.get("contract_asset_account_code")
            or ""
        ).strip()

        contract_liability_code = (
            acct_map.get("contract_liability_account")
            or acct_map.get("contract_liability_code")
            or acct_map.get("contract_liability")
            or acct_map.get("contract_liability_account_code")
            or ""
        ).strip()

        needs_contract_asset = False
        needs_contract_liability = False

        for e in (entries or []):
            ca = float(e.get("contract_asset_delta") or 0)
            cl = float(e.get("contract_liability_delta") or 0)

            if abs(ca) > 0:
                needs_contract_asset = True
            if abs(cl) > 0:
                needs_contract_liability = True

        if not revenue_code:
            raise ValueError("Revenue control code is not configured")
        if needs_contract_asset and not contract_asset_code:
            raise ValueError("Contract asset control code is not configured")
        if needs_contract_liability and not contract_liability_code:
            raise ValueError("Contract liability control code is not configured")

        return {
            "revenue_code": revenue_code,
            "contract_asset_code": contract_asset_code,
            "contract_liability_code": contract_liability_code,
        }


    def post_revenue_recognition_run(
        self,
        company_id: int,
        run_id: int,
        user_id: int | None = None,
        engagement_company_id: int | None = None,
        engagement_id: int | None = None,
    ) -> dict:
        from decimal import Decimal
        from datetime import date
        import json

        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            run = self.fetch_one(
                f"""
                SELECT *
                FROM {schema}.revenue_recognition_runs
                WHERE id=%s
                LIMIT 1
                """,
                (int(run_id),),
                cur=cur,
            )
            if not run:
                raise ValueError("Recognition run not found")

            if str(run.get("status") or "").lower() != "draft":
                raise ValueError("Only draft runs can be posted")

            run_period_end = run.get("period_end")
            if not run_period_end:
                raise ValueError("Recognition run is missing period_end")

            if self.is_date_locked(company_id, tx_date=run_period_end, module="revenue"):
                raise ValueError(f"PERIOD_LOCKED|revenue|{run_period_end}")

            entries = self.fetch_all(
                f"""
                SELECT *
                FROM {schema}.revenue_recognition_entries
                WHERE run_id=%s
                ORDER BY id ASC
                """,
                (int(run_id),),
                cur=cur,
            ) or []

            if not entries:
                raise ValueError("Recognition run has no entries")

            pj = run.get("payload_json") or {}
            if isinstance(pj, str):
                try:
                    pj = json.loads(pj)
                except Exception:
                    pj = {}

            # Always rebuild journal lines at posting time.
            # Never trust payload_json["journal_lines"] from preview/draft.
            try:
                jlines = self._build_revenue_recognition_journal_lines(
                    company_id=company_id,
                    run=run,
                    entries=entries,
                    cur=cur,
                )
            except Exception as build_err:
                raise ValueError(f"Recognition run journal build failed: {build_err}")

            if not jlines:
                debug_rows = []
                for e in entries:
                    debug_rows.append({
                        "entry_id": e.get("id"),
                        "contract_id": e.get("contract_id"),
                        "obligation_id": e.get("obligation_id"),
                        "revenue_delta_this_run": e.get("revenue_delta_this_run"),
                        "contract_asset_delta": e.get("contract_asset_delta"),
                        "contract_liability_delta": e.get("contract_liability_delta"),
                    })

                raise ValueError(
                    "Recognition run has no journal lines. "
                    f"Entry movements were: {debug_rows}"
                )

            # Save rebuilt lines back for audit/display only
            pj = dict(pj or {})
            pj["journal_lines"] = jlines

            cur.execute(
                f"""
                UPDATE {schema}.revenue_recognition_runs
                SET payload_json = COALESCE(payload_json, '{{}}'::jsonb) || %s::jsonb
                WHERE id=%s
                """,
                (json.dumps({"journal_lines": jlines}), int(run_id)),
            )
            run_ref = f"REV-RUN-{int(run_id)}"
            run_desc = f"Revenue recognition run {int(run_id)}"

            entry = {
                "date": run_period_end,
                "ref": run_ref,
                "description": run_desc,
                "lines": jlines,
                "source": "adjustment",
                "source_id": int(run_id),
                "currency": (run.get("currency") or "USD"),
                "created_by_user_id": int(user_id or 0) or None,
                "updated_by_user_id": int(user_id or 0) or None,
                "module_name": "revenue",
                "event_type": "posted",
                "source_table": "revenue_recognition_runs",
                "prepared_by_user_id": int(user_id or 0) or None,
            }

            entry = self._apply_engagement_bridge_to_entry(
                entry,
                row=run,
            )
            if engagement_company_id and engagement_id:
                entry["engagement_company_id"] = int(engagement_company_id)
                entry["engagement_id"] = int(engagement_id)
            journal_id = self.post_journal(
                company_id=int(company_id),
                entry=entry,
                cur=cur,
            )

            cur.execute(
                f"""
                UPDATE {schema}.revenue_recognition_runs
                SET status='posted',
                    journal_id=%s,
                    posted_by_user_id=%s,
                    posted_at=NOW()
                WHERE id=%s
                """,
                (int(journal_id), int(user_id or 0) or None, int(run_id))
            )

            contract_ids = sorted({int(e["contract_id"]) for e in entries if e.get("contract_id")})
            obligation_ids = sorted({int(e["obligation_id"]) for e in entries if e.get("obligation_id")})

            self.recalc_revenue_state(
                company_id=company_id,
                contract_ids=contract_ids,
                obligation_ids=obligation_ids,
                cur=cur,
            )

            # structured engagement posting activity per contract if engagement_id exists
            for cid in contract_ids:
                contract = self.fetch_one(
                    f"""
                    SELECT *
                    FROM {schema}.revenue_contracts
                    WHERE id=%s
                    LIMIT 1
                    """,
                    (cid,),
                    cur=cur,
                ) or {}

                pj = contract.get("payload_json") or {}
                if isinstance(pj, str):
                    try:
                        pj = json.loads(pj)
                    except Exception:
                        pj = {}

                engagement_id = pj.get("engagement_id") if isinstance(pj, dict) else None
                if not engagement_id:
                    continue

                try:
                    self.upsert_engagement_posting_activity(
                        cur,
                        company_id=int(company_id),
                        engagement_id=int(engagement_id),
                        posting_date=run_period_end,
                        module_name="revenue",
                        event_type="posted",
                        reference_no=run_ref,
                        description=run_desc,
                        prepared_by_user_id=run.get("requested_by_user_id"),
                        reviewer_user_id=int(user_id) if user_id else None,
                        status="posted",
                        amount=float(run.get("total_revenue_delta") or 0.0),
                        currency_code=(run.get("currency") or contract.get("contract_currency") or "USD"),
                        source_table="revenue_recognition_runs",
                        source_id=int(run_id),
                        notes=f"Revenue recognition run posted for contract {contract.get('contract_number') or cid}",
                        created_by_user_id=run.get("requested_by_user_id"),
                        updated_by_user_id=int(user_id) if user_id else None,
                    )
                except Exception:
                    pass

            conn.commit()

        return {
            "ok": True,
            "run_id": int(run_id),
            "journal_id": int(journal_id),
        }
        
    def reverse_revenue_recognition_run(self, company_id: int, run_id: int, user_id: int | None = None) -> dict:
        import json
        from datetime import datetime
        from decimal import Decimal

        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            run = self.fetch_one(
                f"SELECT * FROM {schema}.revenue_recognition_runs WHERE id=%s LIMIT 1;",
                (int(run_id),),
                cur=cur,
            )
            if not run:
                raise ValueError("Recognition run not found")

            if str(run.get("status") or "").lower() != "posted":
                raise ValueError("Only posted runs can be reversed")

            payload_json = run.get("payload_json") or {}
            if isinstance(payload_json, str):
                try:
                    payload_json = json.loads(payload_json)
                except Exception:
                    payload_json = {}

            # prevent double reversal
            existing_reversal_journal_id = payload_json.get("reversal_journal_id")
            if existing_reversal_journal_id:
                return {
                    "ok": True,
                    "run_id": int(run_id),
                    "reversal_journal_id": int(existing_reversal_journal_id),
                    "already_reversed": True,
                }

            entries = self.fetch_all(
                f"SELECT * FROM {schema}.revenue_recognition_entries WHERE run_id=%s ORDER BY id ASC;",
                (int(run_id),),
                cur=cur,
            ) or []

            if not entries:
                raise ValueError("Recognition run has no entries")

            reversed_lines = self._build_revenue_recognition_journal_lines(
                company_id=company_id,
                run=run,
                entries=[
                    dict(
                        e,
                        revenue_delta_this_run=float(-(Decimal(str(e.get("revenue_delta_this_run") or 0)))),
                        contract_asset_delta=float(-(Decimal(str(e.get("contract_asset_delta") or 0)))),
                        contract_liability_delta=float(-(Decimal(str(e.get("contract_liability_delta") or 0)))),
                    )
                    for e in entries
                ],
            )

            if not reversed_lines:
                raise ValueError("Recognition run has no reversal journal lines")

            run_period_end = self._as_date(run.get("period_end"))
            if not run_period_end:
                raise ValueError("Recognition run is missing valid period_end")

            entry = {
                "date": run_period_end,
                "ref": f"REV-RUN-{int(run_id)}-REV",
                "description": f"Reverse revenue recognition run {int(run_id)}",
                "lines": reversed_lines,
                "source": "adjustment",
                "source_id": -int(run_id),
                "source_table": "revenue_recognition_runs",
                "currency": (run.get("currency") or "USD"),
                "module_name": "revenue",
                "event_type": "reversed",
                "created_by_user_id": int(user_id or 0) or None,
                "updated_by_user_id": int(user_id or 0) or None,
                "prepared_by_user_id": int(user_id or 0) or None,
            }

            entry = self._apply_engagement_bridge_to_entry(
                entry,
                row=run,
            )

            journal_id = self.post_journal(
                company_id=int(company_id),
                entry=entry,
                cur=cur,
            )

            cur.execute(
                f"""
                UPDATE {schema}.revenue_recognition_runs
                SET status='reversed',
                    payload_json = COALESCE(payload_json, '{{}}'::jsonb) || %s::jsonb
                WHERE id=%s
                """,
                (
                    json.dumps({
                        "reversal_journal_id": int(journal_id),
                        "reversed_by_user_id": int(user_id or 0) or None,
                        "reversed_at": datetime.utcnow().isoformat(),
                    }),
                    int(run_id),
                )
            )

            contract_ids = sorted({int(e["contract_id"]) for e in entries if e.get("contract_id")})
            obligation_ids = sorted({int(e["obligation_id"]) for e in entries if e.get("obligation_id")})

            self.recalc_revenue_state(
                company_id=company_id,
                contract_ids=contract_ids,
                obligation_ids=obligation_ids,
                cur=cur,
            )

            conn.commit()

        return {
            "ok": True,
            "run_id": int(run_id),
            "reversal_journal_id": int(journal_id),
        }

    def recalc_single_revenue_contract(self, company_id: int, contract_id: int, cur=None) -> dict:
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, inner_cur):
            use_cur = cur or inner_cur

            obligations = self.fetch_all(
                f"SELECT id FROM {schema}.revenue_obligations WHERE contract_id = %s",
                (int(contract_id),),
                cur=use_cur,
            ) or []

            obligation_ids = [int(r["id"]) for r in obligations if r.get("id")]

            self.recalc_revenue_state(
                company_id=company_id,
                contract_ids=[int(contract_id)],
                obligation_ids=obligation_ids,
                cur=use_cur,
            )

            contract = self.get_revenue_contract(company_id, int(contract_id), cur=use_cur)
            refreshed_obligations = self.fetch_all(
                f"""
                SELECT *
                FROM {schema}.revenue_obligations
                WHERE contract_id = %s
                ORDER BY id
                """,
                (int(contract_id),),
                cur=use_cur,
            ) or []

            if cur is None:
                conn.commit()

            refreshed_obligations = [
                self._enrich_obligation_milestone_fields(contract, dict(o))
                for o in refreshed_obligations
            ]

            return {
                "contract": contract,
                "obligations": refreshed_obligations,
            }
    
    def recalc_revenue_state(
        self,
        company_id: int,
        contract_ids: list[int] | None = None,
        obligation_ids: list[int] | None = None,
        cur=None,
    ) -> None:
        schema = self.company_schema(company_id)

        contract_ids = sorted({int(x) for x in (contract_ids or []) if x})
        obligation_ids = sorted({int(x) for x in (obligation_ids or []) if x})

        for cid in contract_ids:
            cur.execute(
                f"""
                UPDATE {schema}.revenue_contracts c
                SET
                    recognized_revenue_to_date = COALESCE((
                        SELECT SUM(e.revenue_delta_this_run)
                        FROM {schema}.revenue_recognition_entries e
                        JOIN {schema}.revenue_recognition_runs r
                        ON r.id = e.run_id
                        WHERE e.contract_id = c.id
                        AND r.status = 'posted'
                    ), 0),

                    contract_liability_balance = GREATEST(
                        COALESCE(c.billed_to_date, 0) - COALESCE((
                            SELECT SUM(e.revenue_delta_this_run)
                            FROM {schema}.revenue_recognition_entries e
                            JOIN {schema}.revenue_recognition_runs r
                            ON r.id = e.run_id
                            WHERE e.contract_id = c.id
                            AND r.status = 'posted'
                        ), 0),
                        0
                    ),

                    contract_asset_balance = GREATEST(
                        COALESCE((
                            SELECT SUM(e.revenue_delta_this_run)
                            FROM {schema}.revenue_recognition_entries e
                            JOIN {schema}.revenue_recognition_runs r
                            ON r.id = e.run_id
                            WHERE e.contract_id = c.id
                            AND r.status = 'posted'
                        ), 0) - COALESCE(c.billed_to_date, 0),
                        0
                    ),

                    contract_position_type = CASE
                        WHEN COALESCE(c.billed_to_date, 0) - COALESCE((
                            SELECT SUM(e.revenue_delta_this_run)
                            FROM {schema}.revenue_recognition_entries e
                            JOIN {schema}.revenue_recognition_runs r
                            ON r.id = e.run_id
                            WHERE e.contract_id = c.id
                            AND r.status = 'posted'
                        ), 0) > 0 THEN 'liability'
                        WHEN COALESCE((
                            SELECT SUM(e.revenue_delta_this_run)
                            FROM {schema}.revenue_recognition_entries e
                            JOIN {schema}.revenue_recognition_runs r
                            ON r.id = e.run_id
                            WHERE e.contract_id = c.id
                            AND r.status = 'posted'
                        ), 0) - COALESCE(c.billed_to_date, 0) > 0 THEN 'asset'
                        ELSE 'neutral'
                    END,

                    contract_position_amount = ABS(
                        COALESCE(c.billed_to_date, 0) - COALESCE((
                            SELECT SUM(e.revenue_delta_this_run)
                            FROM {schema}.revenue_recognition_entries e
                            JOIN {schema}.revenue_recognition_runs r
                            ON r.id = e.run_id
                            WHERE e.contract_id = c.id
                            AND r.status = 'posted'
                        ), 0)
                    ),

                    revenue_status = CASE
                        WHEN COALESCE((
                            SELECT SUM(e.revenue_delta_this_run)
                            FROM {schema}.revenue_recognition_entries e
                            JOIN {schema}.revenue_recognition_runs r
                            ON r.id = e.run_id
                            WHERE e.contract_id = c.id
                            AND r.status = 'posted'
                        ), 0) <= 0 THEN 'not_started'
                        WHEN COALESCE((
                            SELECT SUM(e.revenue_delta_this_run)
                            FROM {schema}.revenue_recognition_entries e
                            JOIN {schema}.revenue_recognition_runs r
                            ON r.id = e.run_id
                            WHERE e.contract_id = c.id
                            AND r.status = 'posted'
                        ), 0) >= c.transaction_price THEN 'fully_recognized'
                        ELSE 'in_progress'
                    END,

                    updated_at = NOW()
                WHERE c.id = %s
                """,
                (cid,),
            )

        for oid in obligation_ids:
            cur.execute(
                f"""
                UPDATE {schema}.revenue_obligations o
                SET
                    revenue_to_date = COALESCE((
                        SELECT SUM(e.revenue_delta_this_run)
                        FROM {schema}.revenue_recognition_entries e
                        JOIN {schema}.revenue_recognition_runs r
                        ON r.id = e.run_id
                        WHERE e.obligation_id = o.id
                        AND r.status = 'posted'
                    ), 0),
                    updated_at = NOW()
                WHERE o.id = %s
                """,
                (oid,),
            )

    def list_revenue_contract_versions(self, company_id: int, contract_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT *
            FROM {schema}.revenue_contract_versions
            WHERE contract_id = %s
            ORDER BY version_no DESC, id DESC
        """
        return self.fetch_all(sql, (int(contract_id),)) or []


    def list_revenue_obligations(self, company_id: int, contract_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT *
            FROM {schema}.revenue_obligations
            WHERE contract_id = %s
            ORDER BY id ASC
        """

        rows = self.fetch_all(sql, (int(contract_id),)) or []

        contract = self.get_revenue_contract(
            company_id=int(company_id),
            contract_id=int(contract_id),
        )

        return [
            self._enrich_obligation_milestone_fields(contract, dict(row))
            for row in rows
        ]

    def sync_obligation_progress_to_project_task(self, company_id: int, obligation_id: int, cur=None):
        schema = self.company_schema(company_id)

        def _run(_cur):
            obligation = self.fetch_one(
                f"""
                SELECT
                    o.*,
                    c.project_id
                FROM {schema}.revenue_obligations o
                JOIN {schema}.revenue_contracts c
                ON c.id = o.contract_id
                AND c.company_id = o.company_id
                WHERE o.company_id = %s
                AND o.id = %s
                LIMIT 1
                """,
                (int(company_id), int(obligation_id)),
                cur=_cur,
            )

            if not obligation:
                return None

            payload = obligation.get("payload_json") or {}
            if isinstance(payload, str):
                payload = json.loads(payload or "{}")

            task_id = (
                obligation.get("project_task_id")
                or payload.get("project_task_id")
                or payload.get("task_id")
            )

            if not task_id:
                return None

            progress = float(obligation.get("progress_percent") or 0)

            if (
                str(obligation.get("recognition_timing") or "").lower() == "point_in_time"
                and str(obligation.get("satisfaction_status") or "").lower() == "satisfied"
            ):
                progress = 100.0

            progress = max(0.0, min(progress, 100.0))

            _cur.execute(
                f"""
                UPDATE {schema}.project_tasks
                SET progress_percent = %s,
                    status = CASE
                        WHEN %s >= 100 THEN 'completed'
                        WHEN %s > 0 THEN 'in_progress'
                        ELSE status
                    END,
                    updated_at = NOW()
                WHERE company_id = %s
                AND project_id = %s
                AND id = %s
                RETURNING *;
                """,
                (
                    progress,
                    progress,
                    progress,
                    int(company_id),
                    int(obligation["project_id"]),
                    int(task_id),
                ),
            )

            row = _cur.fetchone()
            return dict(row) if row else None

        if cur:
            return _run(cur)

        with self._conn_cursor() as (conn, _cur):
            row = _run(_cur)
            conn.commit()
            return row
    
    def _as_date(self, value):
        from datetime import date, datetime

        if value in (None, "", 0):
            return None

        if isinstance(value, date) and not isinstance(value, datetime):
            return value

        if isinstance(value, datetime):
            return value.date()

        s = str(value).strip()
        if not s:
            return None

        # handle 'YYYY-MM-DD'
        try:
            return datetime.strptime(s[:10], "%Y-%m-%d").date()
        except Exception:
            pass

        # handle general datetime string
        try:
            return datetime.fromisoformat(s.replace("Z", "+00:00")).date()
        except Exception:
            return None
        
    def _get_latest_revenue_obligation_invoice_link(
        self,
        company_id: int,
        obligation_id: int,
        cur=None,
    ) -> dict | None:
        schema = self.company_schema(company_id)

        row = self.fetch_one(
            f"""
            SELECT
                rbe.id AS billing_event_id,
                rbe.source_invoice_id AS invoice_id,
                rbe.event_date,
                rbe.amount,
                rbe.currency,
                i.number AS invoice_number,
                i.status AS invoice_status
            FROM {schema}.revenue_billing_events rbe
            LEFT JOIN {schema}.invoices i
            ON i.id = rbe.source_invoice_id
            WHERE rbe.obligation_id = %s
            AND rbe.source_invoice_id IS NOT NULL
            ORDER BY rbe.event_date DESC, rbe.id DESC
            LIMIT 1
            """,
            (int(obligation_id),),
            cur=cur,
        )
        return row or None


    def get_revenue_obligation_billable_preview(
        self,
        company_id: int,
        obligation_id: int,
        cur=None,
    ) -> dict | None:
        from decimal import Decimal
        import json

        schema = self.company_schema(company_id)

        obligation = self.get_revenue_obligation(int(company_id), int(obligation_id), cur=cur)
        if not obligation:
            return None

        contract_id = int(obligation.get("contract_id") or 0)
        if not contract_id:
            return None

        contract = self.get_revenue_contract(int(company_id), contract_id, cur=cur)
        if not contract:
            return None

        payload = contract.get("payload_json") or {}
        if isinstance(payload, str):
            try:
                payload = json.loads(payload)
            except Exception:
                payload = {}

        settlement_pattern = str(payload.get("settlement_pattern") or "").strip().lower()
        timing = str(obligation.get("recognition_timing") or "").strip().lower()
        progress_method = str(obligation.get("progress_method") or "").strip().lower() or None

        billed_stats = self._obligation_billing_validation_stats(
            company_id=int(company_id),
            contract=contract,
            obligation=obligation,
            period_end=None,
            cur=cur,
        )

        billed_to_date = Decimal(str(billed_stats.get("billed_to_date") or 0)).quantize(Decimal("0.01"))

        latest_recognition = self.fetch_one(
            f"""
            SELECT
                e.id,
                e.run_id,
                e.period_start,
                e.period_end,
                e.revenue_required_to_date,
                e.revenue_previously_recognized,
                e.revenue_delta_this_run,
                e.contract_asset_delta,
                e.contract_liability_delta,
                r.status AS run_status,
                r.posted_at,
                r.created_at
            FROM {schema}.revenue_recognition_entries e
            JOIN {schema}.revenue_recognition_runs r
            ON r.id = e.run_id
            WHERE e.obligation_id = %s
            AND r.status IN ('draft', 'posted')
            ORDER BY
                CASE WHEN r.status = 'posted' THEN 0 ELSE 1 END,
                COALESCE(r.posted_at, r.created_at) DESC,
                e.id DESC
            LIMIT 1
            """,
            (int(obligation_id),),
            cur=cur,
        ) or {}

        recognized_to_date_posted = Decimal(str(obligation.get("revenue_to_date") or 0)).quantize(Decimal("0.01"))

        recognized_to_date_preview = recognized_to_date_posted
        if latest_recognition:
            recognized_to_date_preview = Decimal(
                str(
                    latest_recognition.get("revenue_required_to_date")
                    if latest_recognition.get("revenue_required_to_date") is not None
                    else obligation.get("revenue_to_date") or 0
                )
            ).quantize(Decimal("0.01"))

        available_to_bill = (recognized_to_date_preview - billed_to_date).quantize(Decimal("0.01"))
        if available_to_bill < Decimal("0.00"):
            available_to_bill = Decimal("0.00")

        linked_invoice = self._get_latest_revenue_obligation_invoice_link(
            company_id=int(company_id),
            obligation_id=int(obligation_id),
            cur=cur,
        )

        return {
            "company_id": int(company_id),
            "contract_id": contract_id,
            "contract_number": contract.get("contract_number"),
            "contract_title": contract.get("contract_title"),
            "customer_id": contract.get("customer_id"),
            "contract_currency": contract.get("contract_currency") or "USD",
            "settlement_pattern": settlement_pattern or None,

            "obligation_id": int(obligation.get("id")),
            "obligation_code": obligation.get("obligation_code"),
            "obligation_name": obligation.get("obligation_name"),
            "linked_milestone_code": obligation.get("linked_milestone_code"),
            "linked_milestone_description": obligation.get("linked_milestone_description"),
            "linked_milestone_amount": obligation.get("linked_milestone_amount"),
            "recognition_timing": timing,
            "progress_method": progress_method,
            "allocated_transaction_price": float(obligation.get("allocated_transaction_price") or 0.0),

            "recognized_to_date_posted": float(recognized_to_date_posted),
            "recognized_to_date_preview": float(recognized_to_date_preview),
            "billed_to_date": float(billed_to_date),
            "available_to_bill": float(available_to_bill),

            "latest_recognition": {
                "entry_id": int(latest_recognition["id"]) if latest_recognition.get("id") else None,
                "run_id": int(latest_recognition["run_id"]) if latest_recognition.get("run_id") else None,
                "run_status": latest_recognition.get("run_status"),
                "period_start": str(latest_recognition.get("period_start")) if latest_recognition.get("period_start") else None,
                "period_end": str(latest_recognition.get("period_end")) if latest_recognition.get("period_end") else None,
                "revenue_required_to_date": float(latest_recognition.get("revenue_required_to_date") or 0.0),
                "revenue_previously_recognized": float(latest_recognition.get("revenue_previously_recognized") or 0.0),
                "revenue_delta_this_run": float(latest_recognition.get("revenue_delta_this_run") or 0.0),
                "contract_asset_delta": float(latest_recognition.get("contract_asset_delta") or 0.0),
                "contract_liability_delta": float(latest_recognition.get("contract_liability_delta") or 0.0),
            } if latest_recognition else None,

            "linked_invoice": {
                "billing_event_id": int(linked_invoice["billing_event_id"]) if linked_invoice.get("billing_event_id") else None,
                "invoice_id": int(linked_invoice["invoice_id"]) if linked_invoice.get("invoice_id") else None,
                "invoice_number": linked_invoice.get("invoice_number"),
                "invoice_status": linked_invoice.get("invoice_status"),
                "event_date": str(linked_invoice.get("event_date")) if linked_invoice.get("event_date") else None,
                "amount": float(linked_invoice.get("amount") or 0.0),
                "currency": linked_invoice.get("currency"),
            } if linked_invoice else None,

            "ui": {
                "view_only": bool(timing == "over_time" and settlement_pattern == "revenue_before_billing"),
                "has_linked_invoice": bool(linked_invoice and linked_invoice.get("invoice_id")),
                "can_create_invoice": bool(
                    timing == "over_time"
                    and settlement_pattern == "revenue_before_billing"
                    and available_to_bill > Decimal("0.00")
                    # and not (linked_invoice and linked_invoice.get("invoice_id"))
                ),
            },
        }

    def get_accounting_work_queue(self, company_id: int, *, date_from=None, date_to=None, limit: int = 20):
        schema = self.company_schema(company_id)
        items = []

        with self._conn_cursor() as (conn, cur):

            # 1) Loan payments due
            cur.execute(f"""
                WITH due AS (
                    SELECT
                        ls.id AS schedule_id,
                        ls.loan_id,
                        ls.due_date,
                        ls.scheduled_payment
                    FROM {schema}.loan_schedules ls
                    JOIN {schema}.loans l
                        ON l.id = ls.loan_id
                        AND l.company_id = ls.company_id
                    WHERE ls.company_id = %s
                    AND ls.payment_status IN ('open', 'partial')
                    AND (%s IS NULL OR ls.due_date >= %s)
                    AND (%s IS NULL OR ls.due_date <= %s)
                    AND COALESCE(l.status, 'active') = 'active'
                    ORDER BY ls.due_date ASC, ls.period_no ASC, ls.id ASC
                )
                SELECT
                    COUNT(*) AS count,
                    COALESCE(SUM(scheduled_payment), 0) AS amount,
                    MIN(due_date) AS next_due,
                    (ARRAY_AGG(loan_id ORDER BY due_date ASC, schedule_id ASC))[1] AS loan_id,
                    (ARRAY_AGG(schedule_id ORDER BY due_date ASC, schedule_id ASC))[1] AS schedule_id
                FROM due
            """, (company_id, date_from, date_from, date_to, date_to))

            row = cur.fetchone() or {}
            if int(row.get("count") or 0) > 0:
                items.append({
                    "type": "loan_payment_due",
                    "title": "Loan payments due",
                    "count": int(row.get("count") or 0),
                    "amount": float(row.get("amount") or 0),
                    "hint": f"Next due: {row.get('next_due')}",
                    "screen": "loans",
                    "severity": "warning",
                    "target": {
                        "screen": "loans",
                        "tab": "payments",
                        "loan_id": row.get("loan_id"),
                        "schedule_id": row.get("schedule_id"),
                        "action": "record_payment",
                    },
                })

            # 1B) Lease payments due
            cur.execute(f"""
                WITH due AS (
                    SELECT
                        s.id AS schedule_id,
                        s.lease_id,
                        s.period_end,
                        s.payment
                    FROM {schema}.lease_schedule s
                    JOIN {schema}.leases l
                        ON l.id = s.lease_id
                        AND l.company_id = s.company_id
                    WHERE s.company_id = %s
                    AND COALESCE(s.is_active, TRUE) = TRUE
                    AND COALESCE(l.status, 'active') = 'active'
                    AND (%s IS NULL OR s.period_end >= %s)
                    AND (%s IS NULL OR s.period_end <= %s)
                    AND NOT EXISTS (
                        SELECT 1
                        FROM {schema}.lease_payments p
                        WHERE p.company_id = s.company_id
                        AND p.lease_id = s.lease_id
                        AND p.schedule_id = s.id
                        AND COALESCE(p.status, '') IN ('draft', 'posted')
                    )
                    ORDER BY s.period_end ASC, s.id ASC
                )
                SELECT
                    COUNT(*) AS count,
                    COALESCE(SUM(payment), 0) AS amount,
                    MIN(period_end) AS next_due,
                    (ARRAY_AGG(lease_id ORDER BY period_end ASC, schedule_id ASC))[1] AS lease_id,
                    (ARRAY_AGG(schedule_id ORDER BY period_end ASC, schedule_id ASC))[1] AS schedule_id
                FROM due
            """, (company_id, date_from, date_from, date_to, date_to))

            row = cur.fetchone() or {}
            if int(row.get("count") or 0) > 0:
                items.append({
                    "type": "lease_payment_due",
                    "title": "Lease payments outstanding",
                    "count": int(row.get("count") or 0),
                    "amount": float(row.get("amount") or 0),
                    "hint": f"Next lease due: {row.get('next_due')}",
                    "screen": "leases",
                    "severity": "warning",
                    "target": {
                        "screen": "leases",
                        "tab": "payments",
                        "lease_id": row.get("lease_id"),
                        "schedule_id": row.get("schedule_id"),
                        "action": "record_lease_payment",
                    },
                })

            # 2) Recognised revenue not billed
            cur.execute(f"""
                WITH due AS (
                    SELECT
                        id AS contract_id,
                        COALESCE(recognized_revenue_to_date, 0) - COALESCE(billed_to_date, 0) AS amount
                    FROM {schema}.revenue_contracts
                    WHERE company_id = %s
                    AND COALESCE(recognized_revenue_to_date, 0) > COALESCE(billed_to_date, 0)
                    AND COALESCE(status, '') IN ('active', 'completed')
                    ORDER BY id ASC
                )
                SELECT
                    COUNT(*) AS count,
                    COALESCE(SUM(amount), 0) AS amount,
                    (ARRAY_AGG(contract_id ORDER BY contract_id ASC))[1] AS contract_id
                FROM due
            """, (company_id,))

            row = cur.fetchone() or {}
            if int(row.get("count") or 0) > 0:
                items.append({
                    "type": "revenue_ready_to_bill",
                    "title": "Recognised revenue not billed",
                    "count": int(row.get("count") or 0),
                    "amount": float(row.get("amount") or 0),
                    "hint": "Create invoices for earned revenue.",
                    "screen": "revenue",
                    "severity": "info",
                    "target": {
                        "screen": "revenue",
                        "tab": "billing",
                        "contract_id": row.get("contract_id"),
                        "action": "bill_recognised_revenue",
                    },
                })

            # 3) Billing ahead of revenue
            cur.execute(f"""
                WITH due AS (
                    SELECT
                        id AS contract_id,
                        COALESCE(billed_to_date, 0) - COALESCE(recognized_revenue_to_date, 0) AS amount
                    FROM {schema}.revenue_contracts
                    WHERE company_id = %s
                    AND COALESCE(billed_to_date, 0) > COALESCE(recognized_revenue_to_date, 0)
                    AND COALESCE(status, '') IN ('active', 'completed')
                    ORDER BY id ASC
                )
                SELECT
                    COUNT(*) AS count,
                    COALESCE(SUM(amount), 0) AS amount,
                    (ARRAY_AGG(contract_id ORDER BY contract_id ASC))[1] AS contract_id
                FROM due
            """, (company_id,))

            row = cur.fetchone() or {}
            if int(row.get("count") or 0) > 0:
                items.append({
                    "type": "billing_ahead_of_revenue",
                    "title": "Billing ahead of recognition",
                    "count": int(row.get("count") or 0),
                    "amount": float(row.get("amount") or 0),
                    "hint": "Review contract liability / deferred income.",
                    "screen": "revenue",
                    "severity": "neutral",
                    "target": {
                        "screen": "revenue",
                        "tab": "contracts",
                        "contract_id": row.get("contract_id"),
                        "action": "review_contract_liability",
                    },
                })

            # 4) Satisfied obligations pending recognition
            cur.execute(f"""
                WITH due AS (
                    SELECT
                        ro.id AS obligation_id,
                        ro.contract_id,
                        ro.satisfied_at,
                        ro.allocated_transaction_price AS amount
                    FROM {schema}.revenue_obligations ro
                    JOIN {schema}.revenue_contracts rc
                        ON rc.id = ro.contract_id
                        AND rc.company_id = ro.company_id
                    WHERE ro.company_id = %s
                    AND ro.recognition_timing = 'point_in_time'
                    AND ro.satisfaction_status = 'satisfied'
                    AND COALESCE(ro.revenue_to_date, 0) < COALESCE(ro.allocated_transaction_price, 0)
                    AND COALESCE(rc.status, '') IN ('active', 'completed')
                    ORDER BY ro.satisfied_at ASC NULLS LAST, ro.id ASC
                )
                SELECT
                    COUNT(*) AS count,
                    COALESCE(SUM(amount), 0) AS amount,
                    MIN(satisfied_at) AS oldest_satisfied,
                    (ARRAY_AGG(contract_id ORDER BY satisfied_at ASC NULLS LAST, obligation_id ASC))[1] AS contract_id,
                    (ARRAY_AGG(obligation_id ORDER BY satisfied_at ASC NULLS LAST, obligation_id ASC))[1] AS obligation_id
                FROM due
            """, (company_id,))

            row = cur.fetchone() or {}
            if int(row.get("count") or 0) > 0:
                items.append({
                    "type": "pit_obligation_ready",
                    "title": "Satisfied obligations pending recognition",
                    "count": int(row.get("count") or 0),
                    "amount": float(row.get("amount") or 0),
                    "hint": f"Oldest satisfied: {row.get('oldest_satisfied')}",
                    "screen": "revenue",
                    "severity": "warning",
                    "target": {
                        "screen": "revenue",
                        "tab": "recognition",
                        "contract_id": row.get("contract_id"),
                        "obligation_id": row.get("obligation_id"),
                        "action": "recognise_obligation",
                    },
                })

            # 5) GRNI receipts pending supplier billing
            cur.execute(f"""
                WITH due AS (
                    SELECT
                        tx.id AS receipt_tx_id,
                        tx.tx_date,
                        tx.ref,
                        COALESCE(
                            SUM(
                                COALESCE(l.qty, 0) * COALESCE(l.unit_cost, 0)
                            ),
                            0
                        ) AS amount
                    FROM {schema}.inventory_tx tx
                    LEFT JOIN {schema}.inventory_tx_lines l
                        ON l.company_id = tx.company_id
                    AND l.tx_id = tx.id

                    WHERE tx.company_id = %s
                    AND lower(COALESCE(tx.tx_type, '')) = 'receipt'
                    AND COALESCE(tx.grni_status, 'unbilled')
                        IN ('unbilled', 'partial')

                    AND NOT EXISTS (
                        SELECT 1
                        FROM {schema}.bill_grni_links gl
                        WHERE gl.company_id = tx.company_id
                        AND gl.receipt_tx_id = tx.id
                    )

                    GROUP BY
                        tx.id,
                        tx.tx_date,
                        tx.ref

                    ORDER BY
                        tx.tx_date ASC,
                        tx.id ASC
                )

                SELECT
                    COUNT(*) AS count,
                    COALESCE(SUM(amount), 0) AS amount,
                    MIN(tx_date) AS oldest_receipt,

                    (
                        ARRAY_AGG(
                            receipt_tx_id
                            ORDER BY tx_date ASC, receipt_tx_id ASC
                        )
                    )[1] AS receipt_tx_id

                FROM due
            """, (company_id,))

            row = cur.fetchone() or {}

            if int(row.get("count") or 0) > 0:
                items.append({
                    "type": "grni_pending_billing",
                    "title": "GRNI pending billing",
                    "count": int(row.get("count") or 0),
                    "amount": float(row.get("amount") or 0),

                    "hint": (
                        f"Oldest receipt: {row.get('oldest_receipt')}"
                    ),

                    "screen": "ap-bills",
                    "severity": "warning",

                    "target": {
                        "screen": "ap-bills",
                        "tab": "bills",
                        "receipt_tx_id": row.get("receipt_tx_id"),
                        "action": "capture_grni_bill",
                    },
                })

            # 6) Asset acquisitions pending vendor bill capture
            cur.execute(f"""
                WITH due AS (
                    SELECT
                        aa.id AS acquisition_id,
                        aa.asset_id,
                        aa.supplier_id AS vendor_id,
                        aa.grn_no,
                        aa.vendor_invoice_no,
                        aa.reference,
                        aa.funding_source,
                        aa.posting_date,
                        aa.amount,
                        a.asset_name
                    FROM {schema}.asset_acquisitions aa
                    JOIN {schema}.assets a
                        ON a.company_id = aa.company_id
                    AND a.id = aa.asset_id
                    WHERE aa.company_id = %s
                    AND lower(COALESCE(aa.funding_source, '')) IN ('grni', 'vendor_credit', 'other')
                    AND aa.supplier_id IS NOT NULL

                    AND NOT EXISTS (
                        SELECT 1
                        FROM {schema}.bills b
                        WHERE b.company_id = aa.company_id
                        AND b.vendor_id = aa.supplier_id
                        AND lower(COALESCE(b.number, '')) IN (
                            lower(COALESCE(aa.grn_no, '')),
                            lower(COALESCE(aa.vendor_invoice_no, '')),
                            lower(COALESCE(aa.reference, ''))
                        )
                    )

                    ORDER BY aa.posting_date ASC, aa.id ASC
                )

                SELECT
                    COUNT(*) AS count,
                    COALESCE(SUM(amount), 0) AS amount,
                    MIN(posting_date) AS oldest_receipt,

                    (
                        ARRAY_AGG(
                            acquisition_id
                            ORDER BY posting_date ASC, acquisition_id ASC
                        )
                    )[1] AS acquisition_id,

                    (
                        ARRAY_AGG(
                            vendor_id
                            ORDER BY posting_date ASC, acquisition_id ASC
                        )
                    )[1] AS vendor_id,

                    (
                        ARRAY_AGG(
                            funding_source
                            ORDER BY posting_date ASC, acquisition_id ASC
                        )
                    )[1] AS funding_source

                FROM due
            """, (company_id,))

            row = cur.fetchone() or {}

            if int(row.get("count") or 0) > 0:
                items.append({
                    "type": "asset_acquisition_pending_billing",
                    "title": "Asset acquisitions pending billing",
                    "count": int(row.get("count") or 0),
                    "amount": float(row.get("amount") or 0),

                    "hint": (
                        f"Oldest acquisition: {row.get('oldest_receipt')}"
                    ),

                    "screen": "ap-bills",
                    "severity": "warning",

                    "target": {
                        "screen": "ap-bills",
                        "tab": "bills",
                        "vendor_id": row.get("vendor_id"),
                        "acquisition_id": row.get("acquisition_id"),
                        "funding_source": row.get("funding_source"),
                        "action": "link_asset_grni",
                    },
                })
        return {
            "items": items[:limit],
            "count": len(items),
        }

    def build_revenue_disclosure(self, company_id: int, date_from, date_to):
        return build_revenue_disclosure_payload(
            self,
            int(company_id),
            date_from,
            date_to,
        )


    def get_financial_statement_note(
        self,
        company_id: int,
        note_key: str,
        period_from,
        period_to,
        *,
        cur=None,
    ) -> Optional[dict]:
        schema = self.company_schema(company_id)

        return self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.financial_statement_notes
            WHERE company_id = %s
            AND note_key = %s
            AND period_from IS NOT DISTINCT FROM %s
            AND period_to IS NOT DISTINCT FROM %s
            LIMIT 1;
            """,
            (int(company_id), note_key, period_from, period_to),
            cur=cur,
        )


    def save_financial_statement_note(
        self,
        company_id: int,
        note_key: str,
        note_title: str,
        period_from,
        period_to,
        content_text: str,
        *,
        system_draft: str | None = None,
        source: str = "user",
        is_custom: bool = True,
        payload_json: dict | None = None,
        cur=None,
    ) -> dict:
        schema = self.company_schema(company_id)

        payload_json = payload_json or {}
        last_generated_hash = _note_hash(system_draft or content_text or "")

        row = self.fetch_one(
            f"""
            INSERT INTO {schema}.financial_statement_notes (
                company_id,
                note_key,
                note_title,
                period_from,
                period_to,
                content_text,
                system_draft,
                source,
                is_custom,
                last_generated_hash,
                payload_json,
                updated_at
            )
            VALUES (
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                %s::jsonb,
                NOW()
            )
            ON CONFLICT (company_id, note_key, period_from, period_to)
            DO UPDATE SET
                note_title = EXCLUDED.note_title,
                content_text = EXCLUDED.content_text,
                system_draft = EXCLUDED.system_draft,
                source = EXCLUDED.source,
                is_custom = EXCLUDED.is_custom,
                last_generated_hash = EXCLUDED.last_generated_hash,
                payload_json = EXCLUDED.payload_json,
                updated_at = NOW()
            RETURNING *;
            """,
            (
                int(company_id),
                note_key,
                note_title,
                period_from,
                period_to,
                content_text or "",
                system_draft,
                source,
                bool(is_custom),
                last_generated_hash,
                _json_dumps(payload_json),
            ),
            cur=cur,
        )

        return dict(row or {})


    def reset_financial_statement_note(
        self,
        company_id: int,
        note_key: str,
        period_from,
        period_to,
        *,
        cur=None,
    ) -> dict:
        # Build the fresh system draft first
        built = self.get_or_build_financial_statement_note(
            company_id=company_id,
            note_key=note_key,
            period_from=period_from,
            period_to=period_to,
            cur=cur,
        )

        fresh_system_draft = built.get("system_draft") or built.get("content_text") or ""
        fresh_hash = _note_hash(fresh_system_draft)
        note_title = built.get("note_title") or note_key

        schema = self.company_schema(company_id)

        row = self.fetch_one(
            f"""
            UPDATE {schema}.financial_statement_notes
            SET
                note_title = %s,
                content_text = %s,
                system_draft = %s,
                last_generated_hash = %s,
                source = 'system',
                is_custom = FALSE,
                updated_at = NOW()
            WHERE company_id = %s
            AND note_key = %s
            AND period_from IS NOT DISTINCT FROM %s
            AND period_to IS NOT DISTINCT FROM %s
            RETURNING *;
            """,
            (
                note_title,
                fresh_system_draft,
                fresh_system_draft,
                fresh_hash,
                int(company_id),
                note_key,
                period_from,
                period_to,
            ),
            cur=cur,
        )

        note = dict(row or {})
        note["current_generated_hash"] = fresh_hash
        note["is_outdated"] = False

        return note

    def _period_label(self, date_from, date_to) -> str:
        if date_from and date_to:
            return f"the reporting period from {date_from} to {date_to}"
        if date_to:
            return f"the reporting period ended {date_to}"
        return "the reporting period"

    def build_ppe_note_package(
        self,
        company_id: int,
        date_from,
        date_to,
        *,
        cur=None,
    ) -> dict:
        """
        IAS 16 PPE disclosure package.

        Returns:
        - policy_note: narrative IAS 16 accounting policy / disclosure text
        - ppe_summary_table: movement summary by asset class
        - totals: overall PPE totals
        """

        if cur is None:
            with self._conn_cursor() as (_conn, cur):
                return self.build_ppe_note_package(
                    company_id,
                    date_from,
                    date_to,
                    cur=cur,
                )

        def num(v):
            try:
                return float(v or 0)
            except (TypeError, ValueError):
                return 0.0

        def fmt(v):
            return f"{num(v):,.2f}"

        disclosure = self.get_ppe_disclosure_by_class(
            cur,
            company_id,
            date_from,
            date_to,
        ) or []

        preferred_order = {
            "land": 1,
            "buildings": 2,
            "plant & equipment": 3,
            "plant and equipment": 3,
            "vehicles": 4,
            "motor vehicles": 4,
            "computer equipment": 5,
            "computers": 5,
            "furniture & fittings": 6,
            "furniture and fittings": 6,
            "office equipment": 7,
            "construction in progress": 8,
            "expansion project": 8,
        }

        def normalise_class(name: str) -> str:
            n = (name or "").strip()
            low = n.lower()

            if low in ("computer", "computers"):
                return "Computer Equipment"
            if low in ("vehicle", "vehicles", "motor vehicle", "motor vehicles"):
                return "Motor Vehicles"
            if low in ("plant and equipment", "plant & equipment"):
                return "Plant & Equipment"
            if low in ("furniture", "furniture and fittings", "furniture & fittings"):
                return "Furniture & Fittings"
            if low in ("cip", "construction in progress", "expansion project"):
                return "Construction in Progress"
            if low == "land":
                return "Land"
            if low == "buildings":
                return "Buildings"
            if low == "office equipment":
                return "Office Equipment"

            return n.title() if n else "Unclassified PPE"

        grouped = {}

        for r in disclosure:
            if not isinstance(r, dict):
                continue

            asset_class = normalise_class(r.get("asset_class"))

            g = grouped.setdefault(asset_class, {
                "asset_class": asset_class,
                "opening_carrying": 0.0,
                "additions": 0.0,
                "transfers": 0.0,
                "disposals": 0.0,
                "depreciation": 0.0,
                "impairment": 0.0,
                "revaluation": 0.0,
                "closing_carrying": 0.0,
            })

            additions = num(r.get("additions_cost")) + num(r.get("subsequent_additions_cost"))

            transfers = (
                num(r.get("transfers_in_carrying"))
                + num(r.get("transfers_out_carrying"))
            )

            disposals = num(r.get("disposals_carrying"))

            impairment = (
                num(r.get("impairment_losses"))
                - num(r.get("impairment_reversals"))
            )

            revaluation = (
                num(r.get("revaluation_upward"))
                + num(r.get("revaluation_downward"))
            )

            g["opening_carrying"] += num(r.get("opening_carrying"))
            g["additions"] += additions
            g["transfers"] += transfers
            g["disposals"] += disposals
            g["depreciation"] += num(r.get("depreciation_charge"))
            g["impairment"] += impairment
            g["revaluation"] += revaluation
            g["closing_carrying"] += num(r.get("closing_carrying"))

        rows = list(grouped.values())

        rows.sort(
            key=lambda x: preferred_order.get(
                (x.get("asset_class") or "").lower(),
                99,
            )
        )

        totals = {
            "opening_carrying": sum(num(r["opening_carrying"]) for r in rows),
            "additions": sum(num(r["additions"]) for r in rows),
            "transfers": sum(num(r["transfers"]) for r in rows),
            "disposals": sum(num(r["disposals"]) for r in rows),
            "depreciation": sum(num(r["depreciation"]) for r in rows),
            "impairment": sum(num(r["impairment"]) for r in rows),
            "revaluation": sum(num(r["revaluation"]) for r in rows),
            "closing_carrying": sum(num(r["closing_carrying"]) for r in rows),
        }

        period_label = self._period_label(date_from, date_to)

        policy_note = f"""
    Property, plant and equipment are initially recognised at cost. Cost includes the purchase price and any costs directly attributable to bringing the asset to the location and condition necessary for it to operate as intended by management.

    Subsequent expenditure is capitalised only when it is probable that future economic benefits associated with the item will flow to the company and the cost can be measured reliably. All other repairs and maintenance are recognised in profit or loss as incurred.

    Property, plant and equipment are subsequently measured at cost less accumulated depreciation and accumulated impairment losses, unless a revaluation model is applied to specific asset classes.

    Depreciation is recognised so as to allocate the depreciable amount of assets over their estimated useful lives. Land and construction in progress are not depreciated. The residual values, useful lives and depreciation methods are reviewed at each reporting date and adjusted prospectively where necessary.

    The company's major classes of property, plant and equipment comprise land, buildings, plant and equipment, motor vehicles, computer equipment, furniture and fittings, office equipment, and construction in progress.

    During {period_label}, additions to property, plant and equipment amounted to R{fmt(totals["additions"])}. Depreciation charged for the period amounted to R{fmt(totals["depreciation"])}. The closing carrying amount of property, plant and equipment was R{fmt(totals["closing_carrying"])}.
    """.strip()

        total_row = {
            "asset_class": "Total",
            **totals,
        }

        return {
            "policy_note": policy_note,
            "ppe_summary_table": rows,
            "ppe_summary_total": total_row,
            "raw_disclosure": disclosure,
        }

    def build_ppe_policy_note_text(
        self,
        company_id: int,
        date_from,
        date_to,
        *,
        cur=None,
    ) -> str:
        package = self.build_ppe_note_package(
            company_id,
            date_from,
            date_to,
            cur=cur,
        )
        return package.get("policy_note") or ""

    def build_lease_policy_note_text(self, company_id: int, date_from, date_to, *, cur=None) -> str:
        d = self.get_ifrs16_disclosure_strict(
            company_id,
            from_date=date_from,
            to_date=date_to,
            as_of=date_to,
            include_terminated=True,
            cur=cur,
        )

        period_label = self._period_label(date_from, date_to)

        rou = d.get("rou") or {}
        liability = d.get("liability") or {}
        pnl = d.get("pnl") or {}
        maturity = d.get("maturity_analysis") or {}
        exemptions = d.get("exemptions") or {}

        short_term = exemptions.get("short_term_lease_expense")
        low_value = exemptions.get("low_value_lease_expense")

        exemption_text = ""
        if short_term is not None or low_value is not None:
            exemption_text = (
                f"\n\nShort-term lease expense recognised during the period amounted to R{_money(short_term):,.2f}. "
                f"Low-value lease expense recognised during the period amounted to R{_money(low_value):,.2f}."
            )

        return f"""
    The company accounts for leases in accordance with IFRS 16 Leases. At the commencement date of a lease, the company recognises a right-of-use asset and a corresponding lease liability, except for leases that qualify for recognition exemptions.

    The lease liability is initially measured at the present value of lease payments that are not paid at commencement date. Lease payments are discounted using the interest rate implicit in the lease where that rate can be readily determined. Where that rate cannot be readily determined, the company uses its incremental borrowing rate.

    The right-of-use asset is initially measured at cost and subsequently depreciated over the shorter of the lease term and the useful life of the underlying asset. The lease liability is subsequently measured using the effective interest method and is remeasured when there is a change in lease payments, lease term or other relevant lease assumptions.

    Management applies judgement in determining the lease term, including whether extension or termination options are reasonably certain to be exercised. Estimation is also involved in determining the incremental borrowing rate where the rate implicit in the lease cannot be readily determined.

    For {period_label}, depreciation on right-of-use assets amounted to R{_money(pnl.get("depreciation")):,.2f}, and interest expense on lease liabilities amounted to R{_money(pnl.get("interest")):,.2f}. The closing carrying amount of right-of-use assets was R{_money(rou.get("closing_rou_nbv_as_of")):,.2f}, and the closing lease liability was R{_money(liability.get("closing_liability_as_of")):,.2f}. Undiscounted future lease payments amounted to R{_money(maturity.get("undiscounted_net_total")):,.2f}.{exemption_text}
    """.strip()

    def build_ifrs16_rou_asset_class_table(self, disclosure: dict) -> list[dict]:
        rows = disclosure.get("rou_asset_table") or []

        class_map = {
            "head office": "Buildings",
            "branch": "Buildings",
            "warehouse": "Buildings",
            "vehicle": "Vehicles",
            "fleet": "Vehicles",
            "equipment": "Equipment",
            "it": "IT Infrastructure",
            "infrastructure": "IT Infrastructure",
            "office space": "Buildings",
        }

        grouped = {}

        for r in rows:
            lease_name = (r.get("lease_name") or "").lower()

            asset_class = "Other ROU Assets"
            for key, value in class_map.items():
                if key in lease_name:
                    asset_class = value
                    break

            g = grouped.setdefault(asset_class, {
                "asset_class": asset_class,
                "opening": 0.0,
                "additions": 0.0,
                "remeasurements": 0.0,
                "depreciation": 0.0,
                "disposals": 0.0,
                "closing": 0.0,
            })

            g["opening"] += float(r.get("opening") or 0)
            g["additions"] += float(r.get("additions") or 0)
            g["remeasurements"] += float(r.get("remeasurements") or 0)
            g["depreciation"] += float(r.get("depreciation") or 0)
            g["disposals"] += float(r.get("disposals") or 0)
            g["closing"] += float(r.get("closing") or 0)

        return list(grouped.values())

    def build_ifrs16_lease_portfolio_table(self, disclosure: dict) -> list[dict]:
        leases = disclosure.get("leases") or []

        out = []
        for l in leases:
            name = l.get("lease_name") or ""

            asset_class = "Other"
            n = name.lower()

            if any(x in n for x in ["office", "branch", "warehouse", "building"]):
                asset_class = "Buildings"
            elif any(x in n for x in ["vehicle", "fleet"]):
                asset_class = "Vehicles"
            elif "equipment" in n:
                asset_class = "Equipment"
            elif any(x in n for x in ["it", "infrastructure", "server"]):
                asset_class = "IT Infrastructure"

            out.append({
                "lease_name": name,
                "asset_class": asset_class,
                "start_date": l.get("start_date"),
                "end_date": l.get("end_date"),
                "frequency": l.get("payment_frequency"),
                "payment": float(l.get("payment_amount") or 0),
                "vat_rate": float(l.get("vat_rate") or 0),
                "status": l.get("status") or "active",
            })

        return out

    def build_ifrs16_disclosure_package(
        self,
        company_id: int,
        date_from,
        date_to,
        *,
        cur=None,
    ) -> dict:

        d = self.get_ifrs16_disclosure_strict(
            company_id,
            from_date=date_from,
            to_date=date_to,
            as_of=date_to,
            include_terminated=True,
            cur=cur,
        )

        policy_note = self.build_lease_policy_note_text(
            company_id,
            date_from,
            date_to,
            cur=cur,
        )

        return {
            "policy_note": policy_note,
            "rou_asset_class_table": self.build_ifrs16_rou_asset_class_table(d),
            "lease_portfolio_table": self.build_ifrs16_lease_portfolio_table(d),
            "rou_asset_table_by_lease": d.get("rou_asset_table") or [],
            "liability_reconciliation": d.get("liability_reconciliation") or {},
            "maturity_analysis": d.get("maturity_analysis") or {},
            "pnl": d.get("pnl") or {},
            "liability": d.get("liability") or {},
            "cashflow": d.get("cashflow") or {},
            "checks": d.get("liability_closing_checks") or {},
            "raw": d,
        }    

    def build_revenue_policy_note_text(self, company_id: int, date_from, date_to, *, cur=None) -> str:
        schema = self.company_schema(company_id)

        rows = self.fetch_all(
            f"""
            SELECT DISTINCT
                recognition_timing,
                progress_method,
                recognition_trigger
            FROM {schema}.revenue_obligations
            WHERE company_id = %s;
            """,
            (int(company_id),),
            cur=cur,
        ) or []

        has_over_time = any((r.get("recognition_timing") or "") == "over_time" for r in rows)
        has_point = any((r.get("recognition_timing") or "") == "point_in_time" for r in rows)

        lines = [
            "Revenue is recognised in accordance with IFRS 15 Revenue from Contracts with Customers. Revenue is recognised when control of promised goods or services transfers to the customer, at an amount that reflects the consideration to which the company expects to be entitled in exchange for those goods or services.",
            "",
            "The company applies the five-step model to contracts with customers by identifying the contract, identifying the performance obligations, determining the transaction price, allocating the transaction price to the performance obligations and recognising revenue when, or as, the performance obligations are satisfied.",
            "",
            "Management applies judgement in identifying distinct performance obligations, determining whether revenue is recognised over time or at a point in time, estimating variable consideration where applicable and assessing whether a significant financing component exists.",
        ]

        if has_over_time:
            lines.extend([
                "",
                "For performance obligations satisfied over time, revenue is recognised by measuring progress towards complete satisfaction of the performance obligation. The method used to measure progress is selected based on the nature of the goods or services promised and the manner in which control transfers to the customer.",
            ])

        if has_point:
            lines.extend([
                "",
                "For performance obligations satisfied at a point in time, revenue is recognised when control transfers to the customer. Indicators of transfer of control may include the customer obtaining legal title, physical possession, acceptance of the asset, or the present right to payment.",
            ])

        return "\n".join(lines)

    def build_revenue_disclosure_note_text(self, company_id: int, date_from, date_to, *, cur=None) -> str:
        d = self.build_revenue_disclosure(company_id, date_from, date_to)

        period_label = self._period_label(date_from, date_to)

        summary = d.get("summary") or {}
        timing = d.get("revenue_timing") or []
        categories = d.get("revenue_by_category") or []
        unsatisfied = d.get("unsatisfied_performance_obligations") or []

        lines = [
            f"Revenue recognised during {period_label} amounted to R{_money(summary.get('total_revenue')):,.2f}.",
            "",
            f"Contract assets amounted to R{_money(summary.get('contract_assets')):,.2f}, while contract liabilities amounted to R{_money(summary.get('contract_liabilities')):,.2f}.",
            f"Gross receivables from contracts with customers amounted to R{_money(summary.get('gross_receivables_from_contracts')):,.2f}.",
        ]

        if timing:
            lines.append("")
            lines.append("Revenue is recognised at the following timing:")
            for r in timing:
                lines.append(f"- {r.get('timing')}: R{_money(r.get('amount')):,.2f}")

        if categories:
            lines.append("")
            lines.append("Revenue by category is as follows:")
            for r in categories:
                lines.append(f"- {r.get('category')}: R{_money(r.get('amount')):,.2f}")

        remaining_total = sum(_money(r.get("remaining_amount")) for r in unsatisfied)
        if remaining_total:
            lines.append("")
            lines.append(
                f"The aggregate amount of transaction price allocated to unsatisfied or partially satisfied performance obligations amounted to R{remaining_total:,.2f}."
            )

        return "\n".join(lines)

    def get_or_build_financial_statement_note(
        self,
        company_id: int,
        note_key: str,
        period_from,
        period_to,
        *,
        cur=None,
    ) -> dict:
        builders = {
            "ias16_ppe_policy": (
                "Property, plant and equipment",
                lambda: self.build_ppe_policy_note_text(company_id, period_from, period_to, cur=cur),
            ),
            "ifrs16_lease_policy": (
                "Leases",
                lambda: self.build_lease_policy_note_text(company_id, period_from, period_to, cur=cur),
            ),
            "ifrs15_revenue_policy": (
                "Revenue recognition",
                lambda: self.build_revenue_policy_note_text(company_id, period_from, period_to, cur=cur),
            ),
            "ifrs15_revenue_disclosure": (
                "Revenue from contracts with customers",
                lambda: self.build_revenue_disclosure_note_text(company_id, period_from, period_to, cur=cur),
            ),

            "ias40_ip_policy": ("Investment property", lambda: self.build_investment_property_policy_note_text(company_id, period_from, period_to, cur=cur)),
            "ias40_ip_disclosure": ("Investment property disclosures", lambda: self.build_investment_property_policy_note_text(company_id, period_from, period_to, cur=cur)),
            "ias38_ia_policy": ("Intangible assets", lambda: self.build_intangible_assets_policy_note_text(company_id, period_from, period_to, cur=cur)),
            "ias38_ia_disclosure": ("Intangible assets disclosures", lambda: self.build_intangible_assets_policy_note_text(company_id, period_from, period_to, cur=cur)),
        }

        if note_key not in builders:
            raise ValueError(f"Unsupported financial statement note: {note_key}")

        note_title, builder = builders[note_key]
        system_draft = builder()
        generated_hash = _note_hash(system_draft)

        existing = self.get_financial_statement_note(
            company_id,
            note_key,
            period_from,
            period_to,
            cur=cur,
        )

        if existing:
            existing = dict(existing)
            existing["system_draft"] = system_draft
            existing["current_generated_hash"] = generated_hash
            existing["is_outdated"] = bool(
                existing.get("last_generated_hash")
                and existing.get("last_generated_hash") != generated_hash
            )
            return existing

        return self.save_financial_statement_note(
            company_id,
            note_key,
            note_title,
            period_from,
            period_to,
            system_draft,
            system_draft=system_draft,
            source="system",
            is_custom=False,
            payload_json={"auto_created": True},
            cur=cur,
        )

    def create_project(self, company_id: int, data: Dict[str, Any]) -> int:
        schema = self.company_schema(company_id)

        def pick(*keys, default=None):
            for k in keys:
                v = data.get(k)
                if v not in (None, ""):
                    return v
            return default

        sql = f"""
        INSERT INTO {schema}.projects (
            company_id,
            project_code,
            project_name,
            customer_id,
            project_type,
            status,
            start_date,
            expected_end_date,
            contract_value,
            budget_value,
            billing_method,
            wip_account_code,
            revenue_account_code,
            cost_account_code,
            location,
            description,
            notes,
            meta,
            created_by
        )
        VALUES (
            %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
            %s,%s,%s,%s,%s,%s,%s,%s,%s
        )
        RETURNING id;
        """

        params = (
            int(company_id),
            (pick("project_code", "projectCode", "code") or "").strip(),
            (pick("project_name", "projectName", "name") or "").strip(),
            pick("customer_id", "customerId"),
            pick("project_type", "projectType", default="service"),
            pick("status", default="draft"),
            pick("start_date", "startDate"),
            pick("expected_end_date", "expectedEndDate"),
            float(pick("contract_value", "contractValue", default=0) or 0),
            float(pick("budget_value", "budgetValue", default=0) or 0),
            pick("billing_method", "billingMethod", default="milestone"),
            pick("wip_account_code", "wipAccountCode"),
            pick("revenue_account_code", "revenueAccountCode"),
            pick("cost_account_code", "costAccountCode"),
            pick("location"),
            pick("description"),
            pick("notes"),
            psycopg2.extras.Json(data.get("meta") or {}),
            pick("created_by", "createdBy"),
        )

        row = self.fetch_one(sql, params) or {}
        return int(row.get("id") or 0)

    def list_projects(
        self,
        company_id: int,
        *,
        q: str = "",
        status: str = "",
        customer_id: int | None = None,
        limit: int = 50,
        offset: int = 0,
    ) -> list[dict]:
        schema = self.company_schema(company_id)

        where = ["p.company_id = %s"]
        params: list[Any] = [company_id]

        if q:
            like = f"%{q}%"
            where.append("""
                (
                    p.project_code ILIKE %s
                    OR p.project_name ILIKE %s
                    OR p.location ILIKE %s
                )
            """)
            params.extend([like, like, like])

        if status:
            where.append("lower(p.status) = lower(%s)")
            params.append(status)

        if customer_id:
            where.append("p.customer_id = %s")
            params.append(customer_id)

        params.extend([limit, offset])

        return self.fetch_all(
            f"""
            SELECT
                p.*,
                c.name AS customer_name,

                COALESCE((
                    SELECT COUNT(*)
                    FROM {schema}.project_tasks t
                    WHERE t.company_id = p.company_id
                    AND t.project_id = p.id
                ), 0) AS task_count,

                COALESCE((
                    SELECT SUM(b.budget_amount)
                    FROM {schema}.project_budget_lines b
                    WHERE b.company_id = p.company_id
                    AND b.project_id = p.id
                ), 0) AS budget_lines_total

            FROM {schema}.projects p
            LEFT JOIN {schema}.customers c
                ON c.company_id = p.company_id
            AND c.id = p.customer_id
            WHERE {" AND ".join(where)}
            ORDER BY p.created_at DESC, p.id DESC
            LIMIT %s OFFSET %s
            """,
            tuple(params),
        )

    def get_project(self, company_id: int, project_id: int) -> dict | None:
        schema = self.company_schema(company_id)

        project = self.fetch_one(
            f"""
            SELECT
                p.*,
                c.name AS customer_name,
                c.email AS customer_email,
                c.phone AS customer_phone
            FROM {schema}.projects p
            LEFT JOIN {schema}.customers c
                ON c.company_id = p.company_id
            AND c.id = p.customer_id
            WHERE p.company_id = %s
            AND p.id = %s
            """,
            (company_id, project_id),
        )

        if not project:
            return None

        tasks = self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.project_tasks
            WHERE company_id = %s
              AND project_id = %s
              AND COALESCE(is_archived, FALSE) = FALSE
            ORDER BY id ASC
            """,
            (company_id, project_id),
        )

        budget_lines = self.fetch_all(
            f"""
            SELECT
                b.*,
                t.task_name,
                COALESCE(NULLIF(b.cost_code, ''), cc.code) AS cost_code,
                b.cost_code AS budget_cost_code,
                cc.code AS linked_cost_code,
                cc.name AS cost_code_name,
                cc.cost_type
            FROM {schema}.project_budget_lines b
            LEFT JOIN {schema}.project_tasks t
                ON t.company_id = b.company_id
               AND t.id = b.task_id
            LEFT JOIN {schema}.project_cost_codes cc
                ON cc.company_id = b.company_id
               AND cc.id = b.cost_code_id
            WHERE b.company_id = %s
              AND b.project_id = %s
              AND COALESCE(b.is_archived, FALSE) = FALSE
            ORDER BY b.line_no ASC, b.id ASC
            """,
            (company_id, project_id),
        )

        project["tasks"] = tasks
        project["budget_lines"] = budget_lines

        project["totals"] = {
            "task_count": len(tasks),
            "budget_total": sum(float(x.get("budget_amount") or 0) for x in budget_lines),
        }

        return project

    def update_project(self, company_id: int, project_id: int, data: Dict[str, Any]) -> bool:
        schema = self.company_schema(company_id)

        allowed = {
            "project_code": ("project_code", "projectCode", "code"),
            "project_name": ("project_name", "projectName", "name"),
            "customer_id": ("customer_id", "customerId"),
            "project_type": ("project_type", "projectType"),
            "status": ("status",),
            "start_date": ("start_date", "startDate"),
            "expected_end_date": ("expected_end_date", "expectedEndDate"),
            "actual_end_date": ("actual_end_date", "actualEndDate"),
            "contract_value": ("contract_value", "contractValue"),
            "budget_value": ("budget_value", "budgetValue"),
            "billing_method": ("billing_method", "billingMethod"),
            "wip_account_code": ("wip_account_code", "wipAccountCode"),
            "revenue_account_code": ("revenue_account_code", "revenueAccountCode"),
            "cost_account_code": ("cost_account_code", "costAccountCode"),
            "location": ("location",),
            "description": ("description",),
            "notes": ("notes",),
            "meta": ("meta",),
        }

        sets = []
        params = []

        for col, keys in allowed.items():
            found = False
            value = None

            for k in keys:
                if k in data:
                    value = data.get(k)
                    found = True
                    break

            if not found:
                continue

            if col in {"project_code", "project_name"}:
                value = (value or "").strip()
                if not value:
                    raise ValueError(f"{col} is required")

            if col in {"contract_value", "budget_value"}:
                value = float(value or 0)

            if col == "meta":
                value = psycopg2.extras.Json(value or {})

            sets.append(f"{col} = %s")
            params.append(value)

        if not sets:
            return False

        sets.append("updated_at = NOW()")
        params.extend([company_id, project_id])

        row = self.fetch_one(
            f"""
            UPDATE {schema}.projects
            SET {", ".join(sets)}
            WHERE company_id = %s
            AND id = %s
            RETURNING id
            """,
            tuple(params),
        )

        return bool(row)

