    def forecast_budget_variance(
        self,
        company_id: int,
        budget_id: int,
        version_id: Optional[int] = None,
        period_start: Optional[str] = None,
        period_end: Optional[str] = None,
    ) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)

        schema = self.company_schema(company_id)

        budget = self.fetch_one(f"""
            SELECT *
            FROM {schema}.forecast_budgets
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(budget_id),
        ))

        if not budget:
            raise ValueError("Budget not found.")

        start_date = (
            period_start
            or str(budget["period_start"])[:10]
        )

        end_date = (
            period_end
            or str(budget["period_end"])[:10]
        )

        if version_id:
            planned_source_sql = f"""
                SELECT
                    fl.account_code,
                    DATE_TRUNC(
                        'month',
                        fl.period_month
                    )::date AS period_month,
                    SUM(fl.amount)::numeric(18,2)
                        AS planned_amount

                FROM {schema}.forecast_lines fl

                INNER JOIN {schema}.forecast_versions fv
                    ON fv.id = fl.version_id
                AND fv.company_id = fl.company_id

                WHERE fl.company_id = %s
                AND fl.version_id = %s
                AND fl.period_month >= %s::date
                AND fl.period_month <= %s::date

                GROUP BY
                    fl.account_code,
                    DATE_TRUNC(
                        'month',
                        fl.period_month
                    )::date
            """

            planned_params = (
                int(company_id),
                int(version_id),
                start_date,
                end_date,
            )

            comparison_type = "forecast_vs_actual"

        else:
            planned_source_sql = f"""
                SELECT
                    fbl.account_code,
                    DATE_TRUNC(
                        'month',
                        fbl.period_month
                    )::date AS period_month,
                    SUM(fbl.amount)::numeric(18,2)
                        AS planned_amount

                FROM {schema}.forecast_budget_lines fbl

                WHERE fbl.company_id = %s
                AND fbl.budget_id = %s
                AND fbl.period_month >= %s::date
                AND fbl.period_month <= %s::date

                GROUP BY
                    fbl.account_code,
                    DATE_TRUNC(
                        'month',
                        fbl.period_month
                    )::date
            """

            planned_params = (
                int(company_id),
                int(budget_id),
                start_date,
                end_date,
            )

            comparison_type = "budget_vs_actual"

        rows = self.fetch_all(f"""
            WITH planned AS (
                {planned_source_sql}
            ),

            actual AS (
                SELECT
                    jl.account_code,

                    DATE_TRUNC(
                        'month',
                        j.date
                    )::date AS period_month,

                    SUM(
                        COALESCE(jl.credit, 0)
                        -
                        COALESCE(jl.debit, 0)
                    )::numeric(18,2) AS raw_actual_amount

                FROM {schema}.journal_lines jl

                INNER JOIN {schema}.journal j
                    ON j.id = jl.journal_id
                AND j.company_id = jl.company_id

                WHERE jl.company_id = %s
                AND j.date >= %s::date
                AND j.date <= %s::date

                GROUP BY
                    jl.account_code,
                    DATE_TRUNC(
                        'month',
                        j.date
                    )::date
            ),

            combined AS (
                SELECT
                    COALESCE(
                        p.account_code,
                        a.account_code
                    ) AS account_code,

                    COALESCE(
                        p.period_month,
                        a.period_month
                    ) AS period_month,

                    COALESCE(
                        p.planned_amount,
                        0
                    )::numeric(18,2)
                        AS planned_amount,

                    COALESCE(
                        a.raw_actual_amount,
                        0
                    )::numeric(18,2)
                        AS raw_actual_amount

                FROM planned p

                FULL OUTER JOIN actual a
                    ON a.account_code = p.account_code
                AND a.period_month = p.period_month
            )

            SELECT
                c.account_code,
                COALESCE(coa.name, c.account_code) AS account_name,
                coa.section,
                coa.category,
                coa.role,
                c.period_month,
                c.planned_amount,

                CASE
                    WHEN UPPER(c.account_code) LIKE 'PL_REV%%'
                    OR UPPER(c.account_code) LIKE 'PL_OI%%'
                    THEN c.raw_actual_amount
                    ELSE ABS(c.raw_actual_amount)
                END::numeric(18,2) AS actual_amount

            FROM combined c

            LEFT JOIN {schema}.coa coa
            ON coa.code = c.account_code

            ORDER BY
                c.period_month,
                c.account_code;
        """, (
            *planned_params,
            int(company_id),
            start_date,
            end_date,
        ))

        output_rows = []

        for row in rows:
            planned = float(
                row.get("planned_amount") or 0
            )

            actual = float(
                row.get("actual_amount") or 0
            )

            variance = actual - planned

            variance_percent = (
                variance / abs(planned) * 100
                if planned != 0
                else None
            )

            classification = self._forecast_variance_classification(
                account_code=row.get("account_code"),
                section=row.get("section"),
                category=row.get("category"),
                planned_amount=planned,
                actual_amount=actual,
            )

            output_rows.append({
                **row,
                "planned_amount": planned,
                "actual_amount": actual,
                "variance_amount": variance,
                "variance_percent": variance_percent,
                "variance_classification": classification,
            })

        return {
            "budget": budget,
            "version_id": version_id,
            "comparison_type": comparison_type,
            "period_start": start_date,
            "period_end": end_date,
            "rows": output_rows,
        }
    
    def _forecast_variance_classification(
        self,
        account_code: str,
        section: Optional[str],
        category: Optional[str],
        planned_amount: float,
        actual_amount: float,
    ) -> str:
        code = str(account_code or "").upper()

        section_key = str(
            section or ""
        ).strip().lower()

        category_key = str(
            category or ""
        ).strip().lower()

        variance = actual_amount - planned_amount

        is_income = (
            code.startswith("PL_REV_")
            or code.startswith("PL_OI_")
            or section_key == "income"
            or category_key in {
                "revenue",
                "service revenue",
                "sales revenue",
                "other income",
            }
        )

        is_cost_or_expense = (
            code.startswith("PL_COS_")
            or code.startswith("PL_COGS_")
            or code.startswith("PL_OPEX_")
            or code.startswith("PL_FIN_")
            or code.startswith("PL_TAX_")
            or section_key in {
                "expense",
                "adjustment",
            }
        )

        if abs(variance) < 0.005:
            return "on_target"

        if is_income:
            return (
                "favourable"
                if variance > 0
                else "unfavourable"
            )

        if is_cost_or_expense:
            return (
                "favourable"
                if variance < 0
                else "unfavourable"
            )

        return (
            "favourable"
            if variance > 0
            else "unfavourable"
        )

    def forecast_update_budget(self, company_id: int, budget_id: int, payload: Dict[str, Any], user_id: Optional[int] = None) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        before = self.forecast_get_budget_required(company_id, budget_id)
        self.forecast_assert_editable(before, "Budget")

        row = self.fetch_one(f"""
            UPDATE {schema}.forecast_budgets
            SET name = COALESCE(%s, name),
                description = COALESCE(%s, description),
                financial_year = COALESCE(%s, financial_year),
                period_start = COALESCE(%s, period_start),
                period_end = COALESCE(%s, period_end),
                currency = COALESCE(%s, currency),
                basis = COALESCE(%s, basis),
                meta_json = COALESCE(%s::jsonb, meta_json),
                updated_at = now()
            WHERE company_id=%s AND id=%s
            RETURNING *;
        """, (
            payload.get("name"),
            payload.get("description"),
            payload.get("financial_year"),
            payload.get("period_start"),
            payload.get("period_end"),
            payload.get("currency"),
            payload.get("basis"),
            json.dumps(payload.get("meta_json")) if payload.get("meta_json") is not None else None,
            int(company_id),
            int(budget_id),
        ))

        self._forecast_audit(
            company_id,
            entity_type="forecast_budget",
            entity_id=budget_id,
            action="update_budget",
            actor_user_id=user_id,
            before_json=before,
            after_json=row,
            message=f"Updated budget {budget_id}",
        )

        return row

    def forecast_get_budget(self, company_id: int, budget_id: int) -> Optional[Dict[str, Any]]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        budget = self.fetch_one(f"""
            SELECT *
            FROM {schema}.forecast_budgets
            WHERE company_id = %s AND id = %s
            LIMIT 1;
        """, (int(company_id), int(budget_id)))

        if not budget:
            return None

        budget["lines"] = self.fetch_all(f"""
            SELECT
                l.*,
                c.name AS account_name,
                c.section,
                c.category
            FROM {schema}.forecast_budget_lines l
            LEFT JOIN {schema}.coa c
                ON c.company_id = l.company_id
            AND c.code = l.account_code
            WHERE l.company_id = %s
            AND l.budget_id = %s
            ORDER BY l.period_month, l.account_code;
        """, (int(company_id), int(budget_id)))

        return budget

    def forecast_submit_budget(self, company_id: int, budget_id: int, user_id: Optional[int] = None) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        line_count = self.fetch_one(f"""
            SELECT COUNT(*) AS cnt
            FROM {schema}.forecast_budget_lines
            WHERE company_id=%s AND budget_id=%s;
        """, (int(company_id), int(budget_id)))

        if int(line_count["cnt"] or 0) <= 0:
            raise ValueError("Cannot submit a budget with no lines.")

        row = self.fetch_one(f"""
            UPDATE {schema}.forecast_budgets
            SET status='submitted',
                submitted_by=%s,
                submitted_at=now(),
                updated_at=now()
            WHERE company_id=%s
            AND id=%s
            AND status='draft'
            RETURNING *;
        """, (user_id, int(company_id), int(budget_id)))

        if not row:
            raise ValueError("Budget not found or cannot be submitted.")

        self.execute_sql(f"""
            INSERT INTO {schema}.forecast_approvals (
                company_id, budget_id, action, action_by, comment
            )
            VALUES (%s,%s,'submitted',%s,%s);
        """, (int(company_id), int(budget_id), user_id, "Budget submitted."))

        return row


    def forecast_approve_budget(self, company_id: int, budget_id: int, user_id: Optional[int] = None, comment: Optional[str] = None) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        row = self.fetch_one(f"""
            UPDATE {schema}.forecast_budgets
            SET status='approved',
                approved_by=%s,
                approved_at=now(),
                updated_at=now()
            WHERE company_id=%s
            AND id=%s
            AND status IN ('draft','submitted')
            RETURNING *;
        """, (user_id, int(company_id), int(budget_id)))

        if not row:
            raise ValueError("Budget not found or cannot be approved.")

        self.execute_sql(f"""
            INSERT INTO {schema}.forecast_approvals (
                company_id, budget_id, action, action_by, comment
            )
            VALUES (%s,%s,'approved',%s,%s);
        """, (int(company_id), int(budget_id), user_id, comment))

        return row


    def forecast_reopen_budget(self, company_id: int, budget_id: int, user_id: Optional[int] = None, comment: Optional[str] = None) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        row = self.fetch_one(f"""
            UPDATE {schema}.forecast_budgets
            SET status='draft',
                locked_by=NULL,
                locked_at=NULL,
                updated_at=now()
            WHERE company_id=%s
            AND id=%s
            AND status IN ('submitted','approved')
            RETURNING *;
        """, (int(company_id), int(budget_id)))

        if not row:
            raise ValueError("Budget not found or cannot be reopened.")

        self.execute_sql(f"""
            INSERT INTO {schema}.forecast_approvals (
                company_id, budget_id, action, action_by, comment
            )
            VALUES (%s,%s,'reopened',%s,%s);
        """, (int(company_id), int(budget_id), user_id, comment))

        return row


    def forecast_lock_budget(self, company_id: int, budget_id: int, user_id: Optional[int] = None) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        row = self.fetch_one(f"""
            UPDATE {schema}.forecast_budgets
            SET status='locked',
                locked_by=%s,
                locked_at=now(),
                updated_at=now()
            WHERE company_id=%s
            AND id=%s
            AND status='approved'
            RETURNING *;
        """, (user_id, int(company_id), int(budget_id)))

        if not row:
            raise ValueError("Budget must be approved before locking.")

        self.execute_sql(f"""
            INSERT INTO {schema}.forecast_approvals (
                company_id, budget_id, action, action_by, comment
            )
            VALUES (%s,%s,'locked',%s,%s);
        """, (int(company_id), int(budget_id), user_id, "Budget locked."))

        return row

    def forecast_budget_vs_actual(self, company_id: int, budget_id: int) -> List[Dict[str, Any]]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        budget = self.forecast_get_budget_required(company_id, budget_id)

        return self.fetch_all(f"""
            WITH b AS (
                SELECT
                    company_id,
                    account_code,
                    period_month,
                    SUM(amount) AS budget_amount
                FROM {schema}.forecast_budget_lines
                WHERE company_id=%s
                AND budget_id=%s
                GROUP BY company_id, account_code, period_month
            ),
            a AS (
                SELECT
                    company_id,
                    account AS account_code,
                    date_trunc('month', date)::date AS period_month,
                    SUM(debit - credit) AS actual_amount
                FROM {schema}.ledger
                WHERE company_id=%s
                AND date BETWEEN %s AND %s
                GROUP BY company_id, account, date_trunc('month', date)::date
            )
            SELECT
                b.account_code,
                c.name AS account_name,
                c.section,
                c.category,
                b.period_month,
                COALESCE(b.budget_amount, 0) AS budget_amount,
                COALESCE(a.actual_amount, 0) AS actual_amount,
                COALESCE(a.actual_amount, 0) - COALESCE(b.budget_amount, 0) AS variance_amount,
                CASE
                    WHEN COALESCE(b.budget_amount, 0)=0 THEN NULL
                    ELSE ROUND(
                        ((COALESCE(a.actual_amount, 0) - COALESCE(b.budget_amount, 0))
                        / NULLIF(ABS(b.budget_amount), 0)) * 100,
                        2
                    )
                END AS variance_pct
            FROM b
            LEFT JOIN a
                ON a.company_id=b.company_id
            AND a.account_code=b.account_code
            AND a.period_month=b.period_month
            LEFT JOIN {schema}.coa c
                ON c.company_id=b.company_id
            AND c.code=b.account_code
            ORDER BY b.period_month, b.account_code;
        """, (
            int(company_id),
            int(budget_id),
            int(company_id),
            budget["period_start"],
            budget["period_end"],
        ))


    def forecast_create_version(
        self,
        company_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        name = (payload.get("name") or "").strip()
        budget_id = payload.get("budget_id")
        period_start = payload.get("period_start")
        period_end = payload.get("period_end")
        actuals_to_date = payload.get("actuals_to_date")
        version_type = payload.get("version_type") or "forecast"

        if not name:
            raise ValueError("Forecast name is required.")
        if not budget_id:
            raise ValueError("An approved budget is required.")
        if not period_start or not period_end:
            raise ValueError("Forecast period start and end are required.")
        if str(period_end) < str(period_start):
            raise ValueError("Forecast period end cannot be before its start.")
        if actuals_to_date and not (str(period_start) <= str(actuals_to_date) <= str(period_end)):
            raise ValueError("Actuals-to-date must fall inside the forecast period.")
        if version_type not in {"forecast", "scenario", "rolling", "year_end"}:
            raise ValueError("Invalid forecast version type.")

        budget = self.forecast_get_budget_required(company_id, int(budget_id))
        if str(budget.get("status") or "").lower() not in {"approved", "locked"}:
            raise ValueError("The budget must be approved before creating a forecast.")

        return self.fetch_one(f"""
            INSERT INTO {schema}.forecast_versions (
                company_id, budget_id, name, version_type, scenario_name,
                actuals_to_date, period_start, period_end, currency,
                status, created_by, meta_json
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,'draft',%s,%s::jsonb)
            RETURNING *;
        """, (
            int(company_id),
            int(budget_id),
            name,
            version_type,
            payload.get("scenario_name"),
            actuals_to_date,
            period_start,
            period_end,
            payload.get("currency") or budget.get("currency"),
            user_id,
            json.dumps(payload.get("meta_json") or {}),
        ))

    def forecast_seed_version_from_budget(
        self,
        company_id: int,
        version_id: int,
    ) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)
        version = self.forecast_get_version_required(company_id, version_id)

        budget_id = version.get("budget_id")
        if not budget_id:
            raise ValueError("Forecast version is not linked to a budget.")

        actuals_to_date = version.get("actuals_to_date")

        result = self.fetch_one(f"""
            WITH inserted AS (
                INSERT INTO {schema}.forecast_lines (
                    company_id,
                    version_id,
                    account_code,
                    period_month,
                    amount,
                    source_type,
                    source_ref,
                    meta_json
                )
                SELECT
                    b.company_id,
                    %s,
                    b.account_code,
                    b.period_month,
                    b.amount,
                    'budget_seed',
                    %s,
                    jsonb_build_object(
                        'budget_id', %s,
                        'seeded_from_budget', TRUE
                    )
                FROM {schema}.forecast_budget_lines b
                WHERE b.company_id = %s
                AND b.budget_id = %s
                AND (
                        %s::date IS NULL
                        OR b.period_month > DATE_TRUNC('month', %s::date)::date
                )
                ON CONFLICT (version_id, account_code, period_month)
                DO NOTHING
                RETURNING id
            )
            SELECT COUNT(*)::int AS count
            FROM inserted;
        """, (
            int(version_id),
            f"budget:{int(budget_id)}",
            int(budget_id),
            int(company_id),
            int(budget_id),
            actuals_to_date,
            actuals_to_date,
        ))

        return {"count": int((result or {}).get("count") or 0)}
        
    # ============================================================
    # Forecast / Budget helpers
    # ============================================================

    def _forecast_audit(
        self,
        company_id: int,
        *,
        entity_type: str,
        entity_id: Optional[int],
        action: str,
        actor_user_id: Optional[int] = None,
        before_json: Optional[dict] = None,
        after_json: Optional[dict] = None,
        message: Optional[str] = None,
    ):
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        self.execute_sql(f"""
            INSERT INTO {schema}.forecast_audit_events (
                company_id, entity_type, entity_id, action,
                actor_user_id, before_json, after_json, message
            )
            VALUES (%s,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s);
        """, (
            int(company_id),
            entity_type,
            entity_id,
            action,
            actor_user_id,
            json.dumps(before_json or {}),
            json.dumps(after_json or {}),
            message,
        ))


    def forecast_validate_account(self, company_id: int, account_code: str) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        row = self.fetch_one(f"""
            SELECT code, name, section, category, posting
            FROM {schema}.coa
            WHERE company_id=%s
            AND code=%s
            AND posting=TRUE
            LIMIT 1;
        """, (int(company_id), account_code))

        if not row:
            raise ValueError(f"Invalid posting account code: {account_code}")

        return row

    def forecast_projected_full_year(
        self,
        company_id: int,
        version_id: int,
    ) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)
        version = self.forecast_get_version_required(company_id, version_id)

        start_date = str(version["period_start"])[:10]
        end_date = str(version["period_end"])[:10]
        actuals_to_date = str(version.get("actuals_to_date") or start_date)[:10]

        rows = self.fetch_all(f"""
            WITH actual AS (
                SELECT
                    jl.account_code,
                    DATE_TRUNC('month', j.date)::date AS period_month,
                    SUM(
                        CASE
                            WHEN LOWER(COALESCE(c.section, '')) IN ('income', 'revenue')
                                THEN COALESCE(jl.credit, 0) - COALESCE(jl.debit, 0)
                            ELSE COALESCE(jl.debit, 0) - COALESCE(jl.credit, 0)
                        END
                    )::numeric(18,2) AS amount
                FROM {schema}.journals j
                JOIN {schema}.journal_lines jl
                ON jl.journal_id = j.id
                AND jl.company_id = j.company_id
                LEFT JOIN {schema}.coa c
                ON c.company_id = jl.company_id
                AND c.code = jl.account_code
                WHERE j.company_id = %s
                AND j.date >= %s::date
                AND j.date <= %s::date
                AND COALESCE(j.status, 'posted') = 'posted'
                GROUP BY jl.account_code, DATE_TRUNC('month', j.date)::date
            ),
            forecast AS (
                SELECT
                    account_code,
                    DATE_TRUNC('month', period_month)::date AS period_month,
                    SUM(amount)::numeric(18,2) AS amount
                FROM {schema}.forecast_lines
                WHERE company_id = %s
                AND version_id = %s
                AND period_month > DATE_TRUNC('month', %s::date)::date
                AND period_month <= %s::date
                GROUP BY account_code, DATE_TRUNC('month', period_month)::date
            ),
            combined AS (
                SELECT account_code, period_month, amount, 'actual' AS source
                FROM actual

                UNION ALL

                SELECT account_code, period_month, amount, 'forecast' AS source
                FROM forecast
            )
            SELECT
                x.account_code,
                c.name AS account_name,
                c.section,
                c.category,
                SUM(x.amount) FILTER (WHERE x.source = 'actual')::numeric(18,2)
                    AS actual_ytd,
                SUM(x.amount) FILTER (WHERE x.source = 'forecast')::numeric(18,2)
                    AS forecast_remaining,
                SUM(x.amount)::numeric(18,2) AS projected_full_year
            FROM combined x
            LEFT JOIN {schema}.coa c
            ON c.company_id = %s
            AND c.code = x.account_code
            GROUP BY x.account_code, c.name, c.section, c.category
            ORDER BY c.section, c.category, x.account_code;
        """, (
            int(company_id),
            start_date,
            actuals_to_date,
            int(company_id),
            int(version_id),
            actuals_to_date,
            end_date,
            int(company_id),
        ))

        return {
            "version": version,
            "period_start": start_date,
            "period_end": end_date,
            "actuals_to_date": actuals_to_date,
            "rows": rows,
        }
            
    def forecast_assert_editable(self, row: Dict[str, Any], label: str = "Record"):
        status = (row.get("status") or "").lower()
        if status in ("approved", "locked"):
            raise ValueError(f"Cannot edit {label.lower()} in status '{status}'.")


    def forecast_validate_capex_parent(
        self,
        company_id: int,
        *,
        version_id: Optional[int] = None,
        budget_id: Optional[int] = None,
    ):
        if not version_id and not budget_id:
            raise ValueError(
                "version_id or budget_id is required."
            )

        if version_id:
            self.forecast_get_version_required(
                company_id,
                int(version_id),
            )

        if budget_id:
            self.forecast_get_budget_required(
                company_id,
                int(budget_id),
            )

    def forecast_list_capex_items(
        self,
        company_id: int,
        *,
        version_id: Optional[int] = None,
        budget_id: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        params = [int(company_id)]
        where = [
            "c.company_id = %s"
        ]

        if version_id:
            where.append(
                "c.version_id = %s"
            )
            params.append(int(version_id))

        if budget_id:
            where.append(
                "c.budget_id = %s"
            )
            params.append(int(budget_id))

        return self.fetch_all(f"""
            SELECT
                c.*,

                CASE
                    WHEN c.funding_source = 'loan'
                        THEN c.total_cost

                    WHEN c.funding_source = 'mixed'
                        THEN ROUND(
                            c.total_cost *
                            (c.loan_percentage / 100.0),
                            2
                        )

                    ELSE 0
                END AS estimated_loan_funding,

                CASE
                    WHEN c.funding_source = 'loan'
                        THEN 0

                    WHEN c.funding_source = 'mixed'
                        THEN ROUND(
                            c.total_cost *
                            (
                                1 -
                                c.loan_percentage / 100.0
                            ),
                            2
                        )

                    ELSE c.total_cost
                END AS estimated_cash_outflow

            FROM {schema}.forecast_capex_items c

            WHERE {' AND '.join(where)}

            ORDER BY
                c.purchase_month,
                c.asset_name,
                c.id;
        """, tuple(params))

    def forecast_create_capex_item(
        self,
        company_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        version_id = payload.get(
            "version_id"
        )
        budget_id = payload.get(
            "budget_id"
        )

        self.forecast_validate_capex_parent(
            company_id,
            version_id=version_id,
            budget_id=budget_id,
        )

        asset_name = str(
            payload.get("asset_name") or ""
        ).strip()

        if not asset_name:
            raise ValueError(
                "asset_name is required."
            )

        purchase_month = payload.get(
            "purchase_month"
        )

        if not purchase_month:
            raise ValueError(
                "purchase_month is required."
            )

        quantity = Decimal(
            str(payload.get("quantity") or 1)
        )

        unit_cost = Decimal(
            str(payload.get("unit_cost") or 0)
        )

        total_cost = payload.get(
            "total_cost"
        )

        if total_cost is None:
            total_cost = (
                quantity * unit_cost
            )
        else:
            total_cost = Decimal(
                str(total_cost)
            )

        useful_life_months = payload.get(
            "useful_life_months"
        )

        if useful_life_months is not None:
            useful_life_months = int(
                useful_life_months
            )

        residual_value = Decimal(
            str(
                payload.get(
                    "residual_value"
                ) or 0
            )
        )

        funding_source = str(
            payload.get(
                "funding_source"
            ) or "cash"
        ).strip().lower()

        loan_percentage = Decimal(
            str(
                payload.get(
                    "loan_percentage"
                ) or 0
            )
        )

        row = self.fetch_one(f"""
            INSERT INTO
                {schema}.forecast_capex_items
            (
                company_id,
                version_id,
                budget_id,

                asset_name,
                asset_class,
                account_code,

                purchase_month,
                quantity,
                unit_cost,
                total_cost,

                useful_life_months,
                residual_value,
                depreciation_method,

                funding_source,
                loan_percentage,

                notes,
                meta_json
            )
            VALUES (
                %s,%s,%s,
                %s,%s,%s,
                %s,%s,%s,%s,
                %s,%s,%s,
                %s,%s,
                %s,%s::jsonb
            )
            RETURNING *;
        """, (
            int(company_id),
            version_id,
            budget_id,

            asset_name,
            payload.get("asset_class"),
            payload.get("account_code"),

            purchase_month,
            quantity,
            unit_cost,
            total_cost,

            useful_life_months,
            residual_value,
            payload.get(
                "depreciation_method"
            ) or "straight_line",

            funding_source,
            loan_percentage,

            payload.get("notes"),
            json.dumps(
                payload.get("meta_json") or {}
            ),
        ))

        self._forecast_audit(
            company_id,
            entity_type="forecast_capex_item",
            entity_id=row["id"],
            action="create_capex_item",
            actor_user_id=user_id,
            after_json=row,
            message=(
                f"Created forecast capex item "
                f"{row['id']}"
            ),
        )

        return row

    def forecast_update_capex_item(
        self,
        company_id: int,
        capex_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        before = self.fetch_one(f"""
            SELECT *
            FROM {schema}.forecast_capex_items
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(capex_id),
        ))

        if not before:
            raise ValueError(
                "Capital expenditure item not found."
            )

        quantity = Decimal(
            str(
                payload.get(
                    "quantity",
                    before["quantity"],
                )
            )
        )

        unit_cost = Decimal(
            str(
                payload.get(
                    "unit_cost",
                    before["unit_cost"],
                )
            )
        )

        total_cost = payload.get(
            "total_cost"
        )

        if total_cost is None:
            total_cost = quantity * unit_cost

        row = self.fetch_one(f"""
            UPDATE
                {schema}.forecast_capex_items

            SET
                asset_name = COALESCE(
                    %s,
                    asset_name
                ),

                asset_class = COALESCE(
                    %s,
                    asset_class
                ),

                account_code = COALESCE(
                    %s,
                    account_code
                ),

                purchase_month = COALESCE(
                    %s,
                    purchase_month
                ),

                quantity = %s,
                unit_cost = %s,
                total_cost = %s,

                useful_life_months =
                    COALESCE(
                        %s,
                        useful_life_months
                    ),

                residual_value =
                    COALESCE(
                        %s,
                        residual_value
                    ),

                depreciation_method =
                    COALESCE(
                        %s,
                        depreciation_method
                    ),

                funding_source =
                    COALESCE(
                        %s,
                        funding_source
                    ),

                loan_percentage =
                    COALESCE(
                        %s,
                        loan_percentage
                    ),

                notes = COALESCE(
                    %s,
                    notes
                ),

                meta_json = COALESCE(
                    %s::jsonb,
                    meta_json
                ),

                updated_at = now()

            WHERE company_id = %s
            AND id = %s

            RETURNING *;
        """, (
            payload.get("asset_name"),
            payload.get("asset_class"),
            payload.get("account_code"),
            payload.get("purchase_month"),

            quantity,
            unit_cost,
            total_cost,

            payload.get(
                "useful_life_months"
            ),

            payload.get(
                "residual_value"
            ),

            payload.get(
                "depreciation_method"
            ),

            payload.get(
                "funding_source"
            ),

            payload.get(
                "loan_percentage"
            ),

            payload.get("notes"),

            (
                json.dumps(
                    payload.get("meta_json")
                )
                if payload.get(
                    "meta_json"
                ) is not None
                else None
            ),

            int(company_id),
            int(capex_id),
        ))

        self._forecast_audit(
            company_id,
            entity_type="forecast_capex_item",
            entity_id=capex_id,
            action="update_capex_item",
            actor_user_id=user_id,
            before_json=before,
            after_json=row,
            message=(
                f"Updated forecast capex item "
                f"{capex_id}"
            ),
        )

        return row

    def forecast_update_capex_item(
        self,
        company_id: int,
        capex_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        before = self.fetch_one(f"""
            SELECT *
            FROM {schema}.forecast_capex_items
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(capex_id),
        ))

        if not before:
            raise ValueError(
                "Capital expenditure item not found."
            )

        quantity = Decimal(
            str(
                payload.get(
                    "quantity",
                    before["quantity"],
                )
            )
        )

        unit_cost = Decimal(
            str(
                payload.get(
                    "unit_cost",
                    before["unit_cost"],
                )
            )
        )

        total_cost = payload.get(
            "total_cost"
        )

        if total_cost is None:
            total_cost = quantity * unit_cost

        row = self.fetch_one(f"""
            UPDATE
                {schema}.forecast_capex_items

            SET
                asset_name = COALESCE(
                    %s,
                    asset_name
                ),

                asset_class = COALESCE(
                    %s,
                    asset_class
                ),

                account_code = COALESCE(
                    %s,
                    account_code
                ),

                purchase_month = COALESCE(
                    %s,
                    purchase_month
                ),

                quantity = %s,
                unit_cost = %s,
                total_cost = %s,

                useful_life_months =
                    COALESCE(
                        %s,
                        useful_life_months
                    ),

                residual_value =
                    COALESCE(
                        %s,
                        residual_value
                    ),

                depreciation_method =
                    COALESCE(
                        %s,
                        depreciation_method
                    ),

                funding_source =
                    COALESCE(
                        %s,
                        funding_source
                    ),

                loan_percentage =
                    COALESCE(
                        %s,
                        loan_percentage
                    ),

                notes = COALESCE(
                    %s,
                    notes
                ),

                meta_json = COALESCE(
                    %s::jsonb,
                    meta_json
                ),

                updated_at = now()

            WHERE company_id = %s
            AND id = %s

            RETURNING *;
        """, (
            payload.get("asset_name"),
            payload.get("asset_class"),
            payload.get("account_code"),
            payload.get("purchase_month"),

            quantity,
            unit_cost,
            total_cost,

            payload.get(
                "useful_life_months"
            ),

            payload.get(
                "residual_value"
            ),

            payload.get(
                "depreciation_method"
            ),

            payload.get(
                "funding_source"
            ),

            payload.get(
                "loan_percentage"
            ),

            payload.get("notes"),

            (
                json.dumps(
                    payload.get("meta_json")
                )
                if payload.get(
                    "meta_json"
                ) is not None
                else None
            ),

            int(company_id),
            int(capex_id),
        ))

        self._forecast_audit(
            company_id,
            entity_type="forecast_capex_item",
            entity_id=capex_id,
            action="update_capex_item",
            actor_user_id=user_id,
            before_json=before,
            after_json=row,
            message=(
                f"Updated forecast capex item "
                f"{capex_id}"
            ),
        )

        return row

    def forecast_delete_capex_item(
        self,
        company_id: int,
        capex_id: int,
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        self.ensure_company_forecast(company_id)
        schema = self.company_schema(company_id)

        row = self.fetch_one(f"""
            DELETE FROM
                {schema}.forecast_capex_items

            WHERE company_id = %s
            AND id = %s

            RETURNING *;
        """, (
            int(company_id),
            int(capex_id),
        ))

        if not row:
            raise ValueError(
                "Capital expenditure item not found."
            )

        self._forecast_audit(
            company_id,
            entity_type="forecast_capex_item",
            entity_id=capex_id,
            action="delete_capex_item",
            actor_user_id=user_id,
            before_json=row,
            message=(
                f"Deleted forecast capex item "
                f"{capex_id}"
            ),
        )

        return {
            "deleted": True,
            "id": int(capex_id),
        }

    def forecast_capex_impacts(
        self,
        company_id: int,
        *,
        version_id: Optional[int] = None,
        budget_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        items = self.forecast_list_capex_items(
            company_id,
            version_id=version_id,
            budget_id=budget_id,
        )

        monthly = {}

        total_capex = Decimal("0")
        total_cash = Decimal("0")
        total_loan = Decimal("0")

        for item in items:
            purchase_month = str(
                item["purchase_month"]
            )[:7] + "-01"

            total_cost = Decimal(
                str(item.get("total_cost") or 0)
            )

            residual_value = Decimal(
                str(
                    item.get(
                        "residual_value"
                    ) or 0
                )
            )

            useful_life = int(
                item.get(
                    "useful_life_months"
                ) or 0
            )

            cash_outflow = Decimal(
                str(
                    item.get(
                        "estimated_cash_outflow"
                    ) or 0
                )
            )

            loan_funding = Decimal(
                str(
                    item.get(
                        "estimated_loan_funding"
                    ) or 0
                )
            )

            monthly_depreciation = (
                (
                    total_cost -
                    residual_value
                ) /
                Decimal(useful_life)
                if (
                    useful_life > 0 and
                    item.get(
                        "depreciation_method"
                    ) == "straight_line"
                )
                else Decimal("0")
            )

            total_capex += total_cost
            total_cash += cash_outflow
            total_loan += loan_funding

            bucket = monthly.setdefault(
                purchase_month,
                {
                    "period_month":
                        purchase_month,

                    "capex_additions":
                        Decimal("0"),

                    "cash_outflow":
                        Decimal("0"),

                    "loan_funding":
                        Decimal("0"),

                    "monthly_depreciation":
                        Decimal("0"),
                },
            )

            bucket["capex_additions"] += (
                total_cost
            )

            bucket["cash_outflow"] += (
                cash_outflow
            )

            bucket["loan_funding"] += (
                loan_funding
            )

            bucket["monthly_depreciation"] += (
                monthly_depreciation
            )

        monthly_rows = []

        for value in monthly.values():
            monthly_rows.append({
                key: float(amount)
                if isinstance(
                    amount,
                    Decimal,
                )
                else amount

                for key, amount in
                value.items()
            })

        monthly_rows.sort(
            key=lambda row:
                row["period_month"]
        )

        return {
            "total_capex":
                float(total_capex),

            "total_cash_outflow":
                float(total_cash),

            "total_loan_funding":
                float(total_loan),

            "monthly":
                monthly_rows,

            "items":
                items,
        }


    # =========================
    # DB METHODS - PAYROLL
    # =========================
    def payroll_tax_regimes_list(self):
        """Return all tax regimes (public schema, not company-scoped)."""
        return self._payroll_query("""
            SELECT  id,
                    authority_code,
                    country_code,
                    name,
                    currency,
                    is_active
            FROM    public.payroll_tax_regimes
            WHERE   is_active = TRUE
            ORDER BY country_code, authority_code
        """)


    def payroll_tax_years_list(self, regime_id=None):
        """Return tax years, optionally filtered by regime."""
        if regime_id:
            return self._payroll_query("""
                SELECT  y.*,
                        r.authority_code,
                        r.country_code,
                        r.name  AS regime_name,
                        r.currency
                FROM    public.payroll_tax_years y
                JOIN    public.payroll_tax_regimes r
                        ON r.id = y.regime_id
                WHERE   y.regime_id = %s
                ORDER   BY y.effective_from DESC
            """, (regime_id,))
        else:
            return self._payroll_query("""
                SELECT  y.*,
                        r.authority_code,
                        r.country_code,
                        r.name  AS regime_name,
                        r.currency
                FROM    public.payroll_tax_years y
                JOIN    public.payroll_tax_regimes r
                        ON r.id = y.regime_id
                ORDER   BY r.country_code, y.effective_from DESC
            """)


    def payroll_tax_year_get(self, year_id):
        """Get a single tax year by ID."""
        rows = self._payroll_query("""
            SELECT  y.*,
                    r.authority_code,
                    r.country_code,
                    r.name  AS regime_name,
                    r.currency
            FROM    public.payroll_tax_years y
            JOIN    public.payroll_tax_regimes r
                    ON r.id = y.regime_id
            WHERE   y.id = %s
        """, (year_id,))
        return rows[0] if rows else None


    def payroll_tax_year_create(self, body, user_id=None):
        """Create a new tax year."""
        return self._payroll_query("""
            INSERT INTO public.payroll_tax_years
                (regime_id, tax_year_label, effective_from,
                effective_to, calculation_basis, is_active)
            VALUES (%s, %s, %s, %s, %s, TRUE)
            RETURNING *
        """, (
            int(body["regime_id"]),
            body["tax_year_label"],
            body["effective_from"],
            body["effective_to"],
            body.get("calculation_basis", "annualised"),
        ))[0]


    def payroll_tax_year_update(self, year_id, body, user_id=None):
        """Update a tax year. Returns updated row or None."""
        sets = []
        params = []

        for field in (
            "tax_year_label", "effective_from",
            "effective_to", "calculation_basis",
        ):
            if field in body and body[field] is not None:
                sets.append(f"{field} = %s")
                params.append(body[field])

        if "is_active" in body:
            sets.append("is_active = %s")
            params.append(bool(body["is_active"]))

        if not sets:
            return self.payroll_tax_year_get(year_id)

        params.append(int(year_id))

        rows = self._payroll_query(f"""
            UPDATE  public.payroll_tax_years
            SET     {', '.join(sets)}
            WHERE   id = %s
            RETURNING *
        """, params)

        return rows[0] if rows else None


    def payroll_tax_brackets_admin_list(self, year_id):
        """Return all brackets for a tax year (flat list)."""
        return self._payroll_query("""
            SELECT  *
            FROM    public.payroll_tax_brackets
            WHERE   tax_year_id = %s
            ORDER   BY residency_status, sort_order
        """, (year_id,))


    def payroll_tax_bracket_create(self, year_id, body, user_id=None):
        """Create a bracket for a tax year."""
        rows = self._payroll_query("""
            INSERT INTO public.payroll_tax_brackets
                (tax_year_id, residency_status,
                lower_bound, upper_bound,
                base_tax, marginal_rate, excess_over,
                sort_order)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING *
        """, (
            int(year_id),
            body.get("residency_status", "resident"),
            body.get("lower_bound", 0),
            body.get("upper_bound"),
            body.get("base_tax", 0),
            body.get("marginal_rate", 0),
            body.get("excess_over", 0),
            body.get("sort_order", 1),
        ))
        return rows[0] if rows else None


    def payroll_tax_bracket_update(self, bracket_id, body, user_id=None):
        """Update a single bracket. Returns updated row or None."""
        sets = []
        params = []

        for field in (
            "residency_status", "lower_bound", "upper_bound",
            "base_tax", "marginal_rate", "excess_over", "sort_order",
        ):
            if field in body and body[field] is not None:
                sets.append(f"{field} = %s")
                params.append(body[field])

        if not sets:
            rows = self._payroll_query("""
                SELECT * FROM public.payroll_tax_brackets
                WHERE id = %s
            """, (int(bracket_id),))
            return rows[0] if rows else None

        params.append(int(bracket_id))

        rows = self._payroll_query(f"""
            UPDATE  public.payroll_tax_brackets
            SET     {', '.join(sets)}
            WHERE   id = %s
            RETURNING *
        """, params)

        return rows[0] if rows else None


    def payroll_tax_bracket_delete(self, bracket_id, user_id=None):
        """Delete a bracket."""
        self._payroll_execute("""
            DELETE FROM public.payroll_tax_brackets
            WHERE id = %s
        """, (int(bracket_id),))


    def payroll_tax_parameters_admin_list(self, year_id):
        """Return all parameters for a tax year (flat list)."""
        return self._payroll_query("""
            SELECT  *
            FROM    public.payroll_tax_parameters
            WHERE   tax_year_id = %s
            ORDER   BY parameter_key
        """, (year_id,))


    def payroll_tax_parameter_upsert(self, year_id, body, user_id=None):
        """
        Create or update a parameter (upsert by tax_year_id + parameter_key).
        """
        rows = self._payroll_query("""
            INSERT INTO public.payroll_tax_parameters
                (tax_year_id, parameter_key,
                numeric_value, text_value)
            VALUES (%s, %s, %s, %s)
            ON CONFLICT (tax_year_id, parameter_key)
                DO UPDATE SET
                    numeric_value = EXCLUDED.numeric_value,
                    text_value   = EXCLUDED.text_value
            RETURNING *
        """, (
            int(year_id),
            body["parameter_key"],
            body.get("numeric_value"),
            body.get("text_value"),
        ))
        return rows[0] if rows else None


    def payroll_tax_parameter_update(self, param_id, body, user_id=None):
        """Update a parameter by ID. Returns updated row or None."""
        sets = []
        params = []

        if "parameter_key" in body:
            sets.append("parameter_key = %s")
            params.append(body["parameter_key"])
        if "numeric_value" in body:
            sets.append("numeric_value = %s")
            params.append(body["numeric_value"])
        if "text_value" in body:
            sets.append("text_value = %s")
            params.append(body["text_value"])

        if not sets:
            rows = self._payroll_query("""
                SELECT * FROM public.payroll_tax_parameters
                WHERE id = %s
            """, (int(param_id),))
            return rows[0] if rows else None

        params.append(int(param_id))

        rows = self._payroll_query(f"""
            UPDATE  public.payroll_tax_parameters
            SET     {', '.join(sets)}
            WHERE   id = %s
            RETURNING *
        """, params)

        return rows[0] if rows else None


    def payroll_tax_parameter_delete(self, param_id, user_id=None):
        """Delete a parameter."""
        self._payroll_execute("""
            DELETE FROM public.payroll_tax_parameters
            WHERE id = %s
        """, (int(param_id),))


    def payroll_tax_year_clone(self, source_year_id, body, user_id=None):
        """Clone a tax year (brackets + parameters) into a new year."""
        # Get source year
        source = self.payroll_tax_year_get(int(source_year_id))
        if not source:
            raise ValueError("Source tax year not found")

        # Create new year
        new_year = self.payroll_tax_year_create({
            "regime_id": source["regime_id"],
            "tax_year_label": body["tax_year_label"],
            "effective_from": body["effective_from"],
            "effective_to": body["effective_to"],
            "calculation_basis": source.get(
                "calculation_basis", "annualised"
            ),
        })

        new_id = new_year["id"]

        # Clone brackets
        self._payroll_execute("""
            INSERT INTO public.payroll_tax_brackets
                (tax_year_id, residency_status,
                lower_bound, upper_bound,
                base_tax, marginal_rate, excess_over,
                sort_order)
            SELECT  %s,
                    residency_status,
                    lower_bound, upper_bound,
                    base_tax, marginal_rate, excess_over,
                    sort_order
            FROM    public.payroll_tax_brackets
            WHERE   tax_year_id = %s
        """, (new_id, int(source_year_id)))

        # Clone parameters
        self._payroll_execute("""
            INSERT INTO public.payroll_tax_parameters
                (tax_year_id, parameter_key,
                numeric_value, text_value)
            SELECT  %s,
                    parameter_key,
                    numeric_value, text_value
            FROM    public.payroll_tax_parameters
            WHERE   tax_year_id = %s
        """, (new_id, int(source_year_id)))

        return new_year

    def _payroll_query(self, sql, params=None):
        """Run SELECT on public schema and return list of dicts."""
        with self._conn_cursor() as (conn, cur):
            cur.execute(sql, params or ())
            return cur.fetchall()

    def _payroll_execute(self, sql, params=None):
        """Run INSERT/UPDATE/DELETE, commit, return None."""
        with self._conn_cursor() as (conn, cur):
            cur.execute(sql, params or ())

    def _ensure_columns(self, schema: str, table: str, columns: dict):
        """Compare expected columns against actual table and ADD any missing."""
        if not columns:
            return
        existing = self.fetch_all("""
            SELECT column_name
            FROM information_schema.columns
            WHERE table_schema = %s AND table_name = %s
        """, (schema, table))
        existing_names = {r["column_name"] for r in existing}
        for col_name, col_def in columns.items():
            if col_name not in existing_names:
                self.execute_sql(
                    f"ALTER TABLE {schema}.{table} "
                    f"ADD COLUMN IF NOT EXISTS {col_name} {col_def};"
                )

    def _sync_payroll_settings(self, company_id: int):
        """Ensure payroll_settings has every column the code expects."""
        schema = self.company_schema(company_id)
        self._ensure_columns(schema, "payroll_settings", {
            "period_start_day":           "INT",
            "period_end_day":             "INT",
            "period_end_month_offset":    "INT NOT NULL DEFAULT 0",
            "payment_day_rule":           "TEXT",
            "payment_month_offset":       "INT NOT NULL DEFAULT 0",
            "payment_adjustment":         "TEXT NOT NULL DEFAULT 'none'",
            "calendar_generation_months": "INT NOT NULL DEFAULT 12",
        })

    def payroll_seed_defaults(self, company_id: int) -> dict:
        company_id = int(company_id)
        schema = self.company_schema(company_id)

        # ── Determine country ──
        company = self.fetch_one("""
            SELECT country
            FROM public.companies
            WHERE id = %s
            LIMIT 1;
        """, (company_id,)) or {}

        country = str(company.get("country") or "").strip().lower()
        is_sa = country in ("south africa", "rsa", "za")

        self.ensure_company_payroll(company_id)

        # ── Earnings (same for all countries) ──
        earnings = [
            ("BASIC", "Basic Salary", True, True),
            ("OVERTIME", "Overtime", True, True),
            ("BONUS", "Bonus", True, True),
            ("COMMISSION", "Commission", True, True),
            ("ALLOW_TRAVEL", "Travel Allowance", True, False),
            ("ALLOW_HOUSING", "Housing Allowance", True, False),
            ("ALLOW_CELLPHONE", "Cellphone Allowance", True, False),
        ]

        # ── Deductions (common to all countries) ──
        deductions = [
            ("PAYE", "PAYE", True),
            ("PENSION_EMP", "Pension Employee Deduction", False),
            ("MEDICAL_EMP", "Medical Aid Employee Deduction", False),
            ("LOAN_REPAY", "Employee Loan Repayment", False),
            ("ADVANCE_RECOVERY", "Salary Advance Recovery", False),
            ("UNION", "Union Fee", False),
        ]

        # ── South Africa ONLY deductions ──
        if is_sa:
            deductions.append(
                ("UIF_EMP", "UIF Employee Deduction", True)
            )

        # ── Employer contributions (common to all) ──
        contributions = [
            ("PENSION_ER", "Employer Pension Contribution"),
            ("MEDICAL_ER", "Employer Medical Aid Contribution"),
        ]

        # ── South Africa ONLY contributions ──
        if is_sa:
            contributions.extend([
                ("UIF_ER", "Employer UIF Contribution"),
                ("SKILLS_LEVY", "Skills Levy"),
            ])

        # ── Benefits (same for all countries) ──
        benefits = [
            ("MEDICAL", "Medical Aid", "mixed"),
            ("PENSION", "Pension Fund", "mixed"),
            ("HOUSING", "Housing Allowance", "allowance"),
            ("TRAVEL", "Travel Allowance", "allowance"),
            ("CELLPHONE", "Cellphone Allowance", "allowance"),
            ("COMPANY_CAR", "Company Vehicle", "fringe_benefit"),
            ("UNIFORM", "Uniform Allowance", "allowance"),
            ("STUDY", "Study Assistance", "fringe_benefit"),
        ]

        leave_types = [
            ("ANNUAL", "Annual Leave", True, True, 15),
            ("SICK", "Sick Leave", True, True, 0),
            ("FAMILY", "Family Responsibility Leave", True, True, 0),
            ("UNPAID", "Unpaid Leave", False, False, 0),
        ]

        for code, name, taxable, pensionable in earnings:
            self.execute_sql(f"""
                INSERT INTO {schema}.payroll_earning_types
                    (company_id, code, name, taxable, pensionable)
                VALUES (%s,%s,%s,%s,%s)
                ON CONFLICT (company_id, code) DO NOTHING;
            """, (company_id, code, name, taxable, pensionable))

        for code, name, statutory in deductions:
            self.execute_sql(f"""
                INSERT INTO {schema}.payroll_deduction_types
                    (company_id, code, name, is_statutory)
                VALUES (%s,%s,%s,%s)
                ON CONFLICT (company_id, code) DO NOTHING;
            """, (company_id, code, name, statutory))

        for code, name in contributions:
            self.execute_sql(f"""
                INSERT INTO {schema}.payroll_employer_contribution_types
                    (company_id, code, name)
                VALUES (%s,%s,%s)
                ON CONFLICT (company_id, code) DO NOTHING;
            """, (company_id, code, name))

        for code, name, category in benefits:
            self.execute_sql(f"""
                INSERT INTO {schema}.payroll_benefit_types
                    (company_id, code, name, benefit_category)
                VALUES (%s,%s,%s,%s)
                ON CONFLICT (company_id, code) DO NOTHING;
            """, (company_id, code, name, category))

        for code, name, paid, accrues, days in leave_types:
            self.execute_sql(f"""
                INSERT INTO {schema}.payroll_leave_types
                    (company_id, code, name, paid, accrues, annual_entitlement_days)
                VALUES (%s,%s,%s,%s,%s,%s)
                ON CONFLICT (company_id, code) DO NOTHING;
            """, (company_id, code, name, paid, accrues, days))

        return {"ok": True}

    def payroll_bootstrap(self, company_id: int) -> dict:
            company_id = int(company_id)

            self.payroll_ensure_ready(company_id)

            return {
                "settings": self.payroll_settings_get(company_id) or {},
                "calendars": self.payroll_calendars_list(company_id),
                "employees": self.payroll_employees_list(company_id),
                "tax_authorities": self.payroll_tax_authorities_list(),
                "setup": self.payroll_setup_master(company_id),
            }

    def payroll_ensure_ready(self, company_id: int) -> dict:
        company_id = int(company_id)

        self.ensure_company_payroll(company_id)
        self.payroll_seed_defaults(company_id)

        settings = self.payroll_settings_get(company_id)
        if not settings:
            company = self.fetch_one("""
                SELECT currency, country
                FROM public.companies
                WHERE id=%s
                LIMIT 1;
            """, (company_id,)) or {}

            # ── Auto-resolve tax authority from country ──
            tax_authority_id = self._resolve_tax_authority(
                company.get("country")
            )

            settings = self.payroll_settings_upsert(company_id, {
                "default_frequency": "monthly",
                "default_currency": company.get("currency") or "USD",
                "payroll_start_date": None,
                "tax_authority_id": tax_authority_id,

                "period_start_day": 21,
                "period_end_day": 20,
                "period_end_month_offset": 1,

                "payment_day_rule": "day:25",
                "payment_month_offset": 0,
                "payment_adjustment": "previous_working_day",

                "calendar_generation_months": 12,
                "is_active": True,
            })
        else:
            # ── Existing company: set authority if still NULL ──
            if not settings.get("tax_authority_id"):
                company = self.fetch_one("""
                    SELECT country
                    FROM public.companies
                    WHERE id=%s
                    LIMIT 1;
                """, (company_id,)) or {}

                tax_authority_id = self._resolve_tax_authority(
                    company.get("country")
                )

                if tax_authority_id:
                    schema = self.company_schema(company_id)
                    self.execute_sql(f"""
                        UPDATE {schema}.payroll_settings
                        SET tax_authority_id = %s
                        WHERE company_id = %s
                        AND tax_authority_id IS NULL;
                    """, (tax_authority_id, company_id))

                    settings["tax_authority_id"] = tax_authority_id

        return {"ok": True, "settings": settings}

    def _resolve_tax_authority(self, country: str) -> int | None:
        """Return the tax_authorities.id for the given country."""
        country = str(country or "").strip().lower()

        country_map = {
            "south africa": "SARS",
            "rsa": "SARS",
            "za": "SARS",
            "lesotho": "RSL",
            "ls": "RSL",
            "botswana": "BURS",
            "bw": "BURS",
        }

        code = country_map.get(country)
        if not code:
            return None

        row = self.fetch_one("""
            SELECT id
            FROM public.tax_authorities
            WHERE UPPER(code) = UPPER(%s)
            LIMIT 1;
        """, (code,))

        return int(row["id"]) if row else None

    def payroll_tax_authorities_list(self):
        """Return all tax authorities for the frontend dropdown."""
        return self.fetch_all("""
            SELECT
                ta.id,
                ta.code,
                ta.name,
                r.country_code,
                r.currency,
                r.is_active
            FROM public.tax_authorities ta
            LEFT JOIN public.payroll_tax_regimes r
                ON UPPER(r.authority_code) = UPPER(ta.code)
            WHERE COALESCE(r.is_active, TRUE) = TRUE
            AND UPPER(ta.code) IN ('SARS', 'RSL', 'BURS')
            ORDER BY ta.name;
        """)

