    def migrate_payroll_employee_number_sequence(
        self,
        company_id: int,
    ) -> dict:
        company_id = int(company_id)
        schema = self.company_schema(company_id)

        self.execute_sql(f"""
            CREATE SEQUENCE IF NOT EXISTS
                {schema}.payroll_employee_number_seq
            START WITH 1
            INCREMENT BY 1
            MINVALUE 1
            NO MAXVALUE
            CACHE 1;
        """)

        result = self.fetch_one(f"""
            WITH existing_numbers AS (
                SELECT
                    MAX(
                        CASE
                            WHEN employee_no IS NULL
                                OR BTRIM(employee_no) = ''
                            THEN NULL

                            ELSE (
                                NULLIF(
                                    RIGHT(
                                        regexp_replace(
                                            employee_no,
                                            '[^0-9]',
                                            '',
                                            'g'
                                        ),
                                        8
                                    ),
                                    ''
                                )
                            )::bigint
                        END
                    ) AS maximum_sequence,
                    COUNT(*)::bigint AS employee_count
                FROM {schema}.payroll_employees
                WHERE company_id = %s
            )
            SELECT setval(
                '{schema}.payroll_employee_number_seq',
                GREATEST(
                    COALESCE(maximum_sequence, 0),
                    1
                ),
                employee_count > 0
            ) AS sequence_value
            FROM existing_numbers;
        """, (company_id,))

        return {
            "ok": True,
            "company_id": company_id,
            "sequence_value": (
                result.get("sequence_value")
                if result
                else None
            ),
        }

